# legacy fields can influence host processes or hardware ownership and must
# remain on an operator-controlled runtime/profile path.
_DECLARATIVE_RUNTIME_FIELDS = {
    "systemd_unit", "launch_args", "env_overrides", "model_path", "cpuset",
    "gpu_id", "bundle", "linked_to", "linked_from", "proxy_port",
    "protected", "cpu_only",
}


def _declarative_runtime_field_errors(payload: Mapping[str, Any]) -> list[str]:
    """Reject host/runtime controls from GUI-defined service drafts."""

    safe_empty = {
        "systemd_unit": None,
        "launch_args": [],
        "env_overrides": {},
        "model_path": "",
        "cpuset": "",
        "gpu_id": None,
        "bundle": None,
        "linked_to": [],
        "linked_from": [],
        "proxy_port": None,
    }
    fields: list[str] = []
    for field in sorted(_DECLARATIVE_RUNTIME_FIELDS):
        if field not in payload:
            continue
        if field in safe_empty and payload[field] == safe_empty[field]:
            continue
        fields.append(field)
    return fields

# --- Phase 3 Scheduler Skeleton ---
_scheduler_judged_ready = False
_scheduler_started_at = time.time()
_scheduler_judgement = {}
_grace_window = {'state': 'completed'}
_last_swap_timestamp = 0.0
_current_selected_group = None
_drain_cutoffs = {}
_last_next_decision = {}


def _maintenance_mode_enabled(scheduling: Mapping[str, Any] | None) -> bool:
    """Normalize maintenance mode, failing closed on malformed values."""
    if not isinstance(scheduling, Mapping):
        return True
    raw = scheduling.get("maintenance_mode", False)
    return raw if isinstance(raw, bool) else True


def _phase3_scheduling_config():
    global _services_config
    try:
        sched = _services_config.get('scheduling', {})
    except NameError:
        sched = {}
    # Stage 5: env-var override for soft live scheduler ownership flip.
    # Default: 'false' (config-file value wins). When GPU Manager systemd unit
    # has GPU_MANAGER_SCHEDULER_OWNS_LOAD=true in its drop-in, this overrides
    # services.json and the scheduler becomes the sole owner of _load_bundle.
    #
    # Invariant: env can only RAISE the flag (OR semantics below) — never lower
    # a config-file True. This avoids a typo'd env var silently flipping
    # ownership off. To turn scheduler ownership off, edit services.json.
    #
    # NOTE: scheduler_dry_run_mode is intentionally NOT env-overridable here.
    # A live scheduler also requires the separate config-file-only
    # ``proactive_scheduling_enabled`` gate. This keeps ownership and telemetry
    # configuration separate from permission to perform a bundle transition.
    #
    # services.json (the source of truth when env-var is unset) is loaded from
    # SERVICES_CONFIG_PATH; see top-of-file for the resolved runtime location.
    env_owns = os.environ.get('GPU_MANAGER_SCHEDULER_OWNS_LOAD', 'false').strip().lower() == 'true'
    maintenance_mode = _maintenance_mode_enabled(sched)
    return {
        'grace_period_seconds': sched.get('grace_period_seconds', 30),
        'grace_min_resume_interval_s': sched.get('grace_min_resume_interval_s', 60),
        'demand_min_lag': sched.get('demand_min_lag', 1),
        'demand_min_ingress': sched.get('demand_min_ingress', 1),
        'min_dwell_seconds': sched.get('min_dwell_seconds', 20),
        # Aging is bounded and only changes the diagnostic/selection score;
        # it does not bypass bundle fencing or scheduler ownership gates.
        'priority_lanes_enabled': bool(sched.get('priority_lanes_enabled', False)),
        'queue_priority_aging_cap': sched.get('queue_priority_aging_cap', 3),
        'priority_aging_interval_s': sched.get('priority_aging_interval_s', 60),
        'priority_aging_cap': sched.get('priority_aging_cap', 100),
        # Queue ownership is deliberately opt-in.  ``split`` preserves the
        # current compatibility behavior while the durable/legacy modes give
        # operators a reversible way to fence one owner during cutover.
        'queue_owner': sched.get('queue_owner', 'split'),
        # Maintenance is an overriding safety fence. An environment override
        # must never grant scheduler ownership while the controller is paused.
        'scheduler_owns_load': False if maintenance_mode else (
            env_owns or sched.get('scheduler_owns_load', False)
        ),
        'scheduler_dry_run_mode': True if maintenance_mode else sched.get(
            'scheduler_dry_run_mode', True
        ),
        'proactive_scheduling_enabled': False if maintenance_mode else sched.get(
            'proactive_scheduling_enabled', False
        ),
        'maintenance_mode': maintenance_mode
    }


_QUEUE_OWNER_MODES = frozenset({'split', 'legacy', 'durable'})


def _queue_owner_mode(scheduling: Mapping[str, Any] | None = None) -> str:
    """Return the normalized startup queue-owner policy.

    ``split`` is the compatibility default because the candidate still has
    legacy ``GPUScheduler`` endpoints and durable Redis worker endpoints.
    Invalid values fail safe to ``split`` and are surfaced in health output;
    they must not silently select one owner and strand the other queue.
    """
    if scheduling is None:
        scheduling = _phase3_scheduling_config()
    raw = scheduling.get('queue_owner', 'split') if isinstance(scheduling, Mapping) else 'split'
    mode = str(raw or 'split').strip().lower()
    if mode not in _QUEUE_OWNER_MODES:
        logger.warning("Invalid scheduling.queue_owner=%r; retaining split compatibility mode", raw)
        return 'split'
    return mode


def _queue_owner_route_fence(route_owner: str, route: str):
    """Return a response when a compatibility route is owned elsewhere.

    The helper is intentionally side-effect free so handlers can call it
    before parsing/admitting a request.  ``None`` means the route is allowed
    under the configured policy.
    """
    configured = _queue_owner_mode()
    if configured == 'split' or configured == route_owner:
        return None
    return web.json_response(
        {
            'error': 'queue_owner_route_fenced',
            'reason': 'queue_owner_cutover_required',
            'configured_owner': configured,
            'route_owner': route_owner,
            'route': route,
        },
        status=503,
    )

def _get_phase3_scheduler_state(groups, all_gpu_states, generation_templates):
    config = _phase3_scheduling_config()
    now = time.time()

    observed_pending = {rg: g.get('queue_lag', 0) for rg, g in groups.items() if g.get('queue_lag', 0) > 0}

    gpu_warm_bundles = {}
    for gid, gs in all_gpu_states.items():
        gs_dict = gs.to_dict() if hasattr(gs, 'to_dict') else {}
        bundle = gs_dict.get('loaded_bundle')
        bundles = gs_dict.get('loaded_bundles', [])
        if bundle or bundles:
            gpu_warm_bundles[gid] = {
                'loaded_bundle': bundle,
                'loaded_bundles': bundles,
                'current_bundle': gs_dict.get('current_bundle'),
                'current_service': gs_dict.get('current_service'),
                'state': gs_dict.get('state')
            }

    try:
        dry_run = _compute_service_group_dry_run(groups, all_gpu_states, generation_templates)
        pending_groups = dry_run.get('pending_groups', [])
    except Exception:
        pending_groups = []

    grace_period_seconds = config.get('grace_period_seconds', 30)
    demand_min_ingress = config.get('demand_min_ingress', 1)
    grace_ends_at = _scheduler_started_at + grace_period_seconds

    global _grace_window
    if 'ingress_counts' not in _grace_window:
        _grace_window['ingress_counts'] = {}
    if 'start_time' not in _grace_window:
        _grace_window['start_time'] = now

    for rg, count in observed_pending.items():
        if count > 0:
            _grace_window['ingress_counts'][rg] = max(_grace_window['ingress_counts'].get(rg, 0), count)
    grace_ingress_counts = _grace_window['ingress_counts']

    grace_started_at = _grace_window.get('start_time', _scheduler_started_at)
    time_in_grace = now - grace_started_at

    has_sufficient_ingress = any(count >= demand_min_ingress for count in grace_ingress_counts.values())

    if now < grace_ends_at:
        if time_in_grace > 5.0 and not has_sufficient_ingress:
            grace_state = 'completed'
            grace_started_at = 0
            grace_ends_at = 0
        else:
            grace_state = 'active'
            grace_started_at = _scheduler_started_at
    else:
        grace_state = 'completed'
        grace_started_at = 0
        grace_ends_at = 0

    global _drain_cutoffs
    if grace_state == 'completed' and pending_groups:
        cand = pending_groups[0].get('group')
        if cand and cand not in _drain_cutoffs:
            _drain_cutoffs[cand] = now

    idle_preferred = (not pending_groups) and (grace_state == 'completed')

    next_decision_val = 'idle'
    next_decision_reason = 'No pending work'
    phase = 'idle'

    if grace_state == 'active':
        next_decision_val = 'awaiting_grace'
        next_decision_reason = f'Grace period active until {grace_ends_at}'
        phase = 'grace'
    elif pending_groups:
        phase = 'demand_driven'
        candidate_group = pending_groups[0].get('group')
        dwell = _last_swap_timestamp
        dwell_time = config.get('min_dwell_seconds', 20)
        if dwell and (now - dwell < dwell_time):
            next_decision_val = 'hold_dwell_time'
            next_decision_reason = f'Holding for dwell time {dwell_time}s on {candidate_group}'
        else:
            next_decision_val = f'demand:{candidate_group}'
            next_decision_reason = f'Pending demand for {candidate_group}'

    global _last_next_decision
    _last_next_decision = {
        'next_decision': next_decision_val,
        'decision_timestamp': now,
        'idle_preferred': idle_preferred
    }

    return {
        'restart_state_judgement': {
            'phase': phase,
            'previous_state_resumable': False,
            'observed_pending': observed_pending,
            'observed_ingress_window': {},
            'gpu_warm_bundles': gpu_warm_bundles,
            'judgment_timestamp': _scheduler_started_at
        },
        'grace_window_state': {
            'state': grace_state,
            'grace_started_at': grace_started_at,
            'grace_ends_at': grace_ends_at,
            'grace_ingress_counts': grace_ingress_counts
        },

        'next_decision': next_decision_val,
        'next_decision_reason': next_decision_reason,
        'decision_timestamp': now,
        'idle_preferred': idle_preferred,
        'drain_cutoffs': dict(_drain_cutoffs),
        'phase3_scheduler': True
    }

def can_consume(service_name, routing_group):
    config = _phase3_scheduling_config()
    if config.get('maintenance_mode'):
        return False, 'paused_maintenance'
    if not config.get('scheduler_owns_load'):
        return True, 'allowed'

    current_decision_state = _last_next_decision.get('next_decision') if isinstance(_last_next_decision, dict) else ''
    if current_decision_state == 'awaiting_grace':
        return False, 'paused_grace'

    try:
        svc_cfg = _services_config.get('services', {}).get(service_name, {})
    except Exception:
        svc_cfg = {}

    service_name_lower = service_name.lower()
    gpu_id = svc_cfg.get('gpu_id', '').lower()

    if 'ccd0' in service_name_lower or gpu_id in ('cpu', 'ccd0') or svc_cfg.get('cpu_only'):
        return True, 'allowed'

    gen_groups = {'comfyui-gen', 'music-gen', 'video-gen', 'image-gen', 'acestep'}
    is_gen = (
        any(g in service_name_lower for g in gen_groups) or
        any(g in routing_group.lower() for g in gen_groups) or
        svc_cfg.get('type') == 'generation_backend'
    )

    if is_gen:
        bundle = svc_cfg.get('bundle')
        if not bundle:
            try:
                templates = _services_config.get('generation_templates', {})
                for k, tmpl in templates.items():
                    if k == routing_group or tmpl.get('routing_group') == routing_group:
                        bundle = tmpl.get('bundle')
                        if bundle:
                            break
            except Exception:
                pass

        # Bundle-backed generation is admitted by WorkerPool._execute_job. A cold
        # bundle must therefore remain claimable: rejecting it here creates a
        # self-deadlock where no worker can reach the only bundle-load transaction.
        if bundle:
            return True, 'allowed_bundle_admission'

        target_decision = f'demand:{routing_group}'
        current_decision = _last_next_decision.get('next_decision', '') if isinstance(_last_next_decision, dict) else str(_last_next_decision)
        if target_decision not in current_decision and _current_selected_group != routing_group:
            return False, 'paused_demand_swap'

        return True, 'allowed'

    if svc_cfg.get('type') == 'llm_backend':
        # A planned stop is backend-local.  Do not freeze the logical
        # routing group: CPU/secondary GPU members must continue consuming Gemma
        # while the GPU member drains toward a bundle swap.
        if event_bus is not None and event_bus.is_planned_stop(service_name):
            return False, 'paused_planned_stop'
        # Gemma is a logical shared queue.  CPU/secondary GPU members must remain
        # eligible while another Gemma member is draining or a higher
        # priority bundle is waiting for the GPUs.
        if routing_group == 'Gemma':
            return True, 'allowed_logical_group'
        if _current_selected_group:
            return False, 'paused_demand_swap'

    return True, 'allowed'


# ── Pipeline stage dispatch seam ──────────────────────────────────────────────
# The validated worker_pipeline metadata (from compile_generation_pipeline) is
# executed here via PipelineDispatchRunner.  The runner is injected at call
# time so the existing Krea path remains intact when no pipeline is present.
#
# Provider injection contract:
#   executor_provider(executor_class, stages, context) -> PipelineExecutor
#   Default: instantiates KreaPipelineExecutor and calls its async dispatch.
#
# Fail-closed guarantees preserved:
#   • Unknown provider in stages → PipelineError at compile time (already done)
#   • No stages in worker_pipeline → Krea path is taken unchanged (existing code)
#   • Stage dispatch error → logged, returns (ctx, []) so caller can handle


async def _run_pipeline_stages(
    stages: list[dict],
    context,
    *,
    max_retries: int = 3,
    max_loop_count: int = 1,
    executor_provider=None,
    pre_results: list | None = None,
) -> tuple:
    """
    Dispatch validated pipeline stages via the injected executor provider.

    This is the seam between the declarative pipeline (service_pipeline.py)
    and the concrete execution (stage_dispatch.py KreaPipelineExecutor).

    Arguments:
        stages: compiled stage list from worker_pipeline["stages"]
        context: StageContext with original_prompt and any prior artifacts
        max_retries: per-stage retry cap (default 3)
        max_loop_count: correction loop cap (default 1)
        executor_provider: callable (class, stages, ctx) -> PipelineExecutor
                          Defaults to KreaPipelineExecutor with a no-op
                          _call_provider_async that raises on unknown kinds.

    Returns:
        (final_context, results_in_execution_order)
        Each StageResult has: stage_id, kind, provider, status, data, error, retries

    The existing Krea post-generation path is NOT modified; this function is
    called only when a compiled pipeline with stages is present in metadata.
    """
    sd = _get_stage_dispatch()
    StageContext = sd.StageContext
    PipelineExecutor = sd.PipelineExecutor
    KreaPipelineExecutor = sd.KreaPipelineExecutor
    DispatchKindError = sd.DispatchKindError
    DispatchProviderError = sd.DispatchProviderError

    if not stages:
        return context, []

    if executor_provider is None:
        # Closure captures the per-call bounds so the default provider
        # gets the right values instead of hardcoded defaults.
        _mr, _mlc = max_retries, max_loop_count
        def _bounded_provider(cls, stages, ctx):
            return _default_pipeline_executor_provider(cls, stages, ctx, _mr, _mlc)
        executor_provider = _bounded_provider

    # Build a concrete executor from the injected provider.  The live seam
    # intentionally accepts either a factory, an object exposing
    # ``build_executor``, or an already-built executor; it must not import a
    # concrete provider class from another project tree.
    if hasattr(executor_provider, "build_executor"):
        executor = executor_provider.build_executor(
            KreaPipelineExecutor,
            list(stages),
            context,
            pre_results=pre_results,
        )
    elif callable(executor_provider):
        executor = executor_provider(
            KreaPipelineExecutor,
            list(stages),
            context,
        )
    else:
        executor = executor_provider
    # Backward-compat: if the provider returns a bare class (not instance),
    # instantiate it with pipeline bounds.
    import inspect
    if inspect.isclass(executor):
        executor = _build_pipeline_executor(executor, max_retries, max_loop_count)

    try:
        ctx, results = await executor.dispatch(
            list(stages),
            context,
        )
        return ctx, results
    except (DispatchKindError, DispatchProviderError) as exc:
        logger.warning(
            "pipeline_dispatch: stage execution error: %s", exc,
        )
        return context, []


# ── Provider ownership registry ─────────────────────────────────────────────────
# Provider ownership is now managed by execution_boundary.py.
# LIVE_WORKER_OWNED_ADAPTERS replaces _KREA_ONLY_PROVIDERS.
# Providers are registered via register_provider_ownership() during init.
# _KREA_ONLY_PROVIDERS is retained as a frozen compat set for tests that
# directly reference it; all new code should use LIVE_WORKER_OWNED_ADAPTERS
# or classify_stages() / get_dispatch_mode() instead.
_KREA_ONLY_PROVIDERS: frozenset[str] = frozenset({
    "open-design",
    "comfyui",
    "comfyui-qwen",
    "combined-gemma",
})


def _has_non_krea_stage(stages: list[dict]) -> bool:
    """
    Return True if any stage in ``stages`` has a provider that is NOT handled
    by the live ComfyUI/OD worker path (i.e. requires the generic HTTP stage
    dispatcher or the inline KreaPipelineExecutor handlers).

    Delegates to execution_boundary.is_external() (backward-compat shim).

    When True, ``run_pipeline_dispatch`` is called instead of
    ``_reconcile_pipeline_evidence`` so that the stage is executed through
    the configured pipeline executor (e.g. HttpPipelineExecutor for ``http``
    provider stages, or the inline KreaPipelineExecutor handlers for other
    non-Krea providers).
    """
    # Keep the historical helper contract for older callers that import the
    # function before the startup registry is populated.  Production dispatch
    # uses get_dispatch_mode() below and remains fail-closed for unknown or
    # mixed ownership; this helper is only a compatibility predicate.
    for stage in stages:
        provider = str(stage.get("provider", ""))
        if not provider:
            return True
        if provider in _KREA_ONLY_PROVIDERS:
            continue
        try:
            if not is_self_owned([stage]):
                return True
        except MissingOwnershipMetadataError:
            return True
    return False


def _fail_mixed_worker_pipeline(
    job_tracker,
    job_id: str,
    *,
    prompt_id: str | None,
    image_data: list[dict],
    qc_report: dict | None,
) -> tuple[str, dict]:
    """Fail a mixed pipeline at the legacy worker boundary.

    Mixed provider ownership must be orchestrated by the controller-level
    coordinator. The legacy worker has already exercised its inline provider
    path, so dispatching external stages here risks duplicate calls.
    """
    code = "pipeline_coordinator_required"
    error = (
        "mixed-ownership pipeline requires pipeline coordinator: worker "
        f"boundary cannot safely dispatch external stages; code={code}"
    )
    payload = {
        "prompt_id": prompt_id,
        "status": "failed",
        "images": image_data,
        "qc": qc_report,
        "code": code,
    }
    if job_tracker:
        job_tracker.update_status(
            job_id,
            "failed",
            error=error,
            result=json.dumps(payload),
        )
    return error, payload


def _reconcile_pipeline_evidence(
    worker_pipeline: dict,
    *,
    original_prompt: str,
    enhanced_prompt: str,
    image_data: list[dict],
    qc_report: dict | None,
) -> tuple:
    """Bind real worker outputs to a declarative pipeline without re-running it.

    The image worker already owns the live prompt-enhancement, ComfyUI, and
    post-generation QC/correction calls.  Re-dispatching those stages here
    would execute synthetic handlers a second time and could falsely claim a
    provider success.  This reconciler therefore creates stage results only
    from evidence produced by those real calls.  An unknown stage kind or a
    missing required artifact is a hard, fail-closed mismatch.

    Returns ``(context, results, reconciled)``.  ``reconciled`` is false when
    the declarative pipeline is not the supported Krea worker contract; callers
    must not silently treat that case as success.
    """
    sd = _get_stage_dispatch()
    StageContext = sd.StageContext
    StageResult = sd.StageResult
    stages = list(worker_pipeline.get("stages") or [])
    if not stages:
        return StageContext(original_prompt=original_prompt), [], False

    context = StageContext(original_prompt=original_prompt)
    results: list = []
    by_id: dict[str, object] = {}
    supported_providers = {
        "prompt_enhance": {"open-design", "n8n"},
        "generate": {"comfyui"},
        "qc": {"combined-gemma"},
        "correct": {"comfyui-qwen"},
    }
    qc = dict(qc_report or {})
    terminal_qc_status = str(qc.get("terminal_qc_status") or "").lower()
    if "qc_pass" in qc:
        qc_pass = bool(qc["qc_pass"])
        terminal_qc_status = terminal_qc_status or ("pass" if qc_pass else "fail")
    else:
        qc_pass = terminal_qc_status in {"pass", "passed", "ok", "success"}
    correction_attempted = bool(qc.get("correction_attempted"))

    for stage in stages:
        stage_id = str(stage.get("id") or "")
        kind = str(stage.get("kind") or "")
        provider = str(stage.get("provider") or "")
        if not stage_id or provider not in supported_providers.get(kind, set()):
            return context, results, False

        for dep in stage.get("depends_on", []) or []:
            dep_result = by_id.get(str(dep))
            if dep_result is None or getattr(dep_result, "status", "failed") == "failed":
                return context, results, False

        if kind == "prompt_enhance":
            if not enhanced_prompt:
                return context, results, False
            result = StageResult(
                stage_id=stage_id, kind=kind, provider=provider, status="ok",
                data={"prompt": enhanced_prompt, "evidence_source": "live_worker"},
            )
            context = context.with_prompt(stage_id, enhanced_prompt)
        elif kind == "generate":
            if not image_data:
                return context, results, False
            result = StageResult(
                stage_id=stage_id, kind=kind, provider=provider, status="ok",
                data={
                    "images": image_data,
                    "artifact_count": len(image_data),
                    "evidence_source": "live_comfyui",
                },
            )
            context = context.with_artifact(stage_id, result.data)
        elif kind == "qc":
            if not qc_report or not terminal_qc_status:
                return context, results, False
            result = StageResult(
                stage_id=stage_id, kind=kind, provider=provider,
                status="ok" if qc_pass else "failed",
                data={**qc, "qc_pass": qc_pass, "evidence_source": "live_qc"},
                error="" if qc_pass else "live QC did not pass",
            )
            context = context.with_qc(stage_id, result.data)
        elif kind == "correct":
            if qc_pass and not correction_attempted:
                result = StageResult(
                    stage_id=stage_id, kind=kind, provider=provider,
                    status="skipped", data={},
                    error="correction not required after passing QC",
                )
            elif correction_attempted:
                result = StageResult(
                    stage_id=stage_id, kind=kind, provider=provider, status="ok",
                    data={"correction_attempted": True, "evidence_source": "live_worker"},
                )
                context = context.with_loop_increment().with_artifact(stage_id, result.data)
            else:
                return context, results, False
        else:
            return context, results, False

        by_id[stage_id] = result
        results.append(result)
        if result.status == "failed":
            return context, results, True

    return context, results, True


def _seed_pipeline_context_from_worker_evidence(
    worker_pipeline: dict,
    *,
    original_prompt: str,
    effective_prompt: str = "",
    image_data: list[dict] | None = None,
    qc_report: dict | None = None,
):
    """Build the handoff context from evidence already produced by the worker.

    Mixed pipelines must not redispatch worker-owned stages.  The worker has
    already performed the local ComfyUI request (and may have performed local
    prompt/QC work), so the generic dispatcher receives a typed evidence bag
    keyed by the declarative stage IDs.  Missing evidence remains visible as an
    empty result and is rejected by the handoff validation/terminal checks.
    """
    sd = _get_stage_dispatch()
    context = sd.StageContext(original_prompt=original_prompt)
    image_data = list(image_data or [])
    qc = dict(qc_report or {})
    terminal_status = str(qc.get("terminal_qc_status") or "").lower()
    if "qc_pass" not in qc and terminal_status:
        qc["qc_pass"] = terminal_status in {"pass", "passed", "ok", "success"}
    correction_attempted = bool(qc.get("correction_attempted"))

    for stage in list(worker_pipeline.get("stages") or []):
        stage_id = str(stage.get("id") or "")
        kind = str(stage.get("kind") or "")
        if not stage_id:
            continue
        if kind == "prompt_enhance" and effective_prompt:
            context = context.with_prompt(stage_id, effective_prompt)
        elif kind in {"generate", "delegate"} and image_data:
            context = context.with_artifact(
                stage_id,
                {
                    "images": image_data,
                    "artifact_count": len(image_data),
                    "evidence_source": "live_comfyui",
                },
            )
        elif kind == "qc" and qc:
            context = context.with_qc(stage_id, qc)
        elif kind == "correct" and correction_attempted:
            context = context.with_loop_increment().with_artifact(
                stage_id,
                {"correction_attempted": True, "evidence_source": "live_worker"},
            )
    return context


class _KreaDispatchRunner:
    """
    PipelineDispatchRunner that wraps KreaPipelineExecutor.

    Injected at worker execution time so tests can substitute a
    FakeKreaPipelineExecutor without modifying the gpu-manager call site.
    """

    def __init__(
        self,
        max_retries: int = 3,
        max_loop_count: int = 1,
    ):
        self.max_retries = max_retries
        self.max_loop_count = max_loop_count

    def build_executor(
        self,
        executor_class,  # type: ignore[override]
        stages=None,
        context=None,
    ) -> "KreaPipelineExecutor":  # type: ignore[name-defined]
        # stages and context are accepted for interface compatibility with
        # _run_pipeline_stages' generic dispatch contract but are not used;
        # _InlineExecutor gets its bounds from self.max_retries / self.max_loop_count.
        return _build_pipeline_executor(executor_class, self.max_retries, self.max_loop_count)


class _MixedOwnershipExecutor:
    """
    Thin wrapper around CompositeProviderExecutor that intercepts dispatch() to
    inject pre-executed worker-owned stage results (seeded from the GPU Manager
    worker's evidence bag) so that external stages can depend on worker-owned
    stages without re-executing them.

    This is the typed seam for the mixed-ownership handoff protocol:
    the GPU Manager worker executes the worker-owned stages (prompt_enhance via
    OpenDesign, generate via ComfyUI, qc via Combined-Gemma), collects their
    outputs into a StageContext, and then passes that context to the
    CompositeProviderExecutor via this wrapper.  The wrapper pre-populates the
    fan-in dependency map so external stages (e.g. n8n, http-qc) see the same
    context as if all stages had run in a single sequential pipeline.

    This class never submits worker-owned stages to the GPU or any HTTP backend.

    Parameters
    ----------
    inner : CompositeProviderExecutor
        The underlying multi-provider executor for external stages.
    seeded_results : list[StageResult]
        Pre-executed results for all worker-owned stages.  These are injected
        into the fan-in dependency map before dispatch begins.
    seeded_context : StageContext
        The StageContext carrying evidence from worker-owned stages
        (enhanced_prompts, artifacts, qc_results, correction_loop_count).
        This replaces the caller's context so external stages receive the
        same evidence as if worker stages had run inline.
    """

    __slots__ = ("_inner", "_seeded_results", "_seeded_context", "_external_stages")

    def __init__(
        self,
        inner: "CompositeProviderExecutor",
        seeded_results: list,
        seeded_context: "StageContext",
        external_stages: list[dict] | None = None,
    ) -> None:
        self._inner = inner
        self._seeded_results = seeded_results
        self._seeded_context = seeded_context
        # The external-only stage list produced by safe_handoff_stages().
        # Only these stages are dispatched to the inner executor; worker-owned
        # stages are already recorded in _seeded_results and must NOT be
        # re-executed (would cause duplicate generation/calls).
        self._external_stages = external_stages if external_stages is not None else []

    async def dispatch(
        self,
        stages: list[dict],
        context: "StageContext",
    ):
        """
        Dispatch stages with pre-seeded worker-owned results pre-populated
        in the fan-in map.

        Passes the full ``stages`` graph so that external stages can look up
        worker-owned stages in their fan-in ``depends_on`` chains via the
        seeded results pre-populated in the dependency map.

        Worker-owned stages are never dispatched (they are already in
        ``seeded_results`` and must NOT be re-executed).  Only the external
        stages from ``_external_stages`` are iterated for actual dispatch.
        """
        # The full graph is passed so stage_defs has all stage IDs for
        # depends_on fan-in lookups.  We iterate only dispatch_stages
        # (external-only) to avoid re-executing worker-owned stages.
        dispatch_stages = self._external_stages
        if not dispatch_stages:
            seeded_ids = {
                getattr(result, "stage_id", "")
                for result in (self._seeded_results or [])
            }
            dispatch_stages = [stage for stage in stages if stage.get("id") not in seeded_ids]

        # A valid handoff normally supplies seeded_context, but callers may
        # construct this wrapper with only a caller context while an ownership
        # handoff is being assembled. Never discard that valid context and
        # replace it with None: downstream adapters require StageContext.
        dispatch_context = (
            self._seeded_context
            if self._seeded_context is not None
            else context
        )
        if dispatch_context is None:
            raise TypeError("mixed-ownership dispatch requires a StageContext")
        dispatch_kwargs = {
            "context": dispatch_context,
            "seeded_results": self._seeded_results,
        }
        # Older injected test doubles expose the pre-contract dispatch
        # signature.  Use introspection rather than catching TypeError from
        # the call, so a genuine provider TypeError is never mistaken for a
        # compatibility downgrade.
        import inspect
        try:
            dispatch_signature = inspect.signature(self._inner.dispatch)
        except (TypeError, ValueError):
            dispatch_signature = None
        if dispatch_signature is not None and "stage_defs" in dispatch_signature.parameters:
            # Keep the complete declarative graph available for dependency
            # validation and loop re-entry while only external stages are
            # eligible for actual dispatch.  Passing the full graph as the
            # positional ``stages`` argument would re-run worker-owned stages.
            dispatch_kwargs["stage_defs"] = {
                str(stage.get("id")): stage for stage in stages
            }
        dispatch_result = self._inner.dispatch(dispatch_stages, **dispatch_kwargs)
        # Production executors are async, while hermetic tests and injected
        # adapters may expose a synchronous stub.  Accept either without
        # weakening the typed result contract.
        import inspect
        if inspect.isawaitable(dispatch_result):
            return await dispatch_result
        return dispatch_result


class _GenericPipelineDispatchRunner:
    """
    PipelineDispatchRunner that builds a CompositeProviderExecutor for the
    generic ``execution_mode``, routing each stage to the provider declared
    in the pipeline contract via the PipelineProviderRuntime.

    This is the injected runner for WorkerPool pools when a generic-mode
    pipeline is present.  It uses the GPU Manager's live services.json
    provider registry and the existing aiohttp session to make real HTTP
    calls for ``http_json`` / ``http_openai_compatible`` stages, and uses
    the ``stage_executor_factory`` for ``gpu_manager_generation`` stages.

    Fail-closed on:
      - Unknown provider IDs (not in the provider registry)
      - ``gpu_manager_generation`` stages without a factory (raises
        ``MissingExecutorFactoryError``)
      - ``gpu_manager_generation`` stages when the provider is not in
        the gpu_executor_map (raises ``MissingExecutorFactoryError``)

    The existing Krea path (legacy_reconcile mode, or generic with all
    stages targeting KREA_ONLY_PROVIDERS) is NOT routed here; it uses
    ``_KreaDispatchRunner`` instead, avoiding any duplicate GPU generation.

    Injected at WorkerPool construction time via ``pipeline_dispatch_runner``.
    """

    def __init__(
        self,
        services_config: dict,
        provider_registry: frozenset[str],
        session: "ClientSession",
        max_retries: int = 3,
        max_loop_count: int = 1,
    ):
        self._services_config = services_config
        self._provider_registry = provider_registry
        self._session = session
        self.max_retries = max_retries
        self.max_loop_count = max_loop_count

    def build_executor(
        self,
        executor_class,  # accepted for interface compatibility; ignored
        stages: list[dict] | None = None,
        context=None,
        pre_results: list | None = None,
    ) -> "CompositeProviderExecutor | _MixedOwnershipExecutor":
        """
        Build a CompositeProviderExecutor from the pipeline contract.

        When the pipeline contains both worker-owned and external stages
        (mixed ownership), safe_handoff_stages() is called to:
          1. Filter stages to external-only (worker stages already executed)
          2. Build a seeded StageContext from the worker's evidence bag
          3. Build StageResult objects for all worker-owned stages

        The returned executor wrapper intercepts dispatch() to inject the
        seeded results and context so external stages see the same evidence
        as if worker stages had run inline.

        Parameters
        ----------
        executor_class : type
            Accepted for interface compatibility with _run_pipeline_stages;
            the generic runner always returns a CompositeProviderExecutor.
        stages : list[dict] | None
            The compiled stage list from the pipeline contract.  Required
            for resolving the transport map.  When None (e.g. during
            class-level inspection), returns an unbound executor.
        context : StageContext | None
            The live execution context from the worker.  Required for
            mixed-ownership pipelines so the seeded context can be built
            with the correct original_prompt, enhanced_prompts, artifacts,
            and qc_results.  Ignored for non-mixed pipelines.

        Returns
        -------
        CompositeProviderExecutor | _MixedOwnershipExecutor
            A standard executor for non-mixed pipelines, or a wrapper
            that injects seeded results for mixed-ownership pipelines.
        """
        # Import lazily to keep the pipeline_provider_runtime import at the
        # top of the stage-dispatch seam, not at module load time.
        from pipeline_provider_runtime import (
            PipelineProviderRuntime,
            MissingExecutorFactoryError,
        )
        from stage_dispatch import GenerationStageExecutor

        # ── Mixed-ownership detection ──────────────────────────────────────
        # Check whether the full pipeline is mixed-ownership before filtering.
        # safe_handoff_stages is called below with the evidence from context
        # to produce the filtered external-only stages and seeded results.
        mixed_cls = None
        if stages:
            try:
                mixed_cls = classify_stages(stages)
            except MissingOwnershipMetadataError:
                pass  # Will raise at dispatch time

        if (
            stages
            and mixed_cls is not None
            and mixed_cls.is_mixed_ownership
        ):
            # Mixed-ownership pipeline: extract worker evidence from context
            # and build a handoff result with external-only stages.
            # context may be None in tests; pass empty evidence rather than
            # crashing so that build_executor can be called without a context.
            if context is not None:
                _original_prompt = context.original_prompt
                _enhanced_prompts = dict(context.enhanced_prompts)
                _artifacts = dict(context.artifacts)
                _qc_results = dict(context.qc_results)
                _correction_loop_count = context.correction_loop_count
            else:
                _original_prompt = ""
                _enhanced_prompts = {}
                _artifacts = {}
                _qc_results = {}
                _correction_loop_count = 0
            handoff = safe_handoff_stages(
                stages,
                original_prompt=_original_prompt,
                enhanced_prompts=_enhanced_prompts,
                artifacts=_artifacts,
                qc_results=_qc_results,
                correction_loop_count=_correction_loop_count,
                pre_results=pre_results,
            )
            # Use the filtered external-only stages for building the executor.
            # Worker-owned stages are NOT re-dispatched.
            exec_stages: list[dict] | None = handoff.external_stages
            seeded_ctx = handoff.seeded_context
            seeded_res = handoff.seeded_results
        else:
            exec_stages = stages
            seeded_ctx = None
            seeded_res = None

        runtime = PipelineProviderRuntime(
            services_config=self._services_config,
            provider_registry=self._provider_registry,
        )

        # Build a transport map for every non-gpu_manager_generation provider
        # referenced in the stages.  gpu_manager_generation providers use the
        # stage_executor_factory instead.
        transport_map: dict[str, Any] = {}
        if exec_stages:
            seen_providers: set[str] = set()
            for stage in exec_stages:
                provider_id = str(stage.get("provider", ""))
                if not provider_id or provider_id in seen_providers:
                    continue
                seen_providers.add(provider_id)
                try:
                    cfg = runtime._resolve_provider_config(provider_id)
                except Exception:
                    continue  # will raise at dispatch time if actually used
                adapter = cfg.get("adapter", "")
                if adapter == "gpu_manager_generation":
                    continue  # handled via stage_executor_factory
                # Wrap the aiohttp session as a transport callable
                transport_map[provider_id] = _AiohttpTransport(self._session)

        # Factory for gpu_manager_generation stages
        def _gpu_factory(
            provider_id: str, _transport: Any
        ) -> GenerationStageExecutor:
            # Build a GPU generation executor using the same runtime
            gpu_adapter = runtime.build_gpu_adapter(provider_id, _transport)
            return _GPUSubmissionExecutor(
                provider_id=provider_id,
                gpu_adapter=gpu_adapter,
                max_retries=self.max_retries,
            )

        multi = runtime.build_multi_provider_executor(
            contract={"stages": exec_stages or [], "max_loop_count": self.max_loop_count},
            transport_map=transport_map,
            stage_executor_factory=_gpu_factory,
            max_delegate_depth=3,
            max_retries=self.max_retries,
        )

        # For mixed-ownership: wrap so dispatch() injects seeded results and
        # dispatches only external stages (worker stages are already done).
        if seeded_res is not None and seeded_ctx is not None:
            return _MixedOwnershipExecutor(
                inner=multi,
                seeded_results=seeded_res,
                seeded_context=seeded_ctx,
                external_stages=exec_stages,
            )
        return multi


class _AiohttpTransport:
    """
    Thin adapter that wraps an aiohttp.ClientSession as a transport callable
    usable by PipelineProviderRuntime.

    Signature: (headers, method, url, body_bytes, timeout) -> Awaitable[tuple[int, bytes, dict]]
    """

    def __init__(self, session: "ClientSession", *, owner_loop=None) -> None:
        self._session = session
        self._owner_loop = owner_loop

    async def __call__(
        self,
        headers: dict,
        method: str,
        url: str,
        body: bytes | None,
        timeout: float = 30.0,
    ) -> tuple[int, bytes, dict]:
        """Make an HTTP request and return (status, body_bytes, headers_dict)."""
        if self._owner_loop is not None and asyncio.get_running_loop() is not self._owner_loop:
            # Coordinator stages run in worker threads with their own loops;
            # aiohttp sessions must execute on their original owning loop.
            pending = asyncio.run_coroutine_threadsafe(
                self(headers, method, url, body, timeout), self._owner_loop,
            )
            return await asyncio.wrap_future(pending)
        request_headers = dict(headers)
        self_authenticated = False
        if not any(str(name).lower() == "authorization" for name in request_headers):
            from urllib.parse import urlsplit

            parsed = urlsplit(url)
            try:
                target_port = parsed.port
            except ValueError:
                target_port = None
            if (
                parsed.scheme == "http"
                and (parsed.hostname or "").lower() in {"127.0.0.1", "localhost", "::1"}
                and target_port == int(LISTEN_PORT)
            ):
                token = _api_token()
                if token:
                    request_headers["Authorization"] = f"Bearer {token}"
                    self_authenticated = True
        kwargs: dict = {
            "headers": request_headers,
            "allow_redirects": not self_authenticated,
        }
        if body:
            kwargs["data"] = body
        timeout_obj = __import__("aiohttp", fromlist=["ClientTimeout"]).ClientTimeout(
            total=timeout
        )
        kwargs["timeout"] = timeout_obj

        async with self._session.request(method, url, **kwargs) as resp:
            try:
                body_bytes = await resp.read()
            except Exception:
                body_bytes = b""
            return (
                resp.status,
                body_bytes,
                dict(resp.headers),
            )


class _GPUSubmissionExecutor(GenerationStageExecutor):
    """
    Concrete GenerationStageExecutor that submits to the GPU Manager generation API
    via the GPUMgrLikeAdapter.

    Raises DispatchProviderError fail-closed on submission failure so the bounded
    retry loop in CompositeProviderExecutor can handle it correctly.
    """

    def __init__(
        self,
        provider_id: str,
        gpu_adapter: Any,  # GPUMgrLikeAdapter
        max_retries: int = 3,
    ) -> None:
        self._provider_id = provider_id
        self._gpu_adapter = gpu_adapter
        self.max_retries = max_retries
        self._job_id: str | None = None

    async def dispatch(
        self,
        stage_id: str,
        kind: str,
        provider: str,
        params: dict,
        context: "StageContext",
    ) -> "StageResult":
        """
        Submit a GPU generation job and wait for its completion.

        Raises DispatchProviderError on submission or polling failure,
        which triggers the bounded retry loop in CompositeProviderExecutor.
        """
        from stage_dispatch import StageResult, DispatchProviderError

        # Build the assignment from stage params and context
        assignment = _build_gpu_assignment(stage_id, kind, provider, params, context)

        try:
            receipt = await self._gpu_adapter.submit(
                assignment,
                state_store=None,
                params=params,
            )
        except Exception as exc:
            raise DispatchProviderError(
                f"GPU submit failed for stage {stage_id!r}: {exc}"
            ) from exc

        self._job_id = getattr(receipt, "job_id", None) or getattr(receipt, "id", None)

        # Poll for completion
        try:
            snapshot = await self._gpu_adapter.poll(
                self._job_id,
                deadline_seconds=params.get("timeout", 300.0),
            )
        except Exception as exc:
            raise DispatchProviderError(
                f"GPU poll failed for job {self._job_id!r}: {exc}"
            ) from exc

        status = getattr(snapshot, "status", "failed")
        if status in ("completed", "ok", "done"):
            return StageResult(
                stage_id=stage_id,
                kind=kind,
                provider=provider,
                status="ok",
                data={
                    "job_id": self._job_id,
                    "outputs": getattr(snapshot, "outputs", []),
                },
                error="",
                retries=0,
            )
        elif status in ("failed", "error"):
            return StageResult(
                stage_id=stage_id,
                kind=kind,
                provider=provider,
                status="failed",
                data={},
                error=getattr(snapshot, "error", f"GPU job {status}"),
                retries=0,
            )
        else:
            # Pending or unknown — treat as ok with available data
            return StageResult(
                stage_id=stage_id,
                kind=kind,
                provider=provider,
                status="ok",
                data={
                    "job_id": self._job_id,
                    "status": status,
                },
                error="",
                retries=0,
            )


def _build_gpu_assignment(
    stage_id: str,
    kind: str,
    provider: str,
    params: dict,
    context: "StageContext",
) -> dict:
    """
    Build a GPU Manager generation assignment dict from a pipeline stage.

    Shapes the stage params + context into the assignment dict expected
    by GPUMgrGenerationAdapter.submit().
    """
    # The assignment is the opaque dict that the GPU Manager generation API
    # receives.  Map from pipeline contract fields to the expected shape.
    prompt = (
        context.enhanced_prompts.get(stage_id, "")
        or list(context.enhanced_prompts.values()[-1:] or [""])[0]
        or context.original_prompt
    )
    assignment: dict = {
        "stage_id": stage_id,
        "kind": kind,
        "provider": provider,
        "params": dict(params),
    }
    if context.original_prompt:
        assignment["original_prompt"] = context.original_prompt
    if prompt and prompt != context.original_prompt:
        assignment["prompt"] = prompt
    # Forward any prior artifacts as context
    if context.artifacts:
        assignment["artifacts"] = dict(context.artifacts)
    return assignment


def _build_pipeline_dispatch_runner(
    services_config: dict,
    provider_registry: frozenset[str],
    session: "ClientSession",
    *,
    max_retries: int = 3,
    max_loop_count: int = 1,
    execution_mode: str = "generic",
) -> "_KreaDispatchRunner | _GenericPipelineDispatchRunner":
    """
    Build the appropriate PipelineDispatchRunner for the given execution mode.

    Parameters
    ----------
    services_config : dict
        The GPU Manager's services.json dict.
    provider_registry : frozenset[str]
        The closed set of known provider IDs.
    session : ClientSession
        The shared aiohttp session for HTTP transport.
    max_retries : int
        Per-stage retry cap.
    max_loop_count : int
        Correction loop cap.
    execution_mode : str
        ``"generic"`` → ``_GenericPipelineDispatchRunner`` (multi-provider HTTP
        dispatch via PipelineProviderRuntime + CompositeProviderExecutor).
        ``"legacy_reconcile"`` → ``_KreaDispatchRunner`` (inline handlers,
        no HTTP, for Krea-only pipelines that are reconciled from live
        worker outputs).

    Returns
    -------
    _KreaDispatchRunner | _GenericPipelineDispatchRunner
    """
    if execution_mode == "generic":
        return _GenericPipelineDispatchRunner(
            services_config=services_config,
            provider_registry=provider_registry,
            session=session,
            max_retries=max_retries,
            max_loop_count=max_loop_count,
        )
    # legacy_reconcile — use the inline handler path (no HTTP, no GPU submission)
    return _KreaDispatchRunner(max_retries=max_retries, max_loop_count=max_loop_count)


def _default_pipeline_executor_provider(executor_class, stages, context, max_retries=3, max_loop_count=1):
    """Default: instantiate the given executor class with pipeline bounds."""
    return _build_pipeline_executor(executor_class, max_retries, max_loop_count)


def _build_pipeline_executor(executor_class, max_retries, max_loop_count):
    """
    Build a concrete PipelineExecutor bound to the CLOSED_KINDS handlers.

    The executor uses the inline async handlers from KreaPipelineExecutor
    directly — no network I/O, no live provider calls.  This lets the
    pipeline be dispatched in-process while keeping the Krea worker path
    completely independent.
    """
    sd = _get_stage_dispatch()

    class _InlineExecutor(executor_class):
        """Executor that calls KreaPipelineExecutor typed handlers inline."""

        async def _call_provider_async(
            self, stage_id, kind, provider, params, ctx
        ):
            # Delegate to the KreaPipelineExecutor typed handlers.
            # These run in-process with fake responses; the real I/O
            # providers are wired separately by the Worker's actual
            # executor (e.g. the ComfyUI + OD adapter path).
            handler_map = {
                "prompt_enhance": self._handle_prompt_enhance,
                "generate": self._handle_generate,
                "qc": self._handle_qc,
                "correct": self._handle_correct,
                "delegate": self._handle_delegate,
            }
            handler = handler_map.get(kind)
            if handler is None:
                sd_DispatchKindError = sd.DispatchKindError
                raise sd_DispatchKindError(f"unknown stage kind '{kind}'")
            return await handler(stage_id, provider, params, ctx)

    ex = _InlineExecutor()
    ex.max_retries = max_retries
    ex.max_loop_count = max_loop_count
    return ex


async def run_pipeline_dispatch(
    worker_pipeline: dict,
    original_prompt: str,
    *,
    max_retries: int = 3,
    max_loop_count: int = 1,
    initial_context=None,
    executor_provider=None,
    pre_results: list | None = None,
) -> tuple:
    """
    Public entry point for pipeline dispatch from a worker execution context.

    Arguments:
        worker_pipeline: the compiled worker_pipeline metadata dict (from
                       compile_generation_pipeline output, stored in job metadata)
        original_prompt: the raw prompt string
        max_retries: per-stage retry cap (default 3, from pipeline max_retries)
        max_loop_count: correction loop cap (default 1)
        initial_context: optional StageContext seeded with worker evidence for
                         a mixed-ownership handoff
        executor_provider: optional callable(class, stages, ctx) -> PipelineExecutor.
                          When supplied (e.g. an HttpPipelineExecutor factory from
                          pipeline_http_provider), it replaces the default
                          KreaPipelineExecutor-based provider.  This is the injection
                          point used by WorkerPool.pipeline_dispatch_runner.

    Returns:
        (final_context, results_in_execution_order, dispatched: bool)
        dispatched is False when worker_pipeline has no stages (legacy path).

    Usage in _execute_job::
        if compiled_stages:
            ctx, results, dispatched = await run_pipeline_dispatch(
                worker_pipeline,
                original_prompt,
                max_retries=max_retries,
                max_loop_count=max_loop_count,
                executor_provider=self.pipeline_dispatch_runner,
            )
            if dispatched:
                # Pipeline ran; handle ctx.artifacts / ctx.qc_results
    """
    sd = _get_stage_dispatch()
    StageContext = sd.StageContext

    stages = worker_pipeline.get("stages") or []
    if not stages:
        return StageContext(original_prompt=original_prompt), [], False

    context = initial_context or StageContext(original_prompt=original_prompt)
    # Merge pre_results into the initial context for safe_handoff_stages
    if pre_results:
        for _pr in pre_results:
            if _pr.kind == "prompt_enhance":
                _pr_prompt = _pr.data.get("prompt", "")
                if _pr_prompt:
                    context = context.with_prompt(_pr.stage_id, _pr_prompt)
            elif _pr.kind in ("generate", "delegate"):
                context = context.with_artifact(_pr.stage_id, dict(_pr.data))
            elif _pr.kind == "qc":
                context = context.with_qc(_pr.stage_id, dict(_pr.data))
    ctx, results = await _run_pipeline_stages(
        stages,
        context,
        max_retries=max_retries,
        max_loop_count=max_loop_count,
        executor_provider=executor_provider,
        pre_results=pre_results,
    )
    return ctx, results, True



def _queue_depth_observation(
    queue,
    service_name: str,
    routing_group: str | None = None,
    *,
    strict: bool = False,
) -> dict[str, Any]:
    """Normalize queue depth without turning missing evidence into demand."""

    fallback = {
        "depth": 0,
        "known": False,
        "reason": "queue_engine_unavailable",
        "pending": 0,
    }
    if queue is None:
        return fallback
    observer = getattr(queue, "get_queue_depth_observation", None)
    if callable(observer):
        try:
            result = observer(service_name, routing_group=routing_group)
            if isinstance(result, Mapping):
                return {
                    "depth": max(0, int(result.get("depth", 0) or 0)),
                    "known": result.get("known") is True,
                    "reason": str(result.get("reason") or "unknown"),
                    "pending": max(0, int(result.get("pending", 0) or 0)),
                    "stream": result.get("stream"),
                    "error": str(result.get("error") or "")[:240],
                }
        except Exception as exc:
            if strict:
                raise
            return {**fallback, "reason": f"observation_error:{type(exc).__name__}"}
    try:
        try:
            depth = queue.get_queue_depth(
                service_name, routing_group=routing_group, strict=strict
            )
        except TypeError as exc:
            if "strict" not in str(exc):
                raise
            # Older queue adapters did not expose the strict keyword.  Retry
            # the bounded integer API instead of turning a non-strict health
            # observation into an avoidable unknown-depth result.
            depth = queue.get_queue_depth(
                service_name, routing_group=routing_group
            )
        return {
            "depth": max(0, int(depth or 0)),
            "known": True,
            "reason": "legacy_integer_api",
            "pending": 0,
        }
    except Exception as exc:
        if strict:
            raise
        return {**fallback, "reason": f"depth_error:{type(exc).__name__}"}


def _logical_group_quiescent(routing_group: str) -> tuple[bool, dict]:
    """Return whether a logical routing group is fully drained.

    Queue lag alone is insufficient: Redis PEL entries may already be
    assigned to workers, and a backend can still be executing a request.
    This helper is intentionally group-wide so a GPU service can drain
    without blocking eligible CPU/other-GPU members of the same group.
    """
    snapshot = {
        'routing_group': routing_group,
        'queue_depth': 0,
        'queue_depth_known': False,
        'queue_depth_reason': 'queue_engine_unavailable',
        'pending': 0,
        'active_workers': 0,
        'job_demand': None,
    }
    try:
        if queue_engine is not None:
            observation = _queue_depth_observation(
                queue_engine, routing_group, routing_group, strict=True
            )
            snapshot['queue_depth'] = observation['depth']
            snapshot['queue_depth_known'] = observation['known']
            snapshot['queue_depth_reason'] = observation['reason']
            pending_reader = queue_engine.get_pending
            try:
                snapshot['pending'] = len(pending_reader(
                    routing_group, routing_group=routing_group, strict=True
                ) or [])
            except TypeError as exc:
                # Compatibility fakes/older queue adapters may not expose the
                # strict keyword yet. Keep their established behavior, while
                # the production RedisQueue takes the fail-closed path above.
                if "strict" not in str(exc):
                    raise
                snapshot['pending'] = len(pending_reader(
                    routing_group, routing_group=routing_group
                ) or [])
            if (
                snapshot['queue_depth_known'] is not True
                and snapshot['queue_depth_reason'] != 'external_queue_authority'
            ):
                snapshot['error'] = (
                    'queue depth unavailable: '
                    f"{snapshot['queue_depth_reason']}"
                )
                return False, snapshot
    except Exception as exc:
        snapshot['error'] = f'queue inspection failed: {exc}'
        return False, snapshot
    try:
        if worker_supervisor is not None:
            for pool in worker_supervisor._pools.values():
                if routing_group in getattr(pool, 'routing_groups', ()):
                    snapshot['active_workers'] += int(
                        getattr(pool, 'active_workers', 0) or 0
                    )
    except Exception as exc:
        snapshot['error'] = f'worker inspection failed: {exc}'
        return False, snapshot

    # Redis stream depth/P.E.L. and worker counters can briefly disagree with
    # the durable tracker. Include claimed/loading/in-flight records; an
    # absent or unavailable tracker is not safe evidence that a shared runtime
    # can be unloaded, so the transition fails closed.
    tracker = globals().get('job_tracker')
    if tracker is None or not hasattr(tracker, 'demand_snapshot'):
        snapshot['error'] = 'job demand tracker unavailable'
        return False, snapshot
    try:
        demand = tracker.demand_snapshot(routing_group=routing_group)
        snapshot['job_demand'] = demand
        if demand.get('status') != 'available':
            snapshot['error'] = 'job demand unavailable'
            return False, snapshot
    except Exception as exc:
        snapshot['error'] = f'job demand inspection failed: {exc}'
        return False, snapshot

    durable_active = (
        int((snapshot.get('job_demand') or {}).get('active_demand') or 0)
        if snapshot.get('job_demand') is not None
        else 0
    )
    return (
        snapshot['queue_depth'] == 0
        and snapshot['pending'] == 0
        and snapshot['active_workers'] == 0
        and durable_active == 0,
        snapshot,
    )


async def _wait_for_logical_group_quiescence(
    routing_group: str, timeout: float = 1800.0, settle_seconds: float = 0.5
) -> bool:
    """Wait until a logical group is empty and stays empty briefly.

    New arrivals remain valid work and are consumed by any healthy eligible
    member.  The settle window closes the check/enqueue race immediately
    before a higher-priority GPU bundle is admitted.
    """
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        empty, snapshot = _logical_group_quiescent(routing_group)
        if empty:
            await asyncio.sleep(settle_seconds)
            empty_again, snapshot_again = _logical_group_quiescent(routing_group)
            if empty_again:
                logger.info(
                    f'Logical group {routing_group} quiescent before swap: '
                    f'{snapshot_again}'
                )
                return True
            snapshot = snapshot_again
        logger.info(
            f'Logical group {routing_group} still draining before swap: '
            f'{snapshot}'
        )
        await asyncio.sleep(0.5)
    logger.warning(
        f'Logical group {routing_group} did not quiesce within {timeout}s; '
        'refusing the bundle swap'
    )
    return False


_can_consume_last_log = {}

def _log_can_consume_pause(service_name, routing_group, reason, worker_id):
    now = time.time()
    key = (service_name, routing_group, reason)
    last_log = _can_consume_last_log.get(key, 0)
    if now - last_log >= 10:
        logger.debug(f"Worker {worker_id} for {service_name} paused on {routing_group}: {reason}")
        _can_consume_last_log[key] = now

# --- Proactive Dispatch Loop (dry-run mode) ---
_PROACTIVE_LOOP_INTERVAL_SEC = 2.5
_PROACTIVE_SPACING_WINDOW_SEC = 10.0
_proactive_dispatch_state = {
    "enabled": True,
    "dry_run": True,
    "iteration_count": 0,
    "last_iteration_at": 0.0,
    "last_decision": None,
    "would_have_evicted": 0,
    "would_have_loaded": 0,
    "would_have_held": 0,
    "dispatched": 0,
    "dispatch_failures": 0,
    "errors": [],
    "spaced_actions": 0,
    "last_action_recorded_at": 0.0,
}
_PROACTIVE_LAST_DECISION = None  # For 10-30s spacing rule (no repeated would-have-done in tight window)

# --- Phase 4 Scheduler Skeleton ---
_dual_swap_lock = None
_last_decision = {'action': 'noop', 'reason': 'init'}
_last_dual_swap_state = 'idle'
_head_job_pre_checks = []
import threading
_head_job_pre_checks_lock = threading.Lock()
_comfyui_admission_lock = threading.Lock()
_comfyui_admission_leases: dict[str, float] = {}
_load_history = []
_group_failure_state = {}
_scheduler_dry_run_mode = True


def _get_dual_swap_lock():
    global _dual_swap_lock
    if _dual_swap_lock is None:
        import asyncio
        _dual_swap_lock = asyncio.Lock()
    return _dual_swap_lock


class _RestoreAdmissionGuard:
    """Acquire bundle admission before the per-manager restore lock.

    The ordering matches the bundle-load transaction (physical admission
    first, lifecycle operation second), so a restore cannot observe an empty
    generation state and then race a new admission into the same GPUs.
    """

    def __init__(self, manager):
        self._manager = manager
        self._admission_lock = _get_dual_swap_lock()

    async def __aenter__(self):
        await self._admission_lock.acquire()
        try:
            await self._manager._evict_lock.acquire()
        except Exception:
            self._admission_lock.release()
            raise
        return self

    async def __aexit__(self, exc_type, exc, tb):
        self._manager._evict_lock.release()
        self._admission_lock.release()
        return False


def _bundle_worker_in_flight(bundle_name: str | None, bundles: dict | None = None) -> int:
    """Return active workers across a bundle and all linked GPU roles."""
    if not bundle_name:
        return 0
    if bundle_name.startswith("llm:"):
        bundle_name = bundle_name[4:]
    bundles = bundles or _resolve_bundles()
    bundle = bundles.get(bundle_name)
    if not bundle:
        return 0
    bundle = dict(bundle)
    bundle["name"] = bundle_name
    total = 0
    for gpu_id in _collect_linked_gpus(bundle, bundles):
        state = _get_gpu_state(gpu_id)
        total += int(getattr(state, "worker_in_flight", 0) or 0)
    return total


def _bundle_transition_is_active() -> bool:
    """Return True while any GPU is in a serialized bundle transition."""
    for state in _gpu_states.values():
        if (
            bool(getattr(state, "loading", False))
            or bool(getattr(state, "evicting", False))
            or bool(getattr(state, "draining", False))
            or str(getattr(state, "state", "")) in {"loading", "evicting", "draining"}
        ):
            return True
    sched_state = getattr(scheduler, "_gpu_state", {}) if scheduler is not None else {}
    if isinstance(sched_state, dict):
        for state in sched_state.values():
            if isinstance(state, dict) and (
                state.get("loading") or state.get("evicting") or state.get("draining")
            ):
                return True
    return False


def _acquire_comfyui_admission(job_id: str, ttl_seconds: float = 1800.0) -> None:
    """Fence ComfyUI from bundle load until its Redis job is worker-owned."""
    if not job_id:
        return
    with _comfyui_admission_lock:
        _comfyui_admission_leases[str(job_id)] = time.monotonic() + ttl_seconds


def _release_comfyui_admission(job_id: str) -> None:
    if not job_id:
        return
    with _comfyui_admission_lock:
        _comfyui_admission_leases.pop(str(job_id), None)


def _comfyui_admission_in_flight() -> int:
    """Return live admission leases, pruning cancelled/abandoned requests."""
    now = time.monotonic()
    with _comfyui_admission_lock:
        expired = [
            job_id for job_id, deadline in _comfyui_admission_leases.items()
            if deadline <= now
        ]
        for job_id in expired:
            _comfyui_admission_leases.pop(job_id, None)
        return len(_comfyui_admission_leases)


def _direct_idle_stop_blockers(
    *,
    comfyui_busy: bool,
    current_backend: str | None,
    worker_in_flight: int,
    transition_active: bool,
    admission_in_flight: int = 0,
) -> list[str]:
    """Return authoritative reasons direct-idle must not stop ComfyUI.

    ComfyUI removes a prompt from its execution queue before the GPUManager
    WorkerPool has fetched /history, downloaded outputs, committed JobTracker,
    and ACKed Redis. The linked WorkerPool lease is therefore the terminal
    ownership signal; an empty ComfyUI queue alone is not sufficient.
    """
    blockers: list[str] = []
    if comfyui_busy:
        blockers.append("comfyui_queue_busy")
    if current_backend:
        blockers.append("scheduler_backend_active")
    if int(worker_in_flight or 0) > 0:
        blockers.append(f"linked_worker_in_flight:{int(worker_in_flight)}")
    if int(admission_in_flight or 0) > 0:
        blockers.append(f"comfyui_admission_in_flight:{int(admission_in_flight)}")
    if transition_active:
        blockers.append("bundle_transition_active")
    return blockers


def _should_run_direct_idle_fence(
    *,
    was_busy: bool,
    comfyui_busy: bool,
    comfyui_terminally_stopped: bool,
) -> bool:
    """Return whether direct-idle may probe ComfyUI's terminal fence.

    A manager-owned auto-stop intentionally closes ComfyUI's port.  Treating
    that closed port as a failed fence re-arms the idle edge forever and turns
    normal cleanup into repeated warnings.
    """
    return bool(was_busy and not comfyui_busy and not comfyui_terminally_stopped)


def _log_direct_idle_fence_state(state: str, *, blockers: list[str]) -> bool:
    """Emit one structured direct-idle transition line per distinct state."""
    global _direct_idle_fence_last_signature
    signature = (str(state), tuple(sorted(str(item) for item in blockers)))
    if signature == _direct_idle_fence_last_signature:
        return False
    _direct_idle_fence_last_signature = signature
    log = logger.warning if state == "probe_failed" else logger.info
    log(
        "direct_idle_fence state=%s blockers=%s",
        state,
        ",".join(signature[1]) if signature[1] else "none",
    )
    return True


def _arm_comfyui_warm_handoff(
    job_id: str,
    terminal_status: str,
    *,
    ttl_seconds: float = 10.0,
) -> str | None:
    """Bridge the terminal-to-next-submit gap for serial ComfyUI batches."""
    if str(terminal_status) != "completed" or not job_id:
        return None
    lease_key = f"warm-handoff:{job_id}"
    _acquire_comfyui_admission(lease_key, ttl_seconds=ttl_seconds)
    return lease_key


def _generation_release_blockers(
    gpu_ids: set[str] | None = None,
    *,
    ignore_scheduler_restoring: bool = False,
    ignore_loaded_bundles: set[str] | None = None,
) -> list[str]:
    """Return service-agnostic reasons idle recovery must remain deferred.

    When ``gpu_ids`` is provided, inspection is restricted to those physical
    GPUs.  This lets a genuine crash on an otherwise-idle GPU recover while a
    different GPU renders.  With no scope, the helper is fail-closed for a
    global restore caller.
    """
    all_states = _get_all_gpu_states()
    states = {
        gpu_id: state for gpu_id, state in all_states.items()
        if gpu_ids is None or gpu_id in gpu_ids
    }
    blockers: list[str] = []
    if any(
        bool(getattr(state, "loading", False))
        or bool(getattr(state, "evicting", False))
        or bool(getattr(state, "draining", False))
        or str(getattr(state, "state", "")) in {"loading", "evicting", "draining"}
        for state in states.values()
    ):
        blockers.append("bundle_transition_active")

    # Scheduler flags carry no physical-GPU identity, so use them only for a
    # global restore. Per-idle-service crash recovery is instead gated by the
    # authoritative state of that service's own GPU.
    if gpu_ids is None:
        active_backend = getattr(scheduler, "_current_backend", None) if scheduler is not None else None
        if active_backend:
            blockers.append("scheduler_backend_active")
        if scheduler is not None and bool(getattr(scheduler, "_swapping", False)):
            blockers.append("scheduler_swapping")
        if (
            not ignore_scheduler_restoring
            and scheduler is not None
            and bool(getattr(scheduler, "_restoring", False))
        ):
            blockers.append("scheduler_restoring")

    worker_in_flight = sum(
        int(getattr(state, "worker_in_flight", 0) or 0)
        for state in states.values()
    )
    if worker_in_flight > 0:
        blockers.append(f"generation_worker_in_flight:{worker_in_flight}")

    bundles = _resolve_bundles()
    ignored = set(ignore_loaded_bundles or ())
    lingering: set[str] = set()
    for gpu_state in states.values():
        # ``loaded_bundle`` is the startup-persisted canonical owner; the
        # list is the post-reconciliation multi-bundle form. Check both so a
        # short startup window cannot fail open.
        bundle_names = set(getattr(gpu_state, "loaded_bundles", []) or [])
        loaded_bundle = getattr(gpu_state, "loaded_bundle", None)
        if loaded_bundle:
            bundle_names.add(str(loaded_bundle))
        for bundle_name in bundle_names:
            if bundle_name in ignored:
                continue
            bundle = bundles.get(bundle_name) or {}
            if bundle_name and not bundle.get("idle", False):
                lingering.add(str(bundle_name))
    if lingering:
        blockers.append("non_idle_bundle_loaded:" + ",".join(sorted(lingering)))
    return blockers


def _idle_service_recovery_blockers(service_name: str) -> list[str]:
    """Return reasons an idle-service port failure is an expected transition.

    An empty list means recovery may treat a failed health probe as a genuine
    crash.  Planned stop stamps are intentionally short-lived caller hints;
    the independently-derived generation-release state keeps recovery
    suppressed for the whole managed transaction even after that stamp clears.
    """
    blockers: list[str] = []
    # Operator intent is an authoritative recovery fence. A disabled idle
    # service may remain in the topology/idle map, but it must not be probed,
    # warned about, or restarted by any recovery path.
    services = (_load_services_config().get("services") or {})
    service_config = services.get(service_name) or {}
    if not service_config.get("enabled", True):
        blockers.append("config_disabled")
    if event_bus is not None and event_bus.is_planned_stop(service_name):
        blockers.append("planned_stop")
    idle_gpus = {
        str(entry.get("gpu_id"))
        for entry in _get_all_idle_services()
        if entry.get("service_name") == service_name and entry.get("gpu_id")
    }
    # Unknown placement cannot be proven unrelated, so global inspection is
    # the fail-closed fallback. Normal configured idle services are scoped.
    blockers.extend(_generation_release_blockers(idle_gpus or None))
    return blockers


def _restore_after_gpu_work_blockers() -> list[str]:
    """Authoritative fences that defer destructive idle-service restoration."""
    blockers = _generation_release_blockers()
    # A ComfyUI handoff lease is an additional terminal-ownership fence for
    # that backend only.  The generic helper above remains the source of truth
    # for all backend types and linked GPU reservations.
    admission_in_flight = _comfyui_admission_in_flight()
    if admission_in_flight:
        blockers.append(f"comfyui_admission_in_flight:{admission_in_flight}")
    return blockers


def _auto_evict_bundle_blockers(
    bundle_name: str, bundles: dict | None = None
) -> list[str]:
    """Return lifecycle blockers while excluding the eviction candidate.

    A loaded non-idle bundle is normally a restore blocker. During that same
    bundle's auto-eviction decision it cannot block itself; only unrelated
    residents, transitions, active workers, and admission leases may defer the
    unload. Linked reservation-only roles are part of the same candidate.
    """
    bundles = bundles or _resolve_bundles()
    ignored = {bundle_name, *_get_linked_bundles(bundle_name, bundles=bundles)}
    blockers = _generation_release_blockers(ignore_loaded_bundles=ignored)
    admission_in_flight = _comfyui_admission_in_flight()
    if admission_in_flight:
        blockers.append(f"comfyui_admission_in_flight:{admission_in_flight}")
    return blockers


def _normalize_readiness_required_fields(value) -> tuple[str, ...]:
    """Return a stable tuple of required readiness-payload field names.

    Accepts ``None``, a sequence of strings, or a single string. Empty
    strings are dropped. The empty tuple means "no fields required" —
    the caller must then decide whether to fall back to legacy HTTP-200
    semantics or to fail closed. This helper only normalises shape; the
    semantics live in :func:`_evaluate_readiness_payload`.
    """
    if value is None:
        return ()
    if isinstance(value, str):
        candidates = [value]
    else:
        try:
            candidates = list(value)
        except TypeError:
            return ()
    out: list[str] = []
    for name in candidates:
        if not isinstance(name, str):
            continue
        name = name.strip()
        if name and name not in out:
            out.append(name)
    return tuple(out)


def _readiness_payload_lookup(payload, field_path: str) -> tuple[bool, object]:
    """Resolve a readiness field from a JSON object without flattening it.

    A literal top-level key takes precedence for backward compatibility.
    Otherwise ``.`` separates object keys, so a backend may expose a stable
    envelope such as ``{"data": {"models_initialized": true}}`` and use
    ``data.models_initialized`` in its readiness contract.
    """
    if not isinstance(payload, dict) or not isinstance(field_path, str):
        return False, None
    if field_path in payload:
        return True, payload[field_path]
    current = payload
    for component in field_path.split("."):
        if not component or not isinstance(current, dict) or component not in current:
            return False, None
        current = current[component]
    return True, current


def _evaluate_readiness_payload(
    *,
    status: int,
    payload,
    required_fields,
    service_name: str,
    required_value_fields=None,
) -> tuple[bool, str]:
    """Evaluate HTTP status plus configured presence and exact-value contracts."""
    try:
        status_code = int(status or 0)
    except (TypeError, ValueError):
        status_code = 0
    if status_code != 200:
        return False, f"readiness: status {status_code} (expected 200)"

    fields = _normalize_readiness_required_fields(required_fields)
    value_fields = required_value_fields if isinstance(required_value_fields, dict) else {}
    if not fields and not value_fields:
        return True, "readiness: HTTP 200 (no required fields)"
    if not isinstance(payload, dict):
        return False, "readiness: payload not a JSON object"

    missing = [name for name in fields if not _readiness_payload_lookup(payload, name)[0]]
    if missing:
        return False, f"readiness: missing required field(s) {missing} for service '{service_name}'"

    mismatched = {}
    for name, expected in value_fields.items():
        present, observed = _readiness_payload_lookup(payload, name)
        if not present or observed != expected:
            mismatched[name] = {"expected": expected, "observed": observed if present else None}
    if mismatched:
        return False, f"readiness: required value mismatch(es) {mismatched} for service '{service_name}'"

    return True, f"readiness: configured fields satisfied for service '{service_name}'"


def _bundle_commit_preconditions(
    *,
    systemd_running: bool,
    health_http_200: bool,
    worker_pool_ready: bool,
    gpu_resident: bool,
    worker_in_flight: int,
    transition_active: bool,
    allow_worker_in_flight: bool = False,
) -> tuple[bool, list[str]]:
    """Evaluate authoritative prerequisites for committing bundle ownership."""
    reasons: list[str] = []
    if not systemd_running:
        reasons.append("systemd_running")
    if not health_http_200:
        reasons.append("health_http_200")
    if not worker_pool_ready:
        reasons.append("worker_pool_ready")
    if not gpu_resident:
        reasons.append("gpu_resident")
    if int(worker_in_flight or 0) > 0 and not allow_worker_in_flight:
        reasons.append("worker_in_flight")
    if transition_active:
        reasons.append("transition_active")
    return not reasons, reasons


def _record_load_history(decision):
    _load_history.insert(0, decision)
    if len(_load_history) > 50:
        _load_history.pop()

def _record_head_job_precheck(record):
    with _head_job_pre_checks_lock:
        _head_job_pre_checks.insert(0, record)
        if len(_head_job_pre_checks) > 20:
            _head_job_pre_checks.pop()

def _group_circuit_state(group, now, config):
    return _group_failure_state.get(group, {'state': 'closed'})

def _active_group_still_draining(target_group: str) -> bool:
    """Dry-run check: is any other active group still draining queue lag?

    When the scheduler sees demand:<target_group>, but a different active
    routing group still reports queue_lag > 0, we hold the load so the
    active group can drain its accepted/cutoff queue before swap.
    """
    for rg, cutoff in _drain_cutoffs.copy().items():
        if rg == target_group:
            continue
        try:
            if (time.time() - float(cutoff)) <= 60:
                return True
        except ValueError:
            return False
    return False

def _target_gpus_hold_warm_bundle(target_group: str) -> bool:
    """Advisory telemetry only.

    Returns True only when at least one target GPU for ``target_group`` is
    holding a bundle that is NOT the target bundle and NOT a valid linked
    component of it. Returns False when:

      * no target GPUs can be derived from a reservation or template/bundle
        topology, or
      * every target GPU is either idle or already holds the target bundle
        (including any valid linked bundle component).

    ``requires_eviction`` is **advisory, factual decision telemetry**: it tells
    operators whether a swap will be required for the upcoming load. It is NOT
    a second control path in the dispatcher. ``_evict_then_load_bundle`` is the
    authoritative atomic state-transition / readiness path and runs its own
    priority-aware precheck. See ``_dispatch_scheduler_decision``.

    NOTE: this function deliberately swallows exceptions from the GPU state
    read and converts unreadable state into a "warm, unknown" signal so the
    caller can choose to fail closed. The fail-closed path is implemented in
    ``_scheduler_evaluate_load`` (which switches to a non-dispatch action when
    state cannot be inspected) rather than here, so this helper remains a
    pure telemetry predicate.
    """
    grp_res = {}
    try:
        grp_res = _group_reservations.get(target_group, {}) or {}
    except Exception:
        grp_res = {}
    target_gpus: list[str] = []
    if isinstance(grp_res, dict) and grp_res.get('requires_gpus'):
        for gid in grp_res.get('requires_gpus') or []:
            if gid and gid not in target_gpus:
                target_gpus.append(gid)
    if not target_gpus:
        # Fall back to a config-driven derivation rather than hard-coded names:
        # the proactive loop must not silently default to "warm, no eviction"
        # when it can't see reservation state.
        target_gpus = list(_resolve_group_target_gpus(target_group) or [])
    else:
        # Reservation slice is non-empty — UNION with topology so a partial or
        # stale reservation can NEVER hide a linked gpu that needs warm-state
        # inspection. Without this, a partial reservation that omits the linked
        # gpu would silently mask an evictor resident on that gpu.
        for gid in list(_resolve_group_target_gpus(target_group) or []):
            if gid and gid not in target_gpus:
                target_gpus.append(gid)
    if not target_gpus:
        return False

    target_bundle, linked_bundles = _resolve_target_bundle_components(target_group)
    accepted_names = set()
    if target_bundle:
        accepted_names.add(target_bundle)
        accepted_names.update(linked_bundles or [])

    for gid in target_gpus:
        try:
            gs = _get_gpu_state(gid)
        except Exception:
            # Fail-closed signal: the caller will see this via
            # _scheduler_evaluate_load's state-unreadable branch and emit a
            # non-dispatch action. Returning False here would falsely advertise
            # "cold, no eviction" for a GPU whose state we cannot inspect.
            raise _TargetStateUnreadable(target_group, gid)
        warm = getattr(gs, 'loaded_bundle', None) or getattr(gs, 'current_bundle', None)
        if not warm:
            continue
        if accepted_names and warm in accepted_names:
            # Same target bundle (or a valid linked component) — not an eviction.
            continue
        return True
    return False


class _TargetStateUnreadable(Exception):
    """Raised when a target GPU's state cannot be inspected.

    The evaluator catches this and converts it into a non-dispatch
    action/reason — the dispatcher's authoritative atomic path stays the
    only place where eviction actually happens, and it must never run on
    state we cannot see.
    """

    def __init__(self, group: str, gpu_id: str):
        super().__init__(f"target state unreadable for group {group!r} gpu {gpu_id!r}")
        self.group = group
        self.gpu_id = gpu_id


def _resolve_target_bundle_components(target_group: str) -> tuple[str | None, list[str]]:
    """Resolve (target_bundle_name, [linked_bundle_names]) for a routing group.

    Reads ``_services_config.generation_templates`` for the template that maps
    to ``target_group`` and pulls the bundle's ``linked_to`` chain from the
    in-memory ``_services_config.bundles``.

    If the in-memory ``_services_config.bundles`` section is absent, falls back
    to the cached/disk ``_resolve_bundles()`` resolver — same safe-fallback
    policy used by ``_resolve_group_target_gpus``. The fallback MUST NOT
    mutate the caller-provided ``_services_config`` (monkeypatched in tests);
    it only refreshes the bundle cache that ``_resolve_bundles`` owns.

    Returns ``(None, [])`` if the group has no template/bundle or if the
    bundle cannot be resolved via either source.
    """
    templates = ((_services_config or {}).get('generation_templates') or {})
    bundle_name: str | None = None
    for tmpl in templates.values():
        if not isinstance(tmpl, dict):
            continue
        if tmpl.get('routing_group') == target_group:
            cand = tmpl.get('bundle')
            if cand and bundle_name is None:
                bundle_name = str(cand)
            elif cand and bundle_name != str(cand):
                # Ambiguous mapping for a single group → refuse to derive.
                return None, []
    if not bundle_name:
        return None, []

    # Walk in-memory bundles first; never trigger _resolve_bundles() if we
    # have the topology locally. _resolve_bundles() may reach disk via
    # _load_services_config() which CAN clobber a monkeypatched _services_config.
    in_memory_bundles = ((_services_config or {}).get('bundles') or {})
    if in_memory_bundles:
        linked: list[str] = []
        try:
            for ln in _get_linked_bundles(bundle_name, bundles=in_memory_bundles) or []:
                if ln and ln not in linked:
                    linked.append(str(ln))
        except Exception:
            pass
        return bundle_name, linked

    # In-memory bundles section is missing — fall back to the cached/disk
    # resolver. Safe-fallback policy matches _resolve_group_target_gpus:
    # snapshot/restore _services_config so _resolve_bundles() → _load_services_config()
    # cannot clobber a caller-provided (monkeypatched) value.
    snapshot = _services_config
    try:
        resolved = _resolve_bundles()
    except Exception:
        return bundle_name, []
    finally:
        try:
            globals()['_services_config'] = snapshot
        except Exception:
            pass
    if not resolved:
        return bundle_name, []
    linked: list[str] = []
    try:
        for ln in _get_linked_bundles(bundle_name, bundles=resolved) or []:
            if ln and ln not in linked:
                linked.append(str(ln))
    except Exception:
        pass
    return bundle_name, linked


def _resolve_group_target_gpus(target_group: str) -> list[str]:
    """Derive the full set of target GPUs for ``target_group`` from current config.

    Order of precedence:
      1. ``_group_reservations[group].requires_gpus`` (HTTP path; pure in-memory).
      2. The target bundle's primary GPU + every linked GPU via
         ``_collect_linked_gpus`` (config-driven; works on a fresh start).
         This step needs ``_resolve_bundles()``, which may read disk if
         ``_services_config`` does not yet carry a ``bundles`` section.

    The two sources are UNIONed (deduped, order preserved) so that a partial
    or stale reservation can NEVER hide the topology-derived linked GPUs.
    A partial reservation that only mentions the primary gpu must still
    surface the linked gpu through step 2 — otherwise the proactive loop
    would inspect only a subset of the topology and incorrectly conclude
    a valid linked component is an evictor.

    Returns an empty list iff neither source resolves — fail closed so the
    caller can choose to advertise a non-dispatch action.

    Safe-fallback policy: when the topology step needs ``_resolve_bundles()``
    and that resolver reaches disk via ``_load_services_config()``, the call
    MAY overwrite the module-level ``_services_config``. To preserve a
    caller-provided (e.g. monkeypatched) ``_services_config``, we snapshot
    and restore around the resolver call. The snapshot/restore is a no-op
    when ``_resolve_bundles`` only refreshes its own cache.
    """
    union: list[str] = []

    # 1) Reservation-driven path — pure memory. Hot path for the steady state.
    try:
        grp_res = _group_reservations.get(target_group, {}) or {}
    except Exception:
        grp_res = {}
    if isinstance(grp_res, dict) and grp_res.get('requires_gpus'):
        for gid in grp_res.get('requires_gpus') or []:
            if gid and gid not in union:
                union.append(gid)

    # 2) Config-driven path. Find the template's bundle in the in-memory
    # _services_config first to avoid triggering a disk load (which would
    # overwrite the caller's monkeypatched _services_config).
    templates = ((_services_config or {}).get('generation_templates') or {})
    bundle_name: str | None = None
    for tmpl in templates.values():
        if not isinstance(tmpl, dict):
            continue
        if tmpl.get('routing_group') == target_group:
            cand = tmpl.get('bundle')
            if cand and bundle_name is None:
                bundle_name = str(cand)
            elif cand and bundle_name != str(cand):
                # Ambiguous mapping: still return what we have so far
                # (the reservation-derived subset is better than nothing).
                return list(dict.fromkeys(union))
    if not bundle_name:
        return list(dict.fromkeys(union))

    # Look the bundle up in-memory first.
    in_memory_bundles = ((_services_config or {}).get('bundles') or {})
    bundle_cfg = in_memory_bundles.get(bundle_name)
    if bundle_cfg is None:
        # Snapshot _services_config so a disk-backed _resolve_bundles() does
        # not clobber a caller-provided (monkeypatched) value. _load_services_config()
        # inside _resolve_bundles() may promote a freshly-read config to the
        # module global; we restore it on the way out.
        snapshot = _services_config
        try:
            bundles = _resolve_bundles()
        except Exception:
            return list(dict.fromkeys(union))
        finally:
            # _resolve_bundles() may have mutated _services_config via
            # _load_services_config(); restore the caller's snapshot.
            try:
                # pylint: disable=global-statement
                globals()['_services_config'] = snapshot
            except Exception:
                pass
        bundle_cfg = bundles.get(bundle_name) or {}
        bundles_for_walk = bundles
    else:
        bundles_for_walk = in_memory_bundles
    try:
        for gid in _collect_linked_gpus(
            bundle_cfg, bundles_for_walk, bundle_name=bundle_name
        ):
            if gid and gid not in union:
                union.append(gid)
    except Exception:
        pass
    return list(dict.fromkeys(union))

def _scheduler_precheck_head_jobs(group: str) -> dict:
    if 'queue_engine' not in globals() or not queue_engine or not getattr(queue_engine, 'r', None):
        return {'group': group, 'decision': 'unknown', 'skipped_reason': 'no_queue_engine'}
    if 'job_tracker' not in globals() or not job_tracker:
        return {'group': group, 'decision': 'unknown', 'skipped_reason': 'no_job_tracker'}

    try:
        # Inspect the same logical stream set as the queue worker.  Lane mode
        # is opt-in, but the scheduler precheck must not silently ignore a
        # ready interactive job when it is enabled; the legacy stream remains
        # last for drain/replay compatibility.
        specs = (
            queue_engine._stream_specs(group, routing_group=group)
            if getattr(queue_engine, 'priority_lanes_enabled', False)
            else [(queue_engine._stream(group, routing_group=group), None)]
        )
        entries = []
        for stream, _lane in specs:
            entries.extend(queue_engine.r.xrange(stream, count=10))
    except Exception as e:
        return {'group': group, 'decision': 'unknown', 'skipped_reason': f'redis_error_or_missing: {e}'}

    if not entries:
        return {'group': group, 'decision': 'skip', 'skipped_reason': 'empty'}

    queued_job_ids = []
    saw_cancelled = False
    for entry_id, data in entries:
        job_id = data.get('job_id')
        if not job_id:
            continue

        job = job_tracker.get_job(job_id)
        if not job:
            continue

        # JobTracker.get_job may return either a Job-shaped object with a
        # `.status` attribute (legacy / live JobTracker) OR a plain mapping
        # (rehydrated payloads, see handle_get_job). A stream entry alone is
        # not dispatch authority: only a durable *queued* job may cause a
        # scheduler-owned bundle transition. Claimed/in-flight entries remain
        # in Redis Streams until terminal ACK and must not trigger a second
        # swap after the worker has already taken ownership.
        if isinstance(job, Mapping):
            status = job.get('status')
        else:
            status = getattr(job, 'status', None)

        if status == 'queued':
            queued_job_ids.append(str(job_id))
        elif status == 'cancelled':
            saw_cancelled = True

    if not queued_job_ids:
        reason = 'all_cancelled' if saw_cancelled else 'no_durable_queued_job'
        return {
            'group': group,
            'decision': 'skip',
            'skipped_reason': reason,
            'head_job_ids': [],
        }

    return {
        'group': group,
        'decision': 'proceed',
        'skipped_reason': 'none',
        'head_job_ids': queued_job_ids,
    }

def _scheduler_run_precheck(group: str) -> dict:
    """Run precheck and record it in the head_job_pre_checks ring buffer."""
    record = _scheduler_precheck_head_jobs(group)
    try:
        record['recorded_at'] = time.time()
    except Exception:
        pass
    _record_head_job_precheck(record)
    return record


def _refresh_phase3_scheduler_state() -> dict:
    """Refresh phase-3 demand/grace state without an observer request."""
    all_gpu_states = _get_all_gpu_states()
    generation_templates = (_services_config.get("generation_templates", {}) or {})
    groups = {}
    for service_name, service_cfg in (_services_config.get("services", {}) or {}).items():
        routing_group = service_cfg.get("routing_group") or service_name
        group = groups.setdefault(
            routing_group,
            {
                "type": "unknown",
                "priority": service_cfg.get("priority", 50),
                "queue_lag": 0,
            },
        )
        if service_cfg.get("type") == "llm_backend":
            group["type"] = "llm"
        elif service_cfg.get("type") == "generation_backend" or service_cfg.get("bundle"):
            group["type"] = "generation"

    if queue_engine is not None:
        for routing_group, group in groups.items():
            try:
                observation = _queue_depth_observation(
                    queue_engine, routing_group, routing_group
                )
                group["queue_lag"] = (
                    observation["depth"] if observation["known"] else 0
                )
                group["queue_lag_observed"] = observation["depth"]
                group["queue_lag_known"] = observation["known"]
                group["queue_lag_reason"] = observation["reason"]
            except Exception as exc:
                logger.debug("phase3 refresh queue-depth failed for %s: %s", routing_group, exc)

    return _get_phase3_scheduler_state(groups, all_gpu_states, generation_templates)


def _scheduler_evaluate_load(now=None) -> dict:
    global _last_decision
    if now is None:
        now = time.time()

    config = _phase3_scheduling_config()
    dry_run_mode = config.get('scheduler_dry_run_mode', True)
    decision = {
        'action': 'noop',
        'reason': 'default',
        'target_gpus': [],
        'head_job_ids': [],
        'decision_id': str(uuid.uuid4()),
        'decided_at': now,
        'group': None,
        'dry_run': dry_run_mode,
        'dispatch_performed': False
    }

    if not config.get('scheduler_owns_load'):
        decision['reason'] = 'scheduler_owns_load_false'
        _last_decision = decision.copy()
        _record_load_history(decision)
        return decision

    last_next = _last_next_decision.get('next_decision')

    if last_next == 'awaiting_grace':
        decision['action'] = 'awaiting_grace'
        decision['reason'] = 'awaiting_grace phase 3 state'
    elif 'queue_engine' not in globals() or not queue_engine or not _services_config:
        decision['action'] = 'awaiting_judging'
        decision['reason'] = 'no queue_engine or service-groups info'
    elif isinstance(last_next, str) and last_next.startswith('demand:'):
        group = last_next.split(':', 1)[1]
        decision['group'] = group
        precheck = _scheduler_run_precheck(group)
        head_job_ids = precheck.get('head_job_ids') or []
        if isinstance(head_job_ids, (list, tuple)):
            decision['head_job_ids'] = [
                str(job_id) for job_id in head_job_ids
                if isinstance(job_id, str) and job_id
            ]
        if (
            precheck.get('skipped_reason') in (
                'empty', 'all_cancelled', 'no_durable_queued_job'
            )
            or not decision['head_job_ids']
        ):
            decision['action'] = 'pre_load_failed_skip'
            decision['reason'] = (
                'precheck has no durable queued head job: '
                f"{precheck.get('skipped_reason', 'missing_head_job_ids')}"
            )
        elif _active_group_still_draining(group):
            decision['action'] = 'hold_drain'
            decision['reason'] = 'active group draining; defer load'
        else:
            target_gpus = list(_resolve_group_target_gpus(group) or [])
            # If we couldn't derive ANY target GPUs from config, fail closed:
            # do not advertise a demand_load the dispatcher can't actually act
            # on. (Advisory telemetry only — the authoritative atomic path is
            # still _evict_then_load_bundle, which validates targets itself.)
            if not target_gpus:
                decision['action'] = 'insufficient_visibility'
                decision['reason'] = (
                    f"unreadable target_gpus for group {group!r}: "
                    "no template/bundle resolution available"
                )
                decision['requires_eviction'] = False
            elif group in {'comfyui-gen', 'image-gen'}:
                decision['action'] = 'dual_gpu_load'
                decision['target_gpus'] = target_gpus
                decision['reason'] = 'demand load for dual gpu'
                try:
                    decision['requires_eviction'] = _target_gpus_hold_warm_bundle(group)
                except _TargetStateUnreadable as exc:
                    decision['action'] = 'insufficient_visibility'
                    decision['reason'] = (
                        f"unreadable target state for group {group!r}: "
                        f"gpu {exc.gpu_id!r}"
                    )
                    decision['requires_eviction'] = False
            else:
                decision['action'] = 'demand_load'
                decision['target_gpus'] = target_gpus
                decision['reason'] = 'demand load'
                try:
                    decision['requires_eviction'] = _target_gpus_hold_warm_bundle(group)
                except _TargetStateUnreadable as exc:
                    decision['action'] = 'insufficient_visibility'
                    decision['reason'] = (
                        f"unreadable target state for group {group!r}: "
                        f"gpu {exc.gpu_id!r}"
                    )
                    decision['requires_eviction'] = False
    elif last_next == 'idle':
        idle_preferred = _last_next_decision.get('idle_preferred', False)
        if idle_preferred:
            decision['action'] = 'idle_load'
            decision['reason'] = 'idle_preferred'
            # This remains dry-run telemetry, but it must identify the
            # configured per-GPU idle bundle scope. An empty target list made
            # restore/accounting evidence ambiguous during dual-GPU recovery.
            idle_services = ((_services_config or {}).get('scheduling') or {}).get(
                'idle_services', {}
            ) or {}
            decision['target_gpus'] = sorted(
                str(gpu_id) for gpu_id in idle_services if gpu_id
            )
            if not decision['target_gpus']:
                decision['target_gpus'] = sorted(
                    str(gpu_id) for gpu_id in _get_all_gpu_states() if gpu_id
                )
        else:
            decision['action'] = 'noop'
            decision['reason'] = 'idle noop'

    logger.info(f"evaluator.decision: {json.dumps(decision)}")
    _last_decision = decision.copy()
    _record_load_history(decision)
    return decision


def _resolve_scheduler_bundle_for_group(group: str) -> tuple[str | None, int | None, str | None]:
    """Resolve exactly one configured generation bundle for a selected group."""
    templates = (_services_config or {}).get("generation_templates", {}) or {}
    bundles = []
    for template in templates.values():
        if not isinstance(template, dict) or template.get("routing_group") != group:
            continue
        bundle = template.get("bundle")
        if bundle and bundle not in bundles:
            bundles.append(str(bundle))
    if len(bundles) != 1:
        if not bundles:
            return None, None, "no_configured_bundle_for_group"
        return None, None, "ambiguous_configured_bundles_for_group"
    return bundles[0], _service_group_priority(group, {}, templates), None


async def _dispatch_scheduler_decision(decision: dict) -> dict:
    """Execute one demand decision only behind three independent live gates."""
    result = dict(decision)
    result["dispatch_performed"] = False
    if result.get("action") not in {"demand_load", "dual_gpu_load"}:
        result["dispatch_reason"] = "non_dispatch_action"
        return result

    config = _phase3_scheduling_config()
    if not config.get("scheduler_owns_load"):
        result["dispatch_reason"] = "scheduler_owns_load_false"
        return result
    if config.get("scheduler_dry_run_mode", True):
        result["dispatch_reason"] = "scheduler_dry_run_mode"
        return result
    if not config.get("proactive_scheduling_enabled", False):
        result["dispatch_reason"] = "proactive_scheduling_disabled"
        return result

    head_job_ids = result.get("head_job_ids")
    if (
        not isinstance(head_job_ids, list)
        or not any(isinstance(job_id, str) and job_id for job_id in head_job_ids)
    ):
        result["dispatch_reason"] = "no_durable_head_job"
        return result

    group = result.get("group")
    if not isinstance(group, str) or not group:
        result["dispatch_reason"] = "missing_selected_group"
        return result
    bundle, priority, resolution_error = _resolve_scheduler_bundle_for_group(group)
    if resolution_error or bundle is None or priority is None:
        result["dispatch_reason"] = resolution_error or "invalid_bundle_resolution"
        return result

    result["bundle"] = bundle
    try:
        loaded = await _evict_then_load_bundle(
            bundle,
            reason=f"scheduler:{group}",
            priority=priority,
        )
    except Exception as exc:
        result["dispatch_reason"] = f"bundle_load_raised:{type(exc).__name__}"
        result["dispatch_error"] = str(exc)[:300]
        return result
    if not loaded:
        result["dispatch_reason"] = "bundle_load_failed"
        return result

    result["dispatch_performed"] = True
    result["dispatch_reason"] = "bundle_loaded"
    return result


async def _proactive_dispatch_loop():
    """Evaluate demand continuously and dispatch only behind the live triple gate.

    In dry-run mode this records would-have decisions. A real bundle transition
    requires scheduler ownership, non-dry-run configuration, and explicit
    proactive scheduling enablement.
    """
    global _last_decision
    logger.info(
        "Proactive dispatch startup grace: waiting %.1fs before first decision",
        GPU_PROBE_STARTUP_GRACE_S,
    )
    await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
    try:
        import time as _time
        _proactive_dispatch_state["last_iteration_at"] = _time.time()
    except Exception as e:
        logger.warning(f"proactive_dispatch_loop import failed: {e}")
        return
    while True:
        try:
            _proactive_dispatch_state["iteration_count"] += 1
            _proactive_dispatch_state["last_iteration_at"] = _time.time()
            # Read phase 3 scheduling config (returns the env-var-aware dict)
            config = _phase3_scheduling_config()
            live_dispatch_enabled = bool(
                config.get("scheduler_owns_load")
                and not config.get("scheduler_dry_run_mode", True)
                and config.get("proactive_scheduling_enabled", False)
            )
            _proactive_dispatch_state["dry_run"] = not live_dispatch_enabled
            # Skip if scheduler is not the owner
            if not config.get("scheduler_owns_load"):
                await asyncio.sleep(_PROACTIVE_LOOP_INTERVAL_SEC)
                continue
            # Get a fresh decision
            now = _time.time()
            _refresh_phase3_scheduler_state()
            decision = _scheduler_evaluate_load(now)
            if not isinstance(decision, dict):
                await asyncio.sleep(_PROACTIVE_LOOP_INTERVAL_SEC)
                continue
            action = decision.get("action", "noop")
            # Classify and update counters
            _proactive_dispatch_state["last_decision"] = decision
            # The 10-second same-action spacing suppresses **dry-run telemetry
            # only**. Live dispatch fires every iteration regardless of the
            # previous decision, because _evict_then_load_bundle is the
            # authoritative atomic path and idempotency is enforced there
            # (priority-aware precheck + readiness probe). See
            # _should_suppress_proactive_spacing.
            global _PROACTIVE_LAST_DECISION
            last_recorded_at = _proactive_dispatch_state.get("last_action_recorded_at", 0.0)
            last_decision_action = (
                _PROACTIVE_LAST_DECISION.get("action")
                if isinstance(_PROACTIVE_LAST_DECISION, dict)
                else None
            )
            suppress_telemetry = _should_suppress_proactive_spacing(
                now=now,
                action=action,
                last_action_recorded_at=last_recorded_at,
                last_decision_action=last_decision_action,
                dry_run=not live_dispatch_enabled,
            )
            if suppress_telemetry:
                _proactive_dispatch_state["spaced_actions"] += 1
            else:
                # Record the would-have-done
                if action in ("demand_load", "dual_gpu_load", "idle_load"):
                    _proactive_dispatch_state["would_have_loaded"] += 1
                elif action == "evict_only":
                    _proactive_dispatch_state["would_have_evicted"] += 1
                elif action in ("hold_drain", "awaiting_grace"):
                    _proactive_dispatch_state["would_have_held"] += 1
                _PROACTIVE_LAST_DECISION = decision
                _proactive_dispatch_state["last_action_recorded_at"] = now
            if live_dispatch_enabled:
                dispatched = await _dispatch_scheduler_decision(decision)
                _proactive_dispatch_state["last_decision"] = dispatched
                _last_decision = dispatched.copy()
                _record_load_history(dispatched)
                if dispatched.get("dispatch_performed"):
                    _proactive_dispatch_state["dispatched"] += 1
                elif dispatched.get("action") in {"demand_load", "dual_gpu_load"}:
                    _proactive_dispatch_state["dispatch_failures"] += 1
        except Exception as e:
            _proactive_dispatch_state["errors"].append({
                "at": _time.time(),
                "error": str(e)[:200]
            })
            # Cap errors list at 10
            if len(_proactive_dispatch_state["errors"]) > 10:
                _proactive_dispatch_state["errors"] = _proactive_dispatch_state["errors"][-10:]
            logger.warning(f"proactive_dispatch_loop error: {e}")
        await asyncio.sleep(_PROACTIVE_LOOP_INTERVAL_SEC)


def _should_suppress_proactive_spacing(
    *,
    now: float,
    action: str,
    last_action_recorded_at: float,
    last_decision_action: str | None,
    dry_run: bool,
) -> bool:
    """Decide whether the proactive loop should suppress dry-run telemetry.

    Returns True iff the previous decision was the same action AND it was
    recorded less than ``_PROACTIVE_SPACING_WINDOW_SEC`` seconds ago AND we
    are in dry-run mode. Live dispatch is NEVER suppressed by this rule —
    see the docstring on ``_proactive_dispatch_loop`` for why.
    """
    if not dry_run:
        return False
    if last_decision_action is None:
        return False
    if action != last_decision_action:
        return False
    if (now - last_action_recorded_at) >= _PROACTIVE_SPACING_WINDOW_SEC:
        return False
    return True

# --- Phase 5 Reservation Skeleton ---
_gpu_reservations = {}
_group_reservations = {}
_last_reservation_change = None
_reservation_history = []
_ingress_blocked_by_reservation = 0
_ingress_blocked_by_reservation_by_group = {}
_reservation_config_warnings = []

def _phase5_reservation_config() -> dict:
    root = _services_config or {}
    res_cfg = root.get('reservations', {}) or {}
    explicit_path = root.get('gpu_reservations_path') or res_cfg.get('gpu_reservations_path')
    path = explicit_path or '/run/gpu-manager/reservations.json'
    defaults = res_cfg.get('reservation_defaults', {}) or {}
    persistence_enabled = bool(explicit_path) or bool(res_cfg.get('enabled') or res_cfg.get('persistence_enabled'))
    return {
        'gpu_reservations_path': path,
        'reservation_defaults': defaults,
        'persistence_enabled': persistence_enabled
    }

def _derive_group_reservations(groups=None, generation_templates=None) -> dict:
    global _reservation_config_warnings
    warnings = []
    derived = {}
    if groups is None:
        groups = {}
    if generation_templates is None:
        generation_templates = {}
    # Qualification/draft templates remain visible in the endpoint's raw
    # inventory, but they must not create operational GPU reservations or
    # warnings that look like active queue ownership.  Services are filtered
    # separately by _is_queue_consumer_service().
    generation_templates = {
        name: template
        for name, template in generation_templates.items()
        if isinstance(template, Mapping)
        and _service_is_publicly_qualified(template)
        and not is_retired_minimax_comfyui_template(template)
    }

    routing_groups_config = {}
    try:
        routing_groups_config = _services_config.get('routing_groups', {}) or {}
    except Exception:
        routing_groups_config = {}

    all_groups = set(list(groups.keys()) + list(generation_templates.keys()) + list(routing_groups_config.keys()))
    for t in generation_templates.values():
        if t.get('routing_group'):
            all_groups.add(t['routing_group'])

    krea_like_groups = {'comfyui-gen', 'image', 'image-edit-krea2'}
    for grp_name in sorted(all_groups):
        explicit = routing_groups_config.get(grp_name, {}) or {}
        requires_gpus = list(dict.fromkeys(explicit.get('requires_gpus', []) or []))
        mode = explicit.get('gpu_reservation_mode', explicit.get('mode', 'exclusive'))
        hold_s = explicit.get('gpu_reservation_hold_s', explicit.get('hold_s', 120))
        priority = _service_group_priority(grp_name, groups, generation_templates)
        owner = explicit.get('owner')
        description = explicit.get('description')

        if 'priority' in explicit:
            priority = _coerce_group_priority(explicit.get('priority'), allow_cpu_fallback=True)

        if not requires_gpus:
            # infer from template bundle
            tmpl = generation_templates.get(grp_name)
            if not tmpl:
                for t in generation_templates.values():
                    if t.get('routing_group') == grp_name:
                        tmpl = t
                        break
            if not tmpl:
                tmpl = {}
            bundle = tmpl.get('bundle')
            if bundle:
                try:
                    bundle_map = _resolve_bundles()
                    res = bundle_map.get(bundle)
                    if res and res.get('gpu_id'):
                        requires_gpus.append(res['gpu_id'])
                        try:
                            linked = _collect_linked_gpus(res, bundle_map)
                            for lg in linked:
                                if lg not in requires_gpus:
                                    requires_gpus.append(lg)
                        except Exception:
                            pass
                except Exception:
                    pass
            basename = str(tmpl.get('workflow_template', '')).split('/')[-1]
            if ('krea2_multigpu' in basename or 'multigpu' in basename) and len(requires_gpus) <= 1:
                warnings.append(f"group '{grp_name}': inferred single GPU but template suggests multigpu")
            if 'image-edit-krea2' in str(tmpl.get('workflow_template', '')) and len(requires_gpus) <= 1:
                warnings.append(f"group '{grp_name}': ambiguous/missing routing_group config; image-edit-krea2 requires both gpu_primary and gpu_secondary but inferred only {requires_gpus}")

        if grp_name in krea_like_groups:
            if grp_name not in routing_groups_config:
                warnings.append(f"group '{grp_name}': missing routing_groups[{grp_name}] config; inferred {requires_gpus or 'no GPUs'}")
            if len(requires_gpus) <= 1:
                warnings.append(f"group '{grp_name}': configured for only {requires_gpus[0] if requires_gpus else 'no GPU'}, but known Krea path needs both gpu_primary and gpu_secondary")

        if grp_name in routing_groups_config and 'priority' not in explicit:
            warnings.append(f"group '{grp_name}': routing_groups entry missing priority; derived ownership priority {priority}")

        derived[grp_name] = {
            'requires_gpus': requires_gpus,
            'mode': mode,
            'hold_s': hold_s,
            'priority': priority,
        }
        if owner is not None:
            derived[grp_name]['owner'] = owner
        if description is not None:
            derived[grp_name]['description'] = description

    _reservation_config_warnings = warnings
    return derived

def _validate_reservation_config(group_reservations) -> list:
    warnings = []
    known_gpus = []
    try:
        known_gpus = list(_services_config.get('gpu_devices', {}).keys())
    except Exception:
        pass

    for grp, res in group_reservations.items():
        if len(res.get('requires_gpus', [])) > 1:
            try:
                tmpl = _services_config.get('generation_templates', {}).get(grp, {})
                bundle = tmpl.get('bundle')
                if bundle:
                    b_info = _resolve_bundles().get(bundle, {})
                    b_gpu = b_info.get('gpu_id')
                    try:
                        linked = _collect_linked_gpus(b_info, _resolve_bundles()) if b_info else []
                    except Exception:
                        linked = []
                    evidence = [b_gpu] + list(linked)
                    if not any(g in evidence for g in res['requires_gpus']):
                        warnings.append(f"group '{grp}': requires_gpus > 1 but no bundle/link evidence inferred")
            except Exception:
                pass

        if grp in {'comfyui-gen', 'image', 'image-edit-krea2'} and set(res.get('requires_gpus', [])) <= {'gpu_primary'}:
            warnings.append(f"group '{grp}': configured for only gpu_primary, but known Krea path needs both gpu_primary and gpu_secondary")

        if known_gpus:
            for g in res.get('requires_gpus', []):
                if g not in known_gpus:
                    warnings.append(f"group '{grp}': unknown gpu_id '{g}' in requires_gpus")

    try:
        config = _phase3_scheduling_config()
        if config.get('scheduler_owns_load'):
            templates = _services_config.get('generation_templates', {})
            for name, tmpl in templates.items():
                if tmpl.get('evict_first'):
                    warnings.append(f"template '{name}': evict_first is forbidden when scheduler_owns_load=true (runtime ignores it; remove from config)")
    except Exception:
        pass

    return warnings

def _record_reservation_change(action, group, token, gpu_ids, **kwargs):
    global _last_reservation_change
    now = time.time()
    record = {
        'timestamp': now,
        'action': action,
        'group': group,
        'token': token,
        'gpu_ids': gpu_ids
    }
    record.update(kwargs)
    _reservation_history.insert(0, record)
    while len(_reservation_history) > 50:
        _reservation_history.pop()

    _last_reservation_change = {
        'group': group,
        'gpu_ids': gpu_ids,
        'action': action,
        'token': token,
        'at': now
    }
    if 'reason' in kwargs:
        _last_reservation_change['reason'] = kwargs['reason']
    if 'mode' in kwargs:
        _last_reservation_change['mode'] = kwargs['mode']
    if 'hold_s' in kwargs:
        _last_reservation_change['hold_s'] = kwargs['hold_s']

def reserve_gpus(group, gpu_ids, token=None, mode='exclusive', hold_s=120) -> tuple:
    if not token:
        token = str(uuid.uuid4())
    now = time.time()

    # check conflict
    for gid in gpu_ids:
        if gid in _gpu_reservations:
            res = _gpu_reservations[gid]
            if res['group'] != group or res['token'] != token:
                if res['hold_expires_at'] > now:
                    return False, {'conflict_gpu': gid, 'reserved_by': res['group']}

    # success
    for gid in gpu_ids:
        _gpu_reservations[gid] = {
            'group': group,
            'token': token,
            'reserved_at': now,
            'hold_expires_at': now + hold_s,
            'mode': mode
        }

    _record_reservation_change('reserve', group, token, gpu_ids, mode=mode, hold_s=hold_s)
    _persist_reservations()
    return True, {'token': token, 'expires_at': now + hold_s}

def release_gpus(group, token, reason='release') -> tuple:
    released = []
    for gid, res in list(_gpu_reservations.items()):
        if res['group'] == group and res['token'] == token:
            del _gpu_reservations[gid]
            released.append(gid)

    if released:
        _record_reservation_change(reason, group, token, released)
        _persist_reservations()
        return True, {'released': released}
    return False, {'reason': 'not_found_or_mismatch'}

def expire_reservations(now=None) -> list:
    if now is None:
        now = time.time()
    expired = []
    for gid, res in list(_gpu_reservations.items()):
        if res['hold_expires_at'] <= now:
            expired.append((gid, res))
            del _gpu_reservations[gid]

    if expired:
        for gid, res in expired:
            _record_reservation_change('expire', res['group'], res['token'], [gid])
        _persist_reservations()
    return [e[0] for e in expired]

def _reservation_persistence_path() -> str:
    return _phase5_reservation_config().get('gpu_reservations_path', '/run/gpu-manager/reservations.json')

def _persist_reservations() -> dict:
    path = _reservation_persistence_path()
    config = _phase5_reservation_config()
    # Explicitly check if persistence is configured
    if not config.get('persistence_enabled'):
        return {'ok': False, 'reason': 'not_enabled', 'path': path}

    try:
        import tempfile
        import os
        import json

        data = {
            'reservations': _gpu_reservations,
            'last_change': _last_reservation_change,
            'timestamp': time.time()
        }

        dir_name = os.path.dirname(path)
        if not os.path.exists(dir_name):
            os.makedirs(dir_name, exist_ok=True)

        fd, temp_path = tempfile.mkstemp(dir=dir_name, prefix='reservations_', suffix='.json.tmp')
        with os.fdopen(fd, 'w') as f:
            json.dump(data, f)
            f.flush()
            os.fsync(f.fileno())

        if os.path.exists(path):
            try:
                os.replace(path, path + '.bak')
            except Exception:
                pass
        os.replace(temp_path, path)
        return {'ok': True, 'path': path}
    except Exception as e:
        return {'ok': False, 'reason': 'error', 'details': str(e)}

def _record_ingress_blocked_by_reservation(group):
    global _ingress_blocked_by_reservation
    _ingress_blocked_by_reservation += 1
    _ingress_blocked_by_reservation_by_group[group] = _ingress_blocked_by_reservation_by_group.get(group, 0) + 1

