# ── Format Converter (LEAN input, JSON output) ─────────────────────
# Phase 5.2: per-service format gate. The previous single global
# `_fmt_converter` singleton is gone — conversion is now decided
# per-job by reading the service entry's `input_body_format` and
# `output_body_format` from services.json. The dispatch table
# (BODY_FORMATS, _PASSTHROUGH_*) and the helpers
# (convert_request_for_format / convert_response_for_format) live in
# format_converter.py — see the "REGISTER NEW FORMAT HERE" comment
# block there for the extension contract.
#
# The following names are bound at module-load either by the import
# below or by the stub block in the except branch — WorkerPool.__init__
# and the worker loop reference them unconditionally.
_FORMAT_CONVERTER_STUB_INPUT  = frozenset({"raw_json", "passthrough"})
_FORMAT_CONVERTER_STUB_OUTPUT = frozenset({"raw_bytes", "raw_json_out"})
try:
    from format_converter import (
        FormatConverter,
        BODY_FORMATS,
        DEFAULT_INPUT_BY_RGT,
        DEFAULT_OUTPUT_BY_RGT,
        _PASSTHROUGH_INPUT,
        _PASSTHROUGH_OUTPUT,
        resolve_input_format,
        resolve_output_format,
        convert_request_for_format,
        convert_response_for_format,
    )
    _FMT_AVAILABLE = True
    logger_init_extra = "Format converter: per-service gate ENABLED (dispatch in format_converter.py)"
except ImportError as e:
    _FMT_AVAILABLE = False
    _fmt_import_error = str(e)
    logger_init_extra = f"Format converter: NOT AVAILABLE — {_fmt_import_error}"
    # Module-level fallbacks (WorkerPool reads these directly).
    _PASSTHROUGH_INPUT  = _FORMAT_CONVERTER_STUB_INPUT
    _PASSTHROUGH_OUTPUT = _FORMAT_CONVERTER_STUB_OUTPUT
    DEFAULT_INPUT_BY_RGT  = {}
    DEFAULT_OUTPUT_BY_RGT = {}
    BODY_FORMATS = ()
    # Stubs so the worker loop can call the helpers unconditionally.
    def resolve_input_format(*_a, **_kw):  return "raw_json"
    def resolve_output_format(*_a, **_kw): return "raw_bytes"
    def convert_request_for_format(_fmt, body, *_a, **_kw):
        return body if isinstance(body, bytes) else body.encode("utf-8")
    def convert_response_for_format(_fmt, body, *_a, **_kw):
        return body.decode("utf-8", errors="replace") if isinstance(body, (bytes, bytearray)) else body

