# ===================================================================
# Queue system helpers — health check, reconciliation, crash recovery
# ===================================================================

def _service_health_check(service_name: str) -> bool:
    """Quick synchronous health check for a service.

    Honours the per-service ``health_path`` advertised by services.json
    (e.g. stable-diffusion.cpp uses ``"/"``, comfyui/gemma use
    ``"/health"``). When the HTTP probe fails or returns non-2xx, falls
    back to a raw TCP connect — mirroring ``WorkerSupervisor._check_health``
    so the periodic reconciler and the EventBus-driven supervisor agree
    on what "healthy" means for a backend whose port is open but whose
    ``/health`` route is missing or 404s (sd-server root-only, etc.).

    Used by CapacityTracker on startup to validate restored counters.
    """
    import socket
    import urllib.request
    svc_cfg = _services_config.get("services", {}).get(service_name, {})
    port = svc_cfg.get("port")
    if not port:
        return False
    health_path = svc_cfg.get("health_path") or "/health"
    try:
        req = urllib.request.Request(f"http://127.0.0.1:{port}{health_path}")
        resp = urllib.request.urlopen(req, timeout=2)
        if resp.status == 200:
            return True
    except Exception:
        pass
    # TCP fallback: a successful connect is sufficient evidence the port
    # is up. Matches WorkerSupervisor._check_health(fallback_tcp=True).
    try:
        with socket.create_connection(("127.0.0.1", int(port)), timeout=2):
            return True
    except Exception:
        return False


def _reconcile_stale_queues() -> int:
    """Flush stale queue entries and reset counters on startup.
    Called once during create_app(). Returns number of entries flushed."""
    if not queue_engine:
        return 0
    flushed = 0
    services = _services_config.get("services", {})
    for svc_name, svc_cfg in services.items():
        if svc_cfg.get("type") != "llm_backend" or not svc_cfg.get("enabled"):
            continue
        if not _service_health_check(svc_name):
            count = queue_engine.purge(svc_name)
            flushed += count
            if count:
                logger.warning("Reconcile: flushed %d stale entries from %s (service DOWN)",
                               count, svc_name)
            # Reset capacity counters for DOWN services
            if capacity_tracker:
                capacity_tracker._active[svc_name] = 0
                capacity_tracker._pending[svc_name] = 0
                capacity_tracker._persist_to_redis(svc_name)
    return flushed


def _crash_recovery() -> int:
    """Count unresolved jobs; startup PEL reconciliation handles recovery."""
    if not job_tracker:
        return 0
    unresolved = 0
    services = _services_config.get("services", {})
    for svc_name in services:
        for status in ["in_flight", "remote"]:
            try:
                jobs = job_tracker.get_jobs_by_status(svc_name, status)
                unresolved += len(jobs)
                if jobs:
                    logger.info(
                        "Crash recovery: preserving %d %s jobs for async PEL reconciliation on %s",
                        len(jobs), status, svc_name,
                    )
            except Exception:
                pass
    return unresolved


def _get_idle_service_name(gpu_id: str | None = None) -> str:
    """Get the configured idle/default LLM service name from scheduling config.

    If gpu_id is provided, looks up idle_services[gpu_id] first, then falls
    back to the global idle_service.  When gpu_id is None (legacy callers),
    returns the global idle_service.
    """
    config = _load_services_config()
    scheduling = config.get("scheduling", {})
    idle_svc = ""

    # Per-GPU idle services take priority
    if gpu_id:
        idle_services = scheduling.get("idle_services", {})
        idle_svc = idle_services.get(gpu_id, "")

    # Fall back to global idle_service
    if not idle_svc:
        idle_svc = scheduling.get("idle_service", "")

    if idle_svc:
        svc = config.get("services", {}).get(idle_svc, {})
        unit = svc.get("systemd_unit", "")
        if unit:
            return unit
    return LLM_SERVICE_NAME_DEFAULT


def _configured_llm_health_target(config: Mapping[str, Any] | None = None) -> tuple[str, str] | None:
    """Resolve an explicit registry-owned LLM health target.

    The controller must not probe an environment default when the registry has
    no idle service.  A target is valid only when its service is enabled and
    supplies a bounded port and path.
    """
    selected = _load_services_config() if config is None else config
    scheduling = selected.get("scheduling", {}) or {}
    services = selected.get("services", {}) or {}
    candidates: list[str] = []
    global_idle = scheduling.get("idle_service")
    if isinstance(global_idle, str) and global_idle:
        candidates.append(global_idle)
    per_gpu = scheduling.get("idle_services", {}) or {}
    if isinstance(per_gpu, Mapping):
        candidates.extend(
            name for name in per_gpu.values()
            if isinstance(name, str) and name
        )
    for service_name in dict.fromkeys(candidates):
        service = services.get(service_name)
        if not isinstance(service, Mapping) or service.get("enabled") is not True:
            continue
        port = service.get("port")
        health_path = service.get("health_path") or "/health"
        if type(port) is not int or not (1 <= port <= 65535):
            continue
        if (
            not isinstance(health_path, str)
            or not health_path.startswith("/")
            or "//" in health_path
            or len(health_path) > 256
            or any(ord(char) < 0x20 or ord(char) == 0x7F for char in health_path)
        ):
            continue
        return f"http://127.0.0.1:{port}{health_path}", service_name
    return None


def _get_loaded_runtime_snapshot() -> dict:
    """Describe bundles/services actually tracked as loaded at runtime.

    ``_get_idle_service_name()`` resolves the configured idle/default service;
    it is not evidence that that unit is currently loaded.  This snapshot is
    derived from the authoritative per-GPU bundle registry so health/state
    consumers can distinguish configuration from runtime occupancy.
    """
    config = _load_services_config()
    bundles = config.get("bundles", {}) or {}
    services = config.get("services", {}) or {}
    loaded_bundles: list[dict] = []
    loaded_service_units: set[str] = set()

    for gpu_id, gpu_state in globals().get("_gpu_states", {}).items():
        bundle_names = list(dict.fromkeys(gpu_state.loaded_bundles or []))
        if gpu_state.loaded_bundle and gpu_state.loaded_bundle not in bundle_names:
            bundle_names.append(gpu_state.loaded_bundle)
        for bundle_name in bundle_names:
            bundle_cfg = bundles.get(bundle_name, {}) or {}
            member_services = []
            for service_name in bundle_cfg.get("services", []) or []:
                service_cfg = services.get(service_name, {}) or {}
                unit = service_cfg.get("systemd_unit") or service_name
                member_services.append({
                    "name": service_name,
                    "systemd_unit": unit,
                })
                loaded_service_units.add(unit)
            loaded_bundles.append({
                "gpu_id": gpu_id,
                "bundle": bundle_name,
                "services": member_services,
            })

    return {
        "bundles": loaded_bundles,
        "services": sorted(loaded_service_units),
    }


def _canonical_runtime_semantics(readiness: dict | None = None) -> dict:
    """Build the single runtime-semantics envelope from current manager facts."""
    config = _load_services_config()
    scheduling = config.get("scheduling", {}) or {}
    services = config.get("services", {}) or {}
    runtime = _get_loaded_runtime_snapshot()

    def _unit(service_name: str) -> str:
        cfg = services.get(service_name, {}) or {}
        return str(cfg.get("systemd_unit") or service_name or "")

    idle_by_gpu = {
        str(gpu_id): _unit(str(service_name))
        for gpu_id, service_name in (scheduling.get("idle_services", {}) or {}).items()
        if service_name
    }
    enabled_units = [
        _unit(name) for name, cfg in services.items() if cfg.get("enabled", False)
    ]
    disabled_units = [
        _unit(name) for name, cfg in services.items() if not cfg.get("enabled", False)
    ]
    states = list(globals().get("_gpu_states", {}).values())
    manager = globals().get("vram")
    gpu_state = getattr(getattr(manager, "gpu_state", None), "value", "")
    pinned = getattr(globals().get("scheduler"), "_pinned_service", "") or scheduling.get(
        "pinned_service", ""
    )
    route_available = bool((readiness or {}).get("available", False))
    snapshot = snapshot_from_manager(
        configured_idle_service=_get_idle_service_name(),
        configured_idle_services_by_gpu=idle_by_gpu,
        pinned_service=str(pinned or ""),
        maintenance_mode=_maintenance_mode_enabled(scheduling),
        enabled_service_names=enabled_units,
        disabled_service_names=disabled_units,
        loaded_runtime_services=runtime["services"],
        loaded_runtime_bundles=runtime["bundles"],
        gpu_state_value=str(gpu_state or ""),
        llm_evicted=bool(getattr(manager, "_llm_evicted", False)),
        queue_active_jobs=int(getattr(globals().get("llm"), "active_requests", 0) or 0),
        queue_pending_jobs=int(getattr(globals().get("llm"), "queued_requests", 0) or 0),
        any_bundle_draining=any(bool(getattr(state, "draining", False)) for state in states),
        any_bundle_loading=any(bool(getattr(state, "loading", False)) for state in states),
        any_bundle_restoring=any(bool(getattr(state, "restoring", False)) for state in states),
        any_bundle_evicting=any(bool(getattr(state, "evicting", False)) for state in states),
        restore_operation_active=bool(
            getattr(globals().get("scheduler"), "_restoring", False)
        ),
        llm_route_available=route_available,
        cpu_fallback_available="combined_router" in (readiness or {}).get(
            "availability_sources", []
        ),
        generation_route_available=bool(runtime["bundles"]),
        observed_at=time.time(),
    )
    return reduce_semantics(snapshot)


def _apply_runtime_semantics(payload: dict, readiness: dict | None = None) -> dict:
    """Attach canonical semantics and stable compatibility projections."""
    envelope = _canonical_runtime_semantics(readiness)
    payload["runtime_semantics"] = envelope
    payload["runtime_mode"] = envelope["runtime_mode"]
    payload["configured_idle_service"] = envelope["configured_intent"][
        "configured_idle_service"
    ]
    payload["loaded_runtime_services"] = envelope["observed_runtime"][
        "loaded_runtime_services"
    ]
    payload["loaded_runtime_bundles"] = envelope["observed_runtime"][
        "loaded_runtime_bundles"
    ]
    payload["intentionally_idle"] = envelope["intentionally_idle"]
    payload["contradictions"] = envelope["contradictions"]
    payload["blocked_reasons"] = envelope["blocked_reasons"]
    payload["active_llm_route"] = envelope["route_availability"]["active_llm_route"]
    payload["observed_at"] = envelope["observed_at"]
    return payload


def _get_idle_service_port(gpu_id: str | None = None) -> int:
    """Get the port for the configured idle/default LLM service.

    If gpu_id is provided, resolves through per-GPU idle_services first.
    """
    config = _load_services_config()
    scheduling = config.get("scheduling", {})
    idle_svc = ""

    if gpu_id:
        idle_services = scheduling.get("idle_services", {})
        idle_svc = idle_services.get(gpu_id, "")

    if not idle_svc:
        idle_svc = scheduling.get("idle_service", "")

    if idle_svc:
        svc = config.get("services", {}).get(idle_svc, {})
        return svc.get("port", 8092)
    return 8092


def _get_all_idle_service_names() -> list[str]:
    """Return all configured idle service systemd unit names (per-GPU + global fallback).

    Deduplicates so the same service isn't listed twice.
    """
    config = _load_services_config()
    scheduling = config.get("scheduling", {})
    services = config.get("services", {})
    units: list[str] = []
    seen: set[str] = set()

    # Per-GPU idle services
    for _gpu_id, svc_name in scheduling.get("idle_services", {}).items():
        svc = services.get(svc_name, {})
        unit = svc.get("systemd_unit", "")
        if unit and unit not in seen:
            units.append(unit)
            seen.add(unit)

    # Global fallback
    global_svc = scheduling.get("idle_service", "")
    if global_svc:
        svc = services.get(global_svc, {})
        unit = svc.get("systemd_unit", "")
        if unit and unit not in seen:
            units.append(unit)
            seen.add(unit)

    return units


def _is_intentionally_idle_service(name: str, svc: dict) -> bool:
    """Determine if a service is expected to be off (down is normal for it).

    Returns True if the service is enabled, but is NOT one of the designated
    idle LLM services (LLM-Primary, LLM-Secondary, etc.) that must always be loaded.
    These are generation backends (comfyui, acestep, sulphur-*,
    gemma-vision, etc.) which should be 'intentionally_idle' rather than 'down'
    when not loaded. Disabled services return False.
    """
    if not svc.get("enabled", False):
        return False
    if _services_config is None:
        return False
    idle_map = _services_config.get("scheduling", {}).get("idle_services", {}) or {}
    # idle_map is {gpu_id: service_name}; collect the service names
    idle_names = set()
    if isinstance(idle_map, dict):
        for v in idle_map.values():
            if isinstance(v, str) and v:
                idle_names.add(v)
    # Also include the global idle_service fallback
    global_idle = _services_config.get("scheduling", {}).get("idle_service", "")
    if isinstance(global_idle, str) and global_idle:
        idle_names.add(global_idle)
    if name in idle_names:
        return False  # Must be on
    return True


def _get_all_idle_services() -> list[dict]:
    """Return list of {gpu_id, service_name, systemd_unit, port} for all configured idle services.

    Uses gpu_id=None for the global idle_service fallback.
    """
    config = _load_services_config()
    scheduling = config.get("scheduling", {})
    services = config.get("services", {})
    result: list[dict] = []
    seen: set[str] = set()

    # Per-GPU idle services
    for gpu_id, svc_name in scheduling.get("idle_services", {}).items():
        if svc_name in seen:
            continue
        seen.add(svc_name)
        svc = services.get(svc_name, {})
        result.append({
            "gpu_id": gpu_id,
            "service_name": svc_name,
            "systemd_unit": svc.get("systemd_unit", ""),
            "port": svc.get("port", 0),
        })

    # Global fallback — only include if not already covered by a per-GPU entry
    global_svc = scheduling.get("idle_service", "")
    if global_svc and global_svc not in seen:
        svc = services.get(global_svc, {})
        result.append({
            "gpu_id": None,
            "service_name": global_svc,
            "systemd_unit": svc.get("systemd_unit", ""),
            "port": svc.get("port", 0),
        })

    return result

async def _check_llm_running_on_gpu(
    services: dict, gpu_id: str | None, exclude_svc: str = ""
) -> str | None:
    """Check if any GPU LLM is already running on the given gpu_id.

    Returns the service name of the first running LLM, or None.
    When gpu_id is None (global fallback), only considers services
    that have no gpu_id set (i.e., the default/primary GPU).
    """
    import asyncio as _asyncio
    for name, svc in services.items():
        if name == exclude_svc:
            continue
        if svc.get("type") != "llm_backend" or svc.get("cpu_only"):
            continue
        # GPU affinity: for per-GPU check, only match same gpu_id
        if gpu_id is not None:
            if svc.get("gpu_id", "") != gpu_id:
                continue
        elif svc.get("gpu_id"):
            # Global idle: skip services pinned to a specific other GPU
            continue
        svc_unit = svc.get("systemd_unit", "")
        if not svc_unit:
            continue
        try:
            proc = await _asyncio.create_subprocess_exec(
                "systemctl", "is-active", "--quiet", svc_unit,
                stdout=_asyncio.subprocess.DEVNULL,
                stderr=_asyncio.subprocess.DEVNULL,
            )
            await _asyncio.wait_for(proc.wait(), timeout=3)
            if proc.returncode == 0:
                return name
        except Exception:
            pass
    return None


# GPU scheduler thresholds
DRAIN_TIMEOUT = 60           # max seconds to wait for active LLM requests
LLM_RELIEF_THRESHOLD = 10   # trigger relief when this many LLM requests queued
LLM_RELIEF_MAX_DURATION = 120  # max seconds to spend in relief before resuming GPU
LLM_RESTORE_TIMEOUT = 90    # max seconds to wait for Qwen3.6 to become healthy
IDLE_RESTORE_INTERVAL = 10  # check every N seconds if LLM should be restored
COMFYUI_IDLE_COOLDOWN = 120  # seconds before auto-stopping ComfyUI when idle

# Model input names that identify the primary diffusion model
MODEL_KEY_FIELDS = [
    "unet_name", "ckpt_name", "checkpoint", "diffusion_model",
    "model_name",  # for UNETLoaderGGUF etc.
]
# Additional model inputs for grouping (secondary — used in fingerprint)
AUX_MODEL_FIELDS = [
    "clip_name", "clip_name1", "clip_name2",
    "vae_name",
    "lora_name",
]


# ===== OOM Recovery State Machine Constants =====
# VRAM thresholds (MiB)
OOM_VRAM_PRESSURE_THRESHOLD_MIB = 1024   # <1GB free is OOM territory
OOM_VRAM_CRITICAL_THRESHOLD_MIB = 512    # <512MB free is critical
OOM_RECOVERY_VRAM_TARGET_MIB = 2048      # Need at least 2GB free to start recovery

# Detection regex (NOT bare "OOM" — false-positive prone, see adversarial issue #7)
# Pattern: matches "cuda/HIP/RuntimeError/torch.cuda" followed by "out of memory" or "OOM" with word boundary
OOM_DETECTION_REGEX = r"(?i)(?:cuda|HIP|RuntimeError|torch\.cuda)\s*[:.]?\s*(?:out of memory|OutOfMemoryError|OOM)\b"

# Timeouts
OOM_VERIFY_TIMEOUT_S = 15              # OOM_VERIFYING state max duration
OOM_RECOVERY_TIMEOUT_S = 30            # OOM_RECOVERING state max duration
OOM_EVICTING_STUCK_TIMEOUT_S = 180     # Per-GPU override for gpu_primary (slower)
OOM_STALL_DETECTION_S = 120            # Job no progress for >120s = silent OOM
OOM_CANCEL_PROMPT_TIMEOUT_S = 10       # comfyui_interrupt timeout
# Phase 7 (OOM fix 3): max time the supervisor will refrain from killing a
# pool whose service is in an OOM recovery state. After this TTL elapses the
# supervisor proceeds with the kill regardless (recovery is stuck/dead).
OOM_SUPERVISOR_TTL_S = 60

# Retry policy
OOM_AUTO_RETRY_MAX = 1                 # First OOM auto-retries with reduced params; second = permanent failure
OOM_PERMANENT_FAILURE_THRESHOLD = 3    # After 3 OOMs in 5min on same GPU = GENERATION_FAILED
OOM_PERMANENT_FAILURE_WINDOW_S = 300   # 5 minutes

# VRAM reduction factor for auto-retry
OOM_RETRY_DIM_SCALE = 0.85             # Multiply width/height by 0.85
OOM_RETRY_BATCH_DIVISOR = 4            # batch_size = max(1, original // 4)

# Watchdog
OOM_WATCHDOG_POLL_INTERVAL_S = 2       # Background task poll interval
OOM_WATCHDOG_HEARTBEAT_INTERVAL_S = 10 # Heartbeat write interval

# Dead letter list
OOM_DEAD_LETTER_TTL_S = 30 * 86400     # 30 days
OOM_DEAD_LETTER_MAX = 100              # Cap at 100 entries

# History query
OOM_HISTORY_DEFAULT_LIMIT = 50
OOM_HISTORY_MAX_LIMIT = 1000
OOM_EVENT_TTL_S = 7 * 86400            # 7 days

# Rate limiting
OOM_FORCE_RESET_MIN_INTERVAL_S = 30    # Rate-limit oom_recovery_force_reset to once per 30s
_OOM_DEAD_LETTER_CAP = 100             # Per adversarial #11: cap dead-letter list at 100
_OOM_DEAD_LETTER_TTL_S = 30 * 86400    # Per adversarial #11: 30 days TTL

# ── Plan 05: OOM dead-letter / atomic retry safety contract ──────────
# Historical OOM records in oom:dead_letters are IMMUTABLE evidence.
# Retry, when permitted, is a NEW job whose tracker + queue-stream
# membership + idempotency key are created atomically. The original
# historical record is NEVER rewritten or removed. Default-all
# behavior is rejected; missing tracker / payload / stream metadata
# is a terminal refusal (fail-closed). All retries require an
# idempotency key supplied by the caller. See plan 05 for the full
# contract.
_OOM_RETRY_IDEMPOTENCY_TTL_S = 7 * 86400   # one week; long enough to absorb
                                           # double-submits without locking
                                           # operators out forever
_OOM_RETRY_AUDIT_PREFIX = "oom:retry:audit:"     # oom:retry:audit:{retry_id}
_OOM_RETRY_IDEMPOTENCY_PREFIX = "oom:retry:idem:"  # oom:retry:idem:{key}
_OOM_RETRY_DEFAULT_ATTEMPT_LIMIT = 2     # per plan 05 #3 / #4
_OOM_RETRY_STREAM_CORRELATION_PREFIX = "oom:retry:stream:"  # oom:retry:stream:{orig_job_id}

# Reasons classification can return. Kept as module-level constants so
# the test suite can pin them without re-deriving strings.
_OOM_RETRY_CLASS_NOT_FOUND = "original_not_found"
_OOM_RETRY_CLASS_NO_TRACKER = "missing_tracker"
_OOM_RETRY_CLASS_NO_PAYLOAD = "missing_payload_artifact"
_OOM_RETRY_CLASS_NO_STREAM = "missing_stream_entry"
_OOM_RETRY_CLASS_REPLAYED = "already_replayed_or_active"
_OOM_RETRY_CLASS_BUDGET_EXCEEDED = "retry_attempt_budget_exceeded"
_OOM_RETRY_CLASS_ELIGIBLE = "eligible"


# ===== Task 8A offline fail-closed guardrail contracts =====
#
# These helpers are deliberately policy/specification functions.  They do not
# write cgroups, mutate services.json, invoke systemd, read a journal, or wire
# themselves into live admission.  Callers must inject already-captured
# evidence; production enforcement is a separately-authorized change.
_TASK8A_UINT64_MAX = 2**64 - 1
_TASK8A_MIB = 1024 * 1024
_TASK8A_PSI_FULL_ABORT_PCT = 5.0
_TASK8A_RESTART_UNITS = (
    "gemma-cpu",
    "gemma-cpu-vision",
    "llm-primary",
    "llm-secondary",
    "gpu-manager",
)


class _MemoryCapRejectReason(Enum):
    MAX_NOT_FINITE = "max_not_finite"
    HIGH_GEQ_MAX = "high_geq_max"
    HIGH_EXCEEDS_P99 = "high_exceeds_p99_x_1_10"
    SWAP_MAX_NOT_FINITE = "swap_max_not_finite"
    SWAP_EXCEEDS_P99 = "swap_exceeds_p99_x_1_25"
    CONFLICTING_ALIASES = "conflicting_aliases"


class _MemoryCapProvenance(dict):
    """Mapping result with attribute access for the audit's ``.valid`` form."""

    def __init__(
        self,
        valid: bool,
        reason: str,
        headroom_mib: int,
        swap_envelope_mib: int,
    ) -> None:
        super().__init__(
            valid=valid,
            reason=reason,
            headroom_mib=headroom_mib,
            swap_envelope_mib=swap_envelope_mib,
        )

    @property
    def valid(self) -> bool:
        return self["valid"]

    @property
    def reason(self) -> str:
        return self["reason"]

    @property
    def headroom_mib(self) -> int:
        return self["headroom_mib"]

    @property
    def swap_envelope_mib(self) -> int:
        return self["swap_envelope_mib"]

    def as_dict(self) -> dict:
        return dict(self)


def _finite_positive_cap(value) -> int | None:
    """Normalize one cgroup byte cap, rejecting zero/infinity/sentinels."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if value != value or value in (float("inf"), float("-inf")):
        return None
    integer = int(value)
    if integer <= 0 or integer >= _TASK8A_UINT64_MAX:
        return None
    return integer


def _positive_measurement(value) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    number = float(value)
    if number <= 0 or number != number or number == float("inf"):
        return None
    return number


def _memory_cap_provenance(
    memory_max_bytes=None,
    memory_high_bytes=None,
    memory_swap_max_bytes=None,
    working_set_p99_mib=None,
    working_set_swap_p99_mib=None,
    **aliases,
) -> _MemoryCapProvenance:
    """Validate finite memory caps against measured p99 envelopes.

    Both the Pythonic parameter names and the names used by ``systemctl show``
    in the Task 8A audit (``MemoryMax``, ``MemoryHigh``, ``MemorySwapMax``,
    ``p99``, ``p99_swap``) are accepted.  Unknown/missing evidence rejects.
    Supplying both spellings is permitted only when the values are identical;
    conflicting spellings are rejected rather than silently giving the alias
    precedence.
    """
    alias_pairs = {
        "MemoryMax": ("memory_max_bytes", memory_max_bytes),
        "MemoryHigh": ("memory_high_bytes", memory_high_bytes),
        "MemorySwapMax": ("memory_swap_max_bytes", memory_swap_max_bytes),
        "p99": ("working_set_p99_mib", working_set_p99_mib),
        "p99_swap": ("working_set_swap_p99_mib", working_set_swap_p99_mib),
    }
    for alias, (python_name, python_value) in alias_pairs.items():
        if alias not in aliases:
            continue
        alias_value = aliases.pop(alias)
        if python_value is not None and alias_value != python_value:
            return _MemoryCapProvenance(
                False, _MemoryCapRejectReason.CONFLICTING_ALIASES.value, 0, 0
            )
        locals_value = alias_value if python_value is None else python_value
        if python_name == "memory_max_bytes":
            memory_max_bytes = locals_value
        elif python_name == "memory_high_bytes":
            memory_high_bytes = locals_value
        elif python_name == "memory_swap_max_bytes":
            memory_swap_max_bytes = locals_value
        elif python_name == "working_set_p99_mib":
            working_set_p99_mib = locals_value
        else:
            working_set_swap_p99_mib = locals_value
    if aliases:
        return _MemoryCapProvenance(
            False, _MemoryCapRejectReason.CONFLICTING_ALIASES.value, 0, 0
        )

    maximum = _finite_positive_cap(memory_max_bytes)
    high = _finite_positive_cap(memory_high_bytes)
    if maximum is None or high is None:
        return _MemoryCapProvenance(
            False, _MemoryCapRejectReason.MAX_NOT_FINITE.value, 0, 0
        )
    headroom_mib = max(0, (maximum - high) // _TASK8A_MIB)
    if high >= maximum:
        return _MemoryCapProvenance(
            False, _MemoryCapRejectReason.HIGH_GEQ_MAX.value, headroom_mib, 0
        )

    p99 = _positive_measurement(working_set_p99_mib)
    if p99 is None or high > p99 * 1.10 * _TASK8A_MIB:
        return _MemoryCapProvenance(
            False, _MemoryCapRejectReason.HIGH_EXCEEDS_P99.value,
            headroom_mib, 0,
        )

    swap_max = _finite_positive_cap(memory_swap_max_bytes)
    if swap_max is None:
        return _MemoryCapProvenance(
            False, _MemoryCapRejectReason.SWAP_MAX_NOT_FINITE.value,
            headroom_mib, 0,
        )
    swap_p99 = _positive_measurement(working_set_swap_p99_mib)
    swap_envelope_mib = int(swap_p99 * 1.25) if swap_p99 is not None else 0
    if swap_p99 is None or swap_max > swap_p99 * 1.25 * _TASK8A_MIB:
        return _MemoryCapProvenance(
            False, _MemoryCapRejectReason.SWAP_EXCEEDS_P99.value,
            headroom_mib, swap_envelope_mib,
        )
    return _MemoryCapProvenance(True, "", headroom_mib, swap_envelope_mib)


def _normalized_unit_name(unit) -> str:
    if not isinstance(unit, str):
        return ""
    normalized = unit.strip().lower()
    return normalized[:-8] if normalized.endswith(".service") else normalized


def _is_cpu_llm_unit(unit: str) -> bool:
    return _normalized_unit_name(unit) in {"gemma-cpu", "gemma-cpu-vision"}


def _validate_production_parallel_invariant(services_config: dict) -> None:
    """Reject multi-worker generation backends in explicit strict mode.

    The worker supervisor accepts the newer ``worker_parallel`` and
    ``queue_parallel`` fields while retaining the legacy ``parallel`` field.
    Validate the same precedence before a startup or hot-reload candidate is
    promoted, but keep the guard opt-in so existing qualification configs are
    not changed implicitly.
    """
    if not isinstance(services_config, dict):
        raise ValueError("services config must be a JSON object")
    if services_config.get("strict_production_parallel") is not True:
        return
    services = services_config.get("services", {})
    if not isinstance(services, dict):
        raise ValueError("services config 'services' must be an object")
    for service_name, service_config in services.items():
        if not isinstance(service_config, dict):
            continue
        if service_config.get("type") != "generation_backend":
            continue
        effective = 1
        selected_field = "default"
        for field in ("worker_parallel", "queue_parallel", "parallel"):
            if field not in service_config or service_config[field] is None:
                continue
            value = service_config[field]
            if isinstance(value, bool):
                raise ValueError(
                    f"production parallel invariant: {service_name} has "
                    f"invalid boolean {field}={value!r}"
                )
            try:
                effective = int(value)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"production parallel invariant: {service_name} has "
                    f"invalid {field}={value!r}"
                ) from exc
            selected_field = field
            break
        if effective > 1:
            raise ValueError(
                "production parallel invariant: "
                f"{service_name} effective {selected_field}={effective} "
                "exceeds strict maximum 1"
            )


# Physical capacity is supplied by each portable registry entry as ``vram_mib``
# plus ``vram_reserve_mib``.  No machine-specific ceiling is embedded here.


def _validate_linked_bundle_graph(config: dict) -> tuple[list[str], list[str]]:
    """Fail-closed validation of the linked-bundle graph.

    Inspects every bundle's ``linked_to``, ``linked_from`` and legacy
    ``linked_bundles`` fields and emits:

      * **errors** — graph corruption that must block the load:
        unknown bundle names, self-links, cycles, broken
        ``linked_from`` ↔ ``linked_to`` asymmetry, ``linked_from``
        listing a parent that does not actually link back, duplicate
        GPU ownership (two bundles with the same ``gpu_id`` and at
        least one not idle), and unknown GPU / service references.
      * **warnings** — recoverable inconsistencies such as a
        non-empty ``linked_from`` for a bundle that has no
        corresponding reverse pointer (advisory only — the runtime
        bidirectional resolver handles this transparently).

    This function is intentionally read-only: it inspects the supplied
    config dict and never mutates it. Errors and warnings are surfaced
    via ``/status`` so they are visible at startup and on every
    hot-reload without changing the parsed config.
    """
    errors: list[str] = []
    warnings: list[str] = []

    if not isinstance(config, dict):
        return errors, warnings

    bundles_raw = config.get("bundles", {})
    if not isinstance(bundles_raw, dict) or not bundles_raw:
        # Backward-compat path: legacy configs auto-generate bundles from
        # services. Surface those as a separate graph once generated.
        return errors, warnings

    gpu_devices = config.get("gpu_devices", {}) or {}
    if not isinstance(gpu_devices, dict):
        gpu_devices = {}
    known_gpus = {str(g) for g in gpu_devices.keys()}

    services = config.get("services", {}) or {}
    if not isinstance(services, dict):
        services = {}
    known_services = {str(s) for s in services.keys()}

    # Pass 1: basic shape validation (self-links, unknown links, type errors,
    # linked_from ↔ linked_to / linked_bundles symmetry).
    forward_edges: dict[str, set[str]] = {}
    reverse_edges: dict[str, set[str]] = {}
    ownership: dict[str, list[str]] = {}

    for name, bundle in bundles_raw.items():
        if not isinstance(bundle, dict):
            errors.append(f"bundle '{name}': not a JSON object")
            continue

        # Normalise the three link fields into lists for analysis. We do not
        # mutate the bundle; we just collect locally.
        def _as_list(field: str) -> list:
            value = bundle.get(field, [])
            if value is None:
                return []
            if not isinstance(value, list):
                errors.append(
                    f"bundle '{name}': '{field}' must be a list, got "
                    f"{type(value).__name__}"
                )
                return []
            return [str(item) for item in value]

        linked_to = _as_list("linked_to")
        linked_from = _as_list("linked_from")
        linked_bundles = _as_list("linked_bundles")

        forward_edges[name] = set(linked_to) | set(linked_bundles)
        reverse_edges[name] = set(linked_from)

        # Self-link checks.
        for field, items in (
            ("linked_to", linked_to),
            ("linked_from", linked_from),
            ("linked_bundles", linked_bundles),
        ):
            if name in items:
                errors.append(
                    f"bundle '{name}': '{field}' contains self-link"
                )

        # Unknown bundle references.
        all_targets = set(linked_to) | set(linked_from) | set(linked_bundles)
        for target in all_targets:
            if target == name:
                continue  # already reported as self-link
            if target not in bundles_raw:
                errors.append(
                    f"bundle '{name}': references unknown bundle '{target}'"
                )

        # Symmetry: A → B in linked_to implies B's linked_from contains A.
        for target in linked_to:
            target_from = (
                bundles_raw.get(target, {}).get("linked_from", [])
                if isinstance(bundles_raw.get(target), dict)
                else []
            )
            target_from_list = target_from if isinstance(target_from, list) else []
            if name not in target_from_list:
                warnings.append(
                    f"bundle '{name}': linked_to '{target}' but '{target}' "
                    f"does not list '{name}' in linked_from "
                    f"(bidirectional resolver will still treat as linked)"
                )

        # Symmetry: A → B in linked_from means B should list A in linked_to
        # (or linked_bundles). If neither, the reverse edge is dangling.
        for parent in linked_from:
            if parent == name:
                continue  # self-link already reported
            parent_bundle = bundles_raw.get(parent)
            if not isinstance(parent_bundle, dict):
                continue  # unknown parent already flagged above
            parent_links = (
                set(parent_bundle.get("linked_to", []) or [])
                | set(parent_bundle.get("linked_bundles", []) or [])
            )
            if name not in parent_links:
                errors.append(
                    f"bundle '{name}': linked_from '{parent}' is asymmetric — "
                    f"'{parent}' does not list '{name}' in linked_to/"
                    f"linked_bundles"
                )

        # Unknown GPU / service references.
        gpu_id = bundle.get("gpu_id")
        if gpu_id is not None and known_gpus and str(gpu_id) not in known_gpus:
            errors.append(
                f"bundle '{name}': gpu_id '{gpu_id}' not declared in "
                f"gpu_devices (known: {sorted(known_gpus)})"
            )

        bundle_services = bundle.get("services", [])
        if isinstance(bundle_services, list) and known_services:
            for svc in bundle_services:
                if str(svc) not in known_services:
                    errors.append(
                        f"bundle '{name}': references unknown service '{svc}'"
                    )

        # Ownership: at most one non-idle bundle per GPU. Idle bundles
        # (the default LLM slot) may share a GPU with at most one other
        # non-idle bundle IF the runtime explicitly permits it; the
        # current contract is "exactly one non-idle owner".
        if gpu_id is not None:
            ownership.setdefault(str(gpu_id), []).append(name)

    # Pass 2: cycle detection via DFS over the merged forward edge set.
    WHITE, GRAY, BLACK = 0, 1, 2
    color: dict[str, int] = {n: WHITE for n in forward_edges}
    cycle_reported: set[frozenset] = set()

    def _visit(node: str, stack: list[str]) -> None:
        if color.get(node, BLACK) == GRAY:
            # Back-edge -> cycle.
            if node in stack:
                idx = stack.index(node)
                cyc = stack[idx:] + [node]
                # Canonicalise so A->B->C and C->B->A produce the same record.
                canonical = frozenset(cyc[:-1])
                if canonical not in cycle_reported:
                    cycle_reported.add(canonical)
                    errors.append(
                        "linked-bundle cycle: "
                        + " -> ".join(cyc)
                    )
            return
        if color.get(node, BLACK) == BLACK:
            return
        color[node] = GRAY
        stack.append(node)
        for nxt in sorted(forward_edges.get(node, set())):
            _visit(nxt, stack)
        stack.pop()
        color[node] = BLACK

    for node in sorted(forward_edges.keys()):
        if color[node] == WHITE:
            _visit(node, [])

    # Pass 3: enumerate alternative candidates sharing each GPU. Multiple
    # configured bundles are expected (ComfyUI, Qwen, ACE-Step, LLM routes);
    # they are not simultaneous owners. Runtime exclusivity is enforced by the
    # lifecycle controller and transition graph, so this is observable advice,
    # not a static configuration error.
    for gid, names in sorted(ownership.items()):
        non_idle = [n for n in names if not bundles_raw.get(n, {}).get("idle", False)]
        if len(non_idle) > 1:
            warnings.append(
                f"gpu '{gid}': alternative non-idle bundle candidates require "
                f"controller fencing: {sorted(non_idle)}"
            )

    # Pass 4: orphan candidates. A bundle is an *orphan candidate* if no
    # other bundle lists it in ``linked_to`` or ``linked_bundles``. Such a
    # bundle is reachable only as a top-level entry point; runtime
    # admission treats it as eligible for direct activation, so we surface
    # the candidate as a warning for operator visibility rather than as an
    # error. Multiple orphans are expected (each top-level bundle starts
    # one), so we cap the report length.
    incoming: dict[str, set[str]] = {n: set() for n in bundles_raw}
    for parent_name, parent in bundles_raw.items():
        if not isinstance(parent, dict):
            continue
        links = set(parent.get("linked_to", []) or []) | set(
            parent.get("linked_bundles", []) or []
        )
        for child in links:
            if child in incoming:
                incoming[child].add(parent_name)
    orphan_candidates = sorted(n for n, parents in incoming.items() if not parents)
    if orphan_candidates:
        warnings.append(
            "linked-bundle orphan candidates (no incoming linked_to/"
            f"linked_bundles): {orphan_candidates}"
        )

    return errors, warnings


def _validate_config_policy(config: dict) -> tuple[list[str], list[str]]:
    """Return the configured per-device VRAM ceiling.

    The registry supplies physical capacity and reserve values.  The controller
    never embeds a machine-specific card ceiling.
    """
    errors: list[str] = []
    warnings: list[str] = []

    if not isinstance(config, dict):
        return errors, warnings

    # Device capacity is validated generically below from the registry entry.
    gpu_devices = config.get("gpu_devices", {}) or {}
    scheduling = config.get("scheduling", {}) or {}
    if not isinstance(scheduling, dict):
        scheduling = {}

    scheduler_owns_load = bool(scheduling.get("scheduler_owns_load", False))

    # 2) Scheduler-owned evict_first -> ERROR (was warning in 5.2.79).
    # Plan 06 demands the prune cannot regress silently: if the
    # operator wanted eviction ordering on a scheduler-owned
    # template, that intent was lost and the template must be fixed.
    if scheduler_owns_load:
        templates = config.get("generation_templates", {}) or {}
        if isinstance(templates, dict):
            for tpl_name, tpl in templates.items():
                if not isinstance(tpl, dict):
                    continue
                evict = tpl.get("evict_first")
                if evict:  # truthy: non-empty list / non-None
                    errors.append(
                        f"template '{tpl_name}': evict_first is forbidden "
                        f"when scheduler_owns_load=true "
                        f"(runtime ignores the directive; remove it)"
                    )

    # 2b) VRAM target / ceiling / reserve coherence per gpu_device.
    if isinstance(gpu_devices, dict):
        for gid, gdev in gpu_devices.items():
            if not isinstance(gdev, dict):
                continue
            try:
                target = (
                    int(gdev["vram_target_mib"])
                    if gdev.get("vram_target_mib") is not None
                    else None
                )
            except (TypeError, ValueError):
                errors.append(
                    f"gpu_devices.{gid}.vram_target_mib must be an integer, "
                    f"got {gdev.get('vram_target_mib')!r}"
                )
                target = None
            try:
                ceiling = (
                    int(gdev["vram_ceiling_mib"])
                    if gdev.get("vram_ceiling_mib") is not None
                    else None
                )
            except (TypeError, ValueError):
                errors.append(
                    f"gpu_devices.{gid}.vram_ceiling_mib must be an integer, "
                    f"got {gdev.get('vram_ceiling_mib')!r}"
                )
                ceiling = None
            try:
                reserve = (
                    int(gdev["vram_reserve_mib"])
                    if gdev.get("vram_reserve_mib") is not None
                    else None
                )
            except (TypeError, ValueError):
                errors.append(
                    f"gpu_devices.{gid}.vram_reserve_mib must be an integer, "
                    f"got {gdev.get('vram_reserve_mib')!r}"
                )
                reserve = None
            try:
                physical = (
                    int(gdev["vram_mib"])
                    if gdev.get("vram_mib") is not None
                    else None
                )
            except (TypeError, ValueError):
                errors.append(
                    f"gpu_devices.{gid}.vram_mib must be an integer, "
                    f"got {gdev.get('vram_mib')!r}"
                )
                physical = None
            if target is not None and ceiling is not None and target > ceiling:
                errors.append(
                    f"gpu_devices.{gid}: vram_target_mib={target} exceeds "
                    f"vram_ceiling_mib={ceiling}"
                )
            if (
                ceiling is not None
                and physical is not None
                and reserve is not None
                and ceiling > (physical - reserve)
            ):
                errors.append(
                    f"gpu_devices.{gid}: vram_ceiling_mib={ceiling} exceeds "
                    f"physical-reserve "
                    f"({physical} - {reserve} = {physical - reserve}); "
                    f"scheduler cannot satisfy the reserve headroom"
                )

    # 3) Idle / pin precedence. The order is:
    #    pinned_service > scheduling.idle_services[gpu_id] > scheduling.idle_service
    # A pinned generation_backend is allowed to override the idle LLM. The
    # differing service types express the normal pin use-case and are not a
    # schema conflict; the warning below makes precedence operator-visible.
    pinned_service = scheduling.get("pinned_service")
    idle_services = scheduling.get("idle_services", {}) or {}
    global_idle_service = scheduling.get("idle_service")

    services_map = config.get("services", {}) or {}
    if not isinstance(services_map, dict):
        services_map = {}

    # 4) Legacy idle_job semantics. idle_job is the obsolete keepalive
    # hook (ComfyUI image at priority 10) pre-dating idle_services. It
    # is dormant when enabled=False (the default). When enabled=True it
    # conflicts with the modern idle selector (idle_services or global
    # idle_service) and with scheduler_owns_load (the scheduler does
    # not honour legacy keepalive jobs).
    idle_job = scheduling.get("idle_job", {}) or {}
    if isinstance(idle_job, dict) and idle_job.get("enabled") is True:
        modern_idle_active = bool(
            (isinstance(idle_services, dict) and idle_services)
            or global_idle_service
        )
        if modern_idle_active:
            errors.append(
                "scheduling.idle_job.enabled=true conflicts with "
                "scheduling.idle_services / scheduling.idle_service "
                "(legacy keepalive cannot coexist with the modern idle "
                "selector; disable idle_job and migrate to idle_services)"
            )
        elif scheduler_owns_load:
            errors.append(
                "scheduling.idle_job.enabled=true conflicts with "
                "scheduler_owns_load=true "
                "(the scheduler does not honour legacy keepalive jobs; "
                "disable idle_job and rely on scheduling.idle_services "
                "or scheduling.idle_service instead)"
            )

    # Informational precedence note (warning) when more than one selector
    # is configured so operators see the resolution order at startup.
    if pinned_service and (global_idle_service or (isinstance(idle_services, dict) and idle_services)):
        warnings.append(
            "scheduling precedence is pinned_service > "
            "idle_services[gpu_id] > idle_service (global); only the "
            "highest-precedence selector fires per request"
        )

    return errors, warnings


def _validate_config_for_observability(config: dict) -> tuple[list[str], list[str]]:
    """Combine graph and policy validation without mutating the candidate."""
    graph_errors, graph_warnings = _validate_linked_bundle_graph(config)
    policy_errors, policy_warnings = _validate_config_policy(config)
    errors = list(dict.fromkeys([*graph_errors, *policy_errors]))
    warnings = list(dict.fromkeys([*graph_warnings, *policy_warnings]))
    bundles = config.get("bundles") or {}
    if isinstance(bundles, Mapping):
        for bundle_name, bundle in bundles.items():
            if not isinstance(bundle, Mapping) or not (
                "runtime_instance" in bundle or "runtime_profile" in bundle
            ):
                continue
            try:
                resolve_checked_runtime_binding(config, str(bundle_name))
            except CheckedRuntimeError as exc:
                errors.append(f"bundle {bundle_name!r}: {exc}")
    errors.extend(checked_runtime_authority_errors(config))
    return list(dict.fromkeys(errors)), warnings


def _expected_restart_policy(unit: str = "gemma-cpu") -> dict[str, int]:
    policies = {
        "gemma-cpu": {
            "RestartSec": 120,
            "StartLimitIntervalSec": 900,
            "StartLimitBurst": 5,
        },
        "gemma-cpu-vision": {
            "RestartSec": 120,
            "StartLimitIntervalSec": 900,
            "StartLimitBurst": 5,
        },
        "llm-primary": {
            "RestartSec": 10,
            "StartLimitIntervalSec": 10,
            "StartLimitBurst": 5,
        },
        "llm-secondary": {
            "RestartSec": 15,
            "StartLimitIntervalSec": 10,
            "StartLimitBurst": 5,
        },
        "gpu-manager": {
            "RestartSec": 10,
            "StartLimitIntervalSec": 10,
            "StartLimitBurst": 5,
        },
    }
    policy = policies.get(_normalized_unit_name(unit))
    return dict(policy) if policy else {}


def _systemd_restart_policy_drift(unit, dropin_dir, systemctl_cat_path):
    """Return expected restart-policy directives that differ from evidence.

    ``systemctl cat`` is the authoritative merged base-unit/drop-in view;
    drop-ins are applied afterward to make the precedence explicit.  This is
    intentionally read-only and reports only the numeric damping directives
    tracked by ``_expected_restart_policy``.
    """
    from pathlib import Path

    unit_name = _normalized_unit_name(unit)
    expected = _expected_restart_policy(unit_name)
    if not expected:
        return {}

    def parse_lines(lines):
        result = {}
        for raw in lines:
            line = raw.strip()
            if not line or line.startswith(("#", ";")) or "=" not in line:
                continue
            key, _, value = line.partition("=")
            key = key.strip()
            if key in expected:
                result[key] = value.strip()
        return result

    cat_path = Path(systemctl_cat_path)
    marker = f"=== {unit_name}.service (systemctl cat) ==="
    lines = cat_path.read_text().splitlines()
    try:
        start = lines.index(marker) + 1
    except ValueError as exc:
        raise ValueError(f"systemctl cat evidence has no section for {unit_name}") from exc
    end = next(
        (index for index in range(start, len(lines)) if lines[index].startswith("=== ")),
        len(lines),
    )
    deployed = parse_lines(lines[start:end])
    for conf in sorted(Path(dropin_dir).glob("*.conf")):
        deployed.update(parse_lines(conf.read_text().splitlines()))

    drift = {}
    for key, expected_value in expected.items():
        deployed_value = deployed.get(key)
        if deployed_value is None:
            drift[key] = ("", expected_value)
            continue
        try:
            numeric = int(str(deployed_value).rstrip("s"))
        except ValueError:
            drift[key] = (deployed_value, expected_value)
            continue
        if numeric != expected_value:
            drift[key] = (deployed_value, expected_value)
    return drift


def _oom_damping_shape(unit: str = "gemma-cpu") -> dict:
    policy = _expected_restart_policy(unit)
    restart_window = policy.get("RestartSec")
    observable = (
        "covers_amplification"
        if restart_window is not None
        and OOM_WATCHDOG_POLL_INTERVAL_S < restart_window
        else "unknown_policy"
    )
    return {
        "watchdog_interval_s": OOM_WATCHDOG_POLL_INTERVAL_S,
        "expected_respawn_window_s": restart_window,
        "expected_damping_factor": 1 if policy.get("StartLimitBurst", 0) > 0 else 0,
        "watchdog_observability": observable,
    }


def _count_pinned_compute_idles(idle_map, compute_gpu_ids) -> int:
    if not isinstance(idle_map, Mapping) or not isinstance(
        compute_gpu_ids, (set, frozenset, list, tuple)
    ):
        return 0
    compute = {str(gpu_id) for gpu_id in compute_gpu_ids}
    return sum(
        1 for gpu_id, service in idle_map.items()
        if str(gpu_id) in compute and bool(service)
    )


def _validate_idle_policy(
    idle_map,
    compute_gpu_ids,
    allow_count=1,
    thermal_provenance=None,
) -> tuple[bool, str]:
    """Validate compute-idle count without mutating scheduler configuration."""
    if not isinstance(idle_map, Mapping) or not isinstance(
        compute_gpu_ids, (set, frozenset, list, tuple)
    ):
        return False, "idle_policy_input_invalid"
    if isinstance(allow_count, bool) or not isinstance(allow_count, int) or allow_count < 0:
        return False, "allow_count_invalid"
    pinned = _count_pinned_compute_idles(idle_map, compute_gpu_ids)
    if pinned <= allow_count:
        return True, ""
    if allow_count == 0:
        return False, "compute_idles_not_allowed"
    if not isinstance(thermal_provenance, Mapping):
        return False, "two_compute_idles_without_thermal_provenance"

    p99 = _positive_measurement(thermal_provenance.get("junction_p99_c"))
    cooled = _positive_measurement(thermal_provenance.get("junction_cooled_c"))
    critical = _positive_measurement(
        thermal_provenance.get("junction_crit_c", 110.0)
    )
    if p99 is not None and critical is not None and p99 >= critical:
        return False, "junction_at_or_above_crit"
    if cooled is not None and critical is not None and cooled >= critical:
        return False, "junction_at_or_above_crit"
    if p99 is None or cooled is None or critical is None:
        return False, "thermal_provenance_incomplete"
    return True, "two_compute_idles_with_thermal_provenance"


def _junction_crit_aborted(per_gpu) -> bool | tuple[str, str]:
    """Classify per-GPU junction evidence as critical, safe, or unknown."""
    if not isinstance(per_gpu, Mapping) or not per_gpu:
        return "unknown", "no_telemetry"
    telemetry_rows = [row for row in per_gpu.values() if isinstance(row, Mapping)]
    for telemetry in telemetry_rows:
        if is_junction_critical(telemetry):
            return True
    if not telemetry_rows:
        return "unknown", "no_telemetry"
    for telemetry in telemetry_rows:
        junction = telemetry.get("temp_junction_c")
        critical = telemetry.get("temp_junction_crit_c")
        if junction is None:
            return "unknown", "junction_channel_unreadable"
        if critical is None:
            return "unknown", "threshold_unknown"
        try:
            float(junction)
            float(critical)
        except (TypeError, ValueError):
            return "unknown", "junction_channel_unreadable"
    return False


def _parse_psi_avg10(psi_text: str) -> tuple[float | None, float | None]:
    some = None
    full = None
    if not isinstance(psi_text, str):
        return some, full
    for raw_line in psi_text.splitlines():
        fields = raw_line.split()
        if not fields:
            continue
        target = fields[0]
        for field in fields[1:]:
            if not field.startswith("avg10="):
                continue
            try:
                value = float(field.split("=", 1)[1])
            except (TypeError, ValueError):
                value = None
            if target == "some":
                some = value
            elif target == "full":
                full = value
    return some, full


def _psi_full_stall_pct(
    psi_path: str,
    *,
    some_avg10=None,
    full_avg10=None,
    psi_text: str | None = None,
    abort_threshold_pct: float = _TASK8A_PSI_FULL_ABORT_PCT,
) -> dict:
    """Classify injected PSI memory evidence; never opens ``psi_path``."""
    del psi_path  # path is provenance only; I/O belongs to an authorized wrapper.
    if psi_text is not None:
        parsed_some, parsed_full = _parse_psi_avg10(psi_text)
        if some_avg10 is None:
            some_avg10 = parsed_some
        if full_avg10 is None:
            full_avg10 = parsed_full
    try:
        some = None if some_avg10 is None else float(some_avg10)
        full = None if full_avg10 is None else float(full_avg10)
    except (TypeError, ValueError):
        some, full = None, None
    result = {
        "some_pct": some,
        "full_pct": full,
        "abort_threshold_pct": float(abort_threshold_pct),
        "abort": full is None or full >= float(abort_threshold_pct),
    }
    if full is None:
        result["reason"] = "psi_full_unreadable"
    return result


def _parse_cgroup_memory_events(events_text: str) -> dict[str, int] | None:
    if not isinstance(events_text, str) or not events_text.strip():
        return None
    result: dict[str, int] = {}
    try:
        for line in events_text.splitlines():
            key, raw_value = line.split()
            value = int(raw_value)
            if value < 0:
                return None
            result[key] = value
    except (TypeError, ValueError):
        return None
    return result or None


def _cgroup_events_oom(per_unit) -> dict:
    """Return nonzero memory.events OOM/high deltas, unknown fail-closed."""
    if not isinstance(per_unit, Mapping):
        return {"any_oom": True, "delta": {"_input": {"unknown": 1}}}
    delta: dict[str, dict[str, int]] = {}
    for unit, events in per_unit.items():
        if not isinstance(events, Mapping):
            delta[str(unit)] = {"unknown": 1}
            continue
        nonzero = {
            key: int(events.get(key, 0) or 0)
            for key in ("high", "max", "oom", "oom_kill")
            if int(events.get(key, 0) or 0) > 0
        }
        if nonzero:
            delta[str(unit)] = nonzero
    return {"any_oom": bool(delta), "delta": delta}


def _journal_timestamp(line: str) -> str | None:
    match = re.match(r"^([A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2})\b", line)
    return match.group(1) if match else None


def _parse_prior_boot_thrash(journal_block: str) -> dict:
    """Parse a caller-supplied prior-boot kernel journal block (no I/O)."""
    lines = journal_block.splitlines() if isinstance(journal_block, str) else []
    oom_markers: list[str] = []
    memcgs: list[str] = []
    page_alloc_failures = 0
    amdgpu_userptr = 0
    for line_number, line in enumerate(lines):
        lower = line.lower()
        is_oom = (
            "invoked oom-killer" in lower
            or "oom-kill:" in lower
            or "out of memory: killed process" in lower
        )
        if is_oom:
            timestamp = _journal_timestamp(line)
            # Timestamp is provenance only.  The line number is part of the
            # event key so same-second bursts remain distinct.
            oom_markers.append(timestamp or f"line:{line_number}")
        if "page allocation failure" in lower:
            page_alloc_failures += 1
        if "amdgpu_amdkfd_restore_userptr_worker" in lower:
            amdgpu_userptr += 1
        match = re.search(r"task_memcg=([^,\s]+)", line)
        if match:
            memcgs.append(match.group(1))
    counts = {memcg: memcgs.count(memcg) for memcg in set(memcgs)}
    dominant = max(counts, key=lambda key: (counts[key], key)) if counts else None
    first = oom_markers[0] if oom_markers else None
    last = oom_markers[-1] if oom_markers else None
    # Synthetic no-timestamp markers are useful for counting but are not valid
    # timestamp provenance.
    first = None if isinstance(first, str) and first.startswith("line:") else first
    last = None if isinstance(last, str) and last.startswith("line:") else last
    return {
        "oom_kills": len(oom_markers),
        "killed_processes": len(oom_markers),
        "page_alloc_failures": page_alloc_failures,
        "amdgpu_userptr": amdgpu_userptr,
        "first_oom_ts": first,
        "last_oom_ts": last,
        "distinct_memcgs": len(counts),
        "dominant_memcg": dominant,
    }


def _prior_boot_oom_rate_per_minute(parsed: Mapping) -> float:
    first = parsed.get("first_oom_ts")
    last = parsed.get("last_oom_ts")
    if not isinstance(first, str) or not isinstance(last, str):
        return 0.0
    try:
        from datetime import datetime
        start = datetime.strptime(f"2000 {first}", "%Y %b %d %H:%M:%S")
        end = datetime.strptime(f"2000 {last}", "%Y %b %d %H:%M:%S")
    except (TypeError, ValueError):
        return 0.0
    elapsed_minutes = (end - start).total_seconds() / 60.0
    if elapsed_minutes <= 0:
        return 0.0
    return float(parsed.get("oom_kills", 0) or 0) / elapsed_minutes


def _prior_boot_is_thrash(parsed) -> bool:
    if not isinstance(parsed, Mapping) or not parsed:
        return True
    try:
        return (
            int(parsed.get("oom_kills", 0) or 0) > 10
            or int(parsed.get("page_alloc_failures", 0) or 0) > 0
            or int(parsed.get("distinct_memcgs", 0) or 0) > 3
            or _prior_boot_oom_rate_per_minute(parsed) > 0.5
        )
    except (TypeError, ValueError):
        return True


def _oom_counters_snapshot(
    restart_signals_fn=None,
    *,
    _read_restart_signals_fn=None,
    now: float | None = None,
) -> dict:
    """Join existing OOM scopes with injected systemd restart evidence."""
    sample_ts = time.time() if now is None else float(now)
    reader = restart_signals_fn or _read_restart_signals_fn
    health = _oom_health_section(now=sample_ts)
    restart_signals: dict = {
        "scope": "systemd",
        "sample_ts": sample_ts,
        "complete": reader is not None,
        "read_errors": {},
    }
    for unit in _TASK8A_RESTART_UNITS:
        normalized = _normalized_unit_name(unit)
        data = None
        if reader is not None:
            try:
                candidate = reader(normalized)
                if isinstance(candidate, Mapping):
                    data = candidate
                else:
                    raise ValueError("restart reader returned non-mapping")
            except Exception as exc:
                restart_signals["read_errors"][normalized] = str(exc)
                restart_signals["complete"] = False
        else:
            restart_signals["read_errors"][normalized] = "reader_not_injected"
        raw_restarts = data.get("NRestarts") if data is not None else None
        restart_usec = data.get("RestartUSec") if data is not None else None
        if data is None:
            count = None
        elif isinstance(raw_restarts, bool) or raw_restarts is None:
            count = None
            restart_signals["read_errors"][normalized] = "invalid_NRestarts"
            restart_signals["complete"] = False
        else:
            try:
                count = int(raw_restarts)
            except (TypeError, ValueError):
                count = None
                restart_signals["read_errors"][normalized] = "invalid_NRestarts"
                restart_signals["complete"] = False
        restart_signals[f"nrestarts_{normalized}"] = count
        restart_signals[f"restart_usec_{normalized}"] = (
            restart_usec if count is not None else None
        )
    return {
        "process_events": health["process_events"],
        "dead_letter_retained": health["dead_letter_retained"],
        "watchdog": health["watchdog"],
        "restart_signals": restart_signals,
    }


def _watchdog_should_escalate(
    counters,
    prior_boot,
    junction,
    psi,
    cgroup,
) -> tuple[bool, str]:
    if not isinstance(counters, Mapping) or not isinstance(
        counters.get("process_events"), Mapping
    ):
        return True, "counters_unknown"
    process = counters["process_events"]
    if not isinstance(process.get("total_events"), (int, float)) or not isinstance(
        process.get("active_recoveries"), Mapping
    ):
        return True, "counters_unknown"
    active = process["active_recoveries"]
    active_state = next(
        (
            state
            for state in active.values()
            if state in {"detected", "draining", "verifying", "recovering"}
        ),
        None,
    )
    if int(process.get("total_events", 0) or 0) > 0 and active_state:
        return True, "oom_state_detected" if active_state == "detected" else "oom_recovery_active"
    if prior_boot is None:
        return True, "prior_boot_unknown"
    prior_thrash = (
        prior_boot
        if isinstance(prior_boot, bool)
        else _prior_boot_is_thrash(prior_boot)
    )
    if prior_thrash:
        return True, "prior_boot_thrash"
    junction_verdict = _junction_crit_aborted(
        {"watchdog": junction} if isinstance(junction, Mapping) else {}
    )
    if junction_verdict is True:
        return True, "junction_critical"
    if junction_verdict is not False:
        return True, "junction_unknown"
    try:
        full_pct = psi.get("full_pct")
        if full_pct is None:
            return True, "psi_unknown"
        if float(full_pct) >= _TASK8A_PSI_FULL_ABORT_PCT:
            return True, "psi_full_stall"
    except (AttributeError, TypeError, ValueError):
        return True, "psi_unknown"
    if not isinstance(cgroup, Mapping) or not isinstance(cgroup.get("any_oom"), bool):
        return True, "cgroup_unknown"
    if cgroup.get("any_oom") is True:
        return True, "cgroup_oom_increment"
    return False, "clear"


def _should_admit_generation(cfg, *, junction, psi, prior_boot) -> bool:
    """Pure fail-closed generation admission gate for Task 8A evidence."""
    if not isinstance(cfg, Mapping):
        return False
    oom = cfg.get("oom")
    if not isinstance(oom, Mapping) or not isinstance(oom.get("any_oom"), bool):
        return False
    if oom.get("any_oom"):
        return False
    junction_verdict = _junction_crit_aborted(
        {"admission": junction} if isinstance(junction, Mapping) else {}
    )
    if junction_verdict is not False:
        return False
    if not isinstance(psi, Mapping) or psi.get("full_pct") is None:
        return False
    try:
        if float(psi["full_pct"]) >= _TASK8A_PSI_FULL_ABORT_PCT:
            return False
    except (TypeError, ValueError):
        return False
    if prior_boot is not False:
        return False
    return True


def _watchdog_ladder_snapshot(
    gpu_id: str,
    *,
    restart_ts: float | None = None,
    state_timestamps: Mapping | None = None,
) -> list[tuple[str, float]]:
    """Return a replayable monotonic escalation ladder from injected times."""
    del gpu_id  # identity is carried by the caller; this helper has no I/O.
    anchor = _scheduler_started_at if restart_ts is None else float(restart_ts)
    supplied = state_timestamps if isinstance(state_timestamps, Mapping) else {}
    states = (
        "idle", "detected", "draining", "verifying", "recovering",
        "restored", "permanent_failed",
    )
    result: list[tuple[str, float]] = []
    last = anchor
    for state in states:
        candidate = supplied.get(state, anchor if state == "idle" else last)
        try:
            since = max(last, float(candidate))
        except (TypeError, ValueError):
            since = last
        result.append((state, since))
        last = since
    result[0] = ("idle", anchor)
    return result


# ── GPU State Machine ──────────────────────────────────────────────

class GpuState(Enum):
    """GPU state machine states.

    LLM_LOADED    → Qwen3.6 on GPU, serving requests (default idle state)
    DRAINING      → Waiting for active LLM requests to finish before evicting
    GPU_WORK      → ComfyUI or ACE-Step using GPU
    LLM_RELIEF    → Temporary LLM restore to clear queued request backlog
    RESTORING     → Qwen3.6 reloading to GPU after GPU work complete
    """
    LLM_LOADED = "llm_loaded"
    DRAINING = "draining"
    GPU_WORK = "gpu_work"
    LLM_RELIEF = "llm_relief"
    RESTORING = "restoring"


# ── Per-GPU Priority System ────────────────────────────────────────
#
# Each GPU tracks its own loaded bundle, priority queue, and drain state.
# This enables per-GPU eviction: a higher-priority bundle arriving on a GPU
# can drain and replace whatever is currently loaded on THAT specific GPU,
# without affecting other GPUs.


class GpuBundleState:
    """Per-GPU bundle state tracker.

    Tracks what bundle is loaded on this GPU, its priority, whether it's
    draining, and the priority queue of pending requests.
    """

    def __init__(self, gpu_id: str):
        self.gpu_id = gpu_id
        self.loaded_bundle: str | None = None  # Currently loaded bundle name
        self.bundle_priority: int = 0          # Priority of the loaded bundle
        self.draining: bool = False            # True when draining pending requests
        self.drain_started_at: float | None = None  # When drain began
        self._drain_event = asyncio.Event()    # Signals drain completion
        self.pending_requests: int = 0         # Count of in-flight requests
        self.state: str = "idle"               # idle | loaded | draining | evicting | loading
        # Priority queue: list of (priority, timestamp, bundle_name, request_data) tuples
        # Sorted by -priority (highest first), then +timestamp (FIFO within same priority)
        self.priority_queue: list[dict] = []
        # ── Phase 0: fields formerly in scheduler._gpu_state[gpu_id] ────
        # GpuBundleState is now the SINGLE SOURCE OF TRUTH for these. Setters
        # below mirror changes back to scheduler._gpu_state for /health.
        self.loaded_bundles: list[str] = []    # Mirror of scheduler._gpu_state["loaded_bundles"]
        self.evicting: bool = False            # Mirror of scheduler._gpu_state["evicting"]
        self.current_priority: int = 0         # Mirror of scheduler._gpu_state["current_priority"]
        self.loading: bool = False             # Mirror of scheduler._gpu_state["loading"]
        # Audit fields (setters populate)
        self.last_change_ts: float | None = None
        self.last_event: str | None = None
        self.events: list[dict] = []
        # ── Phase 4g: idle-bundle auto-eviction activity timestamp ─────
        self.last_activity_at: float = 0.0
        # Phase 5.2.36: count of workers currently executing a job in
        # _execute_job for this bundle. _auto_evict_idle_bundles skips
        # evictions when this is > 0, preventing the auto-evict from
        # killing comfyui mid-inference (Bug C race).
        self.worker_in_flight: int = 0
        # ── Phase 5.2.4: post-load grace deadline (used by _auto_evict) ─
        # Set in _load_bundle after port-ready check. Auto-evict skips
        # bundles where now < this value, so backends that need warmup
        # (e.g. ComfyUI's ComfyRegistry fetch) are not freed mid-grace.
        self.bundle_post_load_grace_at: float = 0.0
        # ── Phase 4h.3 S5: backoff for repeated unload failures ────────
        self.last_evict_attempt_at: float = 0.0
        # ── Phase 5.1.5 P0-1: bundle-load grace (auto-evict skip) ────
        # Set in _load_bundle after port-ready check; auto-evict skips
        # bundles within _BUNDLE_LOAD_GRACE_SECONDS of being loaded.
        self.bundle_loaded_at: float = 0.0
        # ── Phase 1: OOM Recovery State Machine fields ────────────────
        # See OOM_RECOVERY_STATE_MACHINE_DESIGN.md §A.2 for the per-GPU
        # oom sub-state machine. All OOM state lives here, no parallel
        # dict (Phase 0 unified the state owner). Values are written
        # through set_oom_state() / record_oom_event() to keep the audit
        # ring buffer consistent.
        self.oom_event_count: int = 0                  # Lifetime OOM events on this GPU
        self.oom_recovery_count: int = 0               # Successful recoveries
        self.oom_permanent_failure_count: int = 0      # Permanent failures
        self.oom_state: str = "idle"                   # idle | detected | draining | verifying | recovering | restored | permanent_failed
        self.oom_state_since: float = 0.0              # time.time() when entered current state
        self.oom_last_event_ts: float = 0.0            # time.time() of last OOM event
        self.oom_last_reason: str = ""                 # Free-form reason string
        self.oom_active_recovery_job_id: str = ""      # Job being recovered, or ""
        self.oom_retry_attempted: bool = False         # True if an auto-retry was already issued
        self.oom_recent_failure_times: deque = deque(maxlen=10)  # timestamps for permanent-failure window
        # ── Phase 5: OOM-implicated service tracker ────────────────────
        # Set by WorkerPool._worker_loop right before _handle_oom_event so
        # _resolve_service_for_gpu can fall back to it when the GPU has
        # no loaded bundles (typical race: OOM kills the worker before the
        # bundle is registered as loaded).
        self.oom_last_service_name: str | None = None
        # ── Phase 7: oom_state transition timestamp ────────────────────
        # Mirror of oom_state_since; named differently so the supervisor's
        # TTL gate has its own field (clearer intent, future-proof if
        # oom_state_since semantics drift). Updated by set_oom_state().
        self.oom_state_changed_at: float = 0.0
        # State schema version — bumped whenever GpuBundleState adds required
        # fields. from_dict() reads this and runs migrations as needed.
        self.state_version: int = 4

    def _record_event(self, label: str, **fields) -> None:
        """Record a state change. Keeps a bounded 50-entry ring buffer."""
        self.last_change_ts = time.time()
        self.last_event = label
        evt = {"ts": self.last_change_ts, "event": label, **fields}
        self.events.append(evt)
        if len(self.events) > 50:
            self.events = self.events[-50:]

    def set_evicting(self, value: bool, source: str = "unknown") -> None:
        """Set evicting flag atomically; records the change for audit.

        `source` identifies the caller (e.g. "evict_llm", "restore_llm",
        "_load_bundle") so divergence debugging has a trail.
        """
        old = self.evicting
        self.evicting = bool(value)
        self._record_event(
            f"evicting={self.evicting}",
            old=old, new=self.evicting, source=source,
        )
        if old != self.evicting:
            logger.info(
                f"[gpu-bundle:{self.gpu_id}] evicting: {old} -> {self.evicting} "
                f"(source={source})"
            )
            if self.evicting:
                self.state = "evicting"
            elif self.state == "evicting":
                self.state = "idle" if not self.loaded_bundles else "loaded"
        _sync_legacy_gpu_state(self.gpu_id, self)

    def set_draining(self, value: bool, source: str = "unknown") -> None:
        """Set draining flag atomically; syncs to legacy dict."""
        old = self.draining
        self.draining = bool(value)
        self._record_event(
            f"draining={self.draining}",
            old=old, new=self.draining, source=source,
        )
        if old != self.draining:
            logger.debug(
                f"[gpu-bundle:{self.gpu_id}] draining: {old} -> {self.draining} "
                f"(source={source})"
            )
        _sync_legacy_gpu_state(self.gpu_id, self)

    def set_loaded_bundles(self, bundles, source: str = "unknown") -> None:
        """Set loaded_bundles list atomically; syncs to legacy dict."""
        old = list(self.loaded_bundles)
        self.loaded_bundles = list(bundles) if bundles else []
        self._record_event(
            f"loaded_bundles={self.loaded_bundles}",
            old=old, new=self.loaded_bundles, source=source,
        )
        if old != self.loaded_bundles:
            logger.debug(
                f"[gpu-bundle:{self.gpu_id}] loaded_bundles: {old} -> {self.loaded_bundles} "
                f"(source={source})"
            )
        _sync_legacy_gpu_state(self.gpu_id, self)

    def set_current_priority(self, value: int, source: str = "unknown") -> None:
        """Set current_priority atomically; syncs to legacy dict."""
        old = self.current_priority
        self.current_priority = int(value)
        self._record_event(
            f"current_priority={self.current_priority}",
            old=old, new=self.current_priority, source=source,
        )
        _sync_legacy_gpu_state(self.gpu_id, self)

    def set_loading(self, value: bool, source: str = "unknown") -> None:
        """Set loading flag atomically; syncs to legacy dict."""
        old = self.loading
        self.loading = bool(value)
        self._record_event(
            f"loading={self.loading}",
            old=old, new=self.loading, source=source,
        )
        _sync_legacy_gpu_state(self.gpu_id, self)

    def touch_activity(self, source: str = "unknown") -> None:
        """Stamp last_activity_at for idle-bundle auto-eviction decisions.

        Deliberately does NOT call _record_event: at 10 jobs/s this floods
        the audit ring (was 99% of entries). The timestamp itself is the
        signal — see Phase 4h.3 S3.

        Call sites: _load_bundle start (M3), _load_bundle success,
        WorkerPool._execute_job completion (S4).
        """
        self.last_activity_at = time.time()

    def clear_eviction(self, source: str) -> None:
        """Atomically clear evicting + loading + draining after a load/restore.

        Used at every successful bundle load/restore path so evicting can
        never get stuck True (the original Phase 0 bug).
        """
        self.set_evicting(False, source=source)
        self.set_loading(False, source=source)
        self.set_draining(False, source=source)

    # ── Phase 1: OOM Recovery state setters ────────────────────────────
    # The OOM sub-state machine lives entirely on GpuBundleState. Allowed
    # values for oom_state: idle | detected | draining | verifying |
    # recovering | restored | permanent_failed. Setters validate and
    # record the change in the audit ring buffer.
    _VALID_OOM_STATES = frozenset({
        "idle", "detected", "draining", "verifying",
        "recovering", "restored", "permanent_failed",
    })

    def set_oom_state(self, value: str, source: str = "unknown", reason: str = "") -> None:
        """Set oom_state atomically; records the change for audit.

        Unknown states are coerced to "idle" so a bad transition cannot
        wedge the state machine (worst case: we lose the bad state and
        treat it as no-recovery-needed).
        """
        if value not in self._VALID_OOM_STATES:
            logger.warning(
                f"[gpu-bundle:{self.gpu_id}] set_oom_state: unknown state "
                f"'{value}' (source={source}); coercing to 'idle'"
            )
            value = "idle"
        old = self.oom_state
        self.oom_state = value
        self.oom_state_since = time.time()
        # Phase 7: also stamp the dedicated supervisor-readable field.
        # Only stamp on actual transitions (old != new) — repeats of
        # the same state shouldn't reset the supervisor's TTL clock.
        if old != value:
            self.oom_state_changed_at = self.oom_state_since
        if reason:
            self.oom_last_reason = reason
        self._record_event(
            f"oom_state={self.oom_state}",
            old=old, new=self.oom_state, source=source, reason=reason,
        )
        if old != self.oom_state:
            logger.info(
                f"[gpu-bundle:{self.gpu_id}] oom_state: {old} -> {self.oom_state} "
                f"(source={source}, reason={reason!r})"
            )

    def record_oom_event(self, reason: str, job_id: str = "") -> None:
        """Record an OOM event on this GPU. Bumps counters and timestamps.

        Does NOT change oom_state — the caller decides whether this is a
        new detection (→ "detected"), a recovery-in-progress marker, etc.
        The only side effect on oom_state is: if we're in a "happy" state
        (idle or restored) we leave it alone; if the caller wants to move
        to "detected" they should call set_oom_state("detected", ...) right
        after.
        """
        self.oom_event_count += 1
        self.oom_last_event_ts = time.time()
        if reason:
            self.oom_last_reason = reason
        if job_id:
            self.oom_active_recovery_job_id = job_id
        # Track the failure in the bounded window for permanent-failure detection
        self.oom_recent_failure_times.append(time.time())
        self._record_event(
            "oom_event",
            reason=reason, job_id=job_id,
            count=self.oom_event_count,
        )
        logger.info(
            f"[gpu-bundle:{self.gpu_id}] OOM event recorded "
            f"(count={self.oom_event_count}, reason={reason!r}, job_id={job_id!r})"
        )

    def enqueue(self, bundle_name: str, priority: int, request_data: dict) -> None:
        """Add a request to this GPU's priority queue, sorted by priority."""
        import bisect
        entry = {
            "bundle_name": bundle_name,
            "priority": priority,
            "enqueued_at": time.time(),
            "request_data": request_data,
        }
        # Insert in priority order: higher priority first, FIFO within same priority
        # Sort key: (-priority, +timestamp)
        self.priority_queue.append(entry)
        self.priority_queue.sort(key=lambda e: (-e["priority"], e["enqueued_at"]))
        logger.debug(
            f"GPU[{self.gpu_id}]: enqueued {bundle_name} priority={priority} "
            f"(queue depth: {len(self.priority_queue)})"
        )

    def peek_next(self) -> dict | None:
        """Look at the highest-priority item without removing it."""
        if self.priority_queue:
            return self.priority_queue[0]
        return None

    def dequeue_next(self) -> dict | None:
        """Remove and return the highest-priority item."""
        if self.priority_queue:
            entry = self.priority_queue.pop(0)
            logger.debug(
                f"GPU[{self.gpu_id}]: dequeued {entry['bundle_name']} "
                f"priority={entry['priority']}"
            )
            return entry
        return None

    def start_drain(self) -> None:
        """Mark GPU as draining — stop accepting new requests for current bundle."""
        self.draining = True
        self.drain_started_at = time.time()
        self._drain_event.clear()
        self.state = "draining"
        logger.info(f"GPU[{self.gpu_id}]: drain started (pending={self.pending_requests})")

    async def wait_drain(self, timeout: float = DRAIN_TIMEOUT) -> bool:
        """Wait for all pending requests to complete, or timeout.

        Returns True if drained successfully, False on timeout.
        """
        if self.pending_requests == 0:
            logger.info(f"GPU[{self.gpu_id}]: no pending requests — drain immediate")
            self.draining = False
            self.drain_started_at = None
            self._drain_event.set()
            return True

        logger.info(
            f"GPU[{self.gpu_id}]: waiting for {self.pending_requests} "
            f"pending request(s) to complete (timeout={timeout}s)"
        )
        try:
            await asyncio.wait_for(self._drain_event.wait(), timeout=timeout)
            logger.info(f"GPU[{self.gpu_id}]: drain complete")
            return True
        except asyncio.TimeoutError:
            logger.warning(
                f"GPU[{self.gpu_id}]: drain timeout after {timeout}s "
                f"({self.pending_requests} still pending)"
            )
            return False

    def request_started(self) -> None:
        """Called when a request begins processing on this GPU."""
        self.pending_requests += 1

    def request_finished(self) -> None:
        """Called when a request finishes processing on this GPU."""
        self.pending_requests = max(0, self.pending_requests - 1)
        if self.pending_requests == 0 and self.draining:
            self._drain_event.set()

    def to_dict(self) -> dict:
        """Serialize for state persistence."""
        return {
            "gpu_id": self.gpu_id,
            "loaded_bundle": self.loaded_bundle,
            "bundle_priority": self.bundle_priority,
            "draining": self.draining,
            "drain_started_at": self.drain_started_at,
            "pending_requests": self.pending_requests,
            "state": self.state,
            "queue_depth": len(self.priority_queue),
            "queue_items": [
                {"bundle": e["bundle_name"], "priority": e["priority"],
                 "enqueued_at": e["enqueued_at"]}
                for e in self.priority_queue
            ],
            # ── Phase 0: unified fields ──────────────────────────────
            "loaded_bundles": list(self.loaded_bundles),
            "evicting": self.evicting,
            "current_priority": self.current_priority,
            "loading": self.loading,
            # ── Phase 4g: idle-bundle auto-eviction activity timestamp ───
            "last_activity_at": self.last_activity_at,
            # ── Phase 5.2.36: in-flight worker counter (state_version bump → 5) ─
            "worker_in_flight": self.worker_in_flight,
            # ── Phase 1: OOM fields (state_version bump → 2) ──────────
            "state_version": BUNDLE_STATE_SCHEMA_VERSION,
            "oom_event_count": self.oom_event_count,
            "oom_recovery_count": self.oom_recovery_count,
            "oom_permanent_failure_count": self.oom_permanent_failure_count,
            "oom_state": self.oom_state,
            "oom_state_since": self.oom_state_since,
            "oom_last_event_ts": self.oom_last_event_ts,
            "oom_last_reason": self.oom_last_reason,
            "oom_active_recovery_job_id": self.oom_active_recovery_job_id,
            "oom_retry_attempted": self.oom_retry_attempted,
            "oom_recent_failure_times": list(self.oom_recent_failure_times),
            # ── Phase 5/7: OOM-implicated service + state-change timestamp ──
            # state_version bump → 3. oom_last_service_name is set by the
            # WorkerPool right before _handle_oom_event so _resolve_service_for_gpu
            # can recover the offending service even when the GPU has no
            # loaded_bundle recorded yet. oom_state_changed_at mirrors
            # oom_state_since and is read by the supervisor's TTL gate.
            "oom_last_service_name": self.oom_last_service_name,
            "oom_state_changed_at": self.oom_state_changed_at,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "GpuBundleState":
        """Deserialize from persisted state.

        Reads ``state_version`` and runs migration when an older shape is
        detected.

        Migration history:
          v1 (Phase 0 baseline, no OOM fields): OOM fields stay at __init__
              defaults; logged once per GPU at load.
          v2 (Phase 1, full OOM state machine): same as v3 except no
              ``oom_last_service_name`` / ``oom_state_changed_at`` keys.
              Initialized to defaults on load.
          v3 (Phase 5/7, OOM-implicated service tracker + state-change
              timestamp): the current shape written by to_dict().

        Newer-than-current versions are accepted as-is and logged.
        """
        gpu = cls(data.get("gpu_id", "unknown"))
        gpu.loaded_bundle = data.get("loaded_bundle")
        gpu.bundle_priority = data.get("bundle_priority", 0)
        gpu.draining = data.get("draining", False)
        gpu.drain_started_at = data.get("drain_started_at")
        gpu.pending_requests = data.get("pending_requests", 0)
        gpu.state = data.get("state", "idle")
        # ── Phase 0: backward-compat defaults for new fields ────────
        gpu.loaded_bundles = list(data.get("loaded_bundles") or [])
        gpu.evicting = bool(data.get("evicting", False))
        gpu.current_priority = int(data.get("current_priority", 0))
        gpu.loading = bool(data.get("loading", False))
        gpu.last_activity_at = float(data.get("last_activity_at", 0.0))
        gpu.worker_in_flight = int(data.get("worker_in_flight", 0) or 0)
        # ── State-shape migration gate ────────────────────────────
        # v1 → v2: OOM fields added. v2 → v3: oom_last_service_name +
        # oom_state_changed_at added. v3 → v4: last_activity_at added.
        # Newer-than-4 is accepted as-is and logged.
        saved_version = int(data.get("state_version", 1))
        if saved_version < 2:
            logger.info(
                f"[gpu-bundle:{gpu.gpu_id}] migrating state.json v{saved_version} → v2 "
                f"(OOM fields initialized to defaults)"
            )
        if saved_version < 3:
            # v3 adds oom_last_service_name + oom_state_changed_at. v2 files
            # never had them; default them so downstream consumers (the
            # supervisor's TTL gate, _resolve_service_for_gpu) see sane values.
            logger.info(
                f"[gpu-bundle:{gpu.gpu_id}] migrating state.json v{saved_version} → v3 "
                f"(oom_last_service_name + oom_state_changed_at initialized to defaults)"
            )
        if saved_version < 4:
            # v4 adds last_activity_at. v3 files never had it; default to 0.0
            # so auto-evict treats the bundle as needing an activity stamp.
            logger.info(
                f"[gpu-bundle:{gpu.gpu_id}] migrating state.json v{saved_version} → v4 "
                f"(last_activity_at initialized to 0.0)"
            )
        if saved_version < BUNDLE_STATE_SCHEMA_VERSION:
            # v5 adds worker_in_flight. v4 files never had it; default to 0
            # so auto-evict treats the bundle as not having an in-flight
            # worker (the safe behaviour — eviction proceeds normally).
            logger.info(
                f"[gpu-bundle:{gpu.gpu_id}] migrating state.json v{saved_version} → v5 "
                f"(worker_in_flight initialized to 0)"
            )
        elif saved_version > BUNDLE_STATE_SCHEMA_VERSION:
            # Plan 04 §4: this nested per-GPU bundle state schema is v5. An
            # old binary on a newer file must say "up to v5", not "up to v4"
            # (that copy-paste bug is what the plan flagged as a confirmed
            # contradiction against the top-level manager state which is
            # also a v-series schema with its own version).
            logger.warning(
                f"[gpu-bundle:{gpu.gpu_id}] state.json is v{saved_version}, this binary "
                f"understands up to v{BUNDLE_STATE_SCHEMA_VERSION} — proceeding with best-effort load"
            )
        gpu.state_version = max(saved_version, BUNDLE_STATE_SCHEMA_VERSION)
        gpu.oom_event_count = int(data.get("oom_event_count", 0))
        gpu.oom_recovery_count = int(data.get("oom_recovery_count", 0))
        gpu.oom_permanent_failure_count = int(data.get("oom_permanent_failure_count", 0))
        gpu.oom_state = data.get("oom_state", "idle")
        # Validate: bad persisted state can't wedge us
        if gpu.oom_state not in cls._VALID_OOM_STATES:
            logger.warning(
                f"[gpu-bundle:{gpu.gpu_id}] persisted oom_state={gpu.oom_state!r} "
                f"is not in valid set; coercing to 'idle'"
            )
            gpu.oom_state = "idle"
        gpu.oom_state_since = float(data.get("oom_state_since", 0.0))
        gpu.oom_last_event_ts = float(data.get("oom_last_event_ts", 0.0))
        gpu.oom_last_reason = data.get("oom_last_reason", "")
        gpu.oom_active_recovery_job_id = data.get("oom_active_recovery_job_id", "")
        gpu.oom_retry_attempted = bool(data.get("oom_retry_attempted", False))
        # The deque maxlen is set in __init__; .extend() will respect it.
        saved_failures = data.get("oom_recent_failure_times") or []
        gpu.oom_recent_failure_times.extend(float(t) for t in saved_failures)
        # ── Phase 5/7: OOM-implicated service + state-change timestamp ──
        # Use .get() with explicit defaults so a v2 file (no key at all)
        # initializes cleanly. None / 0.0 are the documented defaults.
        gpu.oom_last_service_name = data.get("oom_last_service_name", None)
        gpu.oom_state_changed_at = float(data.get("oom_state_changed_at", 0.0))
        # Note: queue items are not restored — they're ephemeral
        return gpu


# ── Per-GPU State Registry ────────────────────────────────────────

_gpu_states: dict[str, GpuBundleState] = {}  # gpu_id -> GpuBundleState


# ── Cross-GPU Bundle Coordination ──────────────────────────────────

class BundleCoordinator:
    """Tracks per-bundle-job GPU readiness for cross-GPU coordination.

    When a bundle spans multiple GPUs (e.g. sulphur-diffusion on gpu_primary
    linked to sulphur-encoder on gpu_secondary), all GPUs must load their components
    before the bundle can start.  This coordinator tracks which GPUs have
    finished loading and resolves the shared Future when all are ready.
    """

    def __init__(self):
        self._active_jobs: dict[str, dict] = {}  # bundle_job_id -> info
        self._lock = asyncio.Lock()

    async def register_job(
        self,
        bundle_job_id: str,
        bundle_name: str,
        gpu_ids: list[str],
        priority: int,
        request_data: dict,
    ) -> asyncio.Future:
        """Register a new bundle job spanning multiple GPUs.

        Returns a Future that resolves when ALL GPUs are ready.
        """
        async with self._lock:
            loop = asyncio.get_event_loop()
            future = loop.create_future()
            self._active_jobs[bundle_job_id] = {
                "bundle_name": bundle_name,
                "gpu_ids": set(gpu_ids),
                "ready_gpus": set(),
                "priority": priority,
                "request_data": request_data,
                "future": future,
                "created_at": time.time(),
            }
            logger.info(
                f"BundleCoordinator: registered job {bundle_job_id} "
                f"for '{bundle_name}' across GPUs {gpu_ids}"
            )
            return future

    async def mark_gpu_ready(self, bundle_job_id: str, gpu_id: str) -> bool:
        """Mark a GPU as ready for a bundle job.

        Returns True if ALL GPUs are now ready (bundle can start).
        """
        async with self._lock:
            job = self._active_jobs.get(bundle_job_id)
            if not job:
                logger.warning(
                    f"BundleCoordinator: mark_gpu_ready for unknown job {bundle_job_id}"
                )
                return False
            job["ready_gpus"].add(gpu_id)
            all_ready = job["ready_gpus"] >= job["gpu_ids"]
            logger.info(
                f"BundleCoordinator: job {bundle_job_id} GPU {gpu_id} ready "
                f"({len(job['ready_gpus'])}/{len(job['gpu_ids'])}) — all_ready={all_ready}"
            )
            return all_ready

    async def complete_job(self, bundle_job_id: str, success: bool = True) -> None:
        """Resolve the Future and clean up the job."""
        async with self._lock:
            job = self._active_jobs.pop(bundle_job_id, None)
            if job and not job["future"].done():
                if success:
                    job["future"].set_result(True)
                else:
                    job["future"].set_exception(
                        RuntimeError(f"Bundle job {bundle_job_id} failed")
                    )
            logger.info(
                f"BundleCoordinator: job {bundle_job_id} completed (success={success})"
            )

    def is_gpu_ready(self, bundle_job_id: str, gpu_id: str) -> bool:
        """Check if a specific GPU is ready for a bundle job."""
        job = self._active_jobs.get(bundle_job_id)
        if not job:
            return False
        return gpu_id in job["ready_gpus"]

    def get_all_ready(self, bundle_job_id: str) -> set:
        """Return set of ready GPUs for a bundle job."""
        job = self._active_jobs.get(bundle_job_id)
        if not job:
            return set()
        return job["ready_gpus"].copy()

    def get_job_info(self, bundle_job_id: str) -> dict | None:
        """Get full job info for a bundle job."""
        job = self._active_jobs.get(bundle_job_id)
        if not job:
            return None
        return {
            "bundle_name": job["bundle_name"],
            "gpu_ids": list(job["gpu_ids"]),
            "ready_gpus": list(job["ready_gpus"]),
            "priority": job["priority"],
            "created_at": job["created_at"],
        }

    def cleanup_stale(self, max_age: float = 600.0) -> int:
        """Remove jobs older than max_age seconds. Returns count removed."""
        now = time.time()
        stale = [
            bid for bid, job in self._active_jobs.items()
            if (now - job["created_at"]) > max_age
        ]
        for bid in stale:
            job = self._active_jobs.pop(bid, None)
            if job and not job["future"].done():
                job["future"].set_exception(
                    RuntimeError(f"Bundle job {bid} timed out after {max_age}s")
                )
            logger.warning(f"BundleCoordinator: cleaned up stale job {bid}")
        return len(stale)


bundle_coordinator = BundleCoordinator()


# ── OOM Detection Functions (Phase 2) ───────────────────────────────
# All detection functions live at module scope so they can be imported and
# unit-tested. They are purely additive — Phase 2 records events; Phase 3
# will add the recovery pipeline that transitions states.

_OOM_PATTERN = re.compile(OOM_DETECTION_REGEX)


def _detect_oom_in_history(
    status_str: str = "",
    messages: list | None = None,
    response_body: str = "",
    status_code: int = 200,
    model_size_hint_gb: float = 0.0,
    vram_free_mib: int = 0,
    vram_total_mib: int = 0,
) -> dict | None:
    """Detect OOM from a ComfyUI / ACE-Step / generic generation response.

    Returns a dict with detection details if OOM is suspected, None otherwise.

    Sources (any one triggers):
    1. status_str == 'error' AND any message matches OOM_DETECTION_REGEX
    2. response_body matches OOM_DETECTION_REGEX
    3. status_code is 5xx AND vram_free_mib < OOM_VRAM_PRESSURE_THRESHOLD_MIB
    4. model_size_hint_gb * 1024 > vram_total_mib * 0.9 (model too big to fit)

    Per adversarial check #7: do NOT use bare 'OOM' substring. The regex
    OOM_DETECTION_REGEX requires the OOM marker to be preceded by cuda/HIP/
    RuntimeError/torch.cuda to avoid false positives.
    """
    messages = messages or []

    # Source 1: status_str=error AND messages match OOM regex
    if status_str == "error":
        for msg in messages:
            msg_text = str(msg)
            if _OOM_PATTERN.search(msg_text):
                return {
                    "source": "history_messages",
                    "reason": "status_str=error, message matched OOM regex",
                    "details": msg_text[:500],
                }

    # Source 2: response body matches OOM regex
    if response_body:
        match = _OOM_PATTERN.search(response_body)
        if match:
            return {
                "source": "response_body",
                "reason": "response body matched OOM regex",
                "details": match.group(0)[:200],
            }

    # Source 3: 5xx + low VRAM (corroborates a backend OOM)
    if status_code >= 500 and vram_free_mib > 0 and vram_free_mib < OOM_VRAM_PRESSURE_THRESHOLD_MIB:
        return {
            "source": "5xx_low_vram",
            "reason": (
                f"HTTP {status_code} with VRAM {vram_free_mib} MiB free "
                f"(< {OOM_VRAM_PRESSURE_THRESHOLD_MIB})"
            ),
            "details": f"status={status_code}, free={vram_free_mib} MiB",
        }

    # Source 4: model size too big to fit
    if model_size_hint_gb > 0 and vram_total_mib > 0:
        required_mib = model_size_hint_gb * 1024
        if required_mib > vram_total_mib * 0.9:
            return {
                "source": "model_too_large",
                "reason": (
                    f"Model {model_size_hint_gb:.1f} GB > 90% of VRAM "
                    f"{vram_total_mib/1024:.1f} GB"
                ),
                "details": f"required={required_mib:.0f} MiB, available={vram_total_mib*0.9:.0f} MiB",
            }

    # A transport/server failure alone is not evidence of GPU memory pressure.
    # Reporting it as OOM triggers destructive recovery of otherwise healthy
    # model owners. Require one of the corroborated sources above.
    return None


def _verify_oom_via_vram(gpu_id: str) -> dict:
    """Confirm OOM by reading the cached VRAM snapshot for a GPU.

    Returns:
        {gpu_id, available, free_mib, used_mib, total_mib, pressure, critical}
        where `pressure` is True if free < OOM_VRAM_PRESSURE_THRESHOLD_MIB and
        `critical` is True if free < OOM_VRAM_CRITICAL_THRESHOLD_MIB.

        If the snapshot cannot be obtained the function returns
        {gpu_id, available: False} (or {gpu_id, available: False, error: str}).
    """
    try:
        snapshot = None
        vram_mod = globals().get("vram")
        if vram_mod is not None and hasattr(vram_mod, "get_snapshot"):
            try:
                snapshot = vram_mod.get_snapshot(gpu_id)
            except Exception as e:
                logger.debug(f"[oom-detect] vram.get_snapshot({gpu_id}) raised: {e}")
        # Fallback: read from the cached poll result
        if snapshot is None:
            cache = globals().get("_vram_cache") or {}
            for gpu in cache.get("gpus") or []:
                # Match by gpu_id string or card name; the polled cache
                # uses "card" + "pci_address" rather than "gpu_id".
                if gpu.get("gpu_id") == gpu_id or gpu.get("card") == gpu_id:
                    snapshot = gpu
                    break
        if snapshot is None:
            return {"gpu_id": gpu_id, "available": False}
        free = int(snapshot.get("free_mib") or snapshot.get("free_vram_mib") or 0)
        total = int(snapshot.get("total_mib") or snapshot.get("total_vram_mib") or 0)
        used = int(snapshot.get("used_mib") or snapshot.get("vram_used_mib") or (total - free if total else 0))
        return {
            "gpu_id": gpu_id,
            "available": True,
            "free_mib": free,
            "used_mib": used,
            "total_mib": total,
            "pressure": free > 0 and free < OOM_VRAM_PRESSURE_THRESHOLD_MIB,
            "critical": free > 0 and free < OOM_VRAM_CRITICAL_THRESHOLD_MIB,
        }
    except Exception as e:
        logger.debug(f"[oom-detect] vram verify failed for {gpu_id}: {e}")
        return {"gpu_id": gpu_id, "available": False, "error": str(e)}


def _detect_silent_oom_via_dmesg(since_ts: float = 0.0) -> list[dict]:
    """Scan dmesg for OOM-killer events on Linux.

    Returns a list of dicts with keys: ts, pid, name, gpu_hint, raw_line.
    Called by the watchdog to catch process kills that did not surface to
    the worker (e.g. the kernel reaped a backend process before its 5xx
    reached the worker).

    Recognised patterns:
      - 'Out of memory: Killed process <pid> (<name>)' (Linux kernel OOM killer)
      - 'memory cgroup out of memory: Killed process <pid> (<name>)' (cgroup OOM)
      - 'oom-kill:constraint=CONSTRAINT_MEMCG ... Killed process <pid> (<name>)'
        (constraint-based OOM)

    The kernel OOM-killer message format changed in 5.14+ and may include
    additional fields; we only require pid+name for our purposes.
    """
    events: list[dict] = []
    try:
        # dmesg --since only works on journald; fall back to last 200 lines
        args = None
        if since_ts and since_ts > 0:
            try:
                ago = max(1, int(time.time() - since_ts))
                args = ["dmesg", "--since", f"{ago}s ago"]
            except Exception:
                args = None
        if args is None:
            args = ["dmesg", "-T", "-l", "emerg,alert,crit,err,warn"]
        result = subprocess.run(
            args, capture_output=True, text=True, timeout=5,
        )
        if result.returncode != 0 or not (result.stdout or "").strip():
            # Fallback: just get last 200 lines
            result = subprocess.run(
                ["dmesg", "-T"], capture_output=True, text=True, timeout=5,
            )
            lines = (result.stdout or "").splitlines()[-200:]
        else:
            lines = (result.stdout or "").splitlines()
        oom_patterns = [
            re.compile(r"Out of memory: Killed process (\d+) \((\S+)\)", re.IGNORECASE),
            re.compile(r"memory cgroup out of memory: Killed process (\d+) \((\S+)\)", re.IGNORECASE),
            re.compile(r"oom-kill:constraint=CONSTRAINT_MEMCG.*?Killed process (\d+) \((\S+)\)", re.IGNORECASE),
        ]
        for line in lines:
            for pat in oom_patterns:
                m = pat.search(line)
                if m:
                    try:
                        pid = int(m.group(1))
                    except (TypeError, ValueError):
                        pid = 0
                    name = m.group(2) or ""
                    gpu_hint = "cpu"
                    if any(x in name.lower() for x in ("python", "comfyui", "main.py", "sd-server", "llama", "ideogram", "sulphur", "acestep", "gemma", "qwen")):
                        gpu_hint = "gpu_likely"
                    events.append({
                        "ts": time.time(),
                        "pid": pid,
                        "name": name,
                        "gpu_hint": gpu_hint,
                        "raw_line": line[:300],
                    })
                    break
    except Exception as e:
        logger.debug(f"[oom-detect] dmesg scan failed: {e}")
    return events


# Module-level ring buffer of recent OOM events (capped) for /health surfacing.
_recent_oom_events_log: deque = deque(maxlen=1000)

# Module-level state for the dmesg OOM-killer scan inside the VRAM pusher
# loop. Kept here so the watcher can reset them on restart and the linter
# sees the names as bound at module load time.
_oom_dmesg_counter: int = 0
_last_dmesg_ts: float = 0.0

# ── Phase 3: OOM Recovery Coordination ──────────────────────────────
# Per adversarial #4: an asyncio.Lock serialises concurrent recoveries so a
# second OOM event on the OTHER GPU does not race the first recovery's
# multi-GPU eviction check. Without this, two near-simultaneous OOMs could
# each see "other gpu is idle" and both proceed to evict — racing the same
# bundles and corrupting state.
#
# Per adversarial #5: a per-service lock prevents _force_recover_failed_service
# from being re-entered for the same service. The original code could
# recursively unload the same bundle twice (e.g. scheduler -> pipeline ->
# scheduler -> pipeline), each call wiping state the other call needed.
#
# We bind at module load with a Lazy fallback: at import time there is no
# running event loop, so asyncio.Lock() would fail on Python <3.10 (where
# the constructor requires a running loop). Using a factory + lazy dict
# pattern means the first call site pays the init cost inside the running
# loop, and the names are bound so static analysers don't complain.
if hasattr(asyncio, "Lock"):
    _oom_lock: "asyncio.Lock | None" = asyncio.Lock()
else:
    _oom_lock = None
_oom_recovery_in_progress: dict[str, float] = {}    # gpu_id -> started_ts
_force_recover_locks: dict[str, "asyncio.Lock"] = {}  # service_name -> lock

# Phase 4: watchdog heartbeat timestamp. Updated by _oom_recovery_watchdog_loop
# on every poll (every OOM_WATCHDOG_POLL_INTERVAL_S). /health exposes the age
# of the last heartbeat so operators can tell at a glance whether the watchdog
# is alive. Phase 1 known issue: previously the heartbeat was implicit; this
# makes it explicit and queryable.
_last_oom_heartbeat_ts: float = 0.0

# ── Phase 5: OOM Redis Pool + Dead-Letter + Rate Limit State ────────
# Per adversarial #11: dead-letter list is a Redis sorted set, capped at
# _OOM_DEAD_LETTER_CAP, TTL _OOM_DEAD_LETTER_TTL_S. Reuses the existing
# _queue_redis client if available; otherwise opens a dedicated connection.
_oom_redis_pool = None  # Initialized in _init_oom_redis (called from create_app)

# Per adversarial #26: rate-limit oom_recovery_force_reset to once per
# OOM_FORCE_RESET_MIN_INTERVAL_S per GPU. Stored as gpu_id -> last-call ts.
_oom_force_reset_last_call_ts: dict[str, float] = {}

# Cached dead-letter list (refreshed every ~30s by watchdog). /health reads
# len(_dead_letter_cache) so the sync /health handler doesn't have to await
# Redis on every call.
_dead_letter_cache: list = []
# Wall-clock timestamp of the last SUCCESSFUL cache refresh. 0.0 means the
# watchdog has not yet refreshed since process start (or the last refresh
# failed). /health and the websocket full-state payload expose this so
# operators can tell "fresh data" from "stale data, possibly from before
# the last restart".
_dead_letter_cache_refresh_ts: float = 0.0


_force_recover_locks: dict[str, "asyncio.Lock"] = {}  # service_name -> lock
_bundle_load_locks: dict[str, "asyncio.Lock"] = {}     # bundle_name -> lock (Phase 4g)
_bundle_admission_locks: dict[str, "asyncio.Lock"] = {}


def _get_force_recover_lock(service_name: str) -> "asyncio.Lock":
    """Per-service lock for _force_recover_failed_service to prevent reentrancy.

    Per adversarial #5: returning the same asyncio.Lock instance for a given
    service_name means concurrent callers (pipeline + watchdog + worker) will
    queue rather than race. Creates the lock on first use so we don't need a
    running event loop at import time.
    """
    lock = _force_recover_locks.get(service_name)
    if lock is None:
        lock = asyncio.Lock()
        _force_recover_locks[service_name] = lock
    return lock


def _get_bundle_load_lock(bundle_name: str) -> "asyncio.Lock":
    """Per-bundle lock for _load_bundle to prevent concurrent load races."""
    lock = _bundle_load_locks.get(bundle_name)
    if lock is None:
        lock = asyncio.Lock()
        _bundle_load_locks[bundle_name] = lock
    return lock


def _get_bundle_admission_lock(bundle_name: str) -> "asyncio.Lock":
    """Serialize every admission path for a bundle, including eviction."""
    lock = _bundle_admission_locks.get(bundle_name)
    if lock is None:
        lock = asyncio.Lock()
        _bundle_admission_locks[bundle_name] = lock
    return lock


# ---------------------------------------------------------------------------
# Slice B — physical-resource-set admission locks
# ---------------------------------------------------------------------------
# Krea and Qwen both touch the SAME physical GPU pair ({gpu_primary, gpu_secondary}).
# A per-bundle lock is insufficient: two bundles sharing a physical resource
# can still race. The public lock remains cached by the sorted resource set,
# but each set lock is composed from canonical per-device locks. Consequently
# a dual-GPU transition conflicts with either single-GPU transition that
# intersects it, while genuinely disjoint sets can proceed concurrently.
#
# These are in-process transition locks. Durable cross-process ownership is
# provided separately by BundleLifecycleController and must be added before a
# second controller is allowed to mutate the same host.
# ---------------------------------------------------------------------------

class _PhysicalResourceSetLock:
    """Acquire all canonical resource locks in a deterministic order."""

    def __init__(self, resource_ids: tuple[str, ...], atoms: tuple["asyncio.Lock", ...]):
        self.resource_ids = resource_ids
        self._atoms = atoms
        self._acquired = False

    def locked(self) -> bool:
        return self._acquired or any(lock.locked() for lock in self._atoms)

    async def __aenter__(self):
        acquired: list["asyncio.Lock"] = []
        try:
            for lock in self._atoms:
                await lock.acquire()
                acquired.append(lock)
        except BaseException:
            for lock in reversed(acquired):
                lock.release()
            raise
        self._acquired = True
        return self

    async def __aexit__(self, *_exc):
        for lock in reversed(self._atoms):
            if lock.locked():
                lock.release()
        self._acquired = False


_physical_resource_locks: dict[tuple[str, ...], _PhysicalResourceSetLock] = {}
_physical_resource_atom_locks: dict[str, "asyncio.Lock"] = {}


def _get_physical_resource_lock(
    gpu_ids: "list[str] | tuple[str, ...] | set[str]",
) -> _PhysicalResourceSetLock:
    """Return a composite lock for the SORTED physical resource ID set.

    Two bundles that touch the same physical GPU set resolve to the SAME
    composite regardless of ordering or bundle name. Intersecting sets share
    their per-device atom locks, so a dual-GPU request conflicts with either
    single-GPU request that touches one of its devices. A disjoint set has no
    shared atoms and can proceed concurrently.
    """
    normalized = tuple(sorted(
        {str(g) for g in gpu_ids if g}
    ))
    if not normalized:
        raise ValueError(
            "_get_physical_resource_lock requires at least one GPU id"
        )
    lock = _physical_resource_locks.get(normalized)
    if lock is None:
        atoms = tuple(
            _physical_resource_atom_locks.setdefault(resource_id, asyncio.Lock())
            for resource_id in normalized
        )
        lock = _PhysicalResourceSetLock(normalized, atoms)
        _physical_resource_locks[normalized] = lock
    return lock


def _reset_physical_resource_locks_for_tests() -> None:
    """Test helper: clear the physical-resource lock cache."""
    _physical_resource_locks.clear()
    _physical_resource_atom_locks.clear()


def _bundle_physical_gpu_set(
    bundle_name: str, bundles: dict | None = None
) -> tuple[str, ...]:
    """Return the sorted physical GPU set touched by *bundle_name*.

    Walks ``linked_to`` and ``linked_from`` so the result spans every
    physical GPU the bundle needs to own. Used to derive the physical
    admission lock key.
    """
    if bundles is None:
        bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name) or {}
    primary = bundle.get("gpu_id")
    gpus: list[str] = []
    if primary:
        gpus.append(str(primary))
    for linked_name in _get_linked_bundles(bundle_name, bundles=bundles):
        lgid = (bundles.get(linked_name) or {}).get("gpu_id")
        if lgid and lgid not in gpus:
            gpus.append(str(lgid))
    return tuple(sorted(gpus))


def _recent_oom_events(limit: int = 100) -> list[dict]:
    """Return recent OOM events for the /health endpoint."""
    return list(_recent_oom_events_log)[-limit:]


# ── Phase 5: OOM Redis pool lifecycle ──────────────────────────────
async def _init_oom_redis():
    """Initialize the OOM Redis pool. Called from create_app on_startup.

    Per adversarial #11: dead-letter list lives in Redis (sorted set,
    capped, TTL). We prefer to reuse the existing _queue_redis client
    (synchronous redis-py) when available — that keeps the lifecycle tied
    to a single, already-tested connection. If _queue_redis is not set
    (Redis unavailable at create_app time), we open a dedicated client.
    """
    global _oom_redis_pool
    try:
        existing = globals().get("_queue_redis") or globals().get("redis_client")
        if existing is not None:
            _oom_redis_pool = existing
            logger.info("[oom-redis] Reusing existing _queue_redis client for dead-letter store")
            return
        # Fallback: open a dedicated client using the same credential source
        # as the queue engine; this must not drift from the shared client.
        _oom_redis_pool = _redis_mod.Redis(**_redis_connection_kwargs())
        await asyncio.to_thread(_oom_redis_pool.ping)
        logger.info("[oom-redis] Connected to dedicated redis://localhost:6379/0 client")
    except Exception as e:
        logger.warning(f"[oom-redis] Failed to initialize: {e}")
        _oom_redis_pool = None


async def _close_oom_redis():
    """Close the OOM Redis pool. Called on app shutdown.

    No-op if we reused the shared _queue_redis client (which is owned by
    the queue engine and closed elsewhere).
    """
    global _oom_redis_pool
    if _oom_redis_pool is None:
        return
    shared = globals().get("_queue_redis")
    if _oom_redis_pool is shared:
        # Shared client — don't close it here, owner handles lifecycle.
        _oom_redis_pool = None
        return
    try:
        await asyncio.to_thread(_oom_redis_pool.close)
    except Exception:
        pass
    _oom_redis_pool = None


def _dead_letter_identity(entry: dict) -> tuple[str, str] | None:
    """Stable dead-letter identity; blank job IDs are intentionally unkeyed."""
    if not isinstance(entry, dict):
        return None
    job_id = str(entry.get("job_id", "")).strip()
    if not job_id:
        return None
    return job_id, str(entry.get("gpu_id", "")).strip()


def _matching_dead_letter_members(raw_members: list, job_id: str, gpu_id: str) -> list:
    target = (str(job_id).strip(), str(gpu_id).strip())
    matches = []
    if not target[0]:
        return matches
    for raw in raw_members:
        try:
            text = raw.decode("utf-8") if isinstance(raw, bytes) else raw
            if _dead_letter_identity(json.loads(text)) == target:
                matches.append(raw)
        except (TypeError, ValueError, UnicodeDecodeError, json.JSONDecodeError):
            continue
    return matches


# ── Phase 5: Dead-letter list management ────────────────────────────
async def _add_to_dead_letter(job_id: str, gpu_id: str, reason: str, last_state: str) -> bool:
    """Add a job to the dead-letter list (Redis sorted set, capped, TTL).

    Per adversarial #11: sorted set keyed by timestamp (newest = highest
    score), trimmed to the most recent _OOM_DEAD_LETTER_CAP entries, with
    a whole-set TTL of _OOM_DEAD_LETTER_TTL_S so abandoned lists expire
    automatically. Best-effort: returns False if Redis is unreachable.
    """
    if _oom_redis_pool is None:
        return False
    try:
        score = time.time()
        entry = {
            "job_id": job_id,
            "gpu_id": gpu_id,
            "reason": reason,
            "last_state": last_state,
            "ts": score,
        }
        member = json.dumps(entry, sort_keys=True, separators=(",", ":"))
        # Replace prior records for the same job/GPU identity before inserting
        # the latest terminal state. This prevents one recovery from inflating
        # retained history when multiple failure branches report it.
        raw_members = await asyncio.to_thread(
            _oom_redis_pool.zrange, OOM_REDIS_DEAD_LETTER, 0, -1
        )
        duplicates = _matching_dead_letter_members(raw_members, job_id, gpu_id)
        if duplicates:
            await asyncio.to_thread(
                _oom_redis_pool.zrem, OOM_REDIS_DEAD_LETTER, *duplicates
            )
        # ZADD with score=ts; trim oldest entries if over cap (rank 0..-(CAP+1))
        await asyncio.to_thread(
            _oom_redis_pool.zadd, OOM_REDIS_DEAD_LETTER, {member: score}
        )
        await asyncio.to_thread(
            _oom_redis_pool.zremrangebyrank,
            OOM_REDIS_DEAD_LETTER, 0, -(_OOM_DEAD_LETTER_CAP + 1),
        )
        await asyncio.to_thread(
            _oom_redis_pool.expire, OOM_REDIS_DEAD_LETTER, _OOM_DEAD_LETTER_TTL_S
        )
        return True
    except Exception as e:
        logger.debug(f"[oom-dead-letter] Add failed: {e}")
        return False


async def _get_dead_letters(limit: int = 100) -> list[dict]:
    """Return the most recent dead-letter entries (newest first).

    Sorted set is keyed by score=ts; ZREVRANGE returns newest first.

    Returns an empty list if Redis is unreachable, but raises
    RuntimeError on a hard Redis error so callers can distinguish
    "no entries" from "Redis went away". The watchdog's
    ``_refresh_dead_letter_cache`` uses the raise to decide whether
    to stamp the refresh timestamp.
    """
    if _oom_redis_pool is None:
        return []
    try:
        raw = await asyncio.to_thread(
            _oom_redis_pool.zrevrange, OOM_REDIS_DEAD_LETTER, 0, limit - 1
        )
        return [json.loads(r) for r in raw]
    except Exception as e:
        logger.debug(f"[oom-dead-letter] Get failed: {e}")
        raise


async def _refresh_dead_letter_cache() -> int:
    """Refresh _dead_letter_cache from Redis. Returns count.

    Called by the watchdog every ~30s. /health reads len(_dead_letter_cache)
    so the sync handler doesn't have to await Redis.

    On a SUCCESSFUL refresh we also stamp ``_dead_letter_cache_refresh_ts``
    so /health and the websocket payload can compute cache_age_seconds
    without issuing a synchronous Redis call. On failure the timestamp is
    NOT advanced — operators can then see the data is stale.
    """
    global _dead_letter_cache, _dead_letter_cache_refresh_ts
    try:
        rows = await _get_dead_letters(limit=_OOM_DEAD_LETTER_CAP)
    except Exception as e:
        logger.debug(f"[oom-dead-letter] Cache refresh failed: {e}")
        return len(_dead_letter_cache)
    _dead_letter_cache = rows
    _dead_letter_cache_refresh_ts = time.time()
    return len(_dead_letter_cache)


# ── Plan 05: OOM dead-letter classification + atomic retry contract ──
# These helpers pin the safety contract from plan 05:
#   * historical records are immutable;
#   * the original job hash, queue-stream entry, and audit log are
#     never rewritten;
#   * a retry is a NEW job whose tracker, stream membership, and
#     idempotency key are created atomically (or not at all);
#   * classification and dry-run refuse (fail closed) when tracker /
#     payload / stream metadata is missing, or when a replayed
#     attempt already exists, or when the per-original attempt budget
#     is exhausted.
#
# The atomic retry is implemented as a single Redis EVAL — see
# _OOM_RETRY_LUA below. The Lua body covers all branches the test
# suite pins; the FakeRedis stand-in in
# ``scripts/test_oom_retry_contract.py`` mirrors the Lua steps in
# Python so the contract is testable without a live Redis.

# The Lua script that performs the atomic retry.  Returns a 3-element
# array; the first element is a status string the caller switches on.
# The script is intentionally idempotent: if a retry with the same
# idempotency key already exists, the same retry_id is returned and
# no new state is written.  If anything between the original
# validation and the stream append fails, MULTI/EXEC rolls back
# every write.
_OOM_RETRY_LUA = r"""
-- KEYS[1] = oom:retry:idem:{key}      (idempotency marker)
-- KEYS[2] = oom:retry:audit:{retry_id}  (audit hash; created on success)
-- KEYS[3] = oom:retry:stream:{orig_job_id}  (correlation set)
-- KEYS[4] = job:{new_job_id}          (new tracker)
-- KEYS[5] = dead-letter: stream key   (NOT the oom:dead_letters zset;
--              per plan 05 #4 the destination is a stream key
--              supplied by the caller; for OOM retries we use the
--              routing-group queue stream like a normal new job)

-- ARGV[1]  = idempotency_key
-- ARGV[2]  = retry_id
-- ARGV[3]  = new_job_id
-- ARGV[4]  = orig_job_id
-- ARGV[5]  = orig_dead_letter_member  (raw json from oom:dead_letters;
--              the original evidence, never rewritten)
-- ARGV[6]  = gpu_id
-- ARGV[7]  = attempt (int, string form)
-- ARGV[8]  = attempt_limit (int, string form)
-- ARGV[9]  = actor
-- ARGV[10] = reason
-- ARGV[11] = ts (unix seconds, string form)
-- ARGV[12] = payload_hash
-- ARGV[13] = artifact_refs (json-encoded list string)
-- ARGV[14] = service_name
-- ARGV[15] = routing_group
-- ARGV[16] = idem_ttl (int, string form)
-- ARGV[17] = original_error (string)

-- Step 0: idempotency. If the marker already exists, return the
-- stored retry_id WITHOUT writing any new state. Concurrent
-- retries with the same key collapse to one job.
local existing = redis.call('GET', KEYS[1])
if existing then
    return {'replayed', existing, ARGV[1]}
end

-- Step 1: preflight every key type before the first write. Redis Lua
-- errors do not roll back prior writes, so subsequent commands must
-- be made type-safe while EVAL supplies atomic isolation.
local expected = {'string', 'hash', 'set', 'hash', 'stream'}
for i = 1, 5 do
    local actual = redis.call('TYPE', KEYS[i])['ok']
    if actual ~= 'none' and actual ~= expected[i] then
        return {'type_mismatch', tostring(i), actual}
    end
end

-- Derive the attempt from authoritative correlation state inside this
-- EVAL, closing the race between distinct idempotency keys.
local attempt = redis.call('SCARD', KEYS[3]) + 1
local attempt_limit = tonumber(ARGV[8]) or 0
if attempt > attempt_limit then
    return {'budget_exceeded', tostring(attempt), tostring(attempt_limit)}
end

-- Step 2: SET the idempotency marker. If two callers race here,
-- only one wins (NX). The loser's GET above would have seen
-- nothing yet because it ran before this SET.
local set_ok = redis.call('SET', KEYS[1], ARGV[2], 'NX', 'EX', ARGV[16])
if not set_ok then
    local winner = redis.call('GET', KEYS[1])
    return {'replayed', winner or '', ARGV[1]}
end

-- Step 3: all remaining writes execute in this EVAL's atomic isolation
-- boundary after successful type preflight.

-- 3a: audit hash
redis.call('HSET', KEYS[2],
    'retry_id', ARGV[2],
    'new_job_id', ARGV[3],
    'orig_job_id', ARGV[4],
    'orig_dead_letter_member', ARGV[5],
    'gpu_id', ARGV[6],
    'attempt', tostring(attempt),
    'attempt_limit', ARGV[8],
    'actor', ARGV[9],
    'reason', ARGV[10],
    'ts', ARGV[11],
    'payload_hash', ARGV[12],
    'artifact_refs', ARGV[13],
    'service_name', ARGV[14],
    'routing_group', ARGV[15],
    'original_error', ARGV[17])

-- 3b: correlation set
redis.call('SADD', KEYS[3], ARGV[2])
redis.call('EXPIRE', KEYS[3], ARGV[16])
redis.call('EXPIRE', KEYS[2], ARGV[16])

-- 3c: new tracker hash
redis.call('HSET', KEYS[4],
    'job_id', ARGV[3],
    'orig_job_id', ARGV[4],
    'retry_id', ARGV[2],
    'retry_of', ARGV[4],
    'gpu_id', ARGV[6],
    'service_name', ARGV[14],
    'routing_group', ARGV[15],
    'status', 'queued',
    'submitted_at', ARGV[11],
    'attempt', tostring(attempt),
    'attempt_limit', ARGV[8],
    'payload_hash', ARGV[12],
    'artifact_refs', ARGV[13],
    'original_error', ARGV[17],
    'actor', ARGV[9],
    'reason', ARGV[10])
redis.call('EXPIRE', KEYS[4], 86400)

-- 3d: destination stream append. KEYS[5] is the queue stream key.
-- We use XADD so a single entry id is returned; tests pin that
-- the same new_job_id + retry_id round-trip through the audit
-- hash and tracker hash above.
local stream_id = redis.call('XADD', KEYS[5], '*',
    'job_id', ARGV[3],
    'orig_job_id', ARGV[4],
    'retry_id', ARGV[2],
    'gpu_id', ARGV[6],
    'service_name', ARGV[14],
    'routing_group', ARGV[15],
    'status', 'queued',
    'submitted_at', ARGV[11],
    'attempt', tostring(attempt),
    'payload_hash', ARGV[12],
    'artifact_refs', ARGV[13],
    'original_error', ARGV[17],
    'actor', ARGV[9],
    'reason', ARGV[10])

return {'submitted', ARGV[2], stream_id}
"""


def _oom_retry_lua_script() -> str:
    """Return the Lua source for the atomic-retry EVAL.

    Wrapped so tests can monkeypatch a different body (the FakeRedis
    stand-in already has its own reference implementation, but the
    test suite still pins the text of the production script so a
    silent regression in the production body fails fast).
    """
    return _OOM_RETRY_LUA


def _normalize_dead_letter_entry(entry: dict) -> dict:
    """Return a sanitized copy of a dead-letter entry.

    Defensive against partial / malformed records so the rest of
    the retry path can rely on the shape. Plan 05 #1 says historical
    evidence is never rewritten, but reading / classifying a
    malformed entry is not a write — and the classifier is the only
    thing that decides what is even attemptable.
    """
    if not isinstance(entry, dict):
        return {"job_id": "", "gpu_id": ""}
    out = dict(entry)
    out["job_id"] = str(out.get("job_id", "") or "").strip()
    out["gpu_id"] = str(out.get("gpu_id", "") or "").strip()
    out["reason"] = str(out.get("reason", "") or "").strip()
    out["last_state"] = str(out.get("last_state", "") or "").strip()
    return out


async def _oom_retry_check_redis_state(entries: list[dict]) -> list[dict]:
    """For each dead-letter entry, decide retry eligibility.

    Returns the input list annotated with ``classification``,
    ``classification_reason``, and a flag indicating which Redis
    surfaces were observed. NEVER rewrites the input entries or any
    Redis state. Plan 05 #2 + #6 say missing tracker / payload /
    stream metadata is a terminal refusal; that is exactly what
    this function reports.

    The four signals it requires before declaring ``eligible``:

      1. A live tracker hash at ``job:{job_id}`` carrying a
         terminal status (``completed``/``failed``/``cancelled``/
         ``oom_terminal``). Plan 05 #1 says the 32 retained records
         have NO surviving trackers; they all fall out here as
         ``missing_tracker``.
      2. Payload / artifact reference material that can be replayed.
         Encoded as a non-empty ``payload_hash`` on the tracker, or
         an artifact reference list with at least one entry. Plan
         05 #4 says payload/artifact reconstruction is required.
      3. A non-replayed destination stream entry — i.e. no
         ``retry_id`` already recorded against the original
         ``oom:retry:stream:{orig_job_id}`` correlation set, AND
         no active job with ``retry_of == orig_job_id`` still
         queued or running. Plan 05 #4 + #5.
      4. The attempt budget is not exhausted, tracked via the
         audit-set count. Plan 05 #3.

    Any single missing signal downgrades the classification.
    ``dry_run`` callers see the same answer; there is no
    differential path that would let a dry-run report ``eligible``
    while a real run would refuse.
    """
    if not entries:
        return []
    if _oom_redis_pool is None:
        # Fail closed: when Redis is unavailable we cannot verify
        # any of the four signals. The plan is explicit that
        # missing state fails closed; an unreachable store is
        # also missing state.
        return [
            dict(
                _normalize_dead_letter_entry(e),
                classification=_OOM_RETRY_CLASS_NO_TRACKER,
                classification_reason="redis_unavailable",
                has_tracker=False,
                has_payload_artifact=False,
                has_stream_correlation=False,
                attempt_count=0,
            )
            for e in entries
        ]

    out: list[dict] = []
    for raw in entries:
        e = _normalize_dead_letter_entry(raw)
        job_id = e["job_id"]
        gpu_id = e["gpu_id"]
        if not job_id:
            out.append(
                dict(
                    e,
                    classification=_OOM_RETRY_CLASS_NOT_FOUND,
                    classification_reason="blank_job_id",
                    has_tracker=False,
                    has_payload_artifact=False,
                    has_stream_correlation=False,
                    attempt_count=0,
                )
            )
            continue

        observed = {
            "has_tracker": False,
            "has_payload_artifact": False,
            "tracker_status": None,
            "tracker_payload_hash": None,
            "tracker_artifact_refs": None,
            "tracker_service_name": None,
            "tracker_routing_group": None,
            "has_stream_correlation": False,
            "has_active_retry": False,
            "attempt_count": 0,
        }

        # (1) tracker existence + payload / artifact material.
        try:
            tracker = await asyncio.to_thread(
                _oom_redis_pool.hgetall, f"job:{job_id}"
            )
        except Exception as exc:
            logger.debug(
                f"[oom-retry] tracker read failed for {job_id}: {exc}"
            )
            tracker = None
        if tracker:
            observed["has_tracker"] = True
            observed["tracker_status"] = str(
                tracker.get("status", "") or ""
            ).strip() or None
            ph = str(tracker.get("payload_hash", "") or "").strip()
            ar = str(tracker.get("artifact_refs", "") or "").strip()
            observed["tracker_payload_hash"] = ph or None
            observed["tracker_artifact_refs"] = ar or None
            observed["tracker_service_name"] = str(
                tracker.get("service_name", "") or ""
            ).strip() or None
            observed["tracker_routing_group"] = str(
                tracker.get("routing_group", "") or ""
            ).strip() or None
            observed["has_payload_artifact"] = bool(ph) or bool(ar)

        # (3a) correlation set: any prior retries against this orig?
        try:
            members = await asyncio.to_thread(
                _oom_redis_pool.smembers,
                f"{_OOM_RETRY_STREAM_CORRELATION_PREFIX}{job_id}",
            )
        except Exception as exc:
            logger.debug(
                f"[oom-retry] correlation read failed for {job_id}: {exc}"
            )
            members = set()
        observed["attempt_count"] = len(members or set())
        observed["has_stream_correlation"] = bool(members)

        # (3b) any active retry still in flight? Scan retry audit
        # hashes for status=queued/running against this orig.
        if members:
            for retry_id in members:
                try:
                    audit = await asyncio.to_thread(
                        _oom_redis_pool.hgetall,
                        f"{_OOM_RETRY_AUDIT_PREFIX}{retry_id}",
                    )
                except Exception as exc:
                    logger.debug(
                        f"[oom-retry] audit read failed for {retry_id}: {exc}"
                    )
                    audit = None
                if not audit:
                    continue
                new_job_id = str(audit.get("new_job_id", "") or "").strip()
                if not new_job_id:
                    continue
                try:
                    new_tracker = await asyncio.to_thread(
                        _oom_redis_pool.hgetall, f"job:{new_job_id}"
                    )
                except Exception as exc:
                    logger.debug(
                        f"[oom-retry] new tracker read failed: {exc}"
                    )
                    new_tracker = None
                status = (
                    str((new_tracker or {}).get("status", "") or "").strip()
                    if new_tracker
                    else ""
                )
                if status in ("queued", "running", "in_flight"):
                    observed["has_active_retry"] = True
                    break

        # (4) attempt budget gate.
        if observed["attempt_count"] >= _OOM_RETRY_DEFAULT_ATTEMPT_LIMIT:
            classification = _OOM_RETRY_CLASS_BUDGET_EXCEEDED
            reason = f"attempt_count={observed['attempt_count']}>=limit={_OOM_RETRY_DEFAULT_ATTEMPT_LIMIT}"
        elif observed["has_active_retry"]:
            classification = _OOM_RETRY_CLASS_REPLAYED
            reason = "active_retry_in_flight"
        elif not observed["has_tracker"]:
            classification = _OOM_RETRY_CLASS_NO_TRACKER
            reason = "no_live_tracker_at_job_key"
        elif observed["tracker_status"] not in (
            "completed",
            "failed",
            "cancelled",
            "oom_terminal",
        ):
            classification = _OOM_RETRY_CLASS_REPLAYED
            reason = f"non_terminal_tracker_status={observed['tracker_status']!r}"
        elif not observed["has_payload_artifact"]:
            classification = _OOM_RETRY_CLASS_NO_PAYLOAD
            reason = "no_payload_hash_or_artifact_refs"
        else:
            classification = _OOM_RETRY_CLASS_ELIGIBLE
            reason = "all_signals_present"

        out.append(
            dict(
                e,
                gpu_id=gpu_id,
                classification=classification,
                classification_reason=reason,
                has_tracker=observed["has_tracker"],
                has_payload_artifact=observed["has_payload_artifact"],
                has_stream_correlation=observed["has_stream_correlation"],
                has_active_retry=observed["has_active_retry"],
                attempt_count=observed["attempt_count"],
                tracker_status=observed["tracker_status"],
                tracker_payload_hash=observed["tracker_payload_hash"],
                tracker_artifact_refs=observed["tracker_artifact_refs"],
                tracker_service_name=observed["tracker_service_name"],
                tracker_routing_group=observed["tracker_routing_group"],
            )
        )
    return out


def _generate_oom_retry_id(orig_job_id: str) -> str:
    """Build a stable, unique retry id. Pure function — used both
    by the live path and by the test suite.
    """
    suffix = uuid.uuid4().hex[:12]
    ts_ms = int(time.time() * 1000)
    safe_orig = re.sub(r"[^A-Za-z0-9_-]", "_", str(orig_job_id))[:48]
    return f"retry-{safe_orig}-{ts_ms}-{suffix}"


def _generate_oom_retry_job_id(retry_id: str) -> str:
    """New job id derived from a retry_id. Stable mapping so the
    test suite can derive the expected tracker key without
    re-implementing the algorithm.
    """
    return f"job-retry-{retry_id}"


async def _atomic_retry_oom_job(
    dead_letter: dict,
    *,
    actor: str,
    reason: str,
    idempotency_key: str,
    payload_hash: str | None = None,
    artifact_refs: list[str] | None = None,
    service_name: str | None = None,
    routing_group: str | None = None,
) -> dict:
    """Run the atomic retry EVAL for one dead-letter entry.

    Caller MUST have classified first and passed only eligible
    entries; this function does not re-classify, and will refuse
    anything that is not eligible. The result is a dict with the
    same shape the test suite pins:

        {
          "outcome": "submitted" | "replayed" | "budget_exceeded"
                     | "exec_failed" | "refused",
          "retry_id": ...,
          "new_job_id": ...,
          "stream_entry_id": ...,
          "orig_job_id": ...,
          "idempotency_key": ...,
        }

    The original dead-letter record is NEVER removed or rewritten.
    """
    e = _normalize_dead_letter_entry(dead_letter)
    orig_job_id = e["job_id"]
    gpu_id = e["gpu_id"]
    if not orig_job_id:
        return {
            "outcome": "refused",
            "reason": "blank_job_id",
            "orig_job_id": orig_job_id,
            "idempotency_key": idempotency_key,
        }
    if not idempotency_key or not isinstance(idempotency_key, str):
        return {
            "outcome": "refused",
            "reason": "missing_idempotency_key",
            "orig_job_id": orig_job_id,
            "idempotency_key": idempotency_key,
        }
    if _oom_redis_pool is None:
        return {
            "outcome": "refused",
            "reason": "redis_unavailable",
            "orig_job_id": orig_job_id,
            "idempotency_key": idempotency_key,
        }

    # Belt-and-suspenders: refuse if classification was not
    # supplied / says ineligible. Production callers go through
    # ``_oom_retry_check_redis_state`` first; the live MCP path
    # is the only thing that should be invoking this helper, and
    # it always passes a classified entry.
    classification = str(dead_letter.get("classification", "") or "")
    if classification and classification != _OOM_RETRY_CLASS_ELIGIBLE:
        return {
            "outcome": "refused",
            "reason": f"ineligible:{classification}",
            "orig_job_id": orig_job_id,
            "idempotency_key": idempotency_key,
        }

    retry_id = _generate_oom_retry_id(orig_job_id)
    new_job_id = _generate_oom_retry_job_id(retry_id)
    attempt = int(dead_letter.get("attempt_count", 0) or 0) + 1
    attempt_limit = _OOM_RETRY_DEFAULT_ATTEMPT_LIMIT
    service = service_name or e.get("service_name") or ""
    routing = routing_group or e.get("routing_group") or e.get("last_state") or "default"
    payload_hash = payload_hash or e.get("payload_hash") or ""
    artifact_refs = artifact_refs or []
    artifact_refs_json = json.dumps(list(artifact_refs), sort_keys=True)
    ts = f"{time.time():.6f}"

    # The original dead-letter member is preserved verbatim; we
    # only serialize it back as a string for the audit hash so a
    # later audit can prove the original evidence has not been
    # touched.
    try:
        orig_member_json = json.dumps(
            e, sort_keys=True, separators=(",", ":")
        )
    except (TypeError, ValueError):
        orig_member_json = json.dumps({"job_id": orig_job_id, "gpu_id": gpu_id})

    # Destination stream key follows the same convention as
    # RedisQueue.enqueue: queue:{routing_group}.
    stream_key = f"queue:{routing}"

    keys = [
        f"{_OOM_RETRY_IDEMPOTENCY_PREFIX}{idempotency_key}",
        f"{_OOM_RETRY_AUDIT_PREFIX}{retry_id}",
        f"{_OOM_RETRY_STREAM_CORRELATION_PREFIX}{orig_job_id}",
        f"job:{new_job_id}",
        stream_key,
    ]
    args = [
        idempotency_key,
        retry_id,
        new_job_id,
        orig_job_id,
        orig_member_json,
        gpu_id,
        str(attempt),
        str(attempt_limit),
        actor or "",
        reason or "",
        ts,
        payload_hash or "",
        artifact_refs_json,
        service or "",
        routing,
        str(_OOM_RETRY_IDEMPOTENCY_TTL_S),
        e.get("reason", ""),
    ]

    try:
        raw = await asyncio.to_thread(
            _oom_redis_pool.eval, _oom_retry_lua_script(), len(keys), *keys, *args
        )
    except Exception as exc:
        logger.warning(
            f"[oom-retry] EVAL failed for {orig_job_id}: {exc}"
        )
        return {
            "outcome": "exec_failed",
            "reason": str(exc),
            "retry_id": retry_id,
            "new_job_id": new_job_id,
            "orig_job_id": orig_job_id,
            "idempotency_key": idempotency_key,
        }

    # Lua always returns a 3-element list.
    if not isinstance(raw, (list, tuple)) or len(raw) < 1:
        return {
            "outcome": "exec_failed",
            "reason": "malformed_lua_response",
            "retry_id": retry_id,
            "new_job_id": new_job_id,
            "orig_job_id": orig_job_id,
            "idempotency_key": idempotency_key,
        }
    status = raw[0]
    out = {
        "retry_id": retry_id,
        "new_job_id": new_job_id,
        "orig_job_id": orig_job_id,
        "idempotency_key": idempotency_key,
    }
    if status == "submitted":
        out["outcome"] = "submitted"
        out["stream_entry_id"] = raw[2] if len(raw) > 2 else None
        return out
    if status == "replayed":
        replayed_retry_id = raw[1] if len(raw) > 1 else None
        out["outcome"] = "replayed"
        out["retry_id"] = replayed_retry_id
        out["new_job_id"] = (
            _generate_oom_retry_job_id(replayed_retry_id)
            if replayed_retry_id
            else None
        )
        out["replayed_retry_id"] = replayed_retry_id
        return out
    if status == "budget_exceeded":
        out["outcome"] = "budget_exceeded"
        out["attempt"] = raw[1] if len(raw) > 1 else None
        out["attempt_limit"] = raw[2] if len(raw) > 2 else None
        return out
    # exec_failed or anything else: no partial state survived
    # MULTI/EXEC (the Lua script DELs the idempotency marker on
    # EXEC failure so a fresh retry is possible). The original
    # dead-letter member is untouched.
    out["outcome"] = "exec_failed"
    out["reason"] = status
    return out


async def _oom_retry_correlation_snapshot(limit: int = 100) -> dict:
    """Read-only helper: list every retry currently in the audit
    index, group by ``orig_job_id``, and surface cross-store
    correlation so operators can see OOM archive + queue DL +
    retry audit as a unified picture (plan 05 #5 Option A).
    """
    if _oom_redis_pool is None:
        return {
            "schema_version": 1,
            "redis_available": False,
            "by_orig": {},
            "total_retries": 0,
        }
    by_orig: dict[str, list[dict]] = {}
    total = 0
    try:
        cursor = 0
        # SCAN over oom:retry:audit:* to enumerate retries. The
        # audit keys are short-lived (no explicit TTL today; the
        # idempotency marker has the TTL) so a bounded scan is
        # sufficient and avoids the KEYS hot path.
        while True:
            cursor, keys = await asyncio.to_thread(
                _oom_redis_pool.scan,
                cursor=cursor,
                match=f"{_OOM_RETRY_AUDIT_PREFIX}*",
                count=200,
            )
            for k in keys:
                kk = k.decode() if isinstance(k, bytes) else k
                if not kk.startswith(_OOM_RETRY_AUDIT_PREFIX):
                    continue
                retry_id = kk[len(_OOM_RETRY_AUDIT_PREFIX):]
                audit = await asyncio.to_thread(
                    _oom_redis_pool.hgetall, kk
                )
                if not audit:
                    continue
                orig = str(audit.get("orig_job_id", "") or "").strip()
                if not orig:
                    continue
                by_orig.setdefault(orig, []).append(
                    {
                        "retry_id": retry_id,
                        "new_job_id": audit.get("new_job_id", ""),
                        "gpu_id": audit.get("gpu_id", ""),
                        "service_name": audit.get("service_name", ""),
                        "routing_group": audit.get("routing_group", ""),
                        "attempt": audit.get("attempt", ""),
                        "actor": audit.get("actor", ""),
                        "ts": audit.get("ts", ""),
                    }
                )
                total += 1
            if cursor == 0:
                break
            if total >= limit * 4:
                break
    except Exception as exc:
        logger.debug(f"[oom-retry] correlation scan failed: {exc}")
    return {
        "schema_version": 1,
        "redis_available": True,
        "by_orig": by_orig,
        "total_retries": total,
    }


# ── OOM health section (shared by /health and the WebSocket full-state) ──
# /health and the websocket full-state payload must surface the same fields
# so dashboards don't need two decoders. The helper below is the single
# source of truth — callers (handle_health, _websocket_handler) just plug
# the result into their payload.
#
# Scope/retention/cache-freshness contract:
#   * process_events.* — sum of per-GpuBundleState counters that live in
#     process memory and are reset on restart. These are "events observed
#     by THIS process since it started".
#   * dead_letter_retained.* — length / metadata of the in-memory cache
#     backed by Redis zset ``oom:dead_letters``. Retention is 30 days from
#     the latest mutation (TTL refreshed on every add) and entries are
#     capped at _OOM_DEAD_LETTER_CAP (100). The cache is NOT reset on
#     process restart if Redis is reachable.
#   * cache_age_seconds / cache_fresh — explicit staleness signal for the
#     dead-letter cache, computed from _dead_letter_cache_refresh_ts that
#     the watchdog stamps on each successful refresh. /health does NOT
#     issue a synchronous Redis call just to compute this.
_OOM_CACHE_FRESH_WINDOW_S = 60.0   # within this window, cache_fresh=True


def _oom_health_section(
    gpu_states_map: dict | None = None,
    events_last_hour: list | None = None,
    watchdog_heartbeat_ts: float | None = None,
    now: float | None = None,
) -> dict:
    """Build the OOM section for /health and the websocket full-state payload.

    The function is pure-ish: it reads module-level state but never issues a
    blocking I/O call. The caller supplies ``now`` (default ``time.time()``)
    so tests can pin the wall clock and assert cache_age_seconds.
    """
    if gpu_states_map is None:
        gpu_states_map = globals().get("_gpu_states", {}) or {}
    if events_last_hour is None:
        events_last_hour = []
    if watchdog_heartbeat_ts is None:
        watchdog_heartbeat_ts = float(
            globals().get("_last_oom_heartbeat_ts", 0.0) or 0.0
        )
    if now is None:
        now = time.time()
    gpu_states_map = gpu_states_map or {}

    # ── process_events — restart-reset, in-memory only ────────────────
    process_events = {
        "scope": "process_memory",
        "resets_on_restart": True,
        "total_events": sum(int(getattr(bs, "oom_event_count", 0) or 0)
                            for bs in gpu_states_map.values()),
        "total_recoveries": sum(int(getattr(bs, "oom_recovery_count", 0) or 0)
                                for bs in gpu_states_map.values()),
        "total_permanent_failures": sum(int(getattr(bs, "oom_permanent_failure_count", 0) or 0)
                                        for bs in gpu_states_map.values()),
        "active_recoveries": {
            gpu_id: getattr(bs, "oom_state", "idle")
            for gpu_id, bs in gpu_states_map.items()
            if getattr(bs, "oom_state", "idle") not in ("idle", "restored")
        },
        "events_last_hour": events_last_hour,
        "last_event": events_last_hour[-1] if events_last_hour else None,
    }

    # ── dead_letter_retained — Redis zset (30d TTL, cap 100) ──────────
    dead_letter_cache = list(globals().get("_dead_letter_cache", []) or [])
    refresh_ts = float(
        globals().get("_dead_letter_cache_refresh_ts", 0.0) or 0.0
    )
    if refresh_ts > 0:
        cache_age_seconds = max(0.0, now - refresh_ts)
        cache_refresh_ts = refresh_ts
        cache_fresh = cache_age_seconds < _OOM_CACHE_FRESH_WINDOW_S
    else:
        cache_age_seconds = None
        cache_refresh_ts = None
        cache_fresh = False

    keyed_identities = [
        (str(row.get("job_id")), str(row.get("gpu_id", "")))
        for row in dead_letter_cache
        if isinstance(row, dict) and str(row.get("job_id", "")).strip()
    ]
    unique_identities = set(keyed_identities)
    unkeyed_count = sum(
        1 for row in dead_letter_cache
        if not isinstance(row, dict) or not str(row.get("job_id", "")).strip()
    )
    entry_timestamps = [
        float(row["ts"])
        for row in dead_letter_cache
        if isinstance(row, dict)
        and isinstance(row.get("ts"), (int, float))
        and not isinstance(row.get("ts"), bool)
    ]
    dead_letter_retained = {
        "scope": "redis_zset",
        "redis_key": OOM_REDIS_DEAD_LETTER,
        "resets_on_restart": False,
        "count": len(dead_letter_cache),
        "raw_entry_count": len(dead_letter_cache),
        "unique_job_count": len(unique_identities),
        "duplicate_entry_count": max(0, len(keyed_identities) - len(unique_identities)),
        "unkeyed_entry_count": unkeyed_count,
        "oldest_entry_ts": min(entry_timestamps) if entry_timestamps else None,
        "newest_entry_ts": max(entry_timestamps) if entry_timestamps else None,
        "historical_archive": True,
        "affects_current_health": False,
        # Legacy alias preserved for dashboards that already chart it.
        "dead_letter_count": len(dead_letter_cache),
        "cap": _OOM_DEAD_LETTER_CAP,
        "retention_seconds": _OOM_DEAD_LETTER_TTL_S,
        "cache_refresh_ts": cache_refresh_ts,
        "cache_age_seconds": cache_age_seconds,
        "cache_fresh": cache_fresh,
    }

    # ── watchdog health — read off the module-level heartbeat ts ──────
    if watchdog_heartbeat_ts > 0:
        wdt_age_s = max(0.0, now - watchdog_heartbeat_ts)
        wdt_fresh = wdt_age_s < 30
    else:
        wdt_age_s = None
        wdt_fresh = False
    watchdog = {
        "heartbeat_ts": watchdog_heartbeat_ts,
        "heartbeat_age_s": wdt_age_s,
        "heartbeat_fresh": wdt_fresh,
        "inflight": dict(globals().get("_oom_recovery_in_progress", {}) or {}),
    }

    return {
        "process_events": process_events,
        "dead_letter_retained": dead_letter_retained,
        "watchdog": watchdog,
        "current_oom_active": bool(
            process_events["active_recoveries"] or process_events["events_last_hour"]
        ),
        # Legacy top-level keys — keep so existing dashboards do not break.
        "total_events": process_events["total_events"],
        "total_recoveries": process_events["total_recoveries"],
        "total_permanent_failures": process_events["total_permanent_failures"],
        "active_recoveries": process_events["active_recoveries"],
        "dead_letter_count": dead_letter_retained["count"],
        "last_event": process_events["last_event"],
        "events_last_hour": events_last_hour,
        "watchdog_heartbeat_age_s": wdt_age_s,
        "watchdog_heartbeat_fresh": wdt_fresh,
        "watchdog_heartbeat_ts": watchdog_heartbeat_ts,
        "watchdog_inflight": watchdog["inflight"],
    }


# ── Phase 5: Rate-limit helper for oom_recovery_force_reset ─────────
def _check_force_reset_rate_limit(gpu_id: str) -> tuple[bool, float]:
    """Check whether oom_recovery_force_reset may run for `gpu_id` now.

    Per adversarial #26: at most one call per OOM_FORCE_RESET_MIN_INTERVAL_S
    per GPU. Returns (allowed, retry_after_seconds).
    """
    now = time.time()
    last_ts = _oom_force_reset_last_call_ts.get(gpu_id, 0.0)
    elapsed = now - last_ts
    if elapsed < OOM_FORCE_RESET_MIN_INTERVAL_S:
        return False, OOM_FORCE_RESET_MIN_INTERVAL_S - elapsed
    return True, 0.0


def _handle_oom_event(
    gpu_id: str,
    service_name: str,
    job_id: str = "",
    detection_source: str = "unknown",
    reason: str = "",
    details: str = "",
) -> dict:
    """Central OOM event handler. Called from worker error paths and watchdog.

    Behaviour:
    - Looks up GpuBundleState via _gpu_states[gpu_id]
    - Calls bundle_state.record_oom_event(reason=reason, job_id=job_id)
    - Sets oom_state = 'detected' (the recovery pipeline will pick this up)
    - Appends the event to _recent_oom_events_log for /health surfacing
    - Returns the OOM event dict for logging/Redis persistence

    IMPORTANT: This is Phase 2 (DETECTION only). It records the event and sets
    state. Phase 3 will add the recovery pipeline that transitions through
    detected -> draining -> verifying -> recovering -> restored. For now, the
    watchdog will pick up 'detected' state and log a warning.
    """
    bundle_state = _gpu_states.get(gpu_id)
    if bundle_state is None:
        # Unknown GPU — try the primary so we still surface the event
        primary = globals().get("_vram_cache", {}) or {}
        logger.warning(
            f"[oom-detect] OOM event for unknown GPU {gpu_id}: {reason[:160]}"
        )
        # Still record in the ring buffer so /health sees it
        _recent_oom_events_log.append({
            "gpu_id": gpu_id, "ts": time.time(), "reason": reason,
            "service": service_name, "job_id": job_id, "source": detection_source,
        })
        return {"recorded": False, "reason": "unknown_gpu", "gpu_id": gpu_id}

    bundle_state.record_oom_event(reason=reason, job_id=job_id)
    bundle_state.set_oom_state("detected", source=f"_handle_oom_event({detection_source})", reason=reason)
    _recent_oom_events_log.append({
        "gpu_id": gpu_id, "ts": time.time(), "reason": reason,
        "service": service_name, "job_id": job_id, "source": detection_source,
    })
    logger.warning(
        f"[oom-detect] OOM on {gpu_id} (service={service_name}, job={job_id}): "
        f"source={detection_source} reason={reason[:200]!r} details={details[:200]}"
    )
    return {
        "recorded": True,
        "gpu_id": gpu_id,
        "service_name": service_name,
        "job_id": job_id,
        "detection_source": detection_source,
        "reason": reason,
        "details": details[:500],
        "ts": time.time(),
    }


# ── Phase 3: OOM Recovery Pipeline ─────────────────────────────────
#
# The detection half (Phase 2) records OOMs and sets oom_state='detected'.
# The recovery half (THIS phase) consumes that 'detected' state and walks
# the GPU bundle state through the state machine defined in §A.2 of
# OOM_RECOVERY_STATE_MACHINE_DESIGN.md:
#
#     detected -> draining -> verifying -> recovering -> restored
#                                    \-> permanent_failed (after 3 in 5min)
#
# Adversarial-check fixes applied here (every one is annotated inline):
#   #1 Corrected atomic eviction: allow if other GPU has only idle baseline
#      displaced (e.g. sulphur-2 displacing LLM-Secondary)
#   #2 First-OOM auto-retry with reduced params
#      (height*0.85, width*0.85, batch//4 via OOM_RETRY_DIM_SCALE /
#      OOM_RETRY_BATCH_DIVISOR)
#   #3 Restore BOTH GPUs' idle LLMs (not single restore_llm)
#   #4 OOM_LOCK (asyncio.Lock) for concurrent protection
#   #5 Reentrancy lock on _force_recover_failed_service
#   #6 Cancel prompt with 10s timeout (OOM_CANCEL_PROMPT_TIMEOUT_S)
#   #7 Snapshot pre-OOM idle map for correct restoration
#   #8 Idempotent state transitions so watchdog-driven re-entry is safe


def _get_idle_service_for_gpu(gpu_id: str) -> str | None:
    """Return the idle LLM service name for `gpu_id`, or None.

    Reads services.json `scheduling.idle_services[gpu_id]` first, then
    falls back to `scheduling.idle_service`. Returns the service NAME
    (e.g. "LLM-Secondary"), not the systemd unit — the caller resolves the
    unit via the services config.

    Per adversarial #7: we resolve at *recovery time*, not at OOM time,
    so a snapshot reflects what was the idle baseline before the OOM
    event disturbed it. If both GPUs had generation bundles loaded and
    the user changed the idle map mid-OOM, we still restore to the
    pre-OOM snapshot.
    """
    try:
        config = _load_services_config()
    except Exception as e:
        logger.debug(f"[oom-recovery] _get_idle_service_for_gpu: _load_services_config failed: {e}")
        return None
    scheduling = config.get("scheduling", {}) or {}
    idle_services = scheduling.get("idle_services", {}) or {}
    name = idle_services.get(gpu_id) or scheduling.get("idle_service")
    if name and name in (config.get("services", {}) or {}):
        return name
    return None


def _check_both_gpus_safe_to_recover(failed_gpu_id: str, timeout_s: float = 30.0) -> dict:
    """Atomic multi-GPU eviction check.

    Per adversarial #1 (CORRECTED): allow recovery if the OTHER GPU has
    only its idle baseline displaced by a generation bundle. The OLD
    check refused recovery if the other GPU had ANY loaded bundle — this
    caused a deadlock where a sulphur-diffusion job on gpu_primary (linked
    to sulphur-encoder on gpu_secondary) would OOM and the recovery would refuse
    to evict because gpu_secondary still had LLM-Secondary displaced. The corrected
    logic only BLOCKS when the other GPU is mid-loading the idle
    baseline OR mid-eviction (i.e. actively transitioning, not stably
    occupied).

    Returns a dict:
        {
          "safe": bool,
          "reason": str,
          "other_state": str|None,  # "loading" | "evicting" | "draining" | None
          "other_loaded": list,    # bundles loaded on the other GPU
          "idle_for_other": str|None,  # idle service name we expect there
        }

    This function does NOT do any waiting — it returns synchronously. The
    caller (the pipeline) is responsible for sleeping / polling if the
    other GPU is transitioning.
    """
    if failed_gpu_id == "gpu_primary":
        other_gpu_id = "gpu_secondary"
    elif failed_gpu_id == "gpu_secondary":
        other_gpu_id = "gpu_primary"
    else:
        # Unknown GPU — only one GPU or misnamed; allow recovery
        return {"safe": True, "reason": "unknown_gpu_id", "other_state": None}

    other_bs = _gpu_states.get(other_gpu_id)
    if other_bs is None:
        # Unknown other GPU — log and allow (caller will discover at restart)
        return {
            "safe": True,
            "reason": "other_gpu_unknown",
            "other_state": None,
            "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
        }

    # If other GPU is mid-loading the idle baseline, BLOCK.
    # mid-loading means a restore_llm / _load_bundle is in progress on it.
    if other_bs.loading:
        return {
            "safe": False,
            "reason": f"other_gpu {other_gpu_id} is mid-loading idle baseline",
            "other_state": "loading",
            "other_loaded": list(other_bs.loaded_bundles),
            "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
        }

    # If other GPU is evicting or draining, BLOCK.
    if other_bs.evicting or other_bs.draining:
        return {
            "safe": False,
            "reason": f"other_gpu {other_gpu_id} is mid-eviction (evicting={other_bs.evicting}, draining={other_bs.draining})",
            "other_state": "evicting" if other_bs.evicting else "draining",
            "other_loaded": list(other_bs.loaded_bundles),
            "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
        }

    # Otherwise ALLOW — even if other GPU has a bundle loaded (e.g. sulphur-2
    # displacing LLM-Secondary on the gpu_secondary). We will only evict the FAILED
    # GPU's bundles, not the other's.
    return {
        "safe": True,
        "reason": "other_gpu_idle_or_displaced_baseline",
        "other_state": None,
        "other_loaded": list(other_bs.loaded_bundles),
        "idle_for_other": _get_idle_service_for_gpu(other_gpu_id),
    }


def _snapshot_pre_oom_state() -> dict:
    """Capture per-GPU idle baseline expectations before OOM recovery runs.

    Per adversarial #7: returning a snapshot (not reading services.json
    at restore time) ensures we restore to the SAME state we had before
    the OOM disturbed things. If a generation bundle displaced the
    idle LLM on a GPU, we record the displaced idle's service NAME so
    the restore step can put the idle LLM back even if the live
    services.json has changed.

    Returns: {gpu_id: idle_service_name_or_None}
        - None means the GPU was at idle baseline (nothing to restore)
        - "LLM-Secondary" means LLM-Secondary was the idle LLM and we should
          restart it after recovery.
    """
    snapshot: dict[str, str | None] = {}
    for gpu_id, bs in _gpu_states.items():
        # Always record what idle service we EXPECT for this GPU.
        # If the GPU has a bundle loaded (idle displaced), we still
        # snapshot the expected idle name so _restore_both_idle_llms
        # can put it back.
        idle = _get_idle_service_for_gpu(gpu_id)
        snapshot[gpu_id] = idle
        # Touching bs ensures the GPU entry exists in the snapshot even
        # if no idle is configured (the value is None).
        _ = bs.loaded_bundles
    return snapshot


async def _restore_both_idle_llms(snapshot: dict | None = None) -> dict:
    """Restore BOTH GPUs' idle LLMs after OOM recovery.

    Per adversarial #3: do NOT use single restore_llm (which targets one
    GPU). This iterates per GPU and starts the idle service via systemd.

    Per adversarial #7: uses `snapshot` if provided to know what to
    restore. If snapshot is None, reads services.json idle map (current
    config, may differ from pre-OOM state — caller decides which).

    Returns: {gpu_id: restore_status_dict}
        Each status has keys: restored (bool), unit (str|None),
        reason (str|None), error (str|None).

    Phase 6 (OOM fix 2): guard ``systemctl start`` with an ``is-active``
    probe so we don't re-issue ``start`` on a unit that's already running
    (which can confuse systemd, race with the unit's own restart, and
    adds latency in the OOM recovery critical path). If the unit is
    already active we probe /health and treat it as restored when
    healthy; otherwise we issue ``try-restart``.
    """
    if not snapshot:
        snapshot = {}
        for gpu_id in _gpu_states:
            snapshot[gpu_id] = _get_idle_service_for_gpu(gpu_id)

    results: dict[str, dict] = {}
    for gpu_id, idle_service_name in snapshot.items():
        if not idle_service_name:
            results[gpu_id] = {"restored": False, "reason": "no_idle_service"}
            continue
        try:
            services = _services_config.get("services", {}) if isinstance(_services_config, dict) else {}
            svc = services.get(idle_service_name, {}) if isinstance(services, dict) else {}
            unit = svc.get("systemd_unit") if isinstance(svc, dict) else None
            if not unit:
                results[gpu_id] = {"restored": False, "reason": "no_systemd_unit"}
                continue
            # Lifecycle Guard 2026-08-07: disabled services stay disabled.
            # A direct ``systemctl start`` here would override the operator's
            # intent and is a violation of the disabled service contract.
            if svc.get("enabled") is False:
                results[gpu_id] = {
                    "restored": False,
                    "unit": unit,
                    "reason": "disabled_service_untouched",
                }
                logger.info(
                    "[oom-recovery] %s is disabled in services config; "
                    "leaving untouched on %s",
                    idle_service_name,
                    gpu_id,
                )
                continue
            # Lifecycle Guard 2026-08-07: bundle-managed idle services must
            # be admitted via the controller-owned bundle admission path,
            # never via direct systemctl. Direct start would race the
            # scheduler/bundle controller and break atomic fence guarantees.
            service_bundle = _get_bundle_for_service(idle_service_name)
            if service_bundle is not None:
                bundle_name = service_bundle.get("bundle_name")
                if vram is None or scheduler is None:
                    results[gpu_id] = {
                        "restored": False,
                        "unit": unit,
                        "reason": "controller_unavailable_for_bundle_restoration",
                    }
                    logger.error(
                        "[oom-recovery] controller unavailable; cannot restore "
                        "bundle-backed idle %s on %s (refusing direct systemctl)",
                        idle_service_name,
                        gpu_id,
                    )
                    continue
                admitted, _ = await _admit_bundle_backed_llm_service(
                    idle_service_name,
                    priority=service_bundle.get("priority", 0) or 0,
                )
                results[gpu_id] = {
                    "restored": bool(admitted),
                    "unit": unit,
                    "bundle": bundle_name,
                    "reason": (
                        "bundle_admission" if admitted
                        else "bundle_admission_failed"
                    ),
                }
                if admitted:
                    logger.info(
                        "[oom-recovery] Restored bundle-backed idle %s (%s) on %s via admission",
                        idle_service_name,
                        bundle_name,
                        gpu_id,
                    )
                else:
                    logger.warning(
                        "[oom-recovery] Bundle admission refused for %s on %s",
                        idle_service_name,
                        gpu_id,
                    )
                continue
            # Lifecycle Guard 2026-08-07: standalone (non-bundle) services
            # can only be restored directly when the controller stack is
            # available. If scheduler/vram are missing, we have no way to
            # reason about whether restoring this unit is safe — fail
            # closed rather than racing systemd in isolation.
            if vram is None or scheduler is None:
                results[gpu_id] = {
                    "restored": False,
                    "unit": unit,
                    "reason": "controller_unavailable_for_direct_restoration",
                }
                logger.error(
                    "[oom-recovery] controller unavailable; refusing direct "
                    "systemctl start for standalone idle %s on %s",
                    idle_service_name,
                    gpu_id,
                )
                continue
            # Phase 6: probe is-active before issuing start to avoid
            # re-starting a unit that is already running (which can
            # race with the unit's own restart loop and slows OOM
            # recovery). If the unit is already active, fall through to
            # a health check; healthy ⇒ treat as restored, unhealthy
            # ⇒ try-restart so systemd gets a clean restart signal.
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            try:
                rc_active, _ = await asyncio.wait_for(proc.communicate(), timeout=5.0)
            except asyncio.TimeoutError:
                # is-active hung — treat as inactive and try start below
                rc_active = 1
            already_active = (rc_active == 0)
            port = svc.get("port")
            health_path = svc.get("health_path") or "/health"
            if already_active:
                health_ok = await _probe_health_inline(port, health_path=health_path)
                if health_ok:
                    results[gpu_id] = {
                        "restored": True,
                        "unit": unit,
                        "rc": 0,
                        "reason": "already_active_healthy",
                    }
                    logger.info(
                        f"[oom-recovery] {unit} already active+healthy on {gpu_id}; skipping start"
                    )
                    continue
                # Active but unhealthy — try-restart to nudge it
                proc = await asyncio.create_subprocess_exec(
                    "systemctl", "try-restart", unit,
                    stdout=asyncio.subprocess.DEVNULL,
                    stderr=asyncio.subprocess.DEVNULL,
                )
                try:
                    rc = await asyncio.wait_for(proc.wait(), timeout=10.0)
                except asyncio.TimeoutError:
                    results[gpu_id] = {
                        "restored": False,
                        "unit": unit,
                        "reason": "systemctl_try_restart_timeout",
                    }
                    logger.warning(
                        f"[oom-recovery] systemctl try-restart {unit} timed out (>10s)"
                    )
                    continue
                results[gpu_id] = {
                    "restored": rc == 0,
                    "unit": unit,
                    "rc": rc,
                    "reason": "already_active_unhealthy_try_restart",
                }
                if rc == 0:
                    logger.info(
                        f"[oom-recovery] {unit} was active but unhealthy; try-restart ok on {gpu_id}"
                    )
                else:
                    logger.warning(
                        f"[oom-recovery] systemctl try-restart {unit} failed rc={rc}"
                    )
                continue
            # Inactive — start it (original behaviour)
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "start", unit,
                stdout=asyncio.subprocess.DEVNULL,
                stderr=asyncio.subprocess.DEVNULL,
            )
            try:
                rc = await asyncio.wait_for(proc.wait(), timeout=10.0)
            except asyncio.TimeoutError:
                results[gpu_id] = {
                    "restored": False,
                    "unit": unit,
                    "reason": "systemctl_start_timeout",
                }
                logger.warning(
                    f"[oom-recovery] systemctl start {unit} timed out (>10s)"
                )
                continue
            results[gpu_id] = {"restored": rc == 0, "unit": unit, "rc": rc}
            if rc == 0:
                logger.info(
                    f"[oom-recovery] Restored {idle_service_name} on {gpu_id} via {unit}"
                )
            else:
                logger.warning(
                    f"[oom-recovery] systemctl start {unit} failed rc={rc}"
                )
        except Exception as e:
            results[gpu_id] = {"restored": False, "error": str(e)}
            logger.error(
                f"[oom-recovery] Failed to restore {idle_service_name} on {gpu_id}: {e}"
            )

    return results


async def _probe_health_inline(port, health_path: str = "/health", timeout: float = 2.0) -> bool:
    """Module-level liveness probe used by _restore_both_idle_llms.

    Mirrors ``WorkerSupervisor._check_health``'s HTTP-first-then-TCP
    fallback behaviour (PR4 fix). Lives at module level so the free
    function ``_restore_both_idle_llms`` can call it without needing a
    ``WorkerSupervisor`` instance. Returns True on any 2xx from the
    health_path, OR a successful raw TCP connect to the port.
    """
    if not port:
        return False
    try:
        import aiohttp  # local import — module already imports it elsewhere
        timeout_obj = aiohttp.ClientTimeout(total=timeout)
        async with aiohttp.ClientSession(timeout=timeout_obj) as _sess:
            async with _sess.get(f"http://127.0.0.1:{int(port)}{health_path}") as resp:
                if resp.status == 200:
                    return True
    except Exception:
        pass
    # Fallback: TCP connect to the port (matches LoadBundle port-ready gate)
    try:
        fut = asyncio.open_connection("127.0.0.1", int(port))
        _reader, writer = await asyncio.wait_for(fut, timeout=timeout)
        writer.close()
        try:
            await writer.wait_closed()
        except Exception:
            pass
        return True
    except Exception:
        return False


def _resolve_service_for_gpu(gpu_id: str) -> str:
    """Best-effort service name lookup for a GPU.

    Used by the watchdog to pass a service name into
    _oom_recovery_pipeline (which in turn hands it to
    _force_recover_failed_service for reentrancy-locked eviction).

    Strategy:
      1. If a bundle is loaded on the GPU, look up its first service.
      2. Otherwise return "unknown".

    Returns service NAME (not systemd unit).
    """
    bs = _gpu_states.get(gpu_id)
    if bs is None or not bs.loaded_bundles:
        # Phase 5: fall back to the OOM-implicated service name (if any).
        # This is the only signal we have when the GPU is mid-recovery
        # and the bundle is no longer loaded. Skip the literal "unknown"
        # value to avoid masking a real previous service.
        fallback = getattr(bs, "oom_last_service_name", None) if bs is not None else None
        if fallback and fallback != "unknown":
            return fallback
        return "unknown"
    bundle_name = bs.loaded_bundles[0]
    try:
        bundles = _resolve_bundles() or {}
        bundle_cfg = bundles.get(bundle_name, {}) if isinstance(bundles, dict) else {}
        svcs = bundle_cfg.get("services") or []
        if svcs:
            return svcs[0]
    except Exception as e:
        logger.debug(f"[oom-recovery] _resolve_service_for_gpu lookup failed: {e}")
    return bundle_name  # fall back to bundle name as proxy


async def _oom_recovery_pipeline(
    gpu_id: str,
    service_name: str,
    job_id: str = "",
    oom_reason: str = "",
    oom_details: str = "",
) -> dict:
    """OOM recovery state machine. Phase 3 main entry.

    Transitions GpuBundleState through:
        detected -> draining -> verifying -> recovering -> restored
    or
        detected -> permanent_failed (after 3 OOMs in 5 min, or blocked)

    Per adversarial #2: first OOM auto-retry with reduced params.
    Per adversarial #3: restores BOTH GPUs' idle LLMs.
    Per adversarial #4: protected by asyncio.Lock.
    Per adversarial #5: per-service lock on _force_recover_failed_service.
    Per adversarial #6: cancel prompt with 10s timeout.
    Per adversarial #7: snapshot pre-OOM idle map.
    Per adversarial #8: idempotent — re-entry on the same GPU is safe.

    Returns a result dict with keys: state, reason, restore_results (optional).
    """
    bs = _gpu_states.get(gpu_id)
    if bs is None:
        logger.warning(
            f"[oom-recovery] No GpuBundleState for {gpu_id}; cannot recover"
        )
        return {"state": "skipped", "reason": "unknown_gpu", "gpu_id": gpu_id}

    # Idempotency: if this GPU is already past 'detected', don't restart
    # the pipeline. The watchdog may fire repeatedly while a recovery is
    # in flight; we want exactly ONE pipeline per OOM.
    if bs.oom_state in ("recovering", "verifying", "restored", "permanent_failed"):
        logger.debug(
            f"[oom-recovery] {gpu_id} already in oom_state={bs.oom_state!r}; "
            f"skipping re-entry"
        )
        return {"state": "skipped", "reason": f"already_in_{bs.oom_state}"}

    # Acquire the global OOM_LOCK so concurrent recoveries serialise.
    # Per adversarial #4. If we can't get the lock in 5s the watchdog
    # has piled up too many events; bail rather than wedge.
    lock_acquired = False
    if _oom_lock is not None:
        try:
            await asyncio.wait_for(_oom_lock.acquire(), timeout=5.0)
            lock_acquired = True
        except asyncio.TimeoutError:
            logger.warning(
                f"[oom-recovery] Lock timeout for {gpu_id}; another recovery is "
                f"in flight. Skipping."
            )
            return {"state": "skipped", "reason": "lock_timeout"}
        except Exception as e:
            logger.warning(f"[oom-recovery] Lock acquire error: {e}; proceeding unlocked")
            lock_acquired = False

    try:
        # Snapshot pre-OOM state for correct restoration (#7)
        pre_oom_snapshot = _snapshot_pre_oom_state()

        # Mark "in progress" so the watchdog won't re-enter while we run.
        _oom_recovery_in_progress[gpu_id] = time.time()

        # Detection already records the event before setting state=detected.
        # The watchdog may also enter this pipeline directly, so record only
        # when this job/GPU has not already passed through the detector.
        already_recorded = (
            bs.oom_state == "detected"
            and (
                not job_id
                or bs.oom_active_recovery_job_id == job_id
            )
            and bs.oom_event_count > 0
        )
        if not already_recorded:
            bs.record_oom_event(reason=oom_reason or "watchdog_detected", job_id=job_id)

        # Stage 1: DETECTED -> DRAINING
        bs.set_oom_state("draining", source="recovery_pipeline", reason=oom_reason)
        logger.info(
            f"[oom-recovery] {gpu_id}: detected -> draining "
            f"(reason={oom_reason!r}, job={job_id!r})"
        )

        # Atomic multi-GPU check (per adversarial #1 — corrected)
        check = _check_both_gpus_safe_to_recover(gpu_id)
        if not check.get("safe"):
            bs.set_oom_state(
                "permanent_failed",
                source="recovery_pipeline",
                reason=f"blocked: {check.get('reason')}",
            )
            bs.oom_permanent_failure_count += 1
            logger.error(
                f"[oom-recovery] {gpu_id}: BLOCKED - {check.get('reason')!r}"
            )
            # Phase 5: record to dead-letter list (best-effort)
            if job_id:
                try:
                    await _add_to_dead_letter(
                        job_id=job_id,
                        gpu_id=gpu_id,
                        reason=f"blocked: {check.get('reason')}",
                        last_state="permanent_failed",
                    )
                except Exception as _dl_err:
                    logger.debug(f"[oom-recovery] dead-letter add failed: {_dl_err}")
            return {
                "state": "permanent_failed",
                "reason": check.get("reason"),
                "gpu_id": gpu_id,
            }

        # Cancel any in-flight prompt with 10s timeout (#6).
        # We look for a comfyui_client / comfyui_service / interrupt helper
        # in module globals. If absent, this is a no-op (e.g. ACE-Step OOM
        # where we don't have a global cancel handle).
        if job_id:
            cancel_target = (
                globals().get("comfyui_service")
                or globals().get("_comfyui_client")
                or globals().get("comfyui_client")
            )
            if cancel_target is not None and hasattr(cancel_target, "interrupt"):
                try:
                    await asyncio.wait_for(
                        cancel_target.interrupt(),
                        timeout=OOM_CANCEL_PROMPT_TIMEOUT_S,
                    )
                except asyncio.TimeoutError:
                    logger.warning(
                        f"[oom-recovery] Cancel prompt timeout for {job_id} "
                        f"(>{OOM_CANCEL_PROMPT_TIMEOUT_S}s)"
                    )
                except Exception as e:
                    logger.debug(f"[oom-recovery] Cancel prompt error: {e}")

        # Stage 2: DRAINING -> VERIFYING
        bs.set_oom_state("verifying", source="recovery_pipeline")
        logger.info(f"[oom-recovery] {gpu_id}: draining -> verifying")

        # Brief grace period for unload to complete
        await asyncio.sleep(2.0)

        # Verify VRAM has headroom
        try:
            vram = _verify_oom_via_vram(gpu_id)
        except Exception as e:
            logger.debug(f"[oom-recovery] vram verify raised: {e}")
            vram = {"available": False, "error": str(e)}
        if vram.get("available") and not vram.get("pressure", True):
            logger.info(
                f"[oom-recovery] {gpu_id}: VRAM cleared "
                f"({vram.get('free_mib')} MiB free)"
            )
        else:
            logger.warning(
                f"[oom-recovery] {gpu_id}: VRAM still pressured "
                f"(free={vram.get('free_mib', '?')} MiB, "
                f"pressure={vram.get('pressure')})"
            )

        # Stage 3: VERIFYING -> RECOVERING
        bs.set_oom_state("recovering", source="recovery_pipeline")
        logger.info(f"[oom-recovery] {gpu_id}: verifying -> recovering")

        # Force-evict the failed bundle with reentrancy protection (#5).
        # If service_name was 'unknown' (e.g. dmesg-killed PID), we still
        # want to mark recovered; we just skip the force-recover step.
        if service_name and service_name != "unknown":
            lock = _get_force_recover_lock(service_name)
            async with lock:
                try:
                    fr = globals().get("_force_recover_failed_service")
                    if fr is not None and inspect.iscoroutinefunction(fr):
                        await asyncio.wait_for(
                            fr(service_name, job_id or "", oom_reason or "oom"),
                            timeout=OOM_RECOVERY_TIMEOUT_S,
                        )
                    elif fr is not None:
                        # Sync function — call directly (no timeout wrapping)
                        fr(service_name, job_id or "", oom_reason or "oom")
                except asyncio.TimeoutError:
                    logger.warning(
                        f"[oom-recovery] _force_recover timeout for {service_name}"
                    )
                except Exception as e:
                    logger.error(
                        f"[oom-recovery] _force_recover failed for {service_name}: {e}"
                    )
        else:
            logger.info(
                f"[oom-recovery] {gpu_id}: skipping force_recover "
                f"(service_name={service_name!r})"
            )

        bs.oom_recovery_count += 1

        # First-OOM auto-retry marker (#2). The actual retry is handled
        # by the worker when it sees oom_retry_attempted=True on the
        # failed job — here we just set the flag.
        if not bs.oom_retry_attempted and oom_reason:
            bs.oom_retry_attempted = True
            logger.info(
                f"[oom-recovery] {gpu_id}: first-OOM retry flag set "
                f"(worker will retry with dim*{OOM_RETRY_DIM_SCALE}, "
                f"batch//{OOM_RETRY_BATCH_DIVISOR})"
            )

        # Stage 4: RECOVERING -> RESTORED
        bs.set_oom_state("restored", source="recovery_pipeline")
        logger.info(f"[oom-recovery] {gpu_id}: recovering -> restored")

        # Restore BOTH GPUs' idle LLMs (#3) using the pre-OOM snapshot (#7).
        restore_results = await _restore_both_idle_llms(pre_oom_snapshot)
        logger.info(
            f"[oom-recovery] Restore results: {restore_results}"
        )

        # Check permanent failure threshold (3 OOMs in 5 min on same GPU).
        # We check AFTER restore so we don't double-count the very OOM we
        # just recovered from (it's already in oom_recent_failure_times).
        now = time.time()
        recent = [
            t for t in bs.oom_recent_failure_times
            if now - t < OOM_PERMANENT_FAILURE_WINDOW_S
        ]
        bs.oom_recent_failure_times.clear()
        bs.oom_recent_failure_times.extend(recent + [now])
        if len(bs.oom_recent_failure_times) >= OOM_PERMANENT_FAILURE_THRESHOLD:
            bs.set_oom_state(
                "permanent_failed",
                source="recovery_pipeline",
                reason=(
                    f"{len(bs.oom_recent_failure_times)} OOMs in "
                    f"{OOM_PERMANENT_FAILURE_WINDOW_S}s window"
                ),
            )
            bs.oom_permanent_failure_count += 1
            logger.error(
                f"[oom-recovery] {gpu_id}: PERMANENT FAILED "
                f"({len(bs.oom_recent_failure_times)} OOMs in "
                f"{OOM_PERMANENT_FAILURE_WINDOW_S}s)"
            )
            # Phase 5: record to dead-letter list (best-effort)
            if job_id:
                try:
                    await _add_to_dead_letter(
                        job_id=job_id,
                        gpu_id=gpu_id,
                        reason=f"{len(bs.oom_recent_failure_times)} OOMs in {OOM_PERMANENT_FAILURE_WINDOW_S}s window",
                        last_state="permanent_failed",
                    )
                except Exception as _dl_err:
                    logger.debug(f"[oom-recovery] dead-letter add failed: {_dl_err}")
            return {
                "state": "permanent_failed",
                "recent_oom_count": len(bs.oom_recent_failure_times),
                "gpu_id": gpu_id,
            }

        return {
            "state": "restored",
            "gpu_id": gpu_id,
            "restore_results": restore_results,
        }
    finally:
        _oom_recovery_in_progress.pop(gpu_id, None)
        if lock_acquired and _oom_lock is not None:
            try:
                _oom_lock.release()
            except RuntimeError:
                # Already released — defensive
                pass


def _sync_legacy_gpu_state(gpu_id: str, bundle_state: "GpuBundleState") -> None:
    """Mirror GpuBundleState fields into scheduler._gpu_state[gpu_id] (if present).

    Phase 0: GpuBundleState is the single source of truth. This helper keeps
    the legacy scheduler._gpu_state dict in sync for read-only callers (the
    /health endpoint serializes dict(self._gpu_state)). Writes should always
    go through GpuBundleState setters, never directly to scheduler._gpu_state.
    Safe to call when scheduler is not yet initialised — silently no-ops.
    """
    try:
        sched = globals().get("scheduler")  # global GPUScheduler instance
        if sched is None:
            return
        legacy = getattr(sched, "_gpu_state", None)
        if not isinstance(legacy, dict):
            return
        if gpu_id not in legacy:
            legacy[gpu_id] = {
                "loaded_bundles": [],
                "evicting": False,
                "draining": False,
                "current_priority": 0,
            }
        st = legacy[gpu_id]
        st["loaded_bundles"] = list(bundle_state.loaded_bundles)
        st["evicting"] = bundle_state.evicting
        st["draining"] = bundle_state.draining
        st["current_priority"] = bundle_state.current_priority
        if "loading" in st or bundle_state.loading:
            st["loading"] = bool(bundle_state.loading)
    except Exception as e:  # pragma: no cover — defensive
        logger.debug(f"_sync_legacy_gpu_state({gpu_id}) failed: {e}")


def _get_gpu_state(gpu_id: str) -> GpuBundleState:
    """Get or create the state tracker for a GPU."""
    if gpu_id not in _gpu_states:
        _gpu_states[gpu_id] = GpuBundleState(gpu_id)
    return _gpu_states[gpu_id]


def _get_all_gpu_states() -> dict[str, GpuBundleState]:
    """Return all per-GPU states, creating entries for configured GPUs."""
    config = _load_services_config()
    bundles = _resolve_bundles()
    # Ensure all GPUs mentioned in bundles have state entries
    for _name, bundle in bundles.items():
        gpu_id = bundle.get("gpu_id")
        if gpu_id:
            _get_gpu_state(gpu_id)
    return _gpu_states


def _oom_recovery_status_snapshot(*, gpu_id: str | None = None, now: float | None = None) -> dict:
    """Build a stable OOM-status projection for every configured GPU.

    Status reads must not omit a configured GPU merely because no recovery
    path has materialized its mutable state yet. Such an entry is reported as
    idle with ``state_present=false`` rather than silently disappearing.
    """
    observed_now = time.time() if now is None else float(now)
    configured = _services_config.get("gpu_devices", {}) if isinstance(_services_config, dict) else {}
    known_ids = set(configured) if isinstance(configured, dict) else set()
    known_ids.update(_gpu_states)
    if gpu_id is not None:
        if gpu_id not in known_ids:
            return {"schema_version": 1, "error": f"unknown gpu_id: {gpu_id}"}
        ids = [gpu_id]
    else:
        ids = sorted(known_ids)

    heartbeat_age = observed_now - _last_oom_heartbeat_ts if _last_oom_heartbeat_ts > 0 else None
    result = {
        "schema_version": 1,
        "watchdog_heartbeat_age_s": heartbeat_age,
        "watchdog_heartbeat_fresh": heartbeat_age is not None and heartbeat_age < 30,
    }
    states = {}
    for gid in ids:
        state = _gpu_states.get(gid)
        present = state is not None
        states[gid] = {
            "gpu_id": gid,
            "state_present": present,
            "oom_state": state.oom_state if state else "idle",
            "oom_state_since": state.oom_state_since if state else 0.0,
            "oom_event_count": state.oom_event_count if state else 0,
            "oom_recovery_count": state.oom_recovery_count if state else 0,
            "oom_permanent_failure_count": state.oom_permanent_failure_count if state else 0,
            "oom_last_event_ts": state.oom_last_event_ts if state else 0.0,
            "oom_last_reason": state.oom_last_reason if state else "",
            "oom_retry_attempted": state.oom_retry_attempted if state else False,
            "inflight_started_ts": _oom_recovery_in_progress.get(gid),
        }
    if gpu_id is not None:
        result["gpu"] = states[gpu_id]
    else:
        result["gpus"] = states
        result["inflight"] = dict(_oom_recovery_in_progress)
    return result


async def _check_port_healthy(port: int | str | None) -> bool:
    """Quick check if a port is responding on localhost with HTTP 200."""
    if not port:
        return False
    try:
        async with session.get(
            f"http://127.0.0.1:{int(port)}/health",
            timeout=ClientTimeout(total=3),
        ) as resp:
            return resp.status == 200
    except Exception:
        return False


async def _normalise_pcie(addr: str | None) -> str:
    """Canonicalise a PCI Express BDF address from operator-owned input.

    Driver and sysfs sources may emit the same slot in different case,
    prefix, or short-form representations. This normaliser produces a single
    canonical form
    ``dddd:bb:dd.f`` (4-hex domain, 2-hex bus, 2-hex device, 1-hex
    function) so equality comparisons across these forms succeed.

    Returns the empty string for empty / unparseable input.
    """
    if not addr:
        return ""
    s = str(addr).strip()
    if not s:
        return ""
    # Find the first substring of the form hex:hex:hex(.hex)?.
    # The string may contain extra text (sysfs path, etc.); we
    # search the whole string for the first BDF-like sequence.
    import re as _re
    m = _re.search(
        r"([0-9a-fA-F]{1,4}):([0-9a-fA-F]{1,2}):([0-9a-fA-F]{1,2})(?:\.([0-9a-fA-F]))?",
        s,
    )
    if not m:
        return ""
    domain_s, bus_s, dev_s, fn_s = m.groups()
    try:
        domain = int(domain_s, 16)
        bus = int(bus_s, 16)
        dev = int(dev_s, 16)
        func = int(fn_s, 16) if fn_s else 0
    except ValueError:
        return ""
    return f"{domain:04x}:{bus:02x}:{dev:02x}.{func:x}"


# Module-level precompiled regexes (avoids recompiling on every call).
import re as _re_mod
_RENDER_NODE_RE = _re_mod.compile(r"^/dev/dri/renderD(\d+)$")
_PCI_BDF_RE = _re_mod.compile(r"([0-9a-f]{4}:[0-9a-f]{2}:[0-9a-f]{2}\.\d)")

# Short-lived cache for the render-node fdinfo scan. _poll_vram calls it
# at ~1 Hz, and _gpu_has_active_generation_tenant calls it whenever the
# idle-service watchdog runs. Without the cache, every watchdog tick
# would re-walk /proc. TTL is 1 second — shorter than the poll interval
# so stale data never persists between VRAM polls.
_vulkan_scan_cache: dict = {"data": None, "ts": 0.0}
_VULKAN_SCAN_TTL = 1.0
_vulkan_rn_map_cache: dict = {"data": None, "ts": 0.0}
_VULKAN_RN_MAP_TTL = 1.0


def _scan_render_node_fdinfo_cached() -> dict:
    """Cached wrapper around _scan_render_node_fdinfo (1s TTL)."""
    import time as _time
    now = _time.monotonic()
    if _vulkan_scan_cache["data"] is not None and (now - _vulkan_scan_cache["ts"]) < _VULKAN_SCAN_TTL:
        return _vulkan_scan_cache["data"]
    data = _scan_render_node_fdinfo()
    _vulkan_scan_cache["data"] = data
    _vulkan_scan_cache["ts"] = now
    return data


def _build_render_node_to_gpu_map_cached(gpu_devices: dict) -> dict:
    """Cached wrapper around _build_render_node_to_gpu_map (1s TTL)."""
    import time as _time
    now = _time.monotonic()
    if _vulkan_rn_map_cache["data"] is not None and (now - _vulkan_rn_map_cache["ts"]) < _VULKAN_RN_MAP_TTL:
        return _vulkan_rn_map_cache["data"]
    data = _build_render_node_to_gpu_map(gpu_devices)
    _vulkan_rn_map_cache["data"] = data
    _vulkan_rn_map_cache["ts"] = now
    return data


def _read_proc_name(pid: int) -> str:
    """Read the process name from /proc/<pid>/comm. Returns '' on error."""
    try:
        with open(f"/proc/{pid}/comm", "rb") as f:
            return f.read().decode("utf-8", errors="replace").strip()
    except (OSError, IOError):
        return ""


def _scan_render_node_fdinfo() -> dict:
    """Walk /proc/*/fd/ and return per-pid per-rendernode drm-vm + amdgpu VRAM usage.

    The drm-vm-size line in /proc/<pid>/fdinfo/<fd> is per GEM-object fd,
    regardless of whether the user-space driver is ROCm (KFD), Vulkan
    (RADV/amdvlk), OpenGL, or any other GEM-using API. This means a Vulkan
    process holding render-node GEM fds will be visible here even though
    amdgpu_top's per-process fdinfo only attributes to the KFD-visible
    allocation.

    Returns: { pid: { render_node_path: { drm_vm_bytes,
                                         amdgpu_vram_bytes, fd_count } } }
    No sudo required — /proc/<pid>/fdinfo/* is world-readable.
    """
    import os as _os
    result: dict = {}
    try:
        for entry in _os.listdir("/proc"):
            if not entry.isdigit():
                continue
            pid = int(entry)
            fd_dir = f"/proc/{entry}/fd"
            try:
                fd_names = _os.listdir(fd_dir)
            except (OSError, IOError):
                continue
            for fd_name in fd_names:
                try:
                    target = _os.readlink(f"{fd_dir}/{fd_name}")
                except (OSError, IOError):
                    continue
                if not _RENDER_NODE_RE.match(target):
                    continue
                try:
                    with open(f"{fd_dir}/fdinfo/{fd_name}", "rb") as f:
                        info = f.read().decode("utf-8", errors="replace")
                except (OSError, IOError):
                    continue
                drm_vm = 0
                amdgpu_vram = 0
                for line in info.splitlines():
                    if line.startswith("drm-vm-size:"):
                        try:
                            drm_vm += int(line.split(":", 1)[1].strip())
                        except (ValueError, IndexError):
                            pass
                    elif line.startswith("amdgpu-memory-vram:"):
                        try:
                            amdgpu_vram += int(line.split(":", 1)[1].strip())
                        except (ValueError, IndexError):
                            pass
                if drm_vm == 0 and amdgpu_vram == 0:
                    continue
                result.setdefault(pid, {}).setdefault(target, {
                    "drm_vm_bytes": 0,
                    "amdgpu_vram_bytes": 0,
                    "fd_count": 0,
                })
                result[pid][target]["drm_vm_bytes"] += drm_vm
                result[pid][target]["amdgpu_vram_bytes"] += amdgpu_vram
                result[pid][target]["fd_count"] += 1
    except OSError:
        pass
    return result


def _render_node_to_gpu_id(render_node: str, gpu_devices: dict) -> str | None:
    """Map an operator-owned render-node path to a configured logical GPU via PCI metadata."""
    import os as _os
    try:
        device_link = _os.readlink(f"/sys/class/drm/{_os.path.basename(render_node)}/device")
    except OSError:
        return None
    m = _PCI_BDF_RE.search(device_link)
    if not m:
        return None
    target_pci = m.group(1)
    for gid, cfg in gpu_devices.items():
        if cfg.get("pci") == target_pci:
            return gid
    return None


def _build_render_node_to_gpu_map(gpu_devices: dict) -> dict:
    """Build /dev/dri/renderD* -> gpu_id map for all known render nodes."""
    import os as _os
    result: dict = {}
    try:
        for entry in _os.listdir("/sys/class/drm"):
            if not entry.startswith("renderD"):
                continue
            gid = _render_node_to_gpu_id(f"/dev/dri/{entry}", gpu_devices)
            if gid:
                result[f"/dev/dri/{entry}"] = gid
    except OSError:
        pass
    return result


async def _gpu_has_active_generation_tenant(gpu_id: str | None) -> tuple[bool, str]:
    """Return (is_blocked, reason) — True if a generation backend is using this GPU.
    Checks: (a) any generation_backend with matching gpu_id has active systemd unit,
    (b) total VRAM used on the GPU > 2 GiB,
    (c) Vulkan/OpenGL/CL tenant holding GEM fds (drm-vm > 512 MiB)."""
    if not gpu_id:
        return False, ""
    config = _load_services_config()
    services = config.get("services", {})
    for name, svc in services.items():
        if svc.get("type") != "generation_backend":
            continue
        if svc.get("gpu_id") != gpu_id:
            continue
        unit = svc.get("systemd_unit", "")
        if not unit:
            continue
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "is-active", unit,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL,
        )
        stdout, _ = await proc.communicate()
        if stdout.decode().strip() == "active":
            return True, f"generation backend '{name}' ({unit}) is active on GPU {gpu_id}"
    # VRAM threshold check
    # B3 BUGFIX: build a normalized lookup from gpu_devices config so we
    # match by pcie address (or card name) from the vram poll, NOT by a
    # fragile substring match on a free-form gpu_name.  PR10 also
    # routes every comparison through ``_normalise_pcie()`` so that
    # the various BDF encodings (lspci -D, sysfs, sysfs path,
    # short-form) all collapse to a single canonical form before
    # comparison.
    try:
        gpu_devices = config.get("gpu_devices", {}) or {}
        # target_pcie: set of normalised pcie addresses.
        target_pcie: set[str] = set()
        # card -> gpu_id (fallback match for hosts where the
        # gpu_devices config has no ``pci`` field).
        target_card: dict[str, str] = {}
        for dev_id, dev_cfg in gpu_devices.items():
            raw_pci = dev_cfg.get("pci") or dev_cfg.get("pcie") or ""
            n_pci = await _normalise_pcie(raw_pci)
            if n_pci:
                target_pcie.add(n_pci)
            card = dev_cfg.get("card") or ""
            if card:
                target_card[card] = dev_id

        # Direct match: gpu_id itself is a normalised pcie address.
        gpu_id_norm = await _normalise_pcie(gpu_id)
        vram_data = await _poll_vram()
        # Find the GPU entry that matches the caller's gpu_id, either
        # by pcie address or by card name.
        target_gpu = None
        for gpu in vram_data.get("gpus", []):
            gpu_pci = await _normalise_pcie(gpu.get("pci_address") or "")
            gpu_card = gpu.get("card") or ""
            if gpu_id_norm and gpu_pci and gpu_pci == gpu_id_norm:
                target_gpu = gpu
                break
            if gpu_card and gpu_card in target_card and target_card[gpu_card] == gpu_id:
                target_gpu = gpu
                break
        if target_gpu is not None:
            used = target_gpu.get("vram_used_mib", 0) or 0
            if used > 2048:
                return True, f"GPU {gpu_id} VRAM {used} MiB > 2 GiB threshold"
    except Exception as e:
        logger.debug(f"B3 gate: VRAM threshold check failed: {e}")
    # Vulkan-tenant check: walk render-node fdinfo to find processes
    # holding GEM fds on the target GPU. ROCm processes won't show up
    # here (they use KFD, not GEM fds), but Vulkan/OpenGL/CL processes
    # will. This catches cases like a multi-GPU Vulkan backend where
    # the user-space allocation is ~8 GB of Vulkan and invisible to
    # amdgpu_top's KFD fdinfo path.
    try:
        config_v = _load_services_config()
        gpu_devices_v = config_v.get("gpu_devices", {}) or {}
        rn_map = _build_render_node_to_gpu_map_cached(gpu_devices_v)
        if gpu_id in rn_map.values():
            scan = await asyncio.get_event_loop().run_in_executor(
                None, _scan_render_node_fdinfo_cached
            )
            for pid, rn_data in scan.items():
                for rn, info in rn_data.items():
                    if rn_map.get(rn) != gpu_id:
                        continue
                    drm_vm_mib = info["drm_vm_bytes"] // (1024 * 1024)
                    if drm_vm_mib > 512:
                        name = _read_proc_name(pid) or f"pid={pid}"
                        return True, (
                            f"Vulkan tenant {name} (pid={pid}, "
                            f"{drm_vm_mib} MiB GEM-fd) on GPU {gpu_id}"
                        )
    except Exception as e:
        logger.debug(f"B3 gate: Vulkan tenant check failed: {e}")
    return False, ""


def enqueue_bundle_request(
    bundle_name: str,
    priority: int = 5,
    request_data: dict | None = None,
) -> asyncio.Future:
    """Create queue entries in ALL linked GPUs for a bundle request.

    Resolves the bundle's linked bundles from services.json, then creates
    entries in ALL linked GPUs' per-GPU queues with backend='bundle'.
    Each entry gets a shared bundle_job_id for cross-GPU coordination.

    Returns a Future that resolves when ALL components are loaded.

    IMPORTANT: Does NOT modify _load_bundle.  The queue system calls
    _load_bundle when it's time to actually load.
    """
    request_data = request_data or {}
    bundles = _resolve_bundles()
    bundle = bundles.get(bundle_name)

    if not bundle:
        raise ValueError(f"Unknown bundle: {bundle_name}")

    bundle_job_id = f"bundle_{bundle_name}_{int(time.time())}_{uuid.uuid4().hex[:8]}"
    all_gpu_ids = set()
    all_gpu_ids.add(bundle.get("gpu_id"))

    # Collect all linked bundle GPU IDs
    linked_names = bundle.get("linked_to", [])
    for linked_name in linked_names:
        linked = bundles.get(linked_name)
        if linked and linked.get("gpu_id"):
            all_gpu_ids.add(linked["gpu_id"])

    # Also check linked_from
    linked_from = bundle.get("linked_from", [])
    for linked_name in linked_from:
        linked = bundles.get(linked_name)
        if linked and linked.get("gpu_id"):
            all_gpu_ids.add(linked["gpu_id"])

    # Remove None values (CPU-only services)
    all_gpu_ids = {g for g in all_gpu_ids if g}

    # Register with the coordinator (this creates the shared Future)
    # We need to run this synchronously here since the caller expects
    # a return value, not a coroutine. The Future is created eagerly.
    loop = asyncio.get_event_loop()
    bundle_future = loop.create_future()

    bundle_coordinator._active_jobs[bundle_job_id] = {
        "bundle_name": bundle_name,
        "gpu_ids": all_gpu_ids.copy(),
        "ready_gpus": set(),
        "priority": priority,
        "request_data": request_data,
        "future": bundle_future,
        "created_at": time.time(),
    }
    logger.info(
        f"enqueue_bundle_request: '{bundle_name}' bundle_job_id={bundle_job_id} "
        f"gpu_ids={sorted(all_gpu_ids)} priority={priority}"
    )

    # Enqueue into every GPU's per-GPU queue
    for gpu_id in all_gpu_ids:
        gpu = _get_gpu_state(gpu_id)
        entry_request_data = dict(request_data)
        entry_request_data["backend"] = "bundle"
        entry_request_data["bundle_job_id"] = bundle_job_id
        entry_request_data["bundle_future"] = bundle_future
        entry_request_data["retry_count"] = 0
        gpu.enqueue(
            bundle_name=bundle_name,
            priority=priority,
            request_data=entry_request_data,
        )
        logger.info(
            f"enqueue_bundle_request: enqueued '{bundle_name}' "
            f"on GPU {gpu_id} (queue depth: {len(gpu.priority_queue)})"
        )

    return bundle_future


class BundleRequestQueue:
    """Pending HTTP request queue for a single bundle.

    When a request arrives for a bundle that isn't loaded, the request
    is held here as a Future.  When the bundle loads successfully all
    futures are resolved with True; on failure they resolve with False
    and the caller returns 503.

    Each pending entry carries:
      - ``future``: asyncio.Future[bool] that the handler awaits
      - ``enqueued_at``: timestamp for timeout checks
      - ``request_info``: dict with method/path/remote for logging

    Configurable per-bundle timeout (``bundle_config.get('timeout', 60)``).
    """

    def __init__(self, bundle_name: str, timeout: float = 60.0):
        self.bundle_name = bundle_name
        self.timeout = timeout
        # List of pending Future[bool] — True=loaded, False=failed
        self._pending: list[dict] = []
        self._lock = asyncio.Lock()

    # ── Public API ──────────────────────────────────────────────────

    async def wait_for_load(self, request_info: dict | None = None) -> bool:
        """Block until the bundle is ready, fails, or times out.

        Returns True when the bundle loaded successfully, False on
        failure or timeout.  *request_info* is an optional dict
        (method, path, remote) used for logging.
        """
        fut: asyncio.Future[bool] = asyncio.get_event_loop().create_future()
        entry = {
            "future": fut,
            "enqueued_at": time.time(),
            "request_info": request_info or {},
        }
        async with self._lock:
            self._pending.append(entry)

        tag = request_info.get("path", "") if request_info else ""
        logger.info(
            f"BundleQueue[{self.bundle_name}]: request queued "
            f"(pending={len(self._pending)}) {tag}"
        )

        try:
            result = await asyncio.wait_for(fut, timeout=self.timeout)
            return result
        except asyncio.TimeoutError:
            # Remove ourselves from the pending list
            async with self._lock:
                self._pending = [e for e in self._pending if e["future"] is not fut]
            logger.warning(
                f"BundleQueue[{self.bundle_name}]: request timed out "
                f"after {self.timeout}s"
            )
            return False

    async def resolve_all(self, success: bool) -> int:
        """Resolve every pending future and return the count resolved."""
        async with self._lock:
            entries = self._pending[:]
            self._pending.clear()

        for entry in entries:
            fut = entry["future"]
            if not fut.done():
                fut.set_result(success)

        status = "loaded" if success else "failed"
        logger.info(
            f"BundleQueue[{self.bundle_name}]: resolved {len(entries)} "
            f"pending request(s) as {status}"
        )
        return len(entries)

    def pending_count(self) -> int:
        return len(self._pending)

    def to_dict(self) -> dict:
        return {
            "bundle_name": self.bundle_name,
            "timeout": self.timeout,
            "pending_count": len(self._pending),
            "pending_requests": [
                {
                    "enqueued_at": e["enqueued_at"],
                    "elapsed": round(time.time() - e["enqueued_at"], 1),
                    "info": e.get("request_info", {}),
                }
                for e in self._pending
            ],
        }


# Global registry: bundle_name → BundleRequestQueue
_bundle_request_queues: dict[str, BundleRequestQueue] = {}


def _get_bundle_request_queue(bundle_name: str, timeout: float = 60.0) -> BundleRequestQueue:
    """Get or create the request queue for a bundle."""
    if bundle_name not in _bundle_request_queues:
        _bundle_request_queues[bundle_name] = BundleRequestQueue(bundle_name, timeout)
    return _bundle_request_queues[bundle_name]


def _should_evict(
    current_bundle_priority: int,
    incoming_bundle_priority: int,
    gpu_has_pending: bool,
) -> str:
    """Decide whether to evict the current bundle for an incoming request.

    Returns:
        "immediate" — evict right away (no pending requests to wait for)
        "drain_then_evict" — drain pending requests, then evict
        "queue" — don't evict, queue the request behind the current bundle
    """
    # Idle bundle (priority 0 or 1) → always evict
    if current_bundle_priority <= 1:
        if gpu_has_pending:
            return "drain_then_evict"
        return "immediate"

    # Higher priority incoming
    if incoming_bundle_priority > current_bundle_priority:
        if gpu_has_pending:
            return "drain_then_evict"
        return "immediate"

    # Same or lower priority → queue behind current
    return "queue"


# ── Priority Tiers ──────────────────────────────────────────────────

class PriorityTier(Enum):
    HIGH = 1       # Interactive requests - guaranteed 1 slot
    MEDIUM = 2     # Normal batch work
    LOW = 3        # Background/preemptible work


PRIORITY_TIER_MAP = {
    PriorityTier.HIGH: {"label": "HIGH", "color": "#f87171"},
    PriorityTier.MEDIUM: {"label": "MED", "color": "#fbbf24"},
    PriorityTier.LOW: {"label": "LOW", "color": "#6b7280"},
}


# ── Port Forwarding Proxy ────────────────────────────────────────────

class PortProxy:
    """TCP port forwarding proxy that bridges external connections to internal services."""

    def __init__(self, name: str, listen_port: int, target_host: str, target_port: int, logger: logging.Logger):
        self.name = name
        self.listen_port = listen_port
        self.target_host = target_host
        self.target_port = target_port
        self.logger = logger
        self._server = None

    async def start(self):
        """Start the TCP proxy server."""
        async def handle_client(reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
            peername = writer.get_extra_info('peername')
            self.logger.info(f"PortProxy[{self.name}]: connection from {peername}")
            backend_writer = None
            try:
                backend_reader, backend_writer = await asyncio.wait_for(
                    asyncio.open_connection(self.target_host, self.target_port),
                    timeout=10
                )
            except Exception as e:
                self.logger.warning(f"PortProxy[{self.name}]: backend connect failed: {e}")
                try:
                    writer.close()
                except Exception:
                    pass
                return

            async def pipe(src: asyncio.StreamReader, dst: asyncio.StreamWriter, direction: str):
                try:
                    while True:
                        data = await src.read(65536)
                        if not data:
                            break
                        dst.write(data)
                        await dst.drain()
                except Exception as e:
                    self.logger.debug(f"PortProxy[{self.name}]: pipe {direction} closed: {e}")
                finally:
                    try:
                        if direction == "upload":
                            backend_writer.close()
                        else:
                            writer.close()
                    except Exception:
                        pass

            try:
                await asyncio.gather(
                    pipe(reader, backend_writer, "upload"),
                    pipe(backend_reader, writer, "download"),
                )
            except Exception:
                pass
            self.logger.info(f"PortProxy[{self.name}]: connection closed {peername}")

        self._server = await asyncio.start_server(
            handle_client, '0.0.0.0', self.listen_port
        )
        self.logger.info(f"PortProxy[{self.name}]: listening on 0.0.0.0:{self.listen_port} → {self.target_host}:{self.target_port}")

    async def stop(self):
        """Stop the TCP proxy server."""
        if self._server:
            self._server.close()
            await self._server.wait_closed()
            self.logger.info(f"PortProxy[{self.name}]: stopped")
            self._server = None

    @property
    def is_running(self) -> bool:
        return self._server is not None and self._server.is_serving()


# Global port proxy registry
_port_proxies: dict[str, PortProxy] = {}


async def _start_all_port_proxies(config: dict):
    """Port proxies disabled — nginx handles all proxy routing.
    See nginx-manager.sh and _regenerate_nginx_config()."""
    pass


async def _stop_all_port_proxies():
    """Stop all running port proxies."""
    for name in list(_port_proxies.keys()):
        try:
            await _port_proxies[name].stop()
        except Exception as e:
            logger.error(f"PortProxy[{name}]: stop failed: {e}")
    _port_proxies.clear()


# ── Bundle Proxy (Phase 3) ────────────────────────────────────────
#
# Per-bundle HTTP proxy routing.  Requests hit /proxy/{bundle_name}/...
# and GPU Manager either forwards them immediately (if the bundle's
# services are loaded and healthy) or queues them and triggers a load.
# Linked bundles are loaded simultaneously.

BUNDLE_PROXY_WAIT_TIMEOUT = 300  # seconds a queued request waits for bundle load


class _BundleRequestQueue:
    """Manages queued HTTP requests for a single bundle.

    When the bundle is not loaded, incoming requests are held here.
    ``signal_ready()`` unblocks all waiters; ``signal_failed(err)``
    returns 503 to all queued requests.
    """

    def __init__(self, bundle_name: str):
        self.bundle_name = bundle_name
        self._ready_event = asyncio.Event()
        self._failed: bool = False
        self._fail_reason: str = ""
        self._queued_count: int = 0
        self._total_queued: int = 0
        self._total_served: int = 0

    @property
    def is_ready(self) -> bool:
        return self._ready_event.is_set() and not self._failed

    @property
    def is_failed(self) -> bool:
        return self._failed

    @property
    def queued_count(self) -> int:
        return self._queued_count

    def mark_loading(self) -> None:
        """Reset state for a new load attempt."""
        self._ready_event.clear()
        self._failed = False
        self._fail_reason = ""

    def signal_ready(self) -> None:
        """Bundle is healthy — unblock all queued requests."""
        self._failed = False
        self._ready_event.set()

    def signal_failed(self, reason: str = "bundle load failed") -> None:
        """Bundle failed to load — queued requests get 503."""
        self._failed = True
        self._fail_reason = reason
        self._ready_event.set()

    async def wait_for_ready(self, timeout: float = BUNDLE_PROXY_WAIT_TIMEOUT) -> bool:
        """Block until bundle is ready or timeout/failure. Returns True if ready."""
        self._queued_count += 1
        self._total_queued += 1
        try:
            await asyncio.wait_for(self._ready_event.wait(), timeout=timeout)
            return self.is_ready
        except asyncio.TimeoutError:
            return False
        finally:
            self._queued_count -= 1

    def mark_served(self) -> None:
        self._total_served += 1

    def to_dict(self) -> dict:
        return {
            "bundle_name": self.bundle_name,
            "ready": self.is_ready,
            "failed": self._failed,
            "fail_reason": self._fail_reason,
            "queued": self._queued_count,
            "total_queued": self._total_queued,
            "total_served": self._total_served,
        }

    def reset(self) -> None:
        """Reset counters (e.g. after bundle reload)."""
        self._ready_event.clear()
        self._failed = False
        self._fail_reason = ""
        self._queued_count = 0
        self._total_queued = 0
        self._total_served = 0


# Global registry: bundle_name -> _BundleRequestQueue
_bundle_proxy_queues: dict[str, _BundleRequestQueue] = {}


def _get_bundle_queue(bundle_name: str) -> _BundleRequestQueue:
    """Get or create the request queue for a bundle."""
    if bundle_name not in _bundle_proxy_queues:
        _bundle_proxy_queues[bundle_name] = _BundleRequestQueue(bundle_name)
    return _bundle_proxy_queues[bundle_name]


def _check_bundle_services_healthy(bundle: dict) -> bool:
    """Check if ALL services in a bundle are running and port-responding.

    Uses a quick TCP connect to the service port to verify liveness.
    """
    services_cfg = _services_config.get("services", {})
    for svc_name in bundle.get("services", []):
        svc = services_cfg.get(svc_name, {})
        port = svc.get("port")
        if not port:
            continue
        try:
            import socket as _sock
            with _sock.create_connection(("localhost", int(port)), timeout=2) as s:
                pass  # port is open
        except (OSError, TimeoutError):
            return False
    return True


def priority_to_tier(priority: int) -> PriorityTier:
    """Map generation priority through the shared named-priority contract."""
    priority_class = priority_envelope(
        priority,
        convention=PriorityConvention.GENERATION_HIGHER_IS_URGENT,
    ).priority_class.value
    return {
        "interactive": PriorityTier.HIGH,
        "normal": PriorityTier.MEDIUM,
        "background": PriorityTier.LOW,
    }[priority_class]


# ── Helpers ────────────────────────────────────────────────────────

def extract_model_key(workflow: dict) -> str:
    """Extract the primary diffusion model name from a ComfyUI workflow.

    Works with API format: {"3": {"class_type": "...", "inputs": {...}}}
    Returns the first matching model field value, or 'unknown'.
    """
    for nid, node in workflow.items():
        if not isinstance(node, dict) or "inputs" not in node:
            continue
        inputs = node["inputs"]
        for field in MODEL_KEY_FIELDS:
            if field in inputs:
                val = str(inputs[field])
                # Strip path — just use filename
                return val.rsplit("/", 1)[-1] if "/" in val else val
    return "unknown"


def extract_model_fingerprint(workflow: dict) -> str:
    """Create a fingerprint of ALL model inputs for grouping.

    Jobs with the same fingerprint can run in sequence without model swaps.
    """
    parts = []
    for nid, node in workflow.items():
        if not isinstance(node, dict) or "inputs" not in node:
            continue
        inputs = node["inputs"]
        for field in MODEL_KEY_FIELDS + AUX_MODEL_FIELDS:
            if field in inputs:
                val = str(inputs[field])
                basename = val.rsplit("/", 1)[-1] if "/" in val else val
                parts.append(f"{field}={basename}")
    parts.sort()
    return "|".join(parts) if parts else "default"


# ── Job Data ───────────────────────────────────────────────────────

class Job:
    """A queued ComfyUI workflow submission."""
    def __init__(self, workflow: dict, callback_url: str | None = None,
                 priority: int = 0, metadata: dict | None = None):
        self.id = str(uuid.uuid4())[:8]
        self.backend = "comfyui"
        self.workflow = workflow
        self.model_key = extract_model_key(workflow)
        self.fingerprint = extract_model_fingerprint(workflow)
        self.callback_url = callback_url
        self.priority = priority
        self.metadata = metadata or {}
        self.created_at = time.time()
        self.started_at: float | None = None
        self.finished_at: float | None = None
        self.status: str = "queued"  # queued | running | completed | failed | cancelled
        self.result: dict | None = None
        self.comfyui_prompt_id: str | None = None
        self.preempted: bool = False  # flag for preempted-re-queued jobs

    @property
    def priority_tier(self) -> PriorityTier:
        return priority_to_tier(self.priority)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "backend": self.backend,
            "model_key": self.model_key,
            "fingerprint": self.fingerprint,
            "status": self.status,
            "priority": self.priority,
            "priority_tier": self.priority_tier.value,
            "created_at": self.created_at,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "comfyui_prompt_id": self.comfyui_prompt_id,
            "metadata": self.metadata,
            "result": self.result,
            "preempted": self.preempted,
        }


class AceStepJob:
    """A queued ACE-Step music generation job."""
    def __init__(self, payload: dict, callback_url: str | None = None,
                 priority: int = 0, metadata: dict | None = None,
                 service_name: str = "acestep", bundle_name: str | None = None,
                 job_id: str | None = None):
        service = _resolve_acestep_service(service_name)
        self.id = job_id or str(uuid.uuid4())[:8]
        self.backend = "acestep"
        self.payload = payload
        self.callback_url = callback_url
        self.priority = priority
        self.metadata = metadata or {}
        self.created_at = time.time()
        self.started_at: float | None = None
        self.finished_at: float | None = None
        self.status: str = "queued"  # queued | running | completed | failed | cancelled
        self.result: dict | None = None
        self.acestep_task_id: str | None = None
        self.preempted: bool = False  # flag for preempted-re-queued jobs
        self.service_name = service["service_name"]
        self.endpoint = service["endpoint"]
        self.audio_dir = service["audio_dir"]
        self.bundle_name = bundle_name or service.get("bundle_name")

    @property
    def priority_tier(self) -> PriorityTier:
        return priority_to_tier(self.priority)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "backend": self.backend,
            "status": self.status,
            "priority": self.priority,
            "priority_tier": self.priority_tier.value,
            "created_at": self.created_at,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "acestep_task_id": self.acestep_task_id,
            "service_name": self.service_name,
            "endpoint": self.endpoint,
            "bundle_name": self.bundle_name,
            "metadata": self.metadata,
            "preempted": self.preempted,
            "result": {k: v for k, v in (self.result or {}).items()
                       if k != "lyrics"},  # Don't include lyrics in status
        }


# ── Core Services ──────────────────────────────────────────────────

class LLMProxy:
    """Lightweight proxy with health monitoring and request queueing."""

    def __init__(self):
        self.active_requests = 0
        self.queued_requests = 0
        self.total_requests = 0
        self.total_served = 0
        self.total_queued = 0
        self.total_timeouts = 0
        # Explicit process-scoped accounting. Legacy total_* fields remain for
        # compatibility but no longer obscure wait/queue/forward semantics.
        self.wait_attempts = 0
        self.wait_timeouts = 0
        self.durable_queue_admissions = 0
        self.forward_attempts = 0
        self.backend_responses = 0
        self.backend_successes = 0
        self.backend_failures = 0
        self._llm_healthy = False
        self.session: ClientSession | None = None
        self.logger = logging.getLogger("gpu-manager")
        self._llm_ready_event = asyncio.Event()
        self._llm_ready_event.set()

    async def check_health(self) -> bool:
        target = _configured_llm_health_target()
        if target is None:
            self.logger.debug("LLM health check skipped: no configured registry idle service")
            return False
        if self.session is None or self.session.closed:
            self.logger.debug("LLM health check skipped: HTTP session unavailable")
            return False
        url, service_name = target
        try:
            async with self.session.get(
                url,
                timeout=ClientTimeout(total=5, connect=3),
            ) as resp:
                ok = resp.status == 200
                if ok:
                    body = await resp.json()
                    ok = body.get("status") == "ok"
                self.logger.debug(
                    "LLM health check service=%s status=%s ok=%s",
                    service_name,
                    resp.status,
                    ok,
                )
                return ok
        except Exception as e:
            self.logger.warning(f"LLM health check failed: {e}")
            return False

    async def wait_for_llm(self, timeout: float = LLM_WAIT_TIMEOUT) -> bool:
        if self._llm_healthy:
            return True
        try:
            await asyncio.wait_for(self._llm_ready_event.wait(), timeout=timeout)
            return self._llm_healthy
        except asyncio.TimeoutError:
            return False

    def update_health(self, healthy: bool):
        prev = self._llm_healthy
        self._llm_healthy = healthy
        if healthy and not prev:
            if self.queued_requests > 0:
                self.logger.info(f"LLM healthy — waking {self.queued_requests} queued request(s)")
            self._llm_ready_event.set()
        elif not healthy and prev:
            self.logger.info("LLM offline — future requests will queue")
            self._llm_ready_event.clear()

    def status(self) -> dict:
        return {
            "llm_healthy": self._llm_healthy,
            "active_requests": self.active_requests,
            "queued_requests": self.queued_requests,
            "total_requests": self.total_requests,
            "total_served": self.total_served,
            "total_queued": self.total_queued,
            "total_timeouts": self.total_timeouts,
            "request_metrics": {
                "scope": "process_memory",
                "resets_on_restart": True,
                "requests_received": self.total_requests,
                "wait_attempts": self.wait_attempts,
                "wait_timeouts": self.wait_timeouts,
                "durable_queue_admissions": self.durable_queue_admissions,
                "forward_attempts": self.forward_attempts,
                "backend_responses": self.backend_responses,
                "backend_successes": self.backend_successes,
                "backend_failures": self.backend_failures,
            },
        }


# ── Unified GPU Scheduler ──────────────────────────────────────────

class GPUScheduler:
    """Unified GPU scheduler managing ComfyUI and ACE-Step queues.

    GPU state machine:
      LLM_LOADED → DRAINING → GPU_WORK → RESTORING → LLM_LOADED
      GPU_WORK → LLM_RELIEF → DRAINING → GPU_WORK  (backpressure relief)

    Default state: LLM_LOADED (Qwen3.6 on GPU, serving requests)
    When GPU work arrives: evict LLM, process jobs, restore LLM.
    If LLM queue builds up (>=10): temporary relief cycle.

    Scheduling policy:
      - Longest-queue-first: picks ComfyUI or ACE-Step with most pending jobs
      - ComfyUI wins ties (typically faster per-job)
      - LLM relief: restores LLM when queued >= threshold, then resumes GPU
      - Coalesce: runs all queued GPU work before restoring LLM
    """

    def __init__(self, session: ClientSession, logger: logging.Logger):
        self.session = session
        self.logger = logger

        # ComfyUI queue
        self.comfyui_jobs: dict[str, Job] = {}
        self._comfyui_queue: list[Job] = []

        # ACE-Step queue
        self.acestep_jobs: dict[str, AceStepJob] = {}
        self._acestep_queue: list[AceStepJob] = []

        # Scheduling state
        self._running = False
        self._scheduler_task: asyncio.Task | None = None
        self._current_backend: str | None = None  # "comfyui" or "acestep"
        self._restoring = False  # Guard against concurrent restores
        self._swapping = False   # Guard against concurrent idle service swaps
        self._last_idle_restore_attempt: float | None = None  # Legacy throttle (kept for compat)
        self._last_idle_restore_attempt_map: dict[str, float] = {}  # Per-service throttle timestamps
        self._idle_service_last_healthy: dict[str, float] = {}  # Per-service last-known-healthy time
        self._idle_service_last_started: dict[str, float] = {}  # Per-service last-start time (cooldown guard)
        self._idle_recovery_states: dict[str, RecoveryState] = {}  # Shared recovery reducer state
        self._idle_check_event: asyncio.Event = asyncio.Event()  # Signal to trigger immediate idle check

        # ── Phase 2: Per-GPU priority queue management ──────────────
        self._gpu_queues: dict[str, list] = defaultdict(list)  # gpu_id → list of Job/AceStepJob
        self._gpu_state: dict[str, dict] = {}
        # Initialize per-GPU state for all configured GPUs
        try:
            _config = _load_services_config()
            for _gpu_id in _config.get("gpu_devices", {}):
                self._gpu_state[_gpu_id] = {
                    "loaded_bundles": [],
                    "evicting": False,
                    "draining": False,
                    "current_priority": 0,
                }
        except Exception:
            pass  # Config not available yet — state initialized on first use

        # Counters
        self.total_batches = 0
        self.total_jobs_completed = 0
        self.total_jobs_failed = 0
        self.total_auto_frees = 0
        self.total_llm_reliefs = 0
        self.total_preemptions = 0
        self._pinned_service: str | None = None  # Queue override: only this service's backend runs
        self._pinned_service_since: float | None = None  # Phase 5.2.53 Fix B: timestamp when pin was set, for stale-pin auto-clear
        # Phase 5.2.66: manual coexistence mode — SRE pause of auto-restoration.
        # When True, _ensure_idle_service skips auto-restore AND crash-recovery so
        # SREs can perform clean maintenance (e.g. swap LLM weights, evict for a
        # heavy ComfyUI bundle) without the scheduler fight-restarting in a loop.
        # In-memory only — a restart clears the pause. Pause auto-expires when
        # _coexistence_pause_expires > 0 and time.time() > that timestamp.
        self._coexistence_paused: bool = False
        self._coexistence_pause_expires: float = 0.0  # 0 = no expiry
        self._coexistence_paused_at: float = 0.0     # when the current pause began

        # ── Lifecycle transition tracking ──────────────────────────────
        self._lifecycle = {
            "state": "idle",         # idle | transitioning | error
            "type": None,            # swap | start | stop | restore
            "target_service": None, # e.g. "LLM-Primary"
            "steps": [],             # list of step dicts (clone of template)
            "current_step": -1,      # index into steps
            "started_at": None,      # timestamp
            "progress_pct": 0,       # 0-100
            "message": "",           # human-readable current step description
            "error": None,           # error string if state==error
        }
        self._toggle_debounce: dict[str, float] = {}  # service_name → timestamp
        self._debounced_state: dict[str, str] = {}  # service_name → last confirmed health state
        self.DEBOUNCE_WINDOW = 10.0  # seconds to suppress flicker after toggle
        # ── Phase 4h.3 S2: cached read of bundle_idle_threshold_seconds ─
        self._cached_threshold: float | None = None
        self._cached_threshold_at: float = 0.0
        self._THRESHOLD_CACHE_TTL: float = 10.0

        # ── Phase 5.2.69: Orphan reaper state ─────────────────────────
        # Set of PIDs gpu-manager believes it owns (started via _load_bundle
        # or one of the explicit systemctl start paths). The reaper tick
        # consults this set when deciding whether a VRAM-holding process is
        # an orphan (PID not in set + PPID==1 → candidate).
        self._expected_pids: set[int] = set()
        # PIDs we recently signalled (SIGTERM at first, then SIGKILL after
        # grace). Used to avoid double-logging the same orphan across ticks.
        self._terminated_pids: dict[int, float] = {}  # pid → sigterm_at
        # Delay the first potentially disruptive /proc + VRAM poll after a
        # manager restart.  A zero timestamp caused the first scheduler tick
        # to invoke amdgpu_top immediately during driver/firmware recovery.
        self._last_orphan_reaper_at: float = (
            time.time() + ORPHAN_REAPER_STARTUP_GRACE_S - ORPHAN_REAPER_INTERVAL_S
        )
        # Cache of (unit → MainPID) so we don't fork `systemctl show` on
        # every tick for every enabled service.
        self._mainpid_cache: dict[str, tuple[int, float]] = {}  # unit → (pid, ts)
        self._MAINPID_CACHE_TTL_S: float = 10.0

    # ── Lifecycle transition tracking ─────────────────────────────────

    def _lifecycle_begin(self, transition_type: str, target_service: str, template_key: str, from_state: str = None, to_state: str = None):
        """Start a lifecycle transition. Call before a swap/start/stop/restore."""
        self._lifecycle["state"] = "transitioning"
        self._lifecycle["type"] = transition_type
        self._lifecycle["target_service"] = target_service
        self._lifecycle["from_state"] = from_state
        self._lifecycle["to_state"] = to_state
        self._lifecycle["started_at"] = time.time()
        self._lifecycle["error"] = None
        self._lifecycle["current_step"] = -1
        self._lifecycle["progress_pct"] = 0
        # Clone the step template
        import copy
        self._lifecycle["steps"] = copy.deepcopy(TRANSITION_STEPS.get(template_key, []))
        asyncio.create_task(_broadcast_lifecycle())

    def _lifecycle_step_begin(self, step_id: str):
        """Mark a step as active. Call before executing the step's action."""
        for i, step in enumerate(self._lifecycle["steps"]):
            if step["id"] == step_id and step.get("status") != "done":
                step["status"] = "active"
                step["started_at"] = time.time()
                self._lifecycle["current_step"] = i
                self._lifecycle["message"] = step["label"]
                self._lifecycle["progress_pct"] = self._calc_progress(i, 0.0)
                asyncio.create_task(_broadcast_lifecycle())
                return
        self.logger.warning(f"lifecycle_step_begin: unknown step '{step_id}'")

    def _lifecycle_step_done(self, step_id: str, sub_progress: float = 1.0):
        """Mark a step as done. sub_progress (0-1) used for wait loops."""
        for i, step in enumerate(self._lifecycle["steps"]):
            if step["id"] == step_id:
                step["status"] = "done"
                step["duration_s"] = (time.time() - step.get("started_at", time.time()))
                self._lifecycle["progress_pct"] = self._calc_progress(i + 1, 0.0)
                asyncio.create_task(_broadcast_lifecycle())
                return
        self.logger.warning(f"lifecycle_step_done: unknown step '{step_id}'")

    def _lifecycle_step_progress(self, step_id: str, sub_progress: float):
        """Update sub-progress of an active step (e.g. VRAM load 42%)."""
        for step in self._lifecycle["steps"]:
            if step["id"] == step_id and step.get("status") == "active":
                self._lifecycle["progress_pct"] = self._calc_progress(
                    self._lifecycle["current_step"], sub_progress
                )
                asyncio.create_task(_broadcast_lifecycle())
                return

    def _lifecycle_complete(self):
        """Mark transition as complete, return to idle."""
        self._lifecycle["state"] = "idle"
        self._lifecycle["progress_pct"] = 100
        self._lifecycle["message"] = "Complete"
        self._lifecycle["current_step"] = -1
        asyncio.create_task(_broadcast_lifecycle())

    def _lifecycle_error(self, msg: str):
        """Mark transition as failed."""
        self._lifecycle["state"] = "error"
        self._lifecycle["error"] = msg
        self._lifecycle["message"] = f"Error: {msg}"
        asyncio.create_task(_broadcast_lifecycle())

    def _calc_progress(self, completed_steps: int, sub_progress: float) -> int:
        """Calculate overall progress percentage."""
        steps = self._lifecycle["steps"]
        if not steps:
            return 100
        total_weight = sum(s.get("weight", 10) for s in steps)
        completed_weight = sum(
            steps[i].get("weight", 10) for i in range(completed_steps)
        )
        current_weight = steps[completed_steps].get("weight", 10) if completed_steps < len(steps) else 0
        pct = (completed_weight + current_weight * sub_progress) / total_weight * 100
        return int(min(99, pct))  # 100 only when fully done

    def get_lifecycle_status(self) -> dict:
        """Return current lifecycle state for API and WS. Single serialization source."""
        return {
            "state": self._lifecycle["state"],
            "type": self._lifecycle["type"],
            "target_service": self._lifecycle["target_service"],
            "from_state": self._lifecycle.get("from_state"),
            "to_state": self._lifecycle.get("to_state"),
            "started_at": self._lifecycle["started_at"],
            "elapsed_s": round(time.time() - self._lifecycle["started_at"], 1) if self._lifecycle["started_at"] else 0,
            "elapsed_ms": int((time.time() - self._lifecycle["started_at"]) * 1000) if self._lifecycle["started_at"] else 0,
            "current_step": self._lifecycle["current_step"],
            "progress_pct": self._lifecycle["progress_pct"],
            "message": self._lifecycle["message"],
            "error": self._lifecycle["error"],
            "steps": [
                {
                    "id": s["id"],
                    "label": s["label"],
                    "name": s["id"],
                    "status": s.get("status", "pending"),
                    "started_at": s.get("started_at"),
                    "duration_s": s.get("duration_s"),
                    "duration": s.get("duration_s"),
                }
                for s in self._lifecycle["steps"]
            ],
        }

    def is_transitioning(self) -> bool:
        """True if a lifecycle transition is in progress."""
        return self._lifecycle["state"] == "transitioning"

    def get_debounced_health(self, service_name: str, actual_health: str) -> str:
        """Apply toggle-debounce to prevent flickering during transitions."""
        if service_name in self._toggle_debounce:
            elapsed = time.time() - self._toggle_debounce[service_name]
            if elapsed < self.DEBOUNCE_WINDOW:
                # Still within debounce window — show previous confirmed state
                return self._debounced_state.get(service_name, actual_health)
            else:
                # Window expired — clear debounce, use actual
                del self._toggle_debounce[service_name]
        return actual_health

    # ── Job submission ─────────────────────────────────────────────

    def submit_comfyui(self, workflow: dict, callback_url: str | None = None,
                        priority: int = 0, metadata: dict | None = None) -> Job:
        """Add a ComfyUI job to the queue."""
        # Phase 5.2.79 (R2): belt-and-braces sanitizer at the choke point.
        # Every /prompt POST in any code path goes through Job construction,
        # which is fed by this method. The earlier sanitization sites
        # (handle_pipeline_submit, handle_queue_insert, _build_workflow,
        # _build_comfyui_workflow_entry) are the suspenders; this is the
        # belt. Operator sees log warnings when keys get dropped (per R2
        # risk note — never silent).
        from comfyui_workflow_sanitize import sanitize_comfyui_workflow
        workflow = sanitize_comfyui_workflow(workflow, source="submit_comfyui")

        # Auto-start ComfyUI if it was stopped (idle timeout or manual).
        # Fire-and-forget to avoid blocking the API — the scheduler loop
        # has _ensure_comfyui_running() as a secondary guard.
        if vram._comfyui_auto_stopped:
            self.logger.info("ComfyUI auto-stopped — triggering async restart for new job")
            vram._comfyui_auto_stopped = False
            asyncio.create_task(vram._start_comfyui_async())
        elif vram._comfyui_stopped:
            self.logger.info("ComfyUI stopped — triggering async restart for new job")
            asyncio.create_task(vram._start_comfyui_async())

        job = Job(workflow, callback_url, priority, metadata)
        self.comfyui_jobs[job.id] = job
        self._comfyui_queue.append(job)
        # Phase 2: Route to per-GPU priority queue
        self._route_to_gpu_queue(job)
        self.logger.info(
            f"ComfyUI job {job.id} queued: model={job.model_key}, "
            f"fingerprint={job.fingerprint[:60]}, "
            f"comfyui_queue={len(self._comfyui_queue)}, acestep_queue={len(self._acestep_queue)}"
        )
        return job

    def submit_acestep(self, payload: dict, callback_url: str | None = None,
                       priority: int = 0, metadata: dict | None = None,
                       service_name: str = "acestep", bundle_name: str | None = None,
                       job_id: str | None = None) -> AceStepJob:
        """Submit an ACE-Step job. Returns immediately with job info."""
        job = AceStepJob(
            payload, callback_url, priority, metadata,
            service_name=service_name, bundle_name=bundle_name, job_id=job_id,
        )
        self.acestep_jobs[job.id] = job
        self._acestep_queue.append(job)
        # Phase 2: Route to per-GPU priority queue
        self._route_to_gpu_queue(job)
        self.logger.info(
            f"ACE-Step job {job.id} queued: "
            f"comfyui_queue={len(self._comfyui_queue)}, acestep_queue={len(self._acestep_queue)}"
        )
        return job

    def cancel(self, job_id: str) -> bool:
        """Cancel a queued job (ComfyUI or ACE-Step). Returns True if cancelled."""
        # Try ComfyUI
        job = self.comfyui_jobs.get(job_id)
        if job and job.status == "queued":
            job.status = "cancelled"
            job.finished_at = time.time()
            self._comfyui_queue = [j for j in self._comfyui_queue if j.id != job_id]
            self._remove_from_gpu_queue(job)
            self.logger.info(f"ComfyUI job {job_id} cancelled")
            return True
        # Try ACE-Step
        job = self.acestep_jobs.get(job_id)
        if job and job.status == "queued":
            job.status = "cancelled"
            job.finished_at = time.time()
            self._acestep_queue = [j for j in self._acestep_queue if j.id != job_id]
            self._remove_from_gpu_queue(job)
            self.logger.info(f"ACE-Step job {job_id} cancelled")
            return True
        return False

    def get_job(self, job_id: str) -> Job | AceStepJob | None:
        """Get a job by ID (ComfyUI or ACE-Step)."""
        return self.comfyui_jobs.get(job_id) or self.acestep_jobs.get(job_id)

    def get_queue_status(self) -> dict:
        comfyui_queued = [j for j in self._comfyui_queue if j.status == "queued"]
        acestep_queued = [j for j in self._acestep_queue if j.status == "queued"]
        comfyui_running = [j for j in self.comfyui_jobs.values() if j.status == "running"]
        acestep_running = [j for j in self.acestep_jobs.values() if j.status == "running"]

        by_model = defaultdict(list)
        for j in comfyui_queued:
            by_model[j.model_key].append(j.id)

        return {
            "scheduler_running": self._running,
            "gpu_state": vram.gpu_state.value if vram else "unknown",
            "current_backend": self._current_backend,
            "comfyui": {
                "queued": len(comfyui_queued),
                "running": len(comfyui_running),
                "by_model": {k: v for k, v in sorted(by_model.items())},
            },
            "acestep": {
                "queued": len(acestep_queued),
                "running": len(acestep_running),
            },
            "total_completed": self.total_jobs_completed,
            "total_failed": self.total_jobs_failed,
            "total_batches": self.total_batches,
            "total_auto_frees": self.total_auto_frees,
            "total_llm_reliefs": self.total_llm_reliefs,
            "total_preemptions": self.total_preemptions,
            "pinned_service": self._pinned_service,
            "gpu_queues": {
                gid: len([j for j in jobs if j.status == "queued"])
                for gid, jobs in self._gpu_queues.items()
            },
            "gpu_state": dict(self._gpu_state),
        }

    # ── Per-GPU Queue Routing (Phase 2) ───────────────────────────

    def _route_to_gpu_queue(self, job: Job | AceStepJob) -> None:
        """Route a job to the appropriate per-GPU priority queue.

        Determines the target GPU from the backend type, then inserts
        the job sorted by priority (higher priority first, FIFO within
        the same priority).
        """
        # Determine target GPU from backend type
        config = _load_services_config()
        svc_map = config.get("services", {})
        gpu_id = None

        for svc_key, svc_cfg in svc_map.items():
            if svc_cfg.get("type") == "generation_backend":
                if job.backend == "comfyui" and "comfyui" in svc_key:
                    gpu_id = svc_cfg.get("gpu_id", "gpu_primary")
                    break
                elif job.backend == "acestep" and "acestep" in svc_key:
                    gpu_id = svc_cfg.get("gpu_id", "gpu_primary")
                    break

        if not gpu_id:
            gpu_id = "gpu_primary"  # Default to primary GPU

        # Initialize GPU state if needed
        if gpu_id not in self._gpu_state:
            self._gpu_state[gpu_id] = {
                "loaded_bundles": [],
                "evicting": False,
                "draining": False,
                "current_priority": 0,
            }

        # Insert into GPU queue sorted by priority (higher first, FIFO within same)
        gpu_q = self._gpu_queues[gpu_id]
        import bisect
        # Sort key: (-priority, created_at) → higher priority first, older first
        sort_key = (-job.priority, job.created_at)
        # Find insertion point using bisect on existing sort keys
        existing_keys = [(-j.priority, j.created_at) for j in gpu_q]
        idx = bisect.bisect_left(existing_keys, sort_key)
        gpu_q.insert(idx, job)
        self.logger.debug(
            f"Phase2: Routed {job.backend} job {job.id} to GPU {gpu_id} queue "
            f"(priority={job.priority}, queue_depth={len(gpu_q)})"
        )

    def _get_jobs_for_gpu(self, gpu_id: str) -> list[Job | AceStepJob]:
        """Get all active (queued or running) jobs for a specific GPU."""
        return [
            j for j in self._gpu_queues.get(gpu_id, [])
            if j.status in ("queued", "running")
        ]

    def _get_pending_for_gpu(self, gpu_id: str) -> list[Job | AceStepJob]:
        """Get pending (queued) jobs for a specific GPU, sorted by priority."""
        return [
            j for j in self._gpu_queues.get(gpu_id, [])
            if j.status == "queued"
        ]

    def _has_higher_priority_pending(self, gpu_id: str, current_priority: int) -> bool:
        """Check if there's a higher-priority job pending for this GPU."""
        pending = self._get_pending_for_gpu(gpu_id)
        return any(j.priority > current_priority for j in pending)

    def _remove_from_gpu_queue(self, job: Job | AceStepJob, gpu_id: str = None) -> None:
        """Remove a job from the per-GPU queue(s)."""
        if gpu_id:
            if gpu_id in self._gpu_queues:
                self._gpu_queues[gpu_id] = [
                    j for j in self._gpu_queues[gpu_id] if j.id != job.id
                ]
        else:
            # Remove from all GPU queues (we don't know which GPU)
            for gid in list(self._gpu_queues.keys()):
                self._gpu_queues[gid] = [
                    j for j in self._gpu_queues[gid] if j.id != job.id
                ]

    def start(self):
        """Start the background scheduler loop."""
        if self._scheduler_task and not self._scheduler_task.done():
            return
        self._scheduler_task = asyncio.create_task(self._scheduler_loop())
        self.logger.info("Unified GPU scheduler started")

    async def stop(self):
        """Fence scheduler dispatch and bound cancellation during app shutdown."""
        self._running = False
        task = self._scheduler_task
        if not task or task.done():
            return
        task.cancel()
        try:
            await asyncio.wait_for(task, timeout=SCHEDULER_STOP_TIMEOUT_SECONDS)
        except asyncio.CancelledError:
            pass
        except asyncio.TimeoutError:
            self.logger.warning(
                "Scheduler task exceeded %.1fs cancellation budget during shutdown",
                SCHEDULER_STOP_TIMEOUT_SECONDS,
            )

    # ── Phase 5: explicit restart method ─────────────────────────────
    # Per adversarial "scheduler.restart() must be a first-class method":
    # instead of reaching into run_async/run via getattr (which the health
    # loop already does as a fallback), expose restart() that:
    #   - cancels any running scheduler task
    #   - creates a fresh task running self._scheduler_loop()
    #   - sets self._running=True so _scheduler_health_check_loop sees it
    async def restart(self) -> bool:
        """Restart the scheduler loop. Returns True on success.

        Called by _scheduler_health_check_loop when scheduler_running=false
        for >30s. Cancels any in-flight task, then spawns a fresh
        _scheduler_loop() task. This is safer than the getattr-based
        fallback because it always uses the same entrypoint and handles
        cancel/await explicitly.
        """
        self.logger.info("[scheduler] Restart requested")
        if self._scheduler_task and not self._scheduler_task.done():
            self._scheduler_task.cancel()
            try:
                await self._scheduler_task
            except asyncio.CancelledError:
                pass
            except Exception as e:
                self.logger.warning(f"[scheduler] cancel error during restart: {e}")
        self._scheduler_task = asyncio.create_task(self._scheduler_loop())
        self._running = True
        self.logger.info("[scheduler] Restarted (fresh _scheduler_loop task)")
        return True

    # ── Per-GPU Drain ────────────────────────────────────────────────

    async def _gpu_drain(self, gpu_id: str, timeout: float = DRAIN_TIMEOUT) -> bool:
        """Drain pending requests on a specific GPU before eviction.

        1. Sets the GPU to 'draining' state
        2. Stops accepting NEW requests for the current bundle
        3. Waits for in-flight requests to finish
        4. Returns True when drained (or False on timeout)

        After calling this, the caller should evict the current bundle
        and load the new one.
        """
        gpu = _get_gpu_state(gpu_id)

        if gpu.draining:
            self.logger.info(f"GPU[{gpu_id}]: already draining — waiting")
            return await gpu.wait_drain(timeout)

        # Mark as draining — proxy will stop forwarding new requests
        gpu.start_drain()

        # Also mark the global LLM as unhealthy if this is an LLM bundle,
        # so the proxy stops forwarding new LLM requests
        bundles = _resolve_bundles()
        for bname, bundle in bundles.items():
            if bundle.get("gpu_id") == gpu_id and bundle.get("idle"):
                llm.update_health(False)
                break

        return await gpu.wait_drain(timeout)

    async def _force_evict_gpu(self, gpu_id: str) -> bool:
        """Force-evict whatever is currently loaded on a GPU.

        Used when a high-priority request needs immediate GPU access
        and the current load cannot be allowed to finish.

        Lifecycle Guard 2026-08-07: loaded bundles must be torn down via
        the controller-owned ``_unload_bundle`` path (and ultimately the
        bundle lifecycle controller). Direct systemctl stop on bundle
        members races the controller and can leave ledger state out of
        sync with systemd. The authoritative loaded state is only
        cleared once the controller teardown reports success; failure
        leaves the ledger intact and returns False so callers can
        re-route through proper admission.
        """
        gpu = _get_gpu_state(gpu_id)
        loaded = gpu.loaded_bundle
        if not loaded:
            return True  # Nothing loaded

        self.logger.info(
            f"GPU[{gpu_id}]: force-evicting '{loaded}' "
            f"(priority={gpu.bundle_priority}, pending={gpu.pending_requests})"
        )

        # If it's an LLM bundle, update the global LLM health
        bundles = _resolve_bundles()
        for bname, bundle in bundles.items():
            if bundle.get("gpu_id") == gpu_id and bundle.get("idle"):
                if llm:
                    llm.update_health(False)
                break

        # Bundle-managed loads must use the generic linked-graph teardown,
        # which acquires the durable group fence before invoking raw unloads.
        unload_ok = True
        unload_error: str | None = None
        try:
            unload_ok = await _teardown_bundle_graph(
                loaded,
                reason=f"force_evict_gpu:{gpu_id}",
            )
        except Exception as exc:
            unload_ok = False
            unload_error = str(exc)
            self.logger.warning(
                f"GPU[{gpu_id}]: controller teardown for '{loaded}' raised: {exc}"
            )

        if not unload_ok:
            self.logger.error(
                "GPU[%s]: controller teardown for bundle '%s' failed; "
                "leaving authoritative state untouched (%s)",
                gpu_id,
                loaded,
                unload_error or "no detail",
            )
            return False

        # Controller teardown succeeded — only NOW is it safe to clear
        # the ledger. (Per unload_bundle's contract, it has already
        # updated ``loaded_bundles``/``loaded_bundle``; we still refresh
        # the scheduler-level mirror fields so legacy code that reads
        # them sees a consistent idle GPU.)
        gpu.loaded_bundle = None
        gpu.bundle_priority = 0
        gpu.state = "idle"
        gpu.draining = False

        return True

    async def _process_gpu_queue(self, gpu_id: str) -> bool:
        """Process the next request from a GPU's priority queue.

        Returns True if a request was processed, False if queue was empty.
        """
        gpu = _get_gpu_state(gpu_id)
        entry = gpu.dequeue_next()
        if not entry:
            return False

        bundle_name = entry["bundle_name"]
        priority = entry["priority"]
        request_data = entry.get("request_data", {})

        self.logger.info(
            f"GPU[{gpu_id}]: processing queued request for {bundle_name} "
            f"priority={priority} from per-GPU queue"
        )

        # Route to the appropriate backend based on the request
        backend = request_data.get("backend", "comfyui")
        if backend == "comfyui":
            workflow = request_data.get("workflow", {})
            callback_url = request_data.get("callback_url")
            metadata = request_data.get("metadata", {})
            job = self.submit_comfyui(workflow, callback_url, priority, metadata)
            self.logger.info(f"GPU[{gpu_id}]: submitted job {job.id} from priority queue")
            gpu.request_started()
            return True
        elif backend == "acestep":
            payload = request_data.get("payload", {})
            metadata = request_data.get("metadata", {})
            job = self.submit_acestep(payload, priority, metadata)
            self.logger.info(f"GPU[{gpu_id}]: submitted acestep job {job.id} from priority queue")
            gpu.request_started()
            return True
        elif backend == "llm":
            return await self._process_gpu_queue_llm(gpu_id, entry)
        elif backend == "bundle":
            return await self._process_gpu_queue_bundle(gpu_id, entry)
        else:
            self.logger.warning(f"GPU[{gpu_id}]: unknown backend '{backend}' in priority queue")
            return False

    async def _process_gpu_queue_llm(self, gpu_id: str, entry: dict) -> bool:
        """Process an LLM backend request from the per-GPU queue.

        Starts the LLM service, waits for health, then resolves the
        request's Future so the proxy handler can forward the request.
        """
        request_data = entry.get("request_data", {})
        service_name = request_data.get("service_name")
        priority = entry.get("priority", 1)
        future = request_data.get("future")

        if not service_name:
            self.logger.warning(f"GPU[{gpu_id}]: LLM queue entry missing service_name")
            if future and not future.done():
                future.set_exception(RuntimeError("Missing service_name in LLM queue entry"))
            return False

        svc = _services_config.get("services", {}).get(service_name)
        if not svc:
            self.logger.error(f"GPU[{gpu_id}]: unknown LLM service '{service_name}'")
            if future and not future.done():
                future.set_exception(RuntimeError(f"Unknown LLM service: {service_name}"))
            return False

        gpu = _get_gpu_state(gpu_id)
        gpu.request_started()

        try:
            # Bundle-backed services have exactly one path: controller-owned
            # admission. Never let a healthy probe or future refactor fall
            # through to the legacy mutex/systemctl branch below.
            service_bundle = _get_bundle_for_service(service_name)
            if service_bundle is not None:
                admitted, _ = await _admit_bundle_backed_llm_service(
                    service_name,
                    priority,
                )
                if not admitted:
                    if future and not future.done():
                        future.set_exception(
                            RuntimeError(f"Bundle admission failed for {service_name}")
                        )
                    return False
                if llm:
                    llm.update_health(True)
                if event_bus:
                    event_bus.emit(service_name, "healthy")
                if future and not future.done():
                    future.set_result({
                        "status": "ready",
                        "service": service_name,
                        "port": svc.get("port"),
                    })
                return True

            # The remainder is the explicitly unbundled legacy path.
            port = svc.get("port")
            is_healthy = await _check_port_healthy(port) if port else False

            if not is_healthy:
                # ── Queue drain before swap ──
                # If the GPU is currently loading a service OR a worker is
                # mid-inference (worker_in_flight > 0) and a higher-priority
                # request is waiting, let the current work finish first
                # (unless queue depth > INTERRUPT_QUEUE_DEPTH).
                # Phase 5.2.51: previously only "loading" was checked, so an
                # LLM auto-start could OOM cuda:0 when comfyui was mid-inference
                # (LLM 13GB + comfyui 13GB > 16GB card). worker_in_flight is
                # the canonical "actively running inference" signal already
                # used by _auto_evict_idle_bundles (line 4783).
                #
                # Phase 5.2.51v2: also block lower-priority LLM starts when
                # worker_in_flight > 0. The original check relied on
                # should_drain_before_swap returning "wait", but that only
                # fires for higher-priority incoming requests. Lower-priority
                # LLM starts (priority < gpu.bundle_priority) returned "proceed"
                # and proceeded to systemctl start the LLM, OOM-ing the GPU.
                # Now: if worker_in_flight > 0, treat as "wait" regardless of
                # priority comparison. Reasoning: starting an LLM right now
                # would require evicting an active worker (CPU offload storm)
                # OR running concurrent (OOM). Both worse than queueing.
                _bundle_inflight = _bundle_worker_in_flight(gpu.loaded_bundle)
                is_busy = (
                    gpu.state == "loading"
                    or _bundle_inflight > 0
                )
                if is_busy and gpu.bundle_priority > 0:
                    drain_decision = self.should_drain_before_swap(gpu_id, priority)
                    # Phase 5.2.51v2: override "proceed" to "wait" when a worker
                    # is actively running inference. Don't bypass the
                    # drain-before-swap on a busy GPU.
                    if drain_decision["action"] == "proceed" and _bundle_inflight > 0:
                        self.logger.info(
                            f"GPU[{gpu_id}]: override 'proceed' to 'wait' — "
                            f"bundle_worker_in_flight={_bundle_inflight}, deferring "
                            f"{service_name} (priority {priority}) until linked "
                            f"inference completes"
                        )
                        drain_decision = {
                            "action": "wait",
                            "reason": (
                                f"Phase 5.2.51v2: bundle_worker_in_flight="
                                f"{_bundle_inflight} > 0 — starting LLM now "
                                f"would OOM or evict linked active work"
                            ),
                            "current_priority": drain_decision.get("current_priority", 0),
                            "queue_depth": drain_decision.get("queue_depth", 0),
                        }
                    self.logger.info(
                        f"GPU[{gpu_id}]: drain-before-swap check: "
                        f"{drain_decision['action']} — {drain_decision['reason']}"
                    )
                    if drain_decision["action"] == "wait":
                        # Let the current work finish — re-enqueue and wait
                        new_request_data = dict(request_data)
                        new_request_data["retry_count"] = request_data.get("retry_count", 0) + 1
                        gpu.enqueue(
                            bundle_name=f"llm:{service_name}",
                            priority=priority,
                            request_data=new_request_data,
                        )
                        # Signal the scheduler
                        if scheduler:
                            scheduler._idle_check_event.set()
                        gpu.request_finished()
                        return False  # Re-enqueued, will be processed after current load
                    elif drain_decision["action"] == "interrupt":
                        self.logger.warning(
                            f"GPU[{gpu_id}]: interrupting current load for "
                            f"higher-priority LLM (queue depth: {drain_decision['queue_depth']})"
                        )
                        # Force stop whatever is currently loading
                        await self._force_evict_gpu(gpu_id)
                    # "proceed" — fall through to start the service

                # Start the service (enforce mutex if configured)
                unit = svc.get("systemd_unit", f"{service_name}.service")

                # ── Mutex enforcement: stop running siblings before starting ──
                mutex_group = svc.get("mutex_group")
                if mutex_group:
                    for other_name, other_svc in _services_config.get("services", {}).items():
                        if other_name == service_name:
                            continue
                        if other_svc.get("mutex_group") != mutex_group:
                            continue
                        other_unit = other_svc.get("systemd_unit", f"{other_name}.service")
                        other_port = other_svc.get("port")
                        # Check if sibling is running
                        if other_port:
                            try:
                                async with self.session.get(
                                    f"http://127.0.0.1:{int(other_port)}/health",
                                    timeout=ClientTimeout(total=2),
                                ) as resp:
                                    if resp.status == 200:
                                        # Sibling is running — stop it first
                                        self.logger.info(
                                            f"GPU[{gpu_id}]: MUTEX stopping '{other_name}' "
                                            f"before starting '{service_name}'"
                                        )
                                        stop_proc = await asyncio.create_subprocess_exec(
                                            "sudo", "systemctl", "stop", other_unit,
                                            stdout=asyncio.subprocess.PIPE,
                                            stderr=asyncio.subprocess.PIPE,
                                        )
                                        await asyncio.wait_for(stop_proc.communicate(), timeout=30)
                                        if stop_proc.returncode == 0:
                                            self.logger.info(f"GPU[{gpu_id}]: MUTEX '{other_name}' stopped")
                                        else:
                                            self.logger.error(f"GPU[{gpu_id}]: MUTEX failed to stop '{other_name}'")
                            except Exception:
                                pass  # Not running — nothing to stop

                self.logger.info(
                    f"GPU[{gpu_id}]: starting LLM service '{service_name}' "
                    f"unit={unit} (priority={priority})"
                )
                start_proc = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "start", unit,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                await start_proc.wait()
                if start_proc.returncode != 0:
                    stderr = ""
                    if start_proc.stderr:
                        stderr = (await start_proc.stderr.read()).decode().strip()
                    self.logger.error(
                        f"GPU[{gpu_id}]: failed to start {service_name}: {stderr}"
                    )
                    if future and not future.done():
                        future.set_exception(RuntimeError(f"Failed to start {service_name}: {stderr}"))
                    gpu.request_finished()
                    return False

                # Wait for health
                self.logger.info(
                    f"GPU[{gpu_id}]: waiting for '{service_name}' port {port} to become healthy"
                )
                healthy = await _wait_port_ready(service_name, int(port), timeout=60.0)
                if not healthy:
                    self.logger.error(
                        f"GPU[{gpu_id}]: '{service_name}' failed to become healthy within 60s"
                    )
                    if future and not future.done():
                        future.set_exception(RuntimeError(f"{service_name} failed to become healthy"))
                    gpu.request_finished()
                    return False

                # Update health state if this is the default LLM
                if llm:
                    llm.update_health(True)
                if event_bus:
                    event_bus.emit(service_name, "healthy")

            self.logger.info(
                f"GPU[{gpu_id}]: LLM service '{service_name}' is healthy — "
                f"resolving request Future"
            )

            # Mark GPU bundle as loaded using the configured bundle identity.
            # The old ``llm:<service>`` pseudo-owner could not be resolved by
            # _auto_evict_idle_bundles, yielding repeated unknown-bundle errors
            # and a ledger that disagreed with the actual idle tenant.
            service_bundle = _get_bundle_for_service(service_name)
            if service_bundle:
                resolved_bundle_name = service_bundle["bundle_name"]
                resolved_priority = int(service_bundle.get("priority", priority) or priority)
                gpu.loaded_bundle = resolved_bundle_name
                gpu.bundle_priority = resolved_priority
                gpu.state = "loaded"
                gpu.set_loaded_bundles([resolved_bundle_name], source="llm_queue_ready")
                gpu.set_current_priority(resolved_priority, source="llm_queue_ready")
                gpu.touch_activity(source="llm_queue_ready")
            else:
                # An unmapped service must not masquerade as a valid bundle.
                gpu.loaded_bundle = None
                gpu.bundle_priority = 0
                gpu.state = "idle"
                gpu.set_loaded_bundles([], source="llm_queue_unmapped_service")
                gpu.set_current_priority(0, source="llm_queue_unmapped_service")
                self.logger.warning(
                    "GPU[%s]: LLM service '%s' has no configured bundle; "
                    "left scheduler ownership empty",
                    gpu_id,
                    service_name,
                )

            # Resolve the future so the proxy handler can forward
            if future and not future.done():
                future.set_result({
                    "status": "ready",
                    "service": service_name,
                    "port": port,
                })

            return True
        except Exception as e:
            self.logger.error(f"GPU[{gpu_id}]: LLM processing error: {e}", exc_info=True)
            if future and not future.done():
                future.set_exception(e)
            return False
        finally:
            gpu.request_finished()

    async def _process_gpu_queue_bundle(self, gpu_id: str, entry: dict) -> bool:
        """Process a bundle backend request from the per-GPU queue.

        Checks if ALL linked GPUs in the same bundle_job_id have loaded
        their components. If yes, starts the bundle. If no, re-enqueues
        the entry with a lower retry priority.
        """
        request_data = entry.get("request_data", {})
        bundle_name = entry.get("bundle_name")
        priority = entry.get("priority", 5)
        bundle_job_id = request_data.get("bundle_job_id")
        retry_count = request_data.get("retry_count", 0)
        bundle_future = request_data.get("bundle_future")

        if not bundle_job_id or not bundle_name:
            self.logger.warning(
                f"GPU[{gpu_id}]: bundle queue entry missing bundle_job_id or bundle_name"
            )
            return False

        gpu = _get_gpu_state(gpu_id)

        # Mark this GPU as ready in the coordinator
        all_ready = await bundle_coordinator.mark_gpu_ready(bundle_job_id, gpu_id)

        if all_ready:
            # All GPUs are ready — load the bundle
            self.logger.info(
                f"GPU[{gpu_id}]: all GPUs ready for bundle '{bundle_name}' "
                f"(job={bundle_job_id}) — loading"
            )
            gpu.request_started()
            try:
                success = await _evict_then_load_bundle(
                    bundle_name,
                    reason=f"gpu-queue:{bundle_job_id}",
                    priority=priority,
                )
                if success:
                    self.logger.info(
                        f"GPU[{gpu_id}]: bundle '{bundle_name}' loaded successfully"
                    )
                    await bundle_coordinator.complete_job(bundle_job_id, success=True)
                else:
                    self.logger.error(
                        f"GPU[{gpu_id}]: bundle '{bundle_name}' failed to load"
                    )
                    await bundle_coordinator.complete_job(bundle_job_id, success=False)
                return success
            except Exception as e:
                self.logger.error(
                    f"GPU[{gpu_id}]: bundle load error: {e}", exc_info=True
                )
                await bundle_coordinator.complete_job(bundle_job_id, success=False)
                return False
            finally:
                gpu.request_finished()
        else:
            # Not all GPUs ready yet — re-enqueue with lower priority
            info = bundle_coordinator.get_job_info(bundle_job_id)
            ready_count = len(info["ready_gpus"]) if info else 0
            total_count = len(info["gpu_ids"]) if info else 0

            if retry_count >= 30:
                # Max retries exceeded — fail the job
                self.logger.error(
                    f"GPU[{gpu_id}]: bundle '{bundle_name}' max retries "
                    f"({retry_count}) exceeded — giving up"
                )
                await bundle_coordinator.complete_job(bundle_job_id, success=False)
                return False

            # Re-enqueue with reduced priority to avoid infinite loop
            retry_priority = max(1, priority - 1)
            new_request_data = dict(request_data)
            new_request_data["retry_count"] = retry_count + 1
            gpu.enqueue(
                bundle_name=bundle_name,
                priority=retry_priority,
                request_data=new_request_data,
            )
            self.logger.info(
                f"GPU[{gpu_id}]: bundle '{bundle_name}' re-enqueued "
                f"(retry={retry_count + 1}, priority={retry_priority}, "
                f"ready={ready_count}/{total_count})"
            )
            return False

    def should_evict_gpu(self, gpu_id: str, incoming_priority: int) -> str:
        """Check whether to evict the current bundle on a GPU for a new request.

        Uses the per-GPU state to make eviction decisions.
        Returns the _should_evict decision string.
        """
        gpu = _get_gpu_state(gpu_id)
        current_priority = gpu.bundle_priority
        has_pending = gpu.pending_requests > 0 or len(gpu.priority_queue) > 0
        return _should_evict(current_priority, incoming_priority, has_pending)

    # ── Queue Drain Before Swap ────────────────────────────────────

    # Threshold: if a higher-priority request queue depth exceeds this,
    # interrupt the current load immediately instead of waiting.
    INTERRUPT_QUEUE_DEPTH = 5

    def should_drain_before_swap(self, gpu_id: str, incoming_priority: int) -> dict:
        """Check if the current GPU load should be interrupted for a higher-priority request.

        Rules:
          1. Let the current load finish (don't interrupt mid-load)
          2. Then swap to the higher-priority service
          3. Exception: if queue depth > INTERRUPT_QUEUE_DEPTH for a higher
             priority, interrupt immediately

        Returns:
            {
                "action": "wait" | "interrupt" | "proceed",
                "reason": str,
                "current_priority": int,
                "queue_depth": int,
            }
        """
        gpu = _get_gpu_state(gpu_id)
        current_priority = gpu.bundle_priority
        queue_depth = len(gpu.priority_queue)
        current_state = gpu.state

        # No higher-priority request waiting
        if incoming_priority <= current_priority:
            return {
                "action": "proceed",
                "reason": f"same/lower priority ({incoming_priority} <= {current_priority})",
                "current_priority": current_priority,
                "queue_depth": queue_depth,
            }

        # Higher-priority request waiting — check queue depth
        higher_priority_count = sum(
            1 for e in gpu.priority_queue
            if e.get("priority", 0) > current_priority
        )

        if higher_priority_count > self.INTERRUPT_QUEUE_DEPTH:
            # Too many high-priority requests waiting — interrupt immediately
            return {
                "action": "interrupt",
                "reason": (
                    f"queue depth {higher_priority_count} > {self.INTERRUPT_QUEUE_DEPTH} "
                    f"for priority {incoming_priority} > {current_priority}"
                ),
                "current_priority": current_priority,
                "queue_depth": queue_depth,
            }

        # Fewer high-priority requests — let current load finish, then swap
        return {
            "action": "wait",
            "reason": (
                f"higher priority {incoming_priority} > {current_priority}, "
                f"queue depth {higher_priority_count} <= {self.INTERRUPT_QUEUE_DEPTH} — "
                f"letting current load finish"
            ),
            "current_priority": current_priority,
            "queue_depth": queue_depth,
        }

    # ── Main Scheduler Loop ────────────────────────────────────────

    async def _scheduler_loop(self):
        """Main loop: GPU state machine with longest-queue-first scheduling."""
        self._running = True
        self.logger.info(
            "Unified scheduler startup grace: waiting %.1fs before dispatch",
            GPU_PROBE_STARTUP_GRACE_S,
        )
        await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
        self.logger.info("Unified scheduler loop running")

        while True:
            try:
                # ── Phase 1: Process per-GPU priority queues FIRST ──
                # Per-GPU queues may have LLM or bundle work that should
                # be dispatched regardless of whether main backend queues
                # have pending jobs.
                all_gpu_states = _get_all_gpu_states()
                gpu_had_work = False
                for gpu_id, gpu_state in all_gpu_states.items():
                    if gpu_state.priority_queue and not gpu_state.draining:
                        self.logger.debug(
                            f"GPU[{gpu_id}]: per-GPU queue has "
                            f"{len(gpu_state.priority_queue)} item(s) — processing"
                        )
                        processed = await self._process_gpu_queue(gpu_id)
                        if processed:
                            gpu_had_work = True
                if gpu_had_work:
                    # Re-check: per-GPU processing may have changed state
                    continue

                # Count pending GPU work
                c_pending = [j for j in self._comfyui_queue if j.status == "queued"]
                a_pending = [j for j in self._acestep_queue if j.status == "queued"]

                if not c_pending and not a_pending:
                    # Phase 5.2.53 Fix B: auto-clear stale pinned_service.
                    # If the user pinned a generation backend (comfyui / acestep)
                    # but hasn't submitted any work in STALE_PIN_TIMEOUT_S,
                    # the pin was almost certainly forgotten. Clear it so the
                    # idle LLM can be restored by _ensure_idle_service below.
                    # Only fires when no LLM requests are in flight so we
                    # don't disrupt an active LLM session.
                    if self._pinned_service in ("comfyui", "acestep"):
                        _pin_since = self._pinned_service_since or 0.0
                        if _pin_since == 0.0:
                            self._pinned_service_since = time.time()
                        elif (time.time() - _pin_since) > STALE_PIN_TIMEOUT_S and getattr(llm, "active_requests", 0) == 0:
                            held_for = int(time.time() - _pin_since)
                            self.logger.warning(
                                f"scheduler: pinned_service={self._pinned_service} held for "
                                f">{held_for}s with empty generation queue and no LLM in flight "
                                f"— auto-clearing pin"
                            )
                            self._pinned_service = None
                            self._pinned_service_since = None
                            # Persist the clear so a service restart doesn't re-arm the pin.
                            try:
                                _services_config.setdefault("scheduling", {})["pinned_service"] = None
                                _save_services_config(_services_config)
                            except Exception as _persist_err:
                                self.logger.debug(f"scheduler: failed to persist pin clear: {_persist_err}")
                            # Skip the rest of this tick; next tick sees _pinned_service=None
                            # and _ensure_idle_service restores the LLM.
                            await asyncio.sleep(2)
                            continue
                    # ── Idle state: ensure idle LLM service is loaded ──
                    await self._ensure_idle_service()

                    # ── Phase 4g: auto-evict idle generation bundles ──
                    await self._auto_evict_idle_bundles()

                    # ── Phase 5.2.69: orphan reaper tick ─────────────
                    # Catches VRAM-holding PPID=1 processes that escaped
                    # gpu-manager's bookkeeping (orphaned ComfyUI python
                    # from a rapid LoadBundle restart sequence, manually-
                    # spawned python/llama-server from a debug session,
                    # etc.). Throttled by ORPHAN_REAPER_INTERVAL_S so it
                    # only does the (relatively expensive) _poll_vram +
                    # /proc scan on cadence, not every loop iteration.
                    if ORPHAN_REAPER_ENABLED:
                        _throttle_delta = time.time() - self._last_orphan_reaper_at
                        if _throttle_delta >= ORPHAN_REAPER_INTERVAL_S:
                            # DEBUG: per-tick fired event. WARN/INFO logs
                            # inside _orphan_reaper_tick surface orphans.
                            self.logger.debug("[orphan-reaper] tick fired")
                            await self._orphan_reaper_tick()

                    # Reconcile cached auto-stop state against authoritative
                    # systemd state on every idle tick. Never run this while a
                    # bundle transaction is loading/evicting/draining: an
                    # activating ComfyUI belongs to that transaction.
                    if vram._comfyui_auto_stopped and not _bundle_transition_is_active():
                        try:
                            _unit_states = await vram._comfyui_systemd_state()
                            _krea_state = vram._comfyui_unit_state(
                                _unit_states, "comfyui.service"
                            )
                            if _krea_state not in {"inactive", "failed"}:
                                self.logger.warning(
                                    "ComfyUI auto-stop state disagrees with Krea "
                                    f"systemd state={_krea_state!r} "
                                    f"(all={_unit_states!r}); reconciling stop"
                                )
                                await vram.stop_comfyui(reason="auto_stop_reconcile")
                            else:
                                vram._comfyui_stopped = (
                                    not vram._any_comfyui_unit_active(_unit_states)
                                )
                        except Exception as _exc:
                            self.logger.debug(f"ComfyUI auto-stop reconciliation skipped: {_exc}")

                    # Auto-stop ComfyUI when idle to conserve VRAM.
                    # ComfyUI with models loaded uses significant VRAM even at idle.
                    # We stop it after a cooldown period to avoid thrashing on
                    # rapid-fire jobs.
                    # Phase 5.2.5 Fix B: skip this block if comfyui's bundle is
                    # still in its post-load grace window. Without this, auto-stop
                    # fires 30s after grace ends (because _comfyui_idle_since is
                    # seeded at start_comfyui time, which is the start of the grace
                    # window). When we skip, we also reset _comfyui_idle_since to
                    # 'now' so the cooldown clock starts fresh after grace ends.
                    # Phase 5.2.10: REPLACED `getattr(vram, 'gpu_id', None)` with
                    # `_get_all_gpu_states()` iteration. The original read was
                    # silently broken: VRAMLifecycleManager.__init__ never sets
                    # self.gpu_id, so getattr always returned None and the
                    # entire grace check was dead code at runtime. Same pattern
                    # already used by Phase 5.2.4 `_auto_evict_idle_bundles`
                    # (line 4724) and Phase 5.2.9 `_restore_after_gpu_work`
                    # (line 4475).
                    _skip_for_grace = False
                    try:
                        _now = time.time()
                        for _gpu_id, _gs in _get_all_gpu_states().items():
                            _grace_at = float(getattr(_gs, "bundle_post_load_grace_at", 0) or 0)
                            if _grace_at > 0 and _now < _grace_at:
                                _skip_for_grace = True
                                break
                    except Exception:
                        pass
                    if _skip_for_grace:
                        vram._comfyui_idle_since = time.time()
                        self.logger.debug(
                            f"supervisor auto-stop skipped: comfyui in post-load grace"
                        )
                    elif (vram._comfyui_idle_since is not None
                            and not vram._comfyui_stopped):
                        # Phase 5.2.36 Bug C follow-up: also check the
                        # worker_in_flight counter. _auto_evict_idle_bundles
                        # already does this, but the auto-stop-on-idle path
                        # is a SEPARATE code path that also kills ComfyUI.
                        # Without this, a long-running inference (e.g.
                        # a long-running ComfyUI workflow taking 5+ min) gets killed when the
                        # supervisor decides the bundle is "idle" after
                        # the post-load grace expires.
                        _in_flight = 0
                        try:
                            for _gs in _get_all_gpu_states().values():
                                _in_flight += int(getattr(_gs, "worker_in_flight", 0) or 0)
                        except Exception:
                            pass
                        if _in_flight > 0:
                            self.logger.debug(
                                f"supervisor auto-stop skipped: {_in_flight} worker(s) in flight"
                            )
                        idle_sec = time.time() - vram._comfyui_idle_since
                        _idle_blockers = _restore_after_gpu_work_blockers()
                        if idle_sec >= COMFYUI_IDLE_COOLDOWN and _in_flight == 0 and not _idle_blockers:
                            self.logger.info(
                                f"ComfyUI idle for {idle_sec:.0f}s — auto-stopping to free VRAM"
                            )
                            # Recheck immediately before each destructive phase. A
                            # serial row can acquire admission while this coroutine
                            # is yielding to the event loop.
                            _idle_blockers = _restore_after_gpu_work_blockers()
                            if _idle_blockers:
                                self.logger.info(
                                    "supervisor auto-stop deferred before free: "
                                    + ",".join(_idle_blockers)
                                )
                                continue
                            await self._free_comfyui()
                            _idle_blockers = _restore_after_gpu_work_blockers()
                            if _idle_blockers:
                                self.logger.info(
                                    "supervisor auto-stop deferred before stop: "
                                    + ",".join(_idle_blockers)
                                )
                                continue
                            _stopped = await vram.stop_comfyui(reason="idle_timeout")
                            if _stopped:
                                vram._comfyui_auto_stopped = True
                                self.logger.info("ComfyUI auto-stopped — VRAM freed for LLM/ACE-Step")
                            else:
                                self.logger.error(
                                    "ComfyUI auto-stop failed authoritative systemd verification"
                                )

                    # Wait for idle check event (signals when config changes)
                    # or timeout after 2 seconds for normal polling
                    try:
                        await asyncio.wait_for(
                            self._idle_check_event.wait(),
                            timeout=2.0,
                        )
                        self._idle_check_event.clear()
                    except asyncio.TimeoutError:
                        pass
                    continue

                # ── Check pinned_service override ──
                if self._pinned_service:
                    # When pinned, only process jobs matching the pinned backend
                    pinned = self._pinned_service
                    if pinned == "comfyui" and not c_pending:
                        await asyncio.sleep(2)
                        continue
                    elif pinned == "acestep" and not a_pending:
                        await asyncio.sleep(2)
                        continue
                    elif pinned not in ("comfyui", "acestep"):
                        # Pinned to an LLM service — skip GPU work entirely
                        await asyncio.sleep(2)
                        continue

                # ── Transition: LLM_LOADED → DRAINING → GPU_WORK ──
                if vram and vram.gpu_state == GpuState.LLM_LOADED:
                    self.logger.info(
                        f"GPU work pending (comfyui={len(c_pending)}, acestep={len(a_pending)}) "
                        f"— draining LLM"
                    )
                    vram.gpu_state = GpuState.DRAINING
                    drained = await vram.drain_llm(timeout=DRAIN_TIMEOUT)
                    if not drained:
                        self.logger.warning(
                            f"Drain timeout ({DRAIN_TIMEOUT}s) — force evicting LLM "
                            f"({llm.active_requests} still active)"
                        )
                    # A bundle-owned ACE job supplies its own physical-GPU
                    # admission transaction in _run_acestep_job.  Do not apply
                    # the legacy RX-only eviction here: a dual-GPU candidate
                    # would otherwise leave secondary GPU resident and block on the
                    # aggregate <4GiB wait before its bundle can evict both.
                    bundle_owned_acestep = next(
                        (job for job in a_pending if job.bundle_name), None
                    )
                    if bundle_owned_acestep is None:
                        await vram.evict_llm(reason="gpu_work_start")
                    else:
                        self.logger.info(
                            "GPU work pending for bundle-owned ACE job %s; "
                            "deferring physical eviction to bundle %s",
                            bundle_owned_acestep.id,
                            bundle_owned_acestep.bundle_name,
                        )
                    vram.gpu_state = GpuState.GPU_WORK

                # ── Pick longest queue ──
                backend = self._pick_backend()
                if backend is None:
                    # Nothing left (cancelled while we were evicting)
                    await self._restore_after_gpu_work()
                    await asyncio.sleep(2)
                    continue

                # ── Run one batch/job ──
                if backend == "comfyui":
                    await self._run_comfyui_batch()
                elif backend == "acestep":
                    await self._run_acestep_job()

                # ── After job/batch: check LLM relief ──
                if llm.queued_requests >= LLM_RELIEF_THRESHOLD:
                    self.logger.info(
                        f"LLM pressure: {llm.queued_requests} queued ≥ {LLM_RELIEF_THRESHOLD} "
                        f"— initiating relief"
                    )
                    await self._do_llm_relief()
                    continue

                # ── Check if more GPU work ──
                c_pending = [j for j in self._comfyui_queue if j.status == "queued"]
                a_pending = [j for j in self._acestep_queue if j.status == "queued"]

                if not c_pending and not a_pending:
                    await self._restore_after_gpu_work()

                await asyncio.sleep(1)

            except asyncio.CancelledError:
                self._running = False
                raise
            except Exception as e:
                self.logger.error(f"Scheduler error: {e}", exc_info=True)
                await asyncio.sleep(5)

    def _pick_backend(self) -> str | None:
        """Pick the GPU backend with the longest pending queue.

        Tie-breaking: ComfyUI wins (typically faster per-job).
        HIGH-priority jobs win regardless of queue length.
        """
        c_count = sum(1 for j in self._comfyui_queue if j.status == "queued")
        a_count = sum(1 for j in self._acestep_queue if j.status == "queued")

        if c_count == 0 and a_count == 0:
            return None

        # Check for HIGH priority jobs - they get immediate dispatch
        # Use effective_tier() to account for cross-backend boosts
        c_high = sum(1 for j in self._comfyui_queue
                     if j.status == "queued" and self.effective_tier(j) == PriorityTier.HIGH)
        a_high = sum(1 for j in self._acestep_queue
                     if j.status == "queued" and self.effective_tier(j) == PriorityTier.HIGH)

        if c_high > 0 and a_high == 0:
            return "comfyui"
        if a_high > 0 and c_high == 0:
            return "acestep"
        if c_high > 0 and a_high > 0:
            # Both have HIGH - fall through to longest-queue
            pass

        if c_count >= a_count:
            return "comfyui"
        return "acestep"

    def effective_tier(self, job: Job | AceStepJob) -> PriorityTier:
        """Get effective priority tier after cross-backend adjustments."""
        tier = job.priority_tier
        rules = _services_config.get("scheduling", {}).get(
            "cross_backend_priority", {}).get("rules", [])
        for rule in rules:
            if rule["backend"] == job.backend:
                boost = rule.get("tier_boost", 0)
                new_val = max(1, min(3, tier.value + boost))
                return PriorityTier(new_val)
        return tier

    async def _restore_after_gpu_work(self):
        """Free GPU models and restore Qwen3.6 as default tenant.

        Restarts ACE-Step AND ComfyUI to force-release their PyTorch VRAM
        caches. The ComfyUI /free API only unloads models but PyTorch's
        ROCm memory allocator retains the freed VRAM — only a full process
        restart actually releases it to the OS.

        GUARD: Uses _restoring flag to prevent concurrent restores from the
        idle monitor and scheduler completing at the same time.

        MAINTENANCE MODE: Skips all service management when active.
        """
        if not vram:
            return

        config = _load_services_config()
        if _maintenance_mode_enabled(config.get("scheduling", {})):
            self.logger.info("Maintenance mode active — skipping service restore")
            return

        # A generation-backend pin owns residency; an LLM pin is routing-only.
        if _pinned_service_blocks_idle_restore(self._pinned_service):
            return

        # Prevent concurrent restores
        if self._restoring:
            self.logger.debug("Restore already in progress — skipping")
            return
        # A completed ComfyUI row arms a short handoff lease before releasing
        # its WorkerPool ownership. Defer destructive restore_prep while that
        # lease, a next-row admission, any linked worker, or a bundle transition
        # is active. This closes the terminal-to-next-submit race without
        # pinning the bundle indefinitely.
        _restore_blockers = _restore_after_gpu_work_blockers()
        if _restore_blockers:
            self.logger.info(
                "Restore deferred: " + ",".join(_restore_blockers)
            )
            self._restoring = False
            return

        # Acquire this guard only AFTER the blocker query.  The blocker query
        # itself reports ``scheduler_restoring`` while this flag is true; doing
        # this in the opposite order self-deadlocks every restore attempt.
        self._restoring = True

        # Phase 5.2.9: skip restore_prep when any GPU is in post-load grace.
        # During a generation job's post-load grace window (e.g. ComfyUI's
        # 90s warmup for ComfyRegistry fetch + HTTP handler), stopping the
        # backend would interrupt the worker that's about to POST its first
        # request. We scan ALL GPU states (not just the crashing service's
        # GPU) because the crashing service may be on a different GPU than
        # comfyui — e.g. LLM-Secondary (gpu_secondary) crashes while comfyui is on
        # gpu_primary, and `vram` in scope is the gpu_secondary manager, but we still
        # need to detect comfyui's grace on gpu_primary.
        # The supervisor retries every 5-12s, so after grace ends the next
        # tick will resume the restore normally.
        try:
            _now = time.time()
            _any_in_grace = False
            for _gpu_id, _gs in _get_all_gpu_states().items():
                _grace_at = float(getattr(_gs, "bundle_post_load_grace_at", 0) or 0)
                if _grace_at > 0 and _now < _grace_at:
                    _any_in_grace = True
                    break
            if _any_in_grace:
                self.logger.debug(
                    f"restore_prep skipping comfyui stop (some GPU in post-load grace)"
                )
                self._restoring = False  # release lock so supervisor retries
                return
        except Exception:
            pass

        self._lifecycle_begin("restore", _get_idle_service_name(), "restore")

        try:
            self._lifecycle_step_begin("restart_comfyui")
            # Restart ComfyUI to release PyTorch VRAM caches
            await vram._restart_comfyui_for_restore()
            self._lifecycle_step_done("restart_comfyui")

            self._lifecycle_step_begin("restart_acestep")
            # Restart ACE-Step if running to release GPU resources
            await vram._restart_acestep_for_restore()
            self._lifecycle_step_done("restart_acestep")

            # Wait for VRAM to actually clear
            self._lifecycle_step_begin("wait_vram_free")
            for _ in range(20):  # up to 20s
                vram_data = await _poll_vram()
                if vram_data.get("used_vram_mib", 9999) < 500:
                    break
                await asyncio.sleep(1)
            else:
                self.logger.warning("VRAM: still used after ComfyUI+ACE-Step restart")
            self._lifecycle_step_done("wait_vram_free")

            # Transition to RESTORING then restore LLM
            vram.gpu_state = GpuState.RESTORING

            self._lifecycle_step_begin("restore_llm")
            healthy = await vram.restore_llm(reason="all_gpu_work_done")
            if not healthy:
                self._lifecycle_error("LLM not healthy after restore")
                self.logger.error("Restore: LLM not healthy after restore")
                return
            self._lifecycle_step_done("restore_llm")

            # Clear evicted flag and set final state
            vram.mark_llm_evicted(False, source="restore_after_gpu_work")
            vram.gpu_state = GpuState.LLM_LOADED
            self._lifecycle_complete()
            self.logger.info("Restore complete: LLM loaded and healthy")

        except Exception as e:
            self._lifecycle_error(str(e))
            self.logger.error(f"Restore failed: {e}", exc_info=True)
            raise
        finally:
            self._restoring = False

    async def _do_llm_relief(self):
        """Temporarily restore LLM to drain queued request backlog.

        When LLM queue exceeds LLM_RELIEF_THRESHOLD during GPU work, we pause
        GPU work, restore the LLM, let it drain the queue, then evict again.

        State cycle: GPU_WORK → LLM_RELIEF → DRAINING → GPU_WORK

        Uses the _restoring flag to prevent concurrent restore+relief.
        """
        if not vram:
            return

        # Maintenance mode: don't interrupt LLM or attempt relief
        config = _load_services_config()
        if _maintenance_mode_enabled(config.get("scheduling", {})):
            self.logger.info("Maintenance mode — skipping LLM relief")
            return

        self._restoring = True
        self.total_llm_reliefs += 1

        self._lifecycle_begin(
            "relief", _get_idle_service_name(), "relief",
            from_state="gpu_work", to_state="gpu_work"
        )

        try:
            # Step 1: Restore LLM temporarily
            vram.gpu_state = GpuState.LLM_RELIEF
            self._lifecycle_step_begin("restore_temp")

            # Temporarily set _llm_evicted=False so restore_llm() proceeds
            # (restore_llm checks _llm_evicted before doing anything)
            was_evicted = vram._llm_evicted
            vram.mark_llm_evicted(False, source="llm_relief_force")

            healthy = await vram.restore_llm(reason="llm_relief")
            if not healthy:
                self._lifecycle_error("LLM not healthy during relief")
                vram.gpu_state = GpuState.GPU_WORK
                vram.mark_llm_evicted(was_evicted, source="llm_relief_rollback")
                return
            self._lifecycle_step_done("restore_temp")

            # Step 2: Wait for queue to drain
            self._lifecycle_step_begin("drain_requests")
            LLM_RELIEF_DRAIN_TIMEOUT = 120.0  # max seconds to wait for drain
            start = time.time()
            while llm.queued_requests > 0:
                if time.time() - start > LLM_RELIEF_DRAIN_TIMEOUT:
                    self.logger.warning(
                        f"LLM relief drain timed out after {LLM_RELIEF_DRAIN_TIMEOUT}s "
                        f"({llm.queued_requests} still queued)"
                    )
                    break
                # Sub-progress: report how many are left
                sub_p = 1.0 - (llm.queued_requests / max(llm.queued_requests, 1))
                self._lifecycle_step_begin("drain_requests")  # no-op but updates sub_progress
                await asyncio.sleep(2)

            vram.mark_llm_evicted(True, source="llm_relief_reevict")
            self._lifecycle_step_done("drain_requests")

            # Step 3: Re-evict LLM to free GPU for work to resume
            self._lifecycle_step_begin("evict_again")
            vram.gpu_state = GpuState.DRAINING
            await vram.drain_llm(timeout=DRAIN_TIMEOUT)
            success = await vram.evict_llm(reason="relief_complete")
            if not success:
                self._lifecycle_error("LLM re-evict failed after relief")
                vram.gpu_state = GpuState.GPU_WORK
                return
            self._lifecycle_step_done("evict_again")

            vram.gpu_state = GpuState.GPU_WORK
            self._lifecycle_complete()
            self.logger.info(
                f"LLM relief complete: drained queue, evicted, back to GPU_WORK "
                f"(relief #{self.total_llm_reliefs})"
            )

        except Exception as e:
            self._lifecycle_error(str(e))
            self.logger.error(f"LLM relief failed: {e}", exc_info=True)
            vram.gpu_state = GpuState.GPU_WORK
            raise
        finally:
            self._restoring = False

    def _get_idle_threshold(self) -> float:
        """Cached read of bundle_idle_threshold_seconds (10s TTL).

        Replaces the per-tick _load_services_config() call in
        _auto_evict_idle_bundles. Phase 4h.3 S2.
        """
        now = time.time()
        if (
            self._cached_threshold is None
            or now - self._cached_threshold_at > self._THRESHOLD_CACHE_TTL
        ):
            try:
                config = _load_services_config()
                scheduling = config.get("scheduling", {})
                self._cached_threshold = float(
                    scheduling.get("bundle_idle_threshold_seconds", 30)
                )
            except Exception:
                if self._cached_threshold is None:
                    self._cached_threshold = 30.0
            self._cached_threshold_at = now
        return self._cached_threshold

    async def _auto_evict_idle_bundles(self) -> None:
        """Unload generation bundles that have been idle beyond the configured threshold.

        Guards:
          - Only non-idle bundles are candidates (idle = Gemma baseline).
          - Bundle must not be evicting/loading/draining.
          - No in-flight requests on the bundle's services.
          - No pending jobs in routing groups served by the bundle's services,
            so a generational queue always finishes its own work first.

        On successful unload, sets vram._llm_evicted=True so the existing
        _ensure_idle_service path restores the idle LLM on the next tick.
        """
        if vram is None:
            return
        # S6: refuse to evict while vram is mid-eviction/drain/work.
        # M1: prevents the unclaimed-count check below from firing
        # while a DRAINING operation is in progress.
        _vram_state = str(getattr(vram, "gpu_state", "") or "").lower()
        if _vram_state in ("draining", "gpu_work", "llm_relief"):
            return
        # S2: cached read of bundle_idle_threshold_seconds (10s TTL).
        threshold = self._get_idle_threshold()
        if threshold <= 0:
            return
        # We still need the full config below for bundles/templates/etc.
        config = _load_services_config()
        scheduling = config.get("scheduling", {})
        if _maintenance_mode_enabled(scheduling):
            return
        # Skip if any legacy ComfyUI/ACE-Step queue is active; those paths
        # manage their own lifecycle.
        c_active = any(j.status in ("queued", "running") for j in self._comfyui_queue)
        a_active = any(j.status in ("queued", "running") for j in self._acestep_queue)
        if c_active or a_active or self._current_backend:
            return

        bundles = _resolve_bundles()
        templates = config.get("generation_templates", {})
        services_cfg = config.get("services", {})
        now = time.time()

        for gpu_id, gpu_state in _get_all_gpu_states().items():
            bundle_name = gpu_state.loaded_bundle
            if not bundle_name:
                continue
            # Phase 5.2.34 Bug B: gpu.loaded_bundle is tagged with "llm:"
            # prefix (line 4043) but the bundle registry names don't
            # carry the prefix. Strip before any registry lookup or
            # _unload_bundle call. Without this, auto-evict fails
            # every ~62s with "UnloadBundle: unknown bundle 'llm:LLM-Primary'"
            # and the idle-restore path never fires.
            if bundle_name.startswith("llm:"):
                bundle_name = bundle_name[len("llm:"):]
            bundle = bundles.get(bundle_name, {})
            if bundle.get("idle", False):
                continue
            if gpu_state.evicting or gpu_state.loading or gpu_state.draining:
                continue
            if gpu_state.pending_requests > 0:
                continue

            # Phase 5.1 P0-1: bundle-load grace period. If the bundle
            # was loaded within BUNDLE_LOAD_GRACE_SECONDS, skip eviction
            # even if last_activity_at == 0 — the worker is still spinning
            # up the first job and we don't want to kill it.
            _BUNDLE_LOAD_GRACE_SECONDS = 5.0
            if (
                gpu_state.bundle_loaded_at > 0.0
                and (now - gpu_state.bundle_loaded_at) < _BUNDLE_LOAD_GRACE_SECONDS
            ):
                continue

            # Phase 5.2.4: post-load grace window. Skips bundles that are
            # still in their post-load grace (e.g. ComfyUI warming up
            # after port-ready but before HTTP handler is ready). Without
            # this, auto-evict frees models mid-grace and the worker's
            # first POST hits a stale backend. The deadline is stamped
            # in _load_bundle as bundle_loaded_at + post_load_grace_seconds.
            _grace_at = float(getattr(gpu_state, "bundle_post_load_grace_at", 0) or 0)
            if _grace_at > 0 and now < _grace_at:
                continue

            # Auto-eviction is a third destructive lifecycle path, independent
            # of direct-idle stopping and idle-service restoration. Honor the
            # same authoritative worker/admission/transition blockers here so
            # a warm serial batch cannot be unloaded between rows.
            if _auto_evict_bundle_blockers(bundle_name, bundles=bundles):
                continue

            # Phase 5.2.36 Bug C fix: skip eviction if a worker is
            # mid-inference. The pending_requests counter is decremented
            # at dequeue time (before the worker enters _execute_job),
            # so a job can be in flight while pending_requests == 0.
            # The new worker_in_flight counter (incremented in
            # _execute_job, decremented in finally) gives us the live
            # signal we need.
            if _bundle_worker_in_flight(bundle_name, bundles) > 0:
                continue

            # A bundle loaded by startup reconciliation may not have served a
            # request yet, so last_activity_at remains zero forever.  Its
            # completed load time is then the only safe inactivity anchor.
            # A bundle with neither timestamp is unknown and must fail closed.
            last_activity = float(getattr(gpu_state, "last_activity_at", 0.0) or 0.0)
            if last_activity <= 0.0:
                last_activity = float(getattr(gpu_state, "bundle_loaded_at", 0.0) or 0.0)
            if last_activity <= 0.0 or (now - last_activity) < threshold:
                continue

            member_names = bundle.get("services", [])
            # No in-flight jobs on bundle services
            if capacity_tracker is not None:
                active_total = sum(
                    capacity_tracker._active.get(svc_name, 0)
                    for svc_name in member_names
                )
                if active_total > 0:
                    continue

            # No pending jobs in routing groups served by this bundle
            routing_groups = set()
            for tmpl in templates.values():
                if tmpl.get("backend") in member_names:
                    rg = tmpl.get("routing_group")
                    if rg:
                        routing_groups.add(rg)

            has_pending = False
            pending_info: list[str] = []
            if queue_engine is not None and queue_engine.r is not None:
                for rg in routing_groups:
                    try:
                        # Use the queue abstraction so an enabled priority lane
                        # cannot be mistaken for an empty legacy stream.  This
                        # also keeps the same ACK/PEL ownership as the worker
                        # and makes an outage visible to the unload fence.
                        pending = queue_engine.get_pending(
                            rg, routing_group=rg, strict=True
                        )
                        pending_count = len(pending or [])
                        if pending_count > 0:
                            has_pending = True
                            pending_info.append(f"{rg}={pending_count}")
                    except Exception as exc:
                        has_pending = True
                        pending_info.append(
                            f"{rg}=unknown:{type(exc).__name__}"
                        )
            if has_pending:
                self.logger.info(
                    f"Auto-evict: skipping '{bundle_name}' on {gpu_id} "
                    f"(pending {', '.join(pending_info)})"
                )
                continue

            # M1: count XADDed-but-not-yet-XREADGROUPed entries. Use the
            # consumer group's `lag` field (XINFO GROUPS): it is exactly
            # the count of stream entries the group has not yet seen.
            # Combining lag with XINFO GROUPS pending covers both
            # never-delivered (lag) and delivered-but-unacked (pending).
            # Earlier `length - pending` was wrong: a stream with high
            # `length` from historical entries has lag=0 and must NOT
            # block auto-evict (the workers group is caught up).
            unclaimed_total = 0
            if queue_engine is not None and queue_engine.r is not None:
                for _rg in routing_groups:
                    try:
                        _observation = queue_engine.get_queue_depth_observation(
                            _rg, routing_group=_rg
                        )
                        if _observation.get("known") is not True:
                            unclaimed_total += 1
                            pending_info.append(
                                f"{_rg}=unknown:{_observation.get('reason', 'unknown')}"
                            )
                        else:
                            unclaimed_total += int(
                                _observation.get("depth", 0) or 0
                            )
                    except Exception as exc:
                        unclaimed_total += 1
                        pending_info.append(
                            f"{_rg}=unknown:{type(exc).__name__}"
                        )
            if unclaimed_total > 0:
                self.logger.info(
                    f"Auto-evict: skipping '{bundle_name}' on {gpu_id} "
                    f"({unclaimed_total} unclaimed entries in {sorted(routing_groups)})"
                )
                continue

            # S5: back off if a previous unload attempt was within
            # threshold * 2 (avoids spamming the journal when systemd
            # is broken or a service refuses to stop).
            if (
                gpu_state.last_evict_attempt_at > 0.0
                and (now - gpu_state.last_evict_attempt_at) < threshold * 2
            ):
                continue
            gpu_state.last_evict_attempt_at = now

            # Unload linked bundles and the primary under one durable group
            # fence. The group covers the complete mutation boundary so a
            # competing loader cannot acquire a linked member between stops.
            linked = _get_linked_bundles(bundle_name, bundles=bundles)
            try:
                transition_members = _expand_bundle_transition_members(
                    [(bundle_name, BundleDesiredState.STOPPED)],
                    bundles=bundles,
                )
            except Exception as exc:
                self.logger.error(
                    "Auto-evict: refusing '%s' due to invalid bundle group: %s",
                    bundle_name,
                    exc,
                )
                continue

            async def _unload_candidate_graph() -> bool:
                for linked_name in linked:
                    if not await _unload_bundle(linked_name):
                        return False
                return await _unload_bundle(bundle_name)

            unloaded = await _run_bundle_group_transition(
                transition_members,
                _unload_candidate_graph,
                reason=f"auto-evict:{bundle_name}",
            )
            if not unloaded:
                self.logger.warning(
                    f"Auto-evict: failed to unload bundle group rooted at '{bundle_name}'"
                )
                continue

            self.logger.info(
                f"Auto-evict: unloaded idle bundle '{bundle_name}' on {gpu_id} "
                f"(idle {now - last_activity:.0f}s, threshold {threshold:.0f}s)"
            )
            # Signal the scheduler to restore the idle LLM next tick.
            vram.mark_llm_evicted(True, source="auto_evict_idle_bundles")

    # ── Phase 5.2.69: Orphan reaper ─────────────────────────────────
    # Catches the "orphaned ComfyUI python PID 2547085" class of bug:
    # rapid LoadBundle restarts cause systemd to think the new unit is
    # active, but the original python process survives with PPID=1 and
    # keeps holding VRAM. gpu-manager's loaded_bundles bookkeeping says
    # "no bundle loaded", so it has no idea this process exists.
    #
    # The reaper runs on a fixed cadence (ORPHAN_REAPER_INTERVAL_S) from
    # _scheduler_loop. Each tick:
    #   1. Rebuild the expected-PID set from `systemctl show --property=MainPID`
    #      for every enabled service in services.json (cached for 10s).
    #   2. Walk _poll_vram's per-process fdinfo output. For any PID that
    #      holds >= ORPHAN_REAPER_VRAM_THRESHOLD_MB but is NOT in the
    #      expected set AND matches one of ORPHAN_REAPER_TARGET_NAMES,
    #      flag it as a candidate.
    #   3. For each candidate: log WARN, then SIGTERM. If still alive
    #      after ORPHAN_REAPER_GRACE_S, escalate to SIGKILL.
    #   4. Track terminated PIDs in _terminated_pids so a slow dying
    #      process doesn't re-fire every tick.
    #
    # Safety:
    #   - ORPHAN_REAPER_ENABLED kill switch (default True; can be flipped
    #     to False by environment override). When False, the scheduler skips
    #     the reaper scan entirely and no signals can be sent.
    #   - Conservative target name list — only matches python and the
    #     well-known LLM backends. Xorg, kwin, plasmashell, browser
    #     renderers etc. are excluded by name even if orphaned.
    #   - Threshold of 100 MB avoids killing low-VRAM background helpers.

    async def _orphan_reaper_tick(self) -> None:
        """One pass of the orphan reaper. Idempotent and cheap; safe to call
        on every scheduler tick (the cadence is throttled at the call site).
        """
        if not ORPHAN_REAPER_ENABLED:
            return
        try:
            now = time.time()

            # 1. Refresh expected-PID set from systemd. We DO NOT rely
            #    on explicit register/unregister hooks in _load_bundle
            #    etc. — this method is self-healing because it queries
            #    systemd directly for every enabled service's MainPID.
            #    We mirror the resolved PIDs into self._expected_pids
            #    so /health can surface them as a live observability
            #    signal (and so explicit-register callers can merge in
            #    PIDs that systemd doesn't yet know about — e.g. a
            #    freshly-spawned child of a service).
            expected: set[int] = set()
            try:
                config = _load_services_config()
                services_cfg = config.get("services", {})
                for svc_name, svc in services_cfg.items():
                    if not isinstance(svc, dict):
                        continue
                    unit = svc.get("systemd_unit")
                    if not unit:
                        continue
                    main_pid = await self._get_service_main_pid(unit)
                    if main_pid and main_pid > 0:
                        expected.add(main_pid)
            except Exception as e:
                self.logger.debug(f"[orphan-reaper] expected-PID refresh failed: {e}")

            # Also include anything we've explicitly registered in this
            # process — covers edge cases like systemctl show returning
            # MainPID=0 transiently during a service restart.
            expected |= self._expected_pids

            # Mirror into the canonical attribute so /health reflects
            # the live expected set, not just the per-tick scratch set.
            self._expected_pids = set(expected)

            # Prune _terminated_pids entries that have aged out (process
            # died or we stopped tracking). 5 minutes is generous — if
            # the PID is still alive 5 min after SIGKILL we have bigger
            # problems than orphan accounting.
            if self._terminated_pids:
                cutoff = now - 300
                self._terminated_pids = {
                    pid: ts for pid, ts in self._terminated_pids.items()
                    if ts >= cutoff
                }

            # 2. Gather per-process VRAM attribution via _poll_vram.
            #    It already does the KFD fdinfo scan and reports
            #    {pid, name, vram_mib} per process on each GPU.
            try:
                vram_data = await _poll_vram()
            except Exception as e:
                self.logger.debug(f"[orphan-reaper] _poll_vram failed: {e}")
                return

            if not isinstance(vram_data, dict):
                return

            candidates: list[dict] = []
            seen_pids: set[int] = set()

            # Walk per-device process lists. vram_data['per_device'] is
            # the canonical source — it has one entry per GPU with a
            # 'processes' list. Dedup by PID since the same process can
            # appear on multiple GPUs' fdinfo.
            for dev in vram_data.get("per_device", []) or []:
                card = dev.get("card", "?")
                for proc in dev.get("processes", []) or []:
                    pid = proc.get("pid")
                    name = (proc.get("name") or "").strip()
                    vram_mib = int(proc.get("vram_mib", 0) or 0)
                    if not pid or pid in seen_pids:
                        continue
                    seen_pids.add(pid)
                    if vram_mib < ORPHAN_REAPER_VRAM_THRESHOLD_MB:
                        continue
                    if pid in expected:
                        # Known PID (systemd MainPID or registered) — skip.
                        continue
                    if name not in ORPHAN_REAPER_TARGET_NAMES:
                        # Conservative: skip processes that aren't known
                        # VRAM-holding backends (Xorg, kwin, browsers).
                        continue
                    # Skip processes we've already started reaping — they
                    # are in their SIGTERM→SIGKILL grace window.
                    if pid in self._terminated_pids:
                        continue
                    candidates.append({
                        "pid": pid,
                        "name": name,
                        "vram_mib": vram_mib,
                        "card": card,
                    })

            if not candidates:
                self._last_orphan_reaper_at = now
                return

            # 3. For each candidate: check PPID. We treat "PPID=1" or
            #    "PPID points to a dead PID" as orphan. Reading /proc
            #    is cheap; do it inline.
            import os as _os
            for c in candidates:
                pid = c["pid"]
                ppid = -1
                ppid_alive = True
                try:
                    with open(f"/proc/{pid}/stat", "rb") as f:
                        # /proc/<pid>/stat: pid (comm) state ppid ...
                        # comm can contain spaces and parens; parse from
                        # the right — last ")" then fields after.
                        content = f.read().decode("utf-8", errors="replace")
                        rparen = content.rfind(")")
                        if rparen >= 0 and rparen + 2 < len(content):
                            fields = content[rparen + 2:].split()
                            # fields[0] = state, fields[1] = ppid
                            if len(fields) >= 2:
                                ppid = int(fields[1])
                except (OSError, IOError, ValueError):
                    # /proc entry gone — process died between _poll_vram
                    # and this read. Not an orphan anymore.
                    continue

                # Orphans: PPID==1 (init reparented), OR PPID points to
                # a process that no longer exists.
                is_orphan = False
                if ppid == 1:
                    is_orphan = True
                elif ppid > 1 and not _os.path.exists(f"/proc/{ppid}"):
                    is_orphan = True

                if not is_orphan:
                    # PID is alive, has a real parent that exists.
                    # Not an orphan from our perspective — leave alone.
                    self.logger.debug(
                        f"[orphan-reaper] {c['name']} pid={pid} ppid={ppid} "
                        f"vram={c['vram_mib']}MiB on {c['card']} — "
                        f"not orphaned (live parent), skipping"
                    )
                    continue

                # 4. Reap it.
                self.logger.warning(
                    f"[orphan-reaper] ORPHAN: {c['name']} pid={pid} "
                    f"ppid={ppid} vram={c['vram_mib']}MiB on {c['card']} "
                    f"— sending SIGTERM"
                )
                self._terminated_pids[pid] = now
                try:
                    _os.kill(pid, 15)  # SIGTERM
                except ProcessLookupError:
                    pass
                except PermissionError:
                    self.logger.warning(
                        f"[orphan-reaper] pid={pid} not killable "
                        f"by gpu-manager (different uid?) — leaving alone"
                    )
                except Exception as e:
                    self.logger.warning(
                        f"[orphan-reaper] SIGTERM pid={pid} failed: {e}"
                    )

            self._last_orphan_reaper_at = now
        except Exception as e:
            # Never let the reaper take down the scheduler loop.
            self.logger.warning(f"[orphan-reaper] tick crashed: {e}")
            self._last_orphan_reaper_at = time.time()

        # 5. SIGKILL escalation pass: any PID that was SIGTERMed in a
        #    previous tick and is STILL alive after ORPHAN_REAPER_GRACE_S
        #    gets SIGKILL. We do this in the same tick (after the SIGTERM
        #    pass above) so the grace window is honored even if the
        #    reaper ran exactly once between SIGTERM and now.
        try:
            import os as _os2
            now2 = time.time()
            escalate = [
                pid for pid, ts in self._terminated_pids.items()
                if (now2 - ts) >= ORPHAN_REAPER_GRACE_S
            ]
            for pid in escalate:
                try:
                    # Re-check: does the process still exist?
                    if not _os2.path.exists(f"/proc/{pid}"):
                        # Already gone — clean up the tracking entry.
                        self._terminated_pids.pop(pid, None)
                        continue
                    # Read its PPID once more to make sure we didn't
                    # accidentally target a PID that got adopted by a
                    # live parent (rare but possible).
                    try:
                        with open(f"/proc/{pid}/stat", "rb") as f:
                            content = f.read().decode("utf-8", errors="replace")
                            rparen = content.rfind(")")
                            if rparen >= 0 and rparen + 2 < len(content):
                                fields = content[rparen + 2:].split()
                                if len(fields) >= 2:
                                    ppid = int(fields[1])
                                    if ppid != 1 and _os2.path.exists(f"/proc/{ppid}"):
                                        # PID is no longer an orphan;
                                        # some live parent has adopted it.
                                        self.logger.info(
                                            f"[orphan-reaper] pid={pid} "
                                            f"was adopted by live parent "
                                            f"ppid={ppid} — clearing from "
                                            f"terminated set"
                                        )
                                        self._terminated_pids.pop(pid, None)
                                        continue
                    except (OSError, IOError):
                        # /proc gone — process exited.
                        self._terminated_pids.pop(pid, None)
                        continue
                    self.logger.warning(
                        f"[orphan-reaper] ESCALATE: pid={pid} survived "
                        f"SIGTERM by {(now2 - self._terminated_pids.get(pid, now2)):.0f}s "
                        f"(>= {ORPHAN_REAPER_GRACE_S:.0f}s grace) — sending SIGKILL"
                    )
                    try:
                        _os2.kill(pid, 9)  # SIGKILL
                    except ProcessLookupError:
                        pass
                    except PermissionError:
                        self.logger.warning(
                            f"[orphan-reaper] SIGKILL pid={pid} denied "
                            f"(different uid?) — leaving alone"
                        )
                    # Track an additional 60s before we ever re-log this PID.
                    self._terminated_pids[pid] = now2
                except Exception as _esc_err:
                    self.logger.debug(
                        f"[orphan-reaper] escalation for pid={pid} "
                        f"crashed: {_esc_err}"
                    )
        except Exception as _esc_outer:
            self.logger.debug(f"[orphan-reaper] escalation pass crashed: {_esc_outer}")

    async def _get_service_main_pid(self, unit: str) -> int:
        """Resolve a systemd unit's MainPID with a short cache.

        Uses `systemctl show --property=MainPID` (no sudo required for
        most units on this box; falls back to 0 on any error). Cached
        for self._MAINPID_CACHE_TTL_S to avoid a fork per service per
        tick.
        """
        now = time.time()
        cached = self._mainpid_cache.get(unit)
        if cached and (now - cached[1]) < self._MAINPID_CACHE_TTL_S:
            return cached[0]
        pid = 0
        try:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "show", unit, "--property=MainPID", "--no-page",
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            try:
                stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=3)
            except asyncio.TimeoutError:
                proc.kill()
                self._mainpid_cache[unit] = (0, now)
                return 0
            if proc.returncode == 0 and stdout:
                # Output: "MainPID=12345\n"
                line = stdout.decode("utf-8", errors="replace").strip()
                if "=" in line:
                    try:
                        pid = int(line.split("=", 1)[1])
                    except ValueError:
                        pid = 0
        except Exception as e:
            self.logger.debug(f"[orphan-reaper] systemctl show {unit} failed: {e}")
        self._mainpid_cache[unit] = (pid, now)
        return pid

    def _register_expected_pid(self, pid: int) -> None:
        """Add a PID to the expected set (called from start hooks)."""
        try:
            self._expected_pids.add(int(pid))
        except (TypeError, ValueError):
            pass

    def _unregister_expected_pid(self, pid: int) -> None:
        """Remove a PID from the expected set (called from stop hooks)."""
        try:
            self._expected_pids.discard(int(pid))
        except (TypeError, ValueError):
            pass

    async def _ensure_idle_service(self):
        """Ensure all configured idle/default LLM services are running when queue is empty.

        Supports per-GPU idle services (idle_services dict) in addition to the
        global idle_service.  Each GPU's idle service is checked independently —
        if one crashes, only that one is restarted.

        Phase 2: Each GPU's idle bundle is checked independently against
        the per-GPU queue.  If a GPU has active work, its idle service
        is not restored (the work will trigger eviction/restore when done).

        CRASH RECOVERY: Detects when a service's port was recently responding
        but is now down (= crash).  Crashed services bypass the 60s throttle
        for immediate restart.

        MAINTENANCE MODE: Skips all service management when active.
        """
        config = _load_services_config()
        scheduling = config.get("scheduling", {})

        # Maintenance mode: hands off
        if _maintenance_mode_enabled(scheduling):
            return

        # Phase 5.2.66: coexistence mode (manual SRE pause).
        # Auto-expire if a duration was set and the deadline has passed.
        if self._coexistence_paused and self._coexistence_pause_expires > 0:
            if time.time() > self._coexistence_pause_expires:
                self._coexistence_paused = False
                self._coexistence_pause_expires = 0.0
                self.logger.info(
                    "Coexistence pause auto-expired — resuming auto-restoration"
                )
            else:
                # Still paused: log at debug so we don't spam, but emit a WARNING
                # the first time after a pause was set so SREs see the state change.
                # We rely on a separate WARNING emitted at pause-set time (handler),
                # so here we just silently skip the auto-restore path.
                pass

        if self._coexistence_paused:
            # Distinct from maintenance_mode: pause does NOT block manual
            # starts via /v1/services/{name}/toggle — it only blocks the
            # scheduler's auto-restoration loop (incl. crash recovery).
            self.logger.debug(
                "Idle: coexistence mode paused — skipping auto-restore"
            )
            return

        c_active = any(j.status in ("queued", "running") for j in self._comfyui_queue)
        a_active = any(j.status in ("queued", "running") for j in self._acestep_queue)

        if c_active or a_active or self._current_backend:
            return  # Legacy GPU work in progress — don't interrupt

        # WorkerPool jobs are tracked outside the legacy scheduler queues above.
        # Hold every linked generation GPU until the worker reaches a terminal
        # backend state.  In particular, a ComfyUI lease on gpu_primary protects
        # the reservation-only krea2-encoder bundle on gpu_secondary from Gemma restore.
        _bundles_now = _resolve_bundles()
        if any(
            _bundle_worker_in_flight(name, _bundles_now) > 0
            for name, bundle_cfg in _bundles_now.items()
            if not bundle_cfg.get("idle", False)
        ):
            self.logger.debug(
                "Idle: skipping auto-restore — WorkerPool has an in-flight "
                "lease on a generation bundle or linked GPU"
            )
            return

        # If any GPU is currently being evicted/loaded/drained, do not let
        # idle crash-recovery race the transition. A generation bundle load
        # may briefly stop an idle LLM before the generation backend is marked
        # current_backend; restarting that LLM here re-fills VRAM and defeats
        # the requested reservation/switch.
        global _gpu_states, scheduler
        sched_obj = globals().get("scheduler")
        sched_state = getattr(sched_obj, "_gpu_state", {}) if sched_obj is not None else {}
        if any(
            state.get("loading") or state.get("evicting") or state.get("draining")
            for state in sched_state.values()
            if isinstance(state, dict)
        ):
            return
        if any(
            getattr(gs, "state", None) in ("loading", "evicting", "draining")
            for gs in _gpu_states.values()
        ):
            return

        if llm.active_requests > 0:
            return  # LLM requests in flight — don't swap

        if _pinned_service_blocks_idle_restore(self._pinned_service):
            return  # Generation backend is pinned — don't swap to idle

        # Get all configured idle services (per-GPU + global fallback)
        all_idle = _get_all_idle_services()
        if not all_idle:
            return

        now = time.time()

        for idle_entry in all_idle:
            gpu_id = idle_entry["gpu_id"]
            idle_svc_name = idle_entry["service_name"]
            port = idle_entry["port"]
            unit = idle_entry["systemd_unit"]

            if not idle_svc_name or not unit:
                continue

            # Phase 2: Skip this GPU's idle if it has active work in its queue
            if gpu_id and gpu_id in self._gpu_queues:
                gpu_active = any(
                    j.status in ("queued", "running")
                    for j in self._gpu_queues[gpu_id]
                )
                if gpu_active:
                    self.logger.debug(
                        f"Idle: skipping GPU {gpu_id} idle check — "
                        f"has active work in queue"
                    )
                    continue

            # BUGFIX: If a bundle is currently being loaded on this GPU, don't
            # re-load the idle LLM — the watchdog would race the load and
            # cause OOM. The loading state is set by _load_bundle.
            _sched = getattr(self, 'scheduler', None) or globals().get("scheduler")
            _sched_gpu_state = getattr(_sched, '_gpu_state', {}).get(gpu_id, {}) if _sched is not None else {}
            if _sched_gpu_state.get("loading") or _sched_gpu_state.get("evicting") or _sched_gpu_state.get("draining"):
                active_flags = [
                    name for name in ("loading", "evicting", "draining")
                    if _sched_gpu_state.get(name)
                ]
                self.logger.debug(
                    f"Idle: skipping GPU {gpu_id} idle check — "
                    f"scheduler state active ({','.join(active_flags)})"
                )
                continue
            _gs_obj_idle = _gpu_states.get(gpu_id) if isinstance(_gpu_states, dict) else None
            if _gs_obj_idle is not None and getattr(_gs_obj_idle, 'state', None) in ("loading", "evicting", "draining"):
                self.logger.debug(
                    f"Idle: skipping GPU {gpu_id} idle check — "
                    f"gpu_state.state=={getattr(_gs_obj_idle, 'state', None)!r}"
                )
                continue

            # Fence every idle-service start/swap path, not only the later
            # _restore_after_gpu_work call. A serial batch handoff lease exists
            # after the previous worker completes and before the next row is
            # claimed; starting either idle Gemma during that gap can evict or
            # reset the still-warm ComfyUI process.
            _idle_restore_blockers = _restore_after_gpu_work_blockers()
            if _idle_restore_blockers:
                self.logger.debug(
                    f"Idle: skipping auto-restore on GPU {gpu_id} — "
                    + ",".join(_idle_restore_blockers)
                )
                continue

            # B3.2: Gate auto-restore on VRAM/tenant safety
            blocked, reason = await _gpu_has_active_generation_tenant(gpu_id)
            if blocked:
                self.logger.debug(
                    f"Idle: skipping auto-restore on GPU {gpu_id} — {reason}"
                )
                continue

            idle_svc = config.get("services", {}).get(idle_svc_name, {})
            idle_bundle = _get_idle_bundle(gpu_id) if gpu_id else None
            idle_bundle_name = (
                idle_bundle.get("bundle_name", idle_svc_name)
                if idle_bundle
                else idle_svc_name
            )
            last_h = self._idle_service_last_healthy.get(idle_svc_name, 0.0)
            if bundle_lifecycle_controller is not None:
                try:
                    bundle_record = await bundle_lifecycle_controller.snapshot(
                        idle_bundle_name
                    )
                    recovery_state = bundle_record.recovery
                except Exception:
                    self.logger.error(
                        "Idle: failed to read durable lifecycle state for bundle %s",
                        idle_bundle_name,
                        exc_info=True,
                    )
                    continue
            else:
                recovery_state = self._idle_recovery_states.get(
                    idle_svc_name, RecoveryState()
                )
            # Preserve legacy healthy evidence while older records are being
            # adopted into the bundle-level ledger.
            if recovery_state.last_healthy_at is None and last_h > 0:
                recovery_state = RecoveryState(
                    phase=recovery_state.phase,
                    transition_id=recovery_state.transition_id,
                    restart_attempts=recovery_state.restart_attempts,
                    retry_window_started_at=recovery_state.retry_window_started_at,
                    last_restart_at=recovery_state.last_restart_at,
                    last_healthy_at=last_h,
                )

            planned_stop = bool(
                event_bus is not None
                and event_bus.is_planned_stop(idle_svc_name)
            )
            pre_decision = reduce_recovery(
                recovery_state,
                RecoveryObservation(
                    enabled=bool(idle_svc.get("enabled")),
                    desired_state=DesiredState.IDLE,
                    maintenance_mode=_maintenance_mode_enabled(scheduling),
                    planned_stop=planned_stop,
                    coexistence_paused=bool(self._coexistence_paused),
                    now=now,
                ),
            )
            if bundle_lifecycle_controller is not None:
                try:
                    persisted = await bundle_lifecycle_controller.record_recovery_state(
                        idle_bundle_name,
                        pre_decision.next,
                        desired_state=DesiredState.IDLE,
                        reason=f"idle-pre:{pre_decision.reason}",
                    )
                except Exception:
                    self.logger.error(
                        "Idle: failed to persist pre-probe state for bundle %s",
                        idle_bundle_name,
                        exc_info=True,
                    )
                    continue
                if not persisted:
                    self.logger.debug(
                        "Idle: durable bundle state is fenced for %s; deferring probe",
                        idle_bundle_name,
                    )
                    continue
            else:
                self._idle_recovery_states[idle_svc_name] = pre_decision.next
            if pre_decision.action is not RecoveryAction.PROBE:
                if pre_decision.action is RecoveryAction.QUARANTINE:
                    self.logger.error(
                        "Idle service %s recovery quarantined: %s",
                        idle_svc_name,
                        pre_decision.reason,
                    )
                continue

            # ── Check what's actually running on this GPU ──
            running_llm = await self._find_running_llm_on_gpu(
                config, idle_svc_name, gpu_id
            )
            if running_llm and running_llm != idle_svc_name:
                # WRONG service is running — need to swap even if it's healthy
                is_healthy = False  # Force swap path below
            else:
                # ── Check if this idle service is healthy ──
                is_healthy = False
                try:
                    async with self.session.get(
                        f"http://localhost:{port}/health",
                        timeout=ClientTimeout(total=2, connect=1),
                    ) as resp:
                        if resp.status == 200:
                            is_healthy = True
                except Exception:
                    pass

            post_decision = reduce_recovery(
                pre_decision.next,
                RecoveryObservation(
                    enabled=bool(idle_svc.get("enabled")),
                    desired_state=DesiredState.IDLE,
                    maintenance_mode=_maintenance_mode_enabled(scheduling),
                    planned_stop=planned_stop,
                    coexistence_paused=bool(self._coexistence_paused),
                    probe_ok=is_healthy,
                    now=now,
                ),
            )
            if bundle_lifecycle_controller is not None:
                try:
                    persisted = await bundle_lifecycle_controller.record_recovery_state(
                        idle_bundle_name,
                        post_decision.next,
                        desired_state=DesiredState.IDLE,
                        reason=f"idle-post:{post_decision.reason}",
                    )
                except Exception:
                    self.logger.error(
                        "Idle: failed to persist post-probe state for bundle %s",
                        idle_bundle_name,
                        exc_info=True,
                    )
                    continue
                if not persisted:
                    self.logger.debug(
                        "Idle: durable bundle state changed during probe for %s",
                        idle_bundle_name,
                    )
                    continue
            else:
                self._idle_recovery_states[idle_svc_name] = post_decision.next

            if post_decision.action is RecoveryAction.SKIP:
                if post_decision.reason == "ready":
                    self._idle_service_last_healthy[idle_svc_name] = now
                continue
            if post_decision.action is RecoveryAction.QUARANTINE:
                self.logger.error(
                    "Idle service %s recovery quarantined: %s",
                    idle_svc_name,
                    post_decision.reason,
                )
                continue

            is_crash = post_decision.action is RecoveryAction.RESTART
            if post_decision.emit_transition_log and is_crash:
                self.logger.warning(
                    "Idle service CRASH transition: %s port %s; recovery transition_id=%s",
                    idle_svc_name,
                    port,
                    post_decision.next.transition_id,
                )
            self._last_idle_restore_attempt_map[idle_svc_name] = now

            if self._restoring or self._swapping:
                return  # Already in the middle of a restore/swap — don't stack

            # ── Start/restart this idle service ──
            self._idle_service_last_started[idle_svc_name] = now  # Record start time for cooldown
            tag = f" (gpu={gpu_id})" if gpu_id else ""
            self.logger.info(
                f"Idle service: starting {idle_svc_name}{tag} "
                f"(port {port}, crash={is_crash})"
            )

            # Check if another LLM is using the same GPU — if so, stop it first
            running_llm_on_gpu = await self._find_running_llm_on_gpu(
                config, idle_svc_name, gpu_id
            )

            if running_llm_on_gpu and running_llm_on_gpu != idle_svc_name:
                self._swapping = True
                bundles = _resolve_bundles()
                running_bundle = _get_bundle_for_service(running_llm_on_gpu, bundles)
                running_bundle_name = (
                    running_bundle.get("bundle_name", running_llm_on_gpu)
                    if running_bundle
                    else None
                )
                transition_roots = [
                    (idle_bundle_name, BundleDesiredState.IDLE),
                ]
                if running_bundle_name and running_bundle_name != idle_bundle_name:
                    transition_roots.append(
                        (running_bundle_name, BundleDesiredState.STOPPED)
                    )
                try:
                    transition_members = _expand_bundle_transition_members(
                        transition_roots,
                        bundles=bundles,
                    )
                except ValueError:
                    self.logger.error(
                        "Idle: refusing swap with conflicting linked bundle states: %s",
                        transition_roots,
                        exc_info=True,
                    )
                    self._swapping = False
                    return
                async def _swap_operation() -> bool:
                    self.logger.info(
                        f"Idle service: swapping {running_llm_on_gpu} → {idle_svc_name}{tag}"
                    )
                    self._lifecycle_begin(
                        "swap", idle_svc_name, "swap",
                        from_state=running_llm_on_gpu, to_state=idle_svc_name,
                    )

                    # Stop current LLM on this GPU
                    # Phase 3: Use _unload_bundle/_load_bundle instead of raw systemctl
                    self._lifecycle_step_begin("stop_current")
                    if running_bundle_name:
                        await _unload_bundle(running_bundle_name)
                    else:
                        self.logger.error(
                            "Idle: refusing unfenced swap stop for service %s",
                            running_llm_on_gpu,
                        )
                        return False
                    await asyncio.sleep(3)
                    self._lifecycle_step_done("stop_current")

                    # Wait for VRAM to clear
                    self._lifecycle_step_begin("wait_vram_free")
                    for _ in range(15):
                        vram_data = await _poll_vram()
                        if vram_data.get("used_vram_mib", 9999) < 500:
                            break
                        await asyncio.sleep(1)
                    self._lifecycle_step_done("wait_vram_free")

                    # Phase 3: Use _load_bundle to start the idle bundle
                    self._lifecycle_step_begin("start_new")
                    idle_bundle = _get_idle_bundle(gpu_id) if gpu_id else None
                    if idle_bundle:
                        load_bundle_name = idle_bundle.get("bundle_name", idle_svc_name)
                        load_ok = await _load_bundle(
                            load_bundle_name, timeout=LLM_RESTORE_TIMEOUT
                        )
                    else:
                        self.logger.error(
                            "Idle: refusing unfenced start for service %s",
                            idle_svc_name,
                        )
                        return False
                    self._lifecycle_step_done("start_new")

                    # Wait for healthy (already waited in _load_bundle via port check)
                    self._lifecycle_step_begin("wait_healthy")
                    if not load_ok:
                        healthy = False
                    else:
                        healthy = await vram._wait_for_llm_healthy(
                            timeout=LLM_RESTORE_TIMEOUT
                        )
                    self._lifecycle_step_done("wait_healthy")
                    return healthy

                healthy = await _run_bundle_group_transition(
                    transition_members,
                    _swap_operation,
                    reason=f"idle-swap:{idle_svc_name}",
                )
                if healthy:
                    vram.mark_llm_evicted(False, source="ensure_idle_swap_in")
                    vram.gpu_state = GpuState.LLM_LOADED
                    self._lifecycle_complete()
                    self._idle_service_last_healthy[idle_svc_name] = time.time()
                    self.logger.info(
                        f"Idle service: {idle_svc_name}{tag} swapped in and healthy"
                    )
                else:
                    self._lifecycle_error(f"{idle_svc_name} not healthy after swap")
                    self.logger.warning(
                        f"Idle service: {idle_svc_name}{tag} not healthy after swap"
                    )
                self._swapping = False
            else:
                # No other LLM on this GPU (or same LLM crashed) — just start it
                if self._restoring:
                    return
                # The legacy global restore resolves scheduling.idle_service and
                # cannot restore a per-GPU idle_services entry when the global
                # idle service is empty.  Per-GPU recovery already has the exact
                # idle bundle and must use the fenced bundle transition below.
                if vram and vram._llm_evicted and not gpu_id:
                    self.logger.info(
                        f"Idle service: restoring {idle_svc_name}{tag} "
                        f"(no GPU work, service not running)"
                    )
                    await self._restore_after_gpu_work()
                else:
                    # Service simply crashed or was never started — start directly
                    self._swapping = True
                    bundles = _resolve_bundles()
                    try:
                        transition_members = _expand_bundle_transition_members(
                            [(idle_bundle_name, BundleDesiredState.IDLE)],
                            bundles=bundles,
                        )
                    except ValueError:
                        self.logger.error(
                            "Idle: refusing restart with conflicting linked bundle states: %s",
                            idle_bundle_name,
                            exc_info=True,
                        )
                        self._swapping = False
                        return
                    async def _restart_operation() -> bool:
                        self._lifecycle_begin(
                            "restart", idle_svc_name, "restart"
                        )
                        # Phase 3: Use _unload_bundle/_load_bundle for restart
                        self._lifecycle_step_begin("stop_old")
                        idle_b = _get_idle_bundle(gpu_id) if gpu_id else None
                        if idle_b:
                            await _unload_bundle(idle_b.get("bundle_name", idle_svc_name))
                        else:
                            self.logger.error(
                                "Idle: refusing unfenced restart stop for service %s",
                                idle_svc_name,
                            )
                            return False
                        await asyncio.sleep(2)
                        self._lifecycle_step_done("stop_old")

                        self._lifecycle_step_begin("start_new")
                        if idle_b:
                            load_ok = await _load_bundle(
                                idle_b.get("bundle_name", idle_svc_name),
                                timeout=LLM_RESTORE_TIMEOUT,
                            )
                        else:
                            self.logger.error(
                                "Idle: refusing unfenced restart start for service %s",
                                idle_svc_name,
                            )
                            return False
                        self._lifecycle_step_done("start_new")

                        self._lifecycle_step_begin("wait_healthy")
                        if not load_ok:
                            healthy = False
                        else:
                            healthy = await vram._wait_for_llm_healthy(
                                timeout=LLM_RESTORE_TIMEOUT
                            )
                        self._lifecycle_step_done("wait_healthy")
                        return healthy

                    healthy = await _run_bundle_group_transition(
                        transition_members,
                        _restart_operation,
                        reason=f"idle-restart:{idle_svc_name}",
                    )
                    if healthy:
                        vram.mark_llm_evicted(False, source="ensure_idle_restart")
                        vram.gpu_state = GpuState.LLM_LOADED
                        self._lifecycle_complete()
                        self._idle_service_last_healthy[idle_svc_name] = time.time()
                        self.logger.info(
                            f"Idle service: {idle_svc_name}{tag} restarted and healthy"
                        )
                    else:
                        self._lifecycle_error(
                            f"{idle_svc_name} not healthy after restart"
                        )
                        self.logger.warning(
                            f"Idle service: {idle_svc_name}{tag} not healthy after restart"
                        )
                    self._swapping = False

    async def _find_running_llm_on_gpu(
        self, config: dict, exclude_svc: str, gpu_id: str | None
    ) -> str | None:
        """Find which LLM service is currently running on the same GPU as the target idle service.

        Returns the service name of the running LLM, or None.
        For per-GPU idle, only considers services that share the same gpu_id.
        For the global fallback (gpu_id=None), considers any GPU LLM.
        """
        services = config.get("services", {})
        for name, svc in services.items():
            if name == exclude_svc:
                continue
            if svc.get("type") != "llm_backend" or svc.get("cpu_only"):
                continue
            # GPU affinity check: for per-GPU idle, only consider same-gpu services
            if gpu_id is not None:
                svc_gpu = svc.get("gpu_id", "")
                if svc_gpu != gpu_id:
                    continue
            elif svc.get("gpu_id"):
                # Global idle: skip services pinned to a specific other GPU
                continue
            svc_port = svc.get("port", 0)
            try:
                async with self.session.get(
                    f"http://localhost:{svc_port}/health",
                    timeout=ClientTimeout(total=1, connect=0.5),
                ) as resp:
                    if resp.status == 200:
                        return name
            except Exception:
                pass
        return None


    # ── ComfyUI Batch Execution ────────────────────────────────────

    async def _run_comfyui_batch(self):
        """Run one batch of ComfyUI jobs (fingerprint grouping)."""
        pending = [j for j in self._comfyui_queue if j.status == "queued"]
        if not pending:
            return

        # Ensure ComfyUI is running (may have been auto-stopped during idle)
        if not await vram._ensure_comfyui_running():
            self.logger.error("ComfyUI failed to start — cannot run batch")
            return

        # Group by fingerprint
        groups: dict[str, list[Job]] = defaultdict(list)
        for j in pending:
            groups[j.fingerprint].append(j)

        # Pick best group: sort by (tier, aggregate_priority, earliest_created)
        def group_key(fp):
            return (
                min(self.effective_tier(j).value for j in groups[fp]),
                -sum(j.priority for j in groups[fp]),
                -min(j.created_at for j in groups[fp]),
            )
        best_fp = min(groups.keys(), key=group_key)
        batch = sorted(
            groups[best_fp],
            key=lambda j: (self.effective_tier(j).value, -j.priority, j.created_at),
        )

        self._current_backend = "comfyui"
        self.total_batches += 1
        batch_model = batch[0].model_key

        self.logger.info(
            f"── ComfyUI batch #{self.total_batches}: {len(batch)} job(s), "
            f"model={batch_model} ──"
        )

        for job in batch:
            if job.status == "cancelled":
                continue

            # Preemption check: if a new HIGH priority job arrived, let it jump the queue
            if job.priority_tier != PriorityTier.HIGH:
                high_pri_pending = [j for j in self._comfyui_queue
                                    if j.status == "queued"
                                    and self.effective_tier(j) == PriorityTier.HIGH
                                    and j.id not in [b.id for b in batch]]
                if high_pri_pending:
                    self.logger.info(
                        f"Job {job.id}: deferred — HIGH priority job(s) "
                        f"({', '.join(j.id for j in high_pri_pending)}) ahead"
                    )
                    continue

            await self._run_comfyui_job(job)

        self._current_backend = None

        # Mark idle time for auto-stop.
        remaining = [j for j in self._comfyui_queue if j.status == "queued"]
        if not remaining:
            vram._comfyui_idle_since = time.time()
            self.logger.debug(f"ComfyUI batch complete — idle timer started")

    async def _run_comfyui_job(self, job: Job):
        """Submit a single job to ComfyUI and wait for completion."""
        job.status = "running"
        job.started_at = time.time()
        self.logger.info(f"Job {job.id}: submitting to ComfyUI (model={job.model_key})")

        try:
            # BUGFIX: Verify ComfyUI is responsive before submitting.
            # If ComfyUI is mid-restart (from a prior job's restore cycle),
            # POST /prompt returns 200 with a prompt_id but the prompt is
            # silently dropped because ComfyUI's internal state is not ready.
            #
            # We check /queue (not /system_stats) because the queue handler
            # depends on the workflow engine being fully initialized.
            async def _wait_comfyui_ready(timeout_s: int = 90) -> bool:
                """Wait for ComfyUI to be truly ready (workflow engine up)."""
                deadline = time.time() + timeout_s
                while time.time() < deadline:
                    try:
                        async with self.session.get(
                            f"{COMFYUI_URL}/queue",
                            timeout=ClientTimeout(total=5),
                        ) as r:
                            if r.status == 200:
                                data = await r.json()
                                # Validate it's real queue data, not empty dict
                                if "queue_running" in data and "queue_pending" in data:
                                    return True
                    except Exception:
                        pass
                    await asyncio.sleep(2)
                return False

            if not await _wait_comfyui_ready():
                job.status = "failed"
                job.result = {"error": "ComfyUI not ready after 90s wait"}
                job.finished_at = time.time()
                if job_tracker:
                    job_tracker.update_status(
                        job.id, "failed", error=job.result["error"]
                    )
                self.total_jobs_failed += 1
                return

            # Submit to ComfyUI
            async with self.session.post(
                f"{COMFYUI_URL}/prompt",
                json={"prompt": job.workflow},
                timeout=ClientTimeout(total=30),
            ) as resp:
                result = await resp.json()
                if resp.status != 200 or "prompt_id" not in result:
                    error_msg = result.get("error", {}).get("message", str(result))
                    job.status = "failed"
                    job.result = {"error": error_msg}
                    job.finished_at = time.time()
                    self.total_jobs_failed += 1
                    self.logger.error(f"Job {job.id}: submit failed — {error_msg}")
                    return

                job.comfyui_prompt_id = result["prompt_id"]
                self.logger.info(f"Job {job.id}: ComfyUI prompt_id={job.comfyui_prompt_id}")
                # Phase 5.2.51: also persist prompt_id to Redis now that we have it.
                # The earlier in_flight update (in _execute_job) ran before this
                # POST returned, so it couldn't include the prompt_id. This catch-up
                # update ensures the Redis copy is in sync with the in-memory job.
                if job_tracker:
                    job_tracker.update_status(
                        job.id, "in_flight",
                        comfyui_prompt_id=job.comfyui_prompt_id,
                    )

            # Poll for completion
            timeout = 1800
            start = time.time()
            while time.time() - start < timeout:
                # Preemption check: if pending HIGH priority job arrived while running MEDIUM/LOW
                if job.priority_tier in (PriorityTier.MEDIUM, PriorityTier.LOW):
                    high_pri_queue = [j for j in self._comfyui_queue
                                      if j.status == "queued"
                                      and self.effective_tier(j) == PriorityTier.HIGH]
                    if high_pri_queue:
                        self.logger.info(
                            f"Job {job.id}: preempting self for HIGH priority "
                            f"job(s) {', '.join(j.id for j in high_pri_queue)}"
                        )
                        # Interrupt ComfyUI, re-queue current job
                        await self._cancel_comfyui_prompt(job.comfyui_prompt_id)
                        job.status = "queued"
                        job.started_at = None
                        job.preempted = True
                        self.total_preemptions += 1
                        self._comfyui_queue.insert(0, job)
                        del self.comfyui_jobs[job.id]
                        self._current_backend = None
                        return
                try:
                    async with self.session.get(
                        f"{COMFYUI_URL}/history/{job.comfyui_prompt_id}",
                        timeout=ClientTimeout(total=10),
                    ) as resp:
                        history = await resp.json()
                except Exception:
                    await asyncio.sleep(3)
                    continue

                # Detect lost jobs (grace period for model loading)
                if time.time() - start > 120:
                    try:
                        async with self.session.get(
                            f"{COMFYUI_URL}/queue",
                            timeout=ClientTimeout(total=5),
                        ) as qresp:
                            queue_data = await qresp.json()
                        running_ids = set()
                        for item in queue_data.get("queue_running", []):
                            if len(item) > 1:
                                running_ids.add(item[1])
                        for item in queue_data.get("queue_pending", []):
                            if len(item) > 1:
                                running_ids.add(item[1])
                        if (job.comfyui_prompt_id not in history
                                and job.comfyui_prompt_id not in running_ids):
                            self.logger.warning(
                                f"Job {job.id}: lost — not in history or queue, "
                                f"prompt_id={job.comfyui_prompt_id}"
                            )
                            job.status = "failed"
                            job.result = {"error": "Job lost — not found in ComfyUI history or queue"}
                            job.finished_at = time.time()
                            if job_tracker:
                                job_tracker.update_status(
                                    job.id, "failed", error=job.result["error"]
                                )
                            self.total_jobs_failed += 1
                            return
                    except Exception:
                        pass
                    # Do NOT continue here — fall through to check history for completion

                if job.comfyui_prompt_id in history:
                    entry = history[job.comfyui_prompt_id]
                    if entry["status"].get("completed"):
                        outputs = entry.get("outputs", {})
                        files = []
                        for node_id, output in outputs.items():
                            for key in ("images", "videos", "audio", "gifs"):
                                if key in output:
                                    for item in output[key]:
                                        fn = item.get("filename", "")
                                        if fn:
                                            files.append({"type": key, "filename": fn})

                        comfyui_output_dir = str(COMFYUI_ROOT / "output")
                        result_files = []
                        for f in files:
                            fpath = os.path.join(comfyui_output_dir, f["filename"])
                            fsize = 0
                            try:
                                fsize = os.path.getsize(fpath)
                            except OSError:
                                pass
                            result_files.append({
                                "type": f["type"],
                                "filename": f["filename"],
                                "size": fsize,
                                "url": f"/generate/output/{f['filename']}",
                            })
                        job.status = "completed"
                        job.result = {"outputs": outputs, "files": result_files}
                        job.finished_at = time.time()
                        if job_tracker:
                            job_tracker.update_status(
                                job.id, "completed", result=job.result
                            )
                        self.total_jobs_completed += 1
                        elapsed = job.finished_at - job.started_at
                        self.logger.info(
                            f"Job {job.id}: completed in {elapsed:.1f}s "
                            f"({len(files)} file(s))"
                        )
                        return

                    if entry["status"].get("status_str") == "error":
                        job.status = "failed"
                        job.result = {"error": entry["status"]}
                        job.finished_at = time.time()
                        if job_tracker:
                            job_tracker.update_status(
                                job.id, "failed", error=job.result["error"]
                            )
                        self.total_jobs_failed += 1
                        self.logger.error(f"Job {job.id}: ComfyUI error")
                        return

                await asyncio.sleep(3)

            # Timeout
            self.logger.warning(f"Job {job.id}: timed out after {timeout}s — cancelling")
            await self._cancel_comfyui_prompt(job.comfyui_prompt_id)
            job.status = "failed"
            job.result = {"error": f"Job timed out after {timeout}s"}
            job.finished_at = time.time()
            if job_tracker:
                job_tracker.update_status(
                    job.id, "failed", error=job.result["error"]
                )
            self.total_jobs_failed += 1

        except Exception as e:
            job.status = "failed"
            job.result = {"error": str(e)}
            job.finished_at = time.time()
            if job_tracker:
                job_tracker.update_status(
                    job.id, "failed", error=job.result["error"]
                )
            self.total_jobs_failed += 1
            self.logger.error(f"Job {job.id}: exception — {e}")

    async def _cancel_comfyui_prompt(self, prompt_id: str | None):
        """Cancel a running ComfyUI prompt.

        Note: ComfyUI's /interrupt endpoint cancels ALL running prompts,
        not just the target one. Per-prompt cancellation is not available
        in the standard ComfyUI API. The prompt_id parameter is accepted
        for interface consistency but does not affect behavior.
        """
        if not prompt_id:
            return
        try:
            async with self.session.post(
                f"{COMFYUI_URL}/interrupt",
                timeout=ClientTimeout(total=5),
            ) as resp:
                self.logger.info(f"ComfyUI interrupt: status {resp.status}")
        except Exception as e:
            self.logger.error(f"ComfyUI interrupt failed: {e}")

    async def _free_comfyui(self):
        """Tell ComfyUI to unload all models and free VRAM."""
        try:
            async with self.session.post(
                f"{COMFYUI_URL}/free",
                json={"unload_models": True, "free_memory": True},
                timeout=ClientTimeout(total=30),
            ) as resp:
                self.logger.info(f"ComfyUI free: status {resp.status}")
        except Exception as e:
            self.logger.error(f"ComfyUI free failed: {e}")

    # ── ACE-Step Job Execution ─────────────────────────────────────

    def _snapshot_audio_dir(self, audio_dir: str) -> set[str]:
        """Return a snapshot of filenames in the backend's audio output dir."""
        try:
            return set(os.listdir(audio_dir))
        except OSError:
            return set()

    def _find_new_audio(self, audio_dir: str, before: set[str], ext: str = ".flac") -> list[str]:
        """Find audio files that appeared since the snapshot."""
        try:
            current = set(os.listdir(audio_dir))
        except OSError:
            return []
        new_files = current - before
        return sorted(f for f in new_files if f.endswith(ext))

    async def _run_acestep_job(self):
        """Run one ACE-Step job from the queue.

        Uses dual detection:
          1. query_result API (primary, sometimes unreliable)
          2. Filesystem detection (fallback — watches api_audio/ for new files)
        """
        pending = [j for j in self._acestep_queue if j.status == "queued"]
        if not pending:
            return

        # Sort by tier (HIGH first) then priority then created_at
        pending.sort(key=lambda j: (self.effective_tier(j).value, -j.priority, j.created_at))
        job = pending[0]

        # Defer if HIGH priority ComfyUI job pending (cross-backend priority)
        if job.priority_tier != PriorityTier.HIGH:
            comfy_high = [j for j in self._comfyui_queue
                          if j.status == "queued"
                          and self.effective_tier(j) == PriorityTier.HIGH]
            if comfy_high:
                self.logger.info(
                    f"ACE-Step job {job.id}: deferred — HIGH priority ComfyUI "
                    f"job(s) ahead"
                )
                return

        self._current_backend = job.service_name
        if job.bundle_name:
            admitted = await _evict_then_load_bundle(
                job.bundle_name, reason="acestep_job"
            )
            if not admitted:
                job.status = "failed"
                job.result = {"error": f"ACE-Step bundle admission failed: {job.bundle_name}"}
                job.finished_at = time.time()
                if job_tracker:
                    job_tracker.update_status(
                        job.id, "failed", error=job.result["error"]
                    )
                self._acestep_queue = [
                    queued for queued in self._acestep_queue if queued.id != job.id
                ]
                self._remove_from_gpu_queue(job)
                self.total_jobs_failed += 1
                self._current_backend = None
                await self._restore_after_gpu_work()
                return
        job.status = "running"
        job.started_at = time.time()
        if job_tracker:
            try:
                persisted = job_tracker.update_status(job.id, "in_flight")
            except Exception as tracker_error:
                persisted = False
                self.logger.error(
                    "ACE-Step job %s: durable in-flight update failed: %s",
                    job.id,
                    tracker_error,
                )
            if not persisted:
                await self._acestep_job_failed(
                    job, "durable_in_flight_transition_failed"
                )
                return
        self.logger.info(f"ACE-Step job {job.id}: submitting release_task")

        try:
            # Snapshot audio directory BEFORE submission
            audio_before = self._snapshot_audio_dir(job.audio_dir)

            # Submit to ACE-Step
            async with self.session.post(
                f"{job.endpoint}/release_task",
                json=job.payload,
                timeout=ClientTimeout(total=30),
            ) as resp:
                if resp.status != 200:
                    text = await resp.text()
                    error = f"release_task failed: {text}"
                    self.logger.error(f"ACE-Step job {job.id}: submit failed — {text}")
                    await self._acestep_job_failed(job, error)
                    return
                result = await resp.json()

            acestep_task_id = result.get("data", {}).get("task_id", "")
            job.acestep_task_id = acestep_task_id
            self.logger.info(f"ACE-Step job {job.id}: task_id={acestep_task_id}")

            # Poll for completion (dual detection)
            poll_interval = 10
            max_wait = 600
            start = time.time()
            audio_ext = f".{job.payload.get('audio_format', 'flac')}"

            while time.time() - start < max_wait:
                await asyncio.sleep(poll_interval)

                # Preemption check: if pending HIGH priority job arrived while running MEDIUM/LOW
                if job.priority_tier in (PriorityTier.MEDIUM, PriorityTier.LOW):
                    high_pri_queue = [j for j in self._acestep_queue
                                      if j.status == "queued"
                                      and self.effective_tier(j) == PriorityTier.HIGH]
                    comfy_high = [j for j in self._comfyui_queue
                                  if j.status == "queued"
                                  and self.effective_tier(j) == PriorityTier.HIGH]
                    if high_pri_queue or comfy_high:
                        source = "HIGH ACE-Step" if high_pri_queue else "HIGH ComfyUI"
                        self.logger.info(
                            f"ACE-Step job {job.id}: preempting self for {source} job(s)"
                        )
                        # Cancel the running ACE-Step task to free GPU
                        try:
                            cancel_resp = await self.session.post(
                                f"{job.endpoint}/cancel_task",
                                json={"task_id": job.acestep_task_id},
                                timeout=ClientTimeout(total=5),
                            )
                            if cancel_resp.status == 200:
                                self.logger.info(f"ACE-Step job {job.id}: cancelled running task")
                                self._requeue_preempted_acestep_job(job)
                                return
                            self.logger.warning(
                                f"ACE-Step cancel returned {cancel_resp.status} "
                                f"(task may have already finished; retaining running ownership)"
                            )
                        except Exception as e:
                            self.logger.warning(
                                f"ACE-Step job {job.id}: cancel request failed ({e}) "
                                f"— retaining running ownership"
                            )

                # Check LLM relief mid-job
                if llm.queued_requests >= LLM_RELIEF_THRESHOLD:
                    self.logger.info(
                        f"ACE-Step job {job.id}: LLM pressure mid-poll "
                        f"({llm.queued_requests} queued) — will check relief after this job"
                    )

                # ── Method 1: query_result API ──
                try:
                    async with self.session.post(
                        f"{job.endpoint}/query_result",
                        json={"task_id_list": [acestep_task_id]},
                        timeout=ClientTimeout(total=10),
                    ) as resp:
                        result = await resp.json()
                        data = result.get("data", [])

                        if isinstance(data, list) and data:
                            for item in data:
                                if item.get("audio_path"):
                                    await self._acestep_job_complete(
                                        job, item["audio_path"]
                                    )
                                    return
                                if (
                                    item.get("status") == 2
                                    or item.get("stage") == "failed"
                                    or item.get("error")
                                ):
                                    await self._acestep_job_failed(
                                        job,
                                        str(item.get("error") or "ACE-Step backend reported failed"),
                                    )
                                    return
                        elif isinstance(data, dict) and data.get("audio_path"):
                            await self._acestep_job_complete(
                                job, data["audio_path"]
                            )
                            return
                        elif isinstance(data, dict) and (
                            data.get("status") == 2
                            or data.get("stage") == "failed"
                            or data.get("error")
                        ):
                            await self._acestep_job_failed(
                                job,
                                str(data.get("error") or "ACE-Step backend reported failed"),
                            )
                            return
                except Exception as e:
                    self.logger.debug(f"ACE-Step poll error (will retry): {e}")

                # ── Method 2: Filesystem fallback ──
                new_files = self._find_new_audio(job.audio_dir, audio_before, audio_ext)
                if new_files:
                    # New audio file appeared — assume it's ours
                    audio_file = new_files[-1]  # Latest file
                    audio_path = f"api_audio/{audio_file}"
                    self.logger.info(
                        f"ACE-Step job {job.id}: detected new audio file "
                        f"via filesystem: {audio_file} "
                        f"(query_result returned empty)"
                    )
                    await self._acestep_job_complete(job, audio_path)
                    return

            # Timeout
            timeout_error = f"ACE-Step job timed out after {max_wait}s"
            self.logger.warning(f"ACE-Step job {job.id}: timed out after {max_wait}s")
            await self._acestep_job_failed(job, timeout_error)
            return

        except Exception as e:
            self.logger.error(f"ACE-Step job {job.id}: error — {e}")
            await self._acestep_job_failed(job, str(e))
            return

    def _requeue_preempted_acestep_job(self, job: AceStepJob) -> None:
        """Return an acknowledged-preempted ACE task to one durable queued slot."""
        job.status = "queued"
        job.started_at = None
        job.acestep_task_id = None
        job.preempted = True
        self._acestep_queue = [queued for queued in self._acestep_queue if queued.id != job.id]
        self._acestep_queue.insert(0, job)
        self._remove_from_gpu_queue(job)
        self._route_to_gpu_queue(job)
        if job_tracker:
            try:
                job_tracker.update_status(job.id, "queued", preempted=True)
            except Exception as tracker_error:
                self.logger.error(
                    "ACE-Step job %s: durable preemption update failed: %s",
                    job.id,
                    tracker_error,
                )
        self.total_preemptions += 1
        self._current_backend = None

    async def _acestep_job_cancelled(self, job: AceStepJob, error: str = "Cancelled by user"):
        """Terminalize a cancelled ACE task only after backend acknowledgement."""
        if job.status in ("completed", "failed", "cancelled"):
            return
        job.status = "cancelled"
        job.result = {"error": error}
        job.finished_at = time.time()
        self._acestep_queue = [queued for queued in self._acestep_queue if queued.id != job.id]
        self._remove_from_gpu_queue(job)
        if job_tracker:
            try:
                job_tracker.update_status(job.id, "cancelled", error=error)
            except Exception as tracker_error:
                self.logger.error(
                    "ACE-Step job %s: durable cancellation update failed: %s",
                    job.id,
                    tracker_error,
                )
        if job.bundle_name:
            unloaded = await _teardown_acestep_bundle(
                job.bundle_name,
                reason=f"ace-terminal-cancel:{job.id}",
            )
            if not unloaded:
                job.result.setdefault(
                    "cleanup_error",
                    f"terminal bundle teardown failed: {job.bundle_name}",
                )
                self.logger.error(
                    "ACE-Step job %s: terminal teardown failed for bundle %s",
                    job.id,
                    job.bundle_name,
                )
        self._current_backend = None

    async def cancel_acestep_queued(self, job: AceStepJob) -> bool:
        """Cancel a queued ACE job locally before it has a backend task."""
        if job.backend != "acestep" or job.status != "queued" or job.acestep_task_id:
            return False
        await self._acestep_job_cancelled(job)
        return True

    async def cancel_acestep_running(self, job: AceStepJob) -> bool:
        """Cancel one running ACE task using its service-specific endpoint."""
        if job.backend != "acestep" or job.status != "running" or not job.acestep_task_id:
            return False
        try:
            async with self.session.post(
                f"{job.endpoint}/cancel_task",
                json={"task_id": job.acestep_task_id},
                timeout=ClientTimeout(total=10),
            ) as response:
                if not 200 <= response.status < 300:
                    self.logger.warning(
                        "ACE-Step job %s: backend cancel rejected with HTTP %s",
                        job.id,
                        response.status,
                    )
                    return False
        except Exception as error:
            self.logger.warning("ACE-Step job %s: backend cancel failed: %s", job.id, error)
            return False
        await self._acestep_job_cancelled(job)
        return True

    async def _acestep_job_failed(self, job: AceStepJob, error: str):
        """Terminalize a failed ACE task and release every scheduler ownership."""
        if job.status in ("completed", "failed", "cancelled"):
            return
        job.status = "failed"
        job.result = {"error": error}
        job.finished_at = time.time()
        self.total_jobs_failed += 1
        self._acestep_queue = [queued for queued in self._acestep_queue if queued.id != job.id]
        self._remove_from_gpu_queue(job)
        if job_tracker:
            try:
                job_tracker.update_status(job.id, "failed", error=error)
            except Exception as tracker_error:
                self.logger.error(
                    "ACE-Step job %s: durable failure update failed: %s",
                    job.id,
                    tracker_error,
                )
        self.logger.error("ACE-Step job %s: terminal backend failure — %s", job.id, error)
        if job.bundle_name:
            unloaded = await _teardown_acestep_bundle(
                job.bundle_name,
                reason=f"ace-terminal-failed:{job.id}",
            )
            if not unloaded:
                job.result.setdefault(
                    "cleanup_error",
                    f"terminal bundle teardown failed: {job.bundle_name}",
                )
                self.logger.error(
                    "ACE-Step job %s: terminal teardown failed for bundle %s",
                    job.id,
                    job.bundle_name,
                )
        self._current_backend = None

    async def _acestep_job_complete(self, job: AceStepJob, audio_path: str):
        """Mark ACE-Step job as complete with the audio file."""
        artifact_ext = os.path.splitext(str(audio_path).split("?", 1)[0])[1]
        artifact_fmt = artifact_ext.lower().lstrip(".")
        if artifact_fmt == "wave":
            artifact_fmt = "wav"
        audio_fmt = artifact_fmt or job.payload.get("audio_format", "flac")
        job.status = "completed"
        job.result = {"audio_path": audio_path, "audio_format": audio_fmt}
        job.finished_at = time.time()
        self.total_jobs_completed += 1
        self._acestep_queue = [queued for queued in self._acestep_queue if queued.id != job.id]
        self._remove_from_gpu_queue(job)
        if job_tracker:
            try:
                job_tracker.update_status(job.id, "completed", result=job.result)
            except Exception as tracker_error:
                self.logger.error(
                    "ACE-Step job %s: durable completion update failed: %s",
                    job.id,
                    tracker_error,
                )
        elapsed = job.finished_at - job.started_at
        self.logger.info(f"ACE-Step job {job.id}: completed in {elapsed:.1f}s")
        if job.callback_url:
            await self._send_callback(job)
        # A bundle-owned ACE job must release its configured service before the
        # generic idle-restore path starts Gemma. The candidate unit is not the
        # legacy ``acestep-api.service`` restarted by _restart_acestep_for_restore.
        # _unload_bundle is authoritative: it stops the configured unit, removes
        # primary ownership, and releases reservation-only linked members.
        if job.bundle_name:
            self.logger.info(
                "ACE-Step job %s: terminal teardown of bundle %s before idle restore",
                job.id,
                job.bundle_name,
            )
            unloaded = await _teardown_acestep_bundle(
                job.bundle_name,
                reason=f"ace-terminal-completed:{job.id}",
            )
            if not unloaded:
                # Preserve the completed artifact but retain a visible lifecycle
                # failure; the restore fence prevents an unsafe idle-LLM race.
                job.result["cleanup_error"] = (
                    f"terminal bundle teardown failed: {job.bundle_name}"
                )
                self.logger.error(
                    "ACE-Step job %s: terminal teardown failed for bundle %s; "
                    "idle restore remains blocked",
                    job.id,
                    job.bundle_name,
                )
        self._current_backend = None

    async def _send_callback(self, job: AceStepJob):
        """POST result to job's callback URL."""
        try:
            async with self.session.post(
                job.callback_url,
                json={
                    "job_id": job.id,
                    "type": "music-acestep",
                    "status": "complete",
                    "audio_path": job.result.get("audio_path"),
                    "audio_format": job.result.get("audio_format"),
                    "payload": {k: v for k, v in job.payload.items() if k != "lyrics"},
                },
                timeout=ClientTimeout(total=10),
            ) as cb_resp:
                self.logger.info(f"ACE-Step callback for {job.id}: {cb_resp.status}")
        except Exception as e:
            self.logger.error(f"ACE-Step callback error for {job.id}: {e}")

    def verify_state_consistency(self) -> int:
        """Compare GpuBundleState fields vs scheduler._gpu_state dict.

        Phase 0 invariant: GpuBundleState is the single source of truth; the
        legacy scheduler._gpu_state dict is a read-only mirror. This method
        detects any direct write to the dict that bypassed the setters.

        Returns the count of divergent fields. Logs a WARNING for each
        divergence (caller can convert count to health-check signal).
        """
        divergences = 0
        # _gpu_states is the module-level dict of GpuBundleState instances.
        _gpu_states = globals().get("_gpu_states", {})
        for gpu_id, bundle_state in _gpu_states.items():
            legacy = self._gpu_state.get(gpu_id)
            if not legacy:
                continue  # legacy may not be initialized yet
            checks = [
                ("evicting", bundle_state.evicting, legacy.get("evicting", False)),
                ("draining", bundle_state.draining, legacy.get("draining", False)),
                (
                    "loaded_bundles",
                    list(bundle_state.loaded_bundles),
                    list(legacy.get("loaded_bundles", [])),
                ),
                (
                    "current_priority",
                    bundle_state.current_priority,
                    legacy.get("current_priority", 0),
                ),
            ]
            for field_name, bs_value, legacy_value in checks:
                if bs_value != legacy_value:
                    self.logger.warning(
                        f"[state-consistency] {gpu_id}.{field_name}: "
                        f"bundle_state={bs_value!r} vs legacy={legacy_value!r}"
                    )
                    divergences += 1
        if divergences == 0:
            self.logger.info(
                "[state-consistency] OK - all GPU states consistent"
            )
        return divergences


# ── VRAM Lifecycle Manager ──────────────────────────────────────────

class VRAMLifecycleManager:
    """Manages the GPU state machine and default LLM tenant lifecycle.

    GPU state machine:
      LLM_LOADED → DRAINING → GPU_WORK → RESTORING → LLM_LOADED
      GPU_WORK → LLM_RELIEF → DRAINING → GPU_WORK

    Qwen3.6 is the default GPU tenant. ComfyUI and ACE-Step evict it
    when they need the GPU, and it's restored when they're done.
    """

    def __init__(self, session: ClientSession, logger: logging.Logger):
        self.session = session
        self.logger = logger
        self.gpu_state = GpuState.LLM_LOADED
        self._llm_evicted = False
        # C3 BUGFIX: per-GPU eviction flag — eviction is per-GPU,
        # not global. A second call to evict a different GPU must
        # not short-circuit because GPU A was already evicted.
        self._gpu_evicted: dict[str, bool] = {}
        self._comfyui_stopped = False
        # ComfyUI idle auto-stop (VRAM conservation)
        self._comfyui_idle_since: float | None = None
        self._comfyui_auto_stopped: bool = False
        self._evict_lock = asyncio.Lock()

    def mark_llm_evicted(self, value: bool, source: str = "unknown") -> None:
        """Single-source setter for self._llm_evicted.

        No-op when value is unchanged (avoids spurious event noise).
        """
        value = bool(value)
        if value == self._llm_evicted:
            return
        old = self._llm_evicted
        self._llm_evicted = value
        if self.logger:
            self.logger.info(
                f"VRAM: _llm_evicted {old} -> {self._llm_evicted} (source={source})"
            )

    def status(self) -> dict:
        runtime = _get_loaded_runtime_snapshot()
        configured_idle_service = _get_idle_service_name()
        return {
            "gpu_state": self.gpu_state.value,
            "llm_evicted": self._llm_evicted,
            # Legacy alias: this is the configured/default idle service unit,
            # not proof that the unit is currently loaded.
            "llm_service": configured_idle_service,
            "configured_idle_service": configured_idle_service,
            "loaded_runtime_services": runtime["services"],
            "loaded_runtime_bundles": runtime["bundles"],
            "llm_service_semantics": "configured_idle_service_legacy_alias",
            "comfyui_stopped": self._comfyui_stopped,
            "comfyui_auto_stopped": self._comfyui_auto_stopped,
            "comfyui_idle_seconds": (
                time.time() - self._comfyui_idle_since
                if self._comfyui_idle_since else 0
            ),
        }

    # ── Drain before evict ─────────────────────────────────────────

    async def drain_llm(self, timeout: float = DRAIN_TIMEOUT) -> bool:
        """Wait for active LLM requests to finish before evicting.

        Returns True if all requests drained, False if timeout.
        New LLM requests are already queued (not forwarded) because
        the proxy checks _llm_healthy which is set to False during drain.
        """
        if llm.active_requests == 0:
            self.logger.info("Drain: no active LLM requests — immediate")
            # Mark unhealthy so new requests queue instead of forwarding
            llm.update_health(False)
            return True

        self.logger.info(
            f"Drain: waiting for {llm.active_requests} active LLM request(s) "
            f"(timeout={timeout}s)"
        )
        # Mark unhealthy so new requests queue instead of forwarding
        llm.update_health(False)

        start = time.time()
        while time.time() - start < timeout:
            if llm.active_requests == 0:
                self.logger.info(
                    f"Drain: all requests finished in {time.time() - start:.1f}s"
                )
                return True
            self.logger.debug(f"Drain: {llm.active_requests} still active")
            await asyncio.sleep(2)

        self.logger.warning(
            f"Drain: timeout after {timeout}s — {llm.active_requests} still active"
        )
        return False

    # ── LLM evict/restore ──────────────────────────────────────────

    async def evict_llm(self, reason: str = "gpu_work_start", target_gpu: str = None,
                        skip_bundle_name: str | None = None,
                        admission_authorized: bool = False) -> bool:
        """Stop ALL GPU-using LLM services to free VRAM.

        BUGFIX (2026-05-20):
        1. Previously only stopped the idle_service (gemma, CPU-only).
           Now stops ALL services with HIP_VISIBLE_DEVICES=0 to free VRAM.
        2. systemctl stop sometimes leaves orphan processes (PyTorch cache).
           Force-kill by port if systemctl doesn't free the port.
        3. Restart acestep-api after eviction to clear PyTorch VRAM cache.

        MAINTENANCE MODE: Skips eviction entirely — LLM stays loaded.
        """
        if bundle_lifecycle_controller is None:
            # A direct or queue-owned eviction must never fall through to the
            # legacy systemd implementation when the lifecycle owner is gone.
            # Queue admission still passes the explicit authorization flag,
            # but controller availability remains a hard prerequisite here.
            self.logger.error(
                "VRAM: refusing LLM eviction without lifecycle controller (%s)",
                reason,
            )
            return False
        if not admission_authorized:
            return await _run_standalone_llm_eviction(
                self,
                reason=reason,
                target_gpu=target_gpu,
                skip_bundle_name=skip_bundle_name,
            )
        config = _load_services_config()
        if _maintenance_mode_enabled(config.get("scheduling", {})):
            self.logger.info(f"VRAM: Maintenance mode — skipping LLM eviction ({reason})")
            return False

        # ── Phase 2: Per-GPU priority-based eviction ─────────────────
        # If target_gpu is specified, check if the GPU's current tenant
        # has pending work or is higher priority than idle.
        if target_gpu and target_gpu in scheduler._gpu_state:
            gpu_st = scheduler._gpu_state[target_gpu]
            idle_bundle = _get_idle_bundle(target_gpu)
            idle_priority = idle_bundle.get("priority", 0) if idle_bundle else 0

            # If the GPU is already draining, wait for it to finish
            if gpu_st.get("draining"):
                self.logger.info(
                    f"VRAM: GPU {target_gpu} already draining — waiting for drain to complete"
                )
                gpu_bundle_state = _get_gpu_state(target_gpu)
                await gpu_bundle_state.wait_drain(timeout=DRAIN_TIMEOUT)
                gpu_st["draining"] = False

            # Direct callers preserve the conservative priority fence.  The
            # linked-bundle admission transaction has already fenced every
            # target GPU, drained the relevant logical group, and selected a
            # real durable head job; it must not re-interpret an idle/static
            # priority as permanent residency.
            if not admission_authorized and gpu_st.get("current_priority", 0) > idle_priority:
                pending = scheduler._get_pending_for_gpu(target_gpu)
                higher = [j for j in pending if j.priority > gpu_st["current_priority"]]
                if not higher:
                    # Current work is higher priority — don't evict, just return
                    self.logger.info(
                        f"VRAM: GPU {target_gpu} has higher-priority bundle "
                        f"(priority={gpu_st['current_priority']}) — not evicting"
                    )
                    return False

        async with self._evict_lock:
            # C3 BUGFIX: resolve work_gpu BEFORE the early-return so we can
            # check the per-GPU eviction flag, not the global one. (Eviction
            # is per-GPU: evicting GPU A must not block eviction of GPU B.)
            work_gpu = (
                target_gpu
                or (getattr(self, "_evicted_gpu_id", None) or None)
            )
            # BUGFIX: _current_backend lives on GPUScheduler, not on
            # VRAMLifecycleManager. Use getattr() to be defensive.
            if not work_gpu and getattr(self, '_current_backend', None):
                # Try to infer from the active backend's service config.
                _cfg = _load_services_config()
                _svc_map = _cfg.get("services", {})
                _cur = self._current_backend
                _prefix = _cur.split("-")[0] if "-" in _cur else _cur
                for _sk, _sc in _svc_map.items():
                    if (
                        _sc.get("type") == "generation_backend"
                        and _sc.get("systemd_unit", "").startswith(_prefix)
                    ):
                        work_gpu = _sc.get("gpu_id")
                        break
            if not work_gpu:
                # Fallback: assume work is on the primary GPU (gpu_primary)
                work_gpu = "gpu_primary"

            if self._gpu_evicted.get(work_gpu):
                # Phase 5.2.50: stale-flag fix. Verify against actual VRAM
                # before short-circuiting. The flag can be set during a prior
                # crash-detection cycle that didn't actually free VRAM.
                # If GPU is still occupied, clear the stale flag and proceed
                # with real eviction.
                try:
                    vram_data = await _poll_vram()
                    matched = _get_vram_entry_for_gpu(vram_data, work_gpu)
                    if matched and matched.get("vram_used_mib", 0) > 2048:
                        self.logger.warning(
                            f"VRAM: stale _gpu_evicted[{work_gpu}]=True "
                            f"but {work_gpu} still using "
                            f"{matched.get('vram_used_mib')} MiB — "
                            f"clearing flag and proceeding with eviction"
                        )
                        self._gpu_evicted[work_gpu] = False
                except Exception as e:
                    self.logger.debug(f"evict_llm stale-flag check failed: {e}")

                if self._gpu_evicted.get(work_gpu):
                    self.logger.info(
                        f"VRAM: LLM already evicted on GPU {work_gpu} ({reason})"
                    )
                    return True

            self.logger.info(f"VRAM: Evicting GPU LLM services on {work_gpu or 'unknown'} ({reason})")
            self._evicted_gpu_id = work_gpu  # Track for targeted restore

            # BUGFIX (2026-05-20b): Dynamic service discovery.
            # Previous code hardcoded specific service names
            # and missed gemma-e4b-pi (port 8101, 7.3 GB VRAM!) → OOM.
            # Now we stop ALL services with priority < 10 (LLMs/assistants).
            config = _load_services_config()
            svc_map = config.get("services", {})
            gpu_services = []  # (unit_name, port, svc_key)
            for svc_key, svc_cfg in svc_map.items():
                if not svc_cfg.get("enabled", True):
                    continue
                if svc_cfg.get("priority", 99) >= 10:
                    continue  # Skip GPU work backends (ComfyUI=10, ACE-Step=20)
                if svc_key == "gpu-manager":
                    continue  # NEVER stop ourselves!
                if svc_cfg.get("cpu_only"):
                    continue  # Skip CPU-only services (gemma-vision)
                # MULTI-GPU FIX: Only stop services on the same GPU as the work
                svc_gpu = svc_cfg.get("gpu_id", "gpu_primary")  # Default to primary GPU
                if svc_gpu and work_gpu and svc_gpu != work_gpu:
                    self.logger.info(f"VRAM: Skipping {svc_key} (on {svc_gpu}, work on {work_gpu})")
                    continue
                unit = svc_cfg.get("systemd_unit", f"{svc_key}.service")
                port = svc_cfg.get("port", 0)
                gpu_services.append((unit, port, svc_key))

            # Phase 3: Use _unload_bundle to stop bundles on the target GPU
            bundles = _resolve_bundles()
            gpu_bundles = [
                (name, b) for name, b in bundles.items()
                if b.get("gpu_id") == work_gpu
            ]
            # Phase 5.1.6: skip the bundle we're about to (re)load.
            # Without this, _evict_then_load_bundle races itself:
            # unload stops the service, then _load_bundle starts it,
            # and the start can be killed by a queued stop from the
            # unload path. The bundle load then times out waiting for
            # a port that keeps getting killed.
            if skip_bundle_name is not None:
                before = len(gpu_bundles)
                gpu_bundles = [
                    (n, b) for n, b in gpu_bundles if n != skip_bundle_name
                ]
                if before != len(gpu_bundles):
                    self.logger.info(
                        f"VRAM: skip_bundle_name={skip_bundle_name!r} "
                        f"({before} -> {len(gpu_bundles)} bundles to unload)"
                    )
            if gpu_bundles:
                self.logger.info(
                    f"VRAM: Unloading {len(gpu_bundles)} bundle(s) on GPU {work_gpu}: "
                    f"{[n for n, _ in gpu_bundles]}"
                )
                for bundle_name, _bundle in gpu_bundles:
                    await _unload_bundle(bundle_name)
            else:
                # Fallback: no bundles defined — stop services directly
                self.logger.info(
                    f"VRAM: No bundles for GPU {work_gpu}, "
                    f"stopping {len(gpu_services)} service(s) directly"
                )
                for unit, port, svc_key in gpu_services:
                    try:
                        if not await _drain_combined_gemma_member_before_stop(svc_key):
                            return False
                        # Phase 5.1.5: this stop is intentional (we are
                        # evicting the LLM to free VRAM). Stamp it so the
                        # Supervisor doesn't tear down an unrelated pool
                        # whose service briefly looked unhealthy during
                        # the cascade.
                        if event_bus is not None:
                            event_bus.mark_planned_stop(svc_key)
                        result = await asyncio.create_subprocess_exec(
                            "sudo", "systemctl", "stop", unit,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                        )
                        await result.wait()
                        self.logger.info(f"VRAM: systemctl stop {unit}")
                    except Exception as e:
                        self.logger.warning(f"VRAM: Failed to stop {unit}: {e}")
                    finally:
                        # Phase 5.2.6: caller-side clear. Once the
                        # stop returns (success or failure), release
                        # the supervisor's deferral so a real crash
                        # is not silently swallowed.
                        if event_bus is not None:
                            event_bus.clear_planned_stop(svc_key)

            # Wait for ports to free, force-kill if needed
            # (Still needed for services not managed by bundles, or stubborn processes)
            for unit, port_num, svc_name in gpu_services:
                if not port_num:
                    continue
                freed = await self._wait_for_port_free(timeout=15, port=port_num)
                if freed:
                    self.logger.info(f"VRAM: {svc_name} port {port_num} freed")
                else:
                    # BUGFIX (2026-05-20c): Must use sudo to kill system service processes.
                    # gpu-manager runs as operator, service processes run as root.
                    # Sequence: stop → kill → stop (to block Restart=on-failure) → reset-failed.
                    # Without the second stop, Restart=on-failure (default 100ms) would restart
                    # the service before we can reset-failed.
                    self.logger.warning(f"VRAM: Force-killing {svc_name} (unit={unit}, port {port_num})")
                    try:
                        # Step 1: SIGKILL the process through systemd
                        kill_result = await asyncio.create_subprocess_exec(
                            "sudo", "systemctl", "kill", unit,
                            "--signal=SIGKILL",
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                        )
                        await kill_result.wait()
                        # Step 2: Immediately issue 'stop' to block Restart=on-failure trigger.
                        # systemd won't restart a stopped service even if Restart= is set.
                        stop_result = await asyncio.create_subprocess_exec(
                            "sudo", "systemctl", "stop", unit,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                        )
                        await stop_result.wait()
                        await asyncio.sleep(1)
                        # Step 3: Clear the failed state so future starts work cleanly
                        reset_result = await asyncio.create_subprocess_exec(
                            "sudo", "systemctl", "reset-failed", unit,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                        )
                        await reset_result.wait()
                        self.logger.info(f"VRAM: {svc_name} killed and blocked from restart")
                    except Exception:
                        pass

            # BUGFIX (2026-05-20c): Wait for VRAM to actually free before starting ACE-Step.
            # Even after fuser -k, the GPU driver takes a few seconds to reclaim VRAM.
            # ACE-Step needs ~10 GB, so we need VRAM used to drop below ~4 GB.
            self.logger.info("VRAM: Waiting for GPU VRAM to free after service stops...")
            vram_freed = await self._wait_for_vram_below(
                target_mib=4096, timeout=30, gpu_id=work_gpu
            )
            if not vram_freed:
                self.logger.warning("VRAM: GPU VRAM did not free within timeout — proceeding anyway")

            # Cache ownership belongs to the drained runtime. Never start a
            # retired ACE engine as a side effect of switching other services.

            self.mark_llm_evicted(True, source="evict_llm")
            # C3 BUGFIX: also mark this GPU as evicted per-GPU so the
            # early-return check in evict_llm knows about it, and so a
            # future call for a DIFFERENT GPU isn't short-circuited.
            if work_gpu:
                self._gpu_evicted[work_gpu] = True
            llm.update_health(False)
            # Phase 2/Phase 0: Update per-GPU state after eviction.
            # GpuBundleState is the single source of truth — setters sync to
            # the legacy scheduler._gpu_state dict automatically.
            if work_gpu:
                bundle_state = _get_gpu_state(work_gpu)
                bundle_state.loaded_bundle = None
                bundle_state.bundle_priority = 0
                bundle_state.set_evicting(True, source="evict_llm")
                bundle_state.set_draining(False, source="evict_llm")
                bundle_state.set_loaded_bundles([], source="evict_llm")
                bundle_state.set_current_priority(0, source="evict_llm")
            self.logger.info(f"VRAM: LLM evicted ({reason}) — GPU {work_gpu} cleared")
            return True


    async def restore_llm(self, reason: str = "gpu_work_done") -> bool:
        """Restart ALL GPU LLM services after GPU work completes."""
        async with _RestoreAdmissionGuard(self):
            if not self._llm_evicted:
                self.logger.info(f"VRAM: LLM not evicted, skip restore ({reason})")
                return True

            self.logger.info(f"VRAM: Restoring all GPU LLM services ({reason})")

            # This call is made by the scheduler-owned restoration
            # transaction. Its own guard must not deadlock the nested VRAM
            # restore, while all real generation/admission blockers remain
            # authoritative.
            release_blockers = _generation_release_blockers(
                ignore_scheduler_restoring=True
            )
            if release_blockers:
                self.logger.info(
                    "VRAM: restore deferred until generation release: %s",
                    ",".join(release_blockers),
                )
                return False

            # The generic release fence above established that no generation
            # owner remains. Do not wait on a hard-coded backend port here:
            # an unrelated stopped service would otherwise add a full timeout
            # to every idle restore.
            await asyncio.sleep(2)

            # MULTI-GPU FIX: restore every configured per-GPU idle bundle,
            # not only the most recently evicted GPU.  Dual-GPU generation
            # paths (Krea2 = comfyui on gpu_primary + encoder reservation on
            # gpu_secondary) call evict_llm once per target GPU; _evicted_gpu_id is a
            # scalar and can only remember one of them.  Restoring only that
            # GPU left the other idle service to crash-recovery, producing a
            # long unhealthy window and stale scheduler state.  The user's
            # intended post-generation state is the combined Gemma endpoint,
            # so bring all configured idle GPU services back atomically here.
            config = _load_services_config()
            svc_map = config.get("services", {})
            restored_gpus: set[str] = set()
            restored_names: list[str] = []
            restored_member_names: list[str] = []
            healthy = True

            idle_entries = _get_all_idle_services()
            if idle_entries:
                for idle_entry in idle_entries:
                    idle_gpu = idle_entry.get("gpu_id")
                    idle_svc_name = idle_entry.get("service_name")
                    idle_bundle = _get_idle_bundle(idle_gpu) if idle_gpu else None
                    if idle_bundle:
                        idle_name = idle_bundle.get("bundle_name", idle_svc_name or "idle")
                        self.logger.info(
                            f"VRAM: Restoring idle bundle '{idle_name}' on GPU {idle_gpu}"
                        )
                        load_ok = await _run_bundle_transition(
                            idle_name,
                            lambda: _load_bundle(
                                idle_name, timeout=LLM_RESTORE_TIMEOUT
                            ),
                            desired_state=BundleDesiredState.RUNNING,
                            reason=f"restore-llm:{reason}",
                        )
                        if load_ok:
                            self.logger.info(
                                f"VRAM: Idle bundle '{idle_name}' restored and healthy"
                            )
                            if idle_gpu:
                                restored_gpus.add(idle_gpu)
                            restored_names.append(idle_name)
                            if idle_svc_name:
                                restored_member_names.append(idle_svc_name)
                                if not await _rejoin_combined_gemma_member_after_start(
                                    idle_svc_name, timeout=LLM_RESTORE_TIMEOUT
                                ):
                                    healthy = False
                        else:
                            healthy = False
                            self.logger.warning(
                                f"VRAM: Idle bundle '{idle_name}' not healthy "
                                f"after {LLM_RESTORE_TIMEOUT}s"
                            )
                    else:
                        # Fallback: no idle bundle declared for this entry;
                        # start its unit directly and probe its configured port.
                        unit = idle_entry.get("systemd_unit") or ""
                        port = idle_entry.get("port") or 0
                        if not unit:
                            healthy = False
                            self.logger.warning(
                                f"VRAM: No idle bundle/unit for GPU {idle_gpu} "
                                f"service {idle_svc_name}"
                            )
                            continue
                        try:
                            result = await asyncio.create_subprocess_exec(
                                "systemctl", "start", unit,
                                stdout=asyncio.subprocess.PIPE,
                                stderr=asyncio.subprocess.PIPE,
                            )
                            await result.wait()
                            self.logger.info(f"VRAM: Started {unit}")
                            probe_ok = await _probe_health_inline(
                                port, health_path=(svc_map.get(idle_svc_name, {}) or {}).get("health_path") or "/health",
                                timeout=2.0,
                            )
                            if probe_ok:
                                if idle_gpu:
                                    restored_gpus.add(idle_gpu)
                                restored_names.append(idle_svc_name or unit)
                                if idle_svc_name:
                                    restored_member_names.append(idle_svc_name)
                                    if not await _rejoin_combined_gemma_member_after_start(
                                        idle_svc_name, timeout=LLM_RESTORE_TIMEOUT
                                    ):
                                        healthy = False
                            else:
                                healthy = False
                        except Exception as e:
                            healthy = False
                            self.logger.warning(f"VRAM: Failed to start {unit}: {e}")
            else:
                # Last-resort legacy fallback if scheduling.idle_services is
                # missing: preserve the previous dynamic service discovery.
                gpu_services = []
                for svc_key, svc_cfg in svc_map.items():
                    if not svc_cfg.get("enabled", True):
                        continue
                    if svc_cfg.get("priority", 99) >= 10:
                        continue
                    if svc_key == "gpu-manager" or svc_cfg.get("cpu_only"):
                        continue
                    unit = svc_cfg.get("systemd_unit", f"{svc_key}.service")
                    port = svc_cfg.get("port", 0)
                    gpu_services.append((unit, port, svc_key))
                self.logger.info(
                    f"VRAM: No idle_services map, starting {len(gpu_services)} legacy service(s) directly"
                )
                for svc, svc_port, svc_key in gpu_services:
                    if _combined_gemma_broker_owns_service(
                        svc_key, svc_map.get(svc_key, {}) or {}
                    ):
                        restored_member_names.append(svc_key)
                    try:
                        result = await asyncio.create_subprocess_exec(
                            "systemctl", "start", svc,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                        )
                        await result.wait()
                        self.logger.info(f"VRAM: Started {svc}")
                    except Exception as e:
                        healthy = False
                        self.logger.warning(f"VRAM: Failed to start {svc}: {e}")
                healthy = healthy and await self._wait_for_llm_healthy(timeout=LLM_RESTORE_TIMEOUT)
                if healthy:
                    for member_name in restored_member_names:
                        if not await _rejoin_combined_gemma_member_after_start(
                            member_name, timeout=LLM_RESTORE_TIMEOUT
                        ):
                            healthy = False

            self.mark_llm_evicted(False, source="restore_llm")
            # Clear every per-GPU eviction flag we restored.  Older code only
            # cleared the scalar _evicted_gpu_id, which left the other GPU in a
            # dual-GPU generation path looking evicted/stale until a later
            # watchdog pass.
            for restored_gpu in restored_gpus:
                self._gpu_evicted.pop(restored_gpu, None)

            # Phase 2/Phase 0: Update per-GPU state after restore. _load_bundle
            # already stamps most of this, but doing it explicitly here keeps
            # vram.restore_llm() as a complete state transition and repairs
            # stale state from reservation-only bundles like krea2-encoder.
            for restored_gpu in restored_gpus:
                idle_bundle = _get_idle_bundle(restored_gpu)
                idle_name = idle_bundle.get("bundle_name", "idle") if idle_bundle else "idle"
                idle_priority = idle_bundle.get("priority", 1) if idle_bundle else 1
                bundle_state = _get_gpu_state(restored_gpu)
                bundle_state.loaded_bundle = idle_name
                bundle_state.bundle_priority = idle_priority
                bundle_state.state = "loaded"
                bundle_state.set_evicting(False, source="restore_llm")
                bundle_state.set_draining(False, source="restore_llm")
                bundle_state.set_loaded_bundles([idle_name], source="restore_llm")
                bundle_state.set_current_priority(idle_priority, source="restore_llm")
                self.logger.info(
                    f"VRAM: GPU {restored_gpu} restored with idle bundle "
                    f"'{idle_name}' (priority={idle_priority})"
                )
            self.logger.info(
                f"VRAM: Restored idle bundle set: {restored_names}"
            )
            return healthy

    async def _comfyui_systemd_state(self) -> dict:
        """Return the authoritative systemd state per ComfyUI systemd unit.

        Slice B: previously this returned a single string naming only the
        generic ``comfyui.service``. That allowed the scheduler to
        conclude "ComfyUI is stopped" while ``comfyui-qwen.service``
        was still active — the Krea/Qwen serialization bug. The helper
        now reports BOTH the Krea and Qwen units so reconciliation and
        the running-state commit can distinguish "both off" from
        "qwen active, krea inactive".

        Returns a dict like::

            {
                "comfyui.service": "inactive" | "active" | ...,
                "comfyui-qwen.service": "inactive" | "active" | ...,
            }
        """
        config = _load_services_config() or {}
        services = config.get("services") or {}
        krea_unit = str(
            (services.get("comfyui") or {}).get("systemd_unit")
            or "comfyui.service"
        )
        qwen_unit = str(
            (services.get("comfyui-qwen") or {}).get("systemd_unit")
            or "comfyui-qwen.service"
        )
        units = tuple(dict.fromkeys((krea_unit, qwen_unit)))
        states: dict[str, str] = {}
        for unit in units:
            try:
                proc = await asyncio.create_subprocess_exec(
                    "systemctl", "is-active", unit,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.DEVNULL,
                )
                stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
                state = stdout.decode(errors="replace").strip().lower()
                states[unit] = state or "unknown"
            except Exception as exc:
                self.logger.warning(
                    f"VRAM: unable to read ComfyUI systemd state for {unit}: {exc}"
                )
                states[unit] = "unknown"
        # Keep canonical legacy keys as read-only aliases for older status
        # consumers; lifecycle authority remains the resolved registry unit.
        states.setdefault("comfyui.service", states.get(krea_unit, "unknown"))
        states.setdefault("comfyui-qwen.service", states.get(qwen_unit, "unknown"))
        return states

    @staticmethod
    def _checked_comfyui_runtime_configured() -> bool:
        """Return whether ComfyUI is bound to a checked host runtime."""
        config = _load_services_config() or {}
        bundles = config.get("bundles") or {}
        for name in ("comfyui", "qwen-edit-dualgpu"):
            bundle = bundles.get(name) if isinstance(bundles, dict) else None
            if isinstance(bundle, dict) and bundle.get("runtime_instance") and bundle.get(
                "runtime_profile"
            ):
                return True
        return False

    @staticmethod
    def _configured_comfyui_unit(service_name: str) -> str:
        config = _load_services_config() or {}
        services = config.get("services") or {}
        fallback = {
            "comfyui": "comfyui.service",
            "comfyui-qwen": "comfyui-qwen.service",
        }.get(service_name, f"{service_name}.service")
        return str((services.get(service_name) or {}).get("systemd_unit") or fallback)

    @staticmethod
    def _comfyui_unit_state(states: dict[str, str], unit: str) -> str:
        """Return one exact ComfyUI unit state from an authoritative snapshot.

        A string is accepted only as legacy Krea input for older internal test
        doubles; live probes always return the per-unit mapping.
        """
        if isinstance(states, str):
            return states.lower() if unit == "comfyui.service" else "unknown"
        if not isinstance(states, dict):
            return "unknown"
        return str(states.get(unit, "unknown") or "unknown").lower()

    @classmethod
    def _all_comfyui_units_stopped(cls, states: dict[str, str]) -> bool:
        """Return True only when both Krea and Qwen are authoritatively off."""
        stopped = {"inactive", "failed"}
        return all(
            cls._comfyui_unit_state(states, unit) in stopped
            for unit in ("comfyui.service", "comfyui-qwen.service")
        )

    @classmethod
    def _any_comfyui_unit_active(cls, states: dict[str, str]) -> bool:
        """Return True when either exact ComfyUI unit is active."""
        return any(
            cls._comfyui_unit_state(states, unit) == "active"
            for unit in ("comfyui.service", "comfyui-qwen.service")
        )

    async def mark_comfyui_running_after_commit(self, unit: str = "comfyui.service") -> bool:
        """Clear stopped caches only after systemd confirms committed ownership.

        Slice B: takes the unit name explicitly so callers can commit the
        running state of either Krea (``comfyui.service``) or Qwen
        (``comfyui-qwen.service``). The previous single-unit implementation
        would silently accept a Qwen-only active state as a Krea-active
        commit, leading to false "Krea running" claims.
        """
        states = await self._comfyui_systemd_state()
        state = self._comfyui_unit_state(states, unit)
        if state != "active":
            self.logger.error(
                "VRAM: refusing running-state commit; %s systemd state=%r (all=%r)",
                unit, state, states,
            )
            return False
        self._comfyui_stopped = False
        self._comfyui_auto_stopped = False
        self._comfyui_idle_since = time.time()
        self.logger.info(
            "VRAM: ComfyUI running-state committed after authoritative bundle commit (unit=%s)",
            unit,
        )
        return True

    async def _restart_comfyui_for_restore(self):
        """Stop ComfyUI and restart it to force-release PyTorch VRAM cache.

        The ComfyUI /free API only unloads models — PyTorch's ROCm allocator
        retains the freed VRAM until the process exits. A full restart is the
        only way to return VRAM to the OS.

        BUGFIX (2026-05-20): Skip restart if ComfyUI was auto-stopped due to
        idle timeout. Only restart ComfyUI when it was actively used during
        GPU work — don't undo the idle auto-stop optimization.
        """
        # Checked host runtimes own process start/stop and model residency.
        # The legacy helper used to relaunch ``comfyui.service`` after a
        # checked Krea/Qwen transition, creating a second owner whose marker
        # blocked the next Qwen admission.  A checked bundle transition is
        # the only authority in that mode.
        if self._checked_comfyui_runtime_configured():
            try:
                unit_states = await self._comfyui_systemd_state()
                self._comfyui_stopped = self._all_comfyui_units_stopped(unit_states)
                self._comfyui_auto_stopped = self._comfyui_stopped
                if self._comfyui_stopped:
                    self._comfyui_idle_since = time.time()
            except Exception as exc:
                self.logger.debug(
                    "VRAM: checked ComfyUI state sync during restore failed: %s",
                    exc,
                )
            self.logger.info(
                "VRAM: checked ComfyUI runtime configured; skipping legacy restore restart"
            )
            return

        if self._comfyui_auto_stopped:
            unit_states = await self._comfyui_systemd_state()
            krea_state = self._comfyui_unit_state(
                unit_states, "comfyui.service"
            )
            if krea_state in {"inactive", "failed"}:
                self._comfyui_stopped = not self._any_comfyui_unit_active(
                    unit_states
                )
                self.logger.info(
                    "ComfyUI auto-stopped — authoritative Krea unit is inactive; "
                    "skipping restart during restore"
                )
                return

            self.logger.warning(
                "ComfyUI auto-stop cache disagrees with authoritative Krea unit "
                f"state={krea_state!r} (all={unit_states!r}); reconciling stop "
                "before restore"
            )
            self._comfyui_stopped = False
            if await self.stop_comfyui(reason="auto_stop_restore_reconcile"):
                return
            self.logger.warning(
                "ComfyUI authoritative stop reconciliation failed; "
                "continuing with normal restore sequence"
            )
            self._comfyui_auto_stopped = False

        config = _load_services_config()
        comfy_cfg = config.get("services", {}).get("comfyui", {})
        if not comfy_cfg.get("enabled", True):
            return

        # Stop ComfyUI if running
        if not self._comfyui_stopped:
            await self.stop_comfyui(reason="restore_prep")
            await self._wait_for_comfyui_port_free(timeout=30)
            await asyncio.sleep(2)

        # Restart ComfyUI directly via systemctl — bypass the _comfyui_stopped
        # guard in start_comfyui() since we explicitly want it running again
        try:
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "start", self._configured_comfyui_unit("comfyui"),
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
            if proc.returncode != 0:
                self.logger.warning(f"ComfyUI restart failed: {stderr.decode().strip()}")
            else:
                self.logger.info("ComfyUI restarted for VRAM clear")
        except Exception as e:
            self.logger.warning(f"ComfyUI restart error: {e}")

        # Phase 5.2.9: re-stamp grace after systemctl start. The systemctl
        # call above bypasses `_load_bundle`, so bundle_loaded_at and
        # bundle_post_load_grace_at retain their old timestamps. Without
        # this, the new ComfyUI process is unready (ComfyRegistry fetch
        # in progress) but the next grace check sees "now > old_grace_at"
        # and lets traffic through. The worker's first POST would hit an
        # unready backend again — same class of bug as 5.2.1/5.2.2.
        # Re-stamping gives the new process its own grace window.
        try:
            _grace_s = int(comfy_cfg.get("post_load_grace_seconds", 0) or 0)
            if _grace_s > 0:
                _gs = _get_gpu_state("gpu_primary")  # comfyui is always on gpu_primary
                _gs.bundle_loaded_at = time.time()
                _gs.bundle_post_load_grace_at = _gs.bundle_loaded_at + _grace_s
        except Exception:
            pass

        # Reset stopped flags so the scheduler sees ComfyUI as available
        self._comfyui_stopped = False
        self._comfyui_auto_stopped = False

        # Wait for ComfyUI to be ready
        await self._wait_for_comfyui_ready(timeout=120)

    async def _restart_acestep_for_restore(self):
        """Compatibility hook: ACE is retired; checked unload owns release."""
        self.logger.debug("Retired ACE restore hook skipped")

    # ── ComfyUI lifecycle (for pipeline LLM speed boost) ──────────

    async def stop_comfyui(self, reason: str = "pipeline_llm") -> bool:
        """Stop Krea ComfyUI and update the shared cache from both exact units."""
        if self._checked_comfyui_runtime_configured():
            try:
                unit_states = await self._comfyui_systemd_state()
                self._comfyui_stopped = self._all_comfyui_units_stopped(unit_states)
                self._comfyui_auto_stopped = self._comfyui_stopped
                if self._comfyui_stopped:
                    self._comfyui_idle_since = time.time()
            except Exception as exc:
                self.logger.debug(
                    "VRAM: checked ComfyUI state sync during stop skipped: %s",
                    exc,
                )
            self.logger.info(
                "VRAM: checked ComfyUI lifecycle is controller-owned; "
                "legacy stop helper deferred (%s)", reason
            )
            return True
        unit_states = await self._comfyui_systemd_state()
        krea_state = self._comfyui_unit_state(
            unit_states, "comfyui.service"
        )
        if krea_state in {"inactive", "failed"}:
            self._comfyui_stopped = not self._any_comfyui_unit_active(unit_states)
            self.logger.info(
                "VRAM: Krea ComfyUI already stopped "
                f"({reason}, state={krea_state}, all={unit_states!r})"
            )
            return True

        if self._comfyui_stopped:
            self.logger.warning(
                "VRAM: cached ComfyUI stopped state disagrees with Krea systemd "
                f"state={krea_state!r} (all={unit_states!r}); issuing "
                "authoritative stop"
            )
            self._comfyui_stopped = False

        self.logger.info(f"VRAM: Stopping ComfyUI for LLM speed ({reason})")
        await self._free_comfyui()
        await asyncio.sleep(2)

        try:
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "stop", "comfyui.service",
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
            if proc.returncode != 0:
                self.logger.error(f"VRAM: ComfyUI stop failed: {stderr.decode().strip()}")
                return False
            if event_bus:
                event_bus.emit("comfyui", "unhealthy")
        except Exception as e:
            self.logger.error(f"VRAM: ComfyUI stop error: {e}")
            return False

        freed = await self._wait_for_comfyui_port_free(timeout=30)
        if not freed:
            self.logger.warning("VRAM: ComfyUI port still in use after 30s")

        unit_states = await self._comfyui_systemd_state()
        krea_state = self._comfyui_unit_state(
            unit_states, "comfyui.service"
        )
        if krea_state not in {"inactive", "failed"}:
            self.logger.error(
                "VRAM: Krea ComfyUI stop command returned but authoritative "
                f"unit state is {krea_state!r} (all={unit_states!r}); refusing "
                "stopped-state commit"
            )
            self._comfyui_stopped = False
            return False

        self._comfyui_stopped = not self._any_comfyui_unit_active(unit_states)
        self.logger.info(
            "VRAM: Krea ComfyUI service authoritatively stopped, ~9.8GB VRAM "
            "freed for LLM"
        )
        return True

    async def start_comfyui(self, reason: str = "pipeline_gpu") -> bool:
        """Start ComfyUI service after LLM is done."""
        if self._checked_comfyui_runtime_configured():
            self.logger.info(
                "VRAM: checked ComfyUI lifecycle is controller-owned; "
                "legacy start helper deferred (%s)", reason
            )
            return True
        # Phase 5.2.50: VRAM pre-flight check. If cuda:0 already has > 10 GiB
        # used (likely by LLM-Primary idle LLM at ~13 GiB), refuse to start
        # ComfyUI — would OOM during first inference. The bundle priority
        # should evict the LLM first, but the stale _gpu_evicted flag can
        # short-circuit that. This defensive check prevents the OOM at source.
        try:
            vram_data = await _poll_vram()
            matched = _get_vram_entry_for_gpu(vram_data, "gpu_primary")
            if matched:
                used_mib = matched.get("vram_used_mib", 0)
                if used_mib > 10000:
                    self.logger.error(
                        f"start_comfyui: REFUSING to start — gpu_primary has "
                        f"{used_mib} MiB used (likely LLM-Primary idle LLM). "
                        f"Evict LLM first to avoid CUDA OOM."
                    )
                    return False
        except Exception as e:
            self.logger.debug(f"start_comfyui pre-flight VRAM check failed: {e}")

        if not self._comfyui_stopped:
            self.logger.info(f"VRAM: ComfyUI not stopped, skip start ({reason})")
            return True

        self.logger.info(f"VRAM: Starting ComfyUI ({reason})")

        try:
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", "start", "comfyui.service",
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
            if proc.returncode != 0:
                self.logger.error(f"VRAM: ComfyUI start failed: {stderr.decode().strip()}")
                return False
            if event_bus:
                event_bus.emit("comfyui", "healthy")
            self.logger.info("VRAM: ComfyUI service started")
        except Exception as e:
            self.logger.error(f"VRAM: ComfyUI start error: {e}")
            return False

        ready = await self._wait_for_comfyui_ready(timeout=120)
        if ready:
            self.logger.info("VRAM: ComfyUI ready")
        else:
            self.logger.warning("VRAM: ComfyUI not ready after 120s")

        self._comfyui_stopped = False
        self._comfyui_auto_stopped = False
        # Start idle timer if no pending ComfyUI jobs — ComfyUI will
        # be auto-stopped after COMFYUI_IDLE_COOLDOWN if nothing uses it.
        pending = [j for j in self._comfyui_queue if j.status == "queued"]
        self._comfyui_idle_since = None if pending else time.time()
        return True

    async def _ensure_comfyui_running(self):
        """Ensure ComfyUI is running before dispatching jobs.

        Called when the scheduler needs ComfyUI for work but it may have
        been auto-stopped. Blocks until ComfyUI is ready or times out.
        Returns True if ComfyUI is confirmed running.
        """
        if not self._comfyui_stopped and not self._comfyui_auto_stopped:
            return True  # Already running

        self.logger.info("ComfyUI not running — starting for GPU work")
        return await self.start_comfyui(reason="gpu_work_needed")

    async def _start_comfyui_async(self):
        """Async task: start ComfyUI in background (for pre-warming on job submit)."""
        try:
            await self.start_comfyui(reason="job_submitted")
        except Exception as e:
            self.logger.error(f"Async ComfyUI start failed: {e}")

    # ── Internal helpers ───────────────────────────────────────────

    async def _check_service_active(self, service_name: str = None) -> bool:
        name = service_name or _get_idle_service_name()
        try:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", "--quiet", name,
                stdout=asyncio.subprocess.DEVNULL,
                stderr=asyncio.subprocess.DEVNULL,
            )
            await proc.wait()
            return proc.returncode == 0
        except Exception as e:
            self.logger.error(f"VRAM: systemctl check failed: {e}")
            return False

    async def _systemctl(self, action: str, service_name: str = None) -> bool:
        name = service_name or _get_idle_service_name()
        try:
            proc = await asyncio.create_subprocess_exec(
                "sudo", "systemctl", action, name,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
            if proc.returncode != 0:
                self.logger.error(
                    f"VRAM: systemctl {action} failed (rc={proc.returncode}): "
                    f"{stderr.decode().strip()}"
                )
                return False
            self.logger.info(f"VRAM: systemctl {action} {name} succeeded")
            return True
        except asyncio.TimeoutError:
            self.logger.error(f"VRAM: systemctl {action} timed out")
            return False
        except Exception as e:
            self.logger.error(f"VRAM: systemctl {action} error: {e}")
            return False

    async def _wait_for_port_free(self, timeout: float = 30, port: int = None) -> bool:
        if port is None:
            port = _get_idle_service_port()
        url = f"http://localhost:{port}/health"
        start = time.time()
        while time.time() - start < timeout:
            try:
                async with self.session.get(
                    url,
                    timeout=ClientTimeout(total=2, connect=1),
                ) as resp:
                    pass
            except Exception:
                return True
            await asyncio.sleep(2)
        return False

    async def _wait_for_vram_below(self, target_mib: int = 4096, timeout: float = 30,
                                  *, gpu_id: str | None = None) -> bool:
        """Wait on the evicted GPU; other GPUs may still serve live work."""
        start = time.time()
        while time.time() - start < timeout:
            vram_data = await _poll_vram()
            if gpu_id:
                entry = _get_vram_entry_for_gpu(vram_data, gpu_id) or {}
                used = entry.get("vram_used_mib", entry.get("used_mib", 999999))
            else:
                used = vram_data.get("used_vram_mib", 999999)
            if not isinstance(used, (int, float)) or used < 0:
                used = 999999
            if used < target_mib:
                self.logger.info(f"VRAM: Freed — {used} MiB < {target_mib} MiB threshold")
                return True
            self.logger.info(f"VRAM: Still used {used} MiB, waiting... (target <{target_mib})")
            await asyncio.sleep(3)
        return False

    async def wait_for_free_mib(self, gpu_id: str, target_mib: int,
                                timeout_s: float = 5.0,
                                poll_interval_s: float = 0.25) -> bool:
        """Phase 5.2.19: block until `gpu_id` has `target_mib` free VRAM.

        Used after `systemctl start` of a new bundle, before HTTP probe,
        to close the TOCTOU window between process-exit and PyTorch CUDA
        allocator release (verified ~1s in llama.cpp + PyTorch per
        RESEARCH_PHASE_5_2_19_EVIDENCE.md).

        Returns True if target reached within timeout, False otherwise.
        Caller should log on False but NOT fail the load — the OOM
        watchdog will catch real failure (5.2.11 bug pattern).

        Backend dispatch via _detect_backend():
        - rocm:    read _vram_cache["gpus"] by matching card/pci
        - cuda:    nvidia-smi --query-gpu=memory.free (not implemented
                   yet — falls back to True)
        - vulkan:  GEM-fd scan (not implemented — falls back to True)
        - cpu:     always True (no VRAM)

        Per-GPU lookup key (P0-2 from PHASE5.2.19_ADVERSARIAL): services
        gpu_ids are logical names ("gpu_primary", "gpu_secondary"). _poll_vram()
        returns cards by "card" name ("card0", "card1") or pci_address.
        We resolve gpu_id → pci via services.json gpu_devices, then
        match on pci_address.
        """
        deadline = time.monotonic() + timeout_s
        backend = self._detect_backend_for_gpu(gpu_id)
        # CPU-only services (gemma-vision, no gpu_id): always free.
        if backend == "cpu" or not gpu_id:
            return True
        # Resolve gpu_id → pci for matching
        pci = self._pci_for_gpu(gpu_id)
        last_free = 0
        while time.monotonic() < deadline:
            free_mib = await self._free_mib_for_async(gpu_id, pci, backend)
            last_free = free_mib
            if free_mib >= target_mib:
                return True
            await asyncio.sleep(poll_interval_s)
        self.logger.warning(
            f"wait_for_free_mib({gpu_id}): target {target_mib} MiB not "
            f"reached in {timeout_s:.1f}s (last seen: {last_free} MiB)"
        )
        return False

    def _detect_backend_for_gpu(self, gpu_id: str | None) -> str:
        """One of 'rocm' | 'cuda' | 'vulkan' | 'cpu'."""
        if gpu_id in (None, "", "cpu", "cpu_only"):
            return "cpu"
        config = _load_services_config()
        gpu_devices = config.get("gpu_devices", {}) or {}
        dev = gpu_devices.get(gpu_id, {})
        if dev.get("cpu_only"):
            return "cpu"
        # Heuristic: try rocm-smi, then nvidia-smi, then vulkaninfo
        import shutil
        if shutil.which("rocm-smi"):
            return "rocm"
        if shutil.which("nvidia-smi"):
            return "cuda"
        if shutil.which("vulkaninfo"):
            return "vulkan"
        return "cpu"

    def _pci_for_gpu(self, gpu_id: str) -> str | None:
        config = _load_services_config()
        gpu_devices = config.get("gpu_devices", {}) or {}
        return gpu_devices.get(gpu_id, {}).get("pci")

    async def _free_mib_for_async(self, gpu_id: str, pci: str | None,
                                   backend: str) -> int:
        if backend == "rocm":
            vram_data = await _poll_vram()
            gpus = vram_data.get("gpus", []) or []
            target_pci = _normalize_pci_address(pci)
            for gpu in gpus:
                if (
                    target_pci
                    and _normalize_pci_address(gpu.get("pci_address")) == target_pci
                ):
                    used = gpu.get("vram_used_mib")
                    total = gpu.get("vram_total_mib") or 16368
                    if used is None:
                        return 0
                    return max(0, total - used)
            if target_pci:
                return 0
            mapped_card = (
                (_load_services_config().get("gpu_devices", {}) or {})
                .get(gpu_id, {})
                .get("card")
            )
            for gpu in gpus:
                card = gpu.get("card", "")
                if mapped_card and card == mapped_card:
                    used = gpu.get("vram_used_mib")
                    total = gpu.get("vram_total_mib") or 16368
                    return max(0, total - (used or 0))
            return 0
        if backend == "cuda":
            try:
                proc = await asyncio.create_subprocess_exec(
                    "nvidia-smi",
                    "--query-gpu=memory.free",
                    "--format=csv,noheader,nounits",
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.DEVNULL,
                )
                stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=1.0)
                return int(stdout.decode().strip().splitlines()[0])
            except Exception:
                return 0
        # Vulkan + cpu: best-effort return True semantics upstream.
        return 1 << 30

    async def _wait_for_llm_healthy(self, timeout: float = LLM_RESTORE_TIMEOUT) -> bool:
        port = _get_idle_service_port()
        url = f"http://localhost:{port}/health"
        start = time.time()
        while time.time() - start < timeout:
            try:
                async with self.session.get(
                    url,
                    timeout=ClientTimeout(total=5, connect=3),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        if data.get("status") == "ok":
                            llm.update_health(True)
                            return True
            except Exception:
                pass
            await asyncio.sleep(3)
        return False

    async def _free_comfyui(self):
        try:
            async with self.session.post(
                f"{COMFYUI_URL}/free",
                json={"unload_models": True, "free_memory": True},
                timeout=ClientTimeout(total=30),
            ) as resp:
                self.logger.info(f"VRAM: ComfyUI free → status {resp.status}")
        except Exception as e:
            self.logger.error(f"VRAM: ComfyUI free failed: {e}")

    async def _wait_for_comfyui_port_free(self, timeout: float = 30) -> bool:
        start = time.time()
        while time.time() - start < timeout:
            try:
                async with self.session.get(
                    f"{COMFYUI_URL}/system_stats",
                    timeout=ClientTimeout(total=2, connect=1),
                ) as resp:
                    pass
            except Exception:
                return True
            await asyncio.sleep(2)
        return False

    async def _wait_for_comfyui_ready(self, timeout: float = 120) -> bool:
        start = time.time()
        while time.time() - start < timeout:
            try:
                async with self.session.get(
                    f"{COMFYUI_URL}/system_stats",
                    timeout=ClientTimeout(total=5, connect=3),
                ) as resp:
                    if resp.status == 200:
                        return True
            except Exception:
                pass
            await asyncio.sleep(3)
        return False

    def get_gpu_services(self) -> list:
        """Return all GPU-using services sorted by eviction priority (lowest priority = most evictable).
        Skips cpu_only services (they don't use GPU VRAM)."""
        global _services_config
        if _services_config is None:
            _services_config = _load_services_config()
        services = _services_config.get("services", {})
        gpu_svcs = []
        for name, svc in services.items():
            if svc.get("cpu_only", False):
                continue  # CPU-only services don't need VRAM management
            if svc.get("enabled") and svc.get("systemd_unit"):
                gpu_svcs.append((name, svc))
        gpu_svcs.sort(key=lambda x: x[1].get("priority", 0))
        return gpu_svcs

    async def evict_for_vram(self, needed_mib: int) -> list:
        """Evict lowest-priority non-protected services until enough VRAM is free.

        Returns list of evicted service names.
        """
        global _services_config
        if _services_config is None:
            _services_config = _load_services_config()

        evicted = []
        bundles = _resolve_bundles()
        candidates = self.get_gpu_services()
        bundle_candidates = []
        for candidate_name, candidate_svc in candidates:
            if candidate_svc.get("protected", False):
                continue
            if not candidate_svc.get("systemd_unit"):
                continue
            resolved_bundle = _get_bundle_for_service(
                candidate_name, bundles=bundles
            )
            if resolved_bundle is not None:
                bundle_candidates.append((candidate_name, resolved_bundle))

        # A bundle-backed candidate may never be downgraded to the legacy
        # per-service systemd path when the durable owner is unavailable.
        # Preflight the whole candidate set so an unbundled service cannot be
        # stopped first and leave a partial eviction behind a later refusal.
        if bundle_candidates and bundle_lifecycle_controller is None:
            self.logger.error(
                "VRAM: refusing evict_for_vram without lifecycle controller "
                "for bundle-backed candidates: %s",
                [name for name, _ in bundle_candidates],
            )
            return []

        handled_bundle_roots: set[str] = set()
        for name, svc in candidates:
            if svc.get("protected", False):
                continue
            unit = svc.get("systemd_unit")
            if not unit:
                continue

            resolved_bundle = _get_bundle_for_service(name, bundles=bundles)
            if resolved_bundle is not None:
                bundle_name = resolved_bundle["bundle_name"]
                if bundle_name in handled_bundle_roots:
                    continue
                handled_bundle_roots.add(bundle_name)
                self.logger.info(
                    "VRAM: evict_for_vram(%sMiB) — evicting bundle %s "
                    "for service %s (priority=%s)",
                    needed_mib,
                    bundle_name,
                    name,
                    svc.get("priority"),
                )
                try:
                    bundle_ok = await _run_bundle_eviction_for_vram(
                        bundle_name,
                        reason=f"evict-for-vram:{name}:{needed_mib}",
                        bundles=bundles,
                    )
                except Exception as exc:
                    bundle_ok = False
                    self.logger.error(
                        "VRAM: exception evicting bundle %s for %s: %s",
                        bundle_name,
                        name,
                        exc,
                    )
                if bundle_ok:
                    evicted.append(name)
                else:
                    self.logger.warning(
                        "VRAM: controller refused/failed bundle eviction %s",
                        bundle_name,
                    )
                continue

            # This is the genuinely unbundled compatibility path. It remains
            # allowed, but it is deliberately unreachable for any service that
            # resolves through the bundle registry above.
            self.logger.info(f"VRAM: evict_for_vram({needed_mib}MiB) — evicting {name} (priority={svc.get('priority')})")
            try:
                # Phase 5.1.5: stamp this stop as planned (we initiated
                # it to free VRAM). The Supervisor will defer pool
                # shutdown for the planned window so a transient
                # unhealthy probe during the systemd stop cascade does
                # not get misclassified as a crash.
                if event_bus is not None:
                    event_bus.mark_planned_stop(name)
                proc = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "stop", unit,
                    stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=30)
                if event_bus:
                    event_bus.emit(name, "unhealthy")
                if proc.returncode == 0:
                    evicted.append(name)
                    self.logger.info(f"VRAM: evicted {name} for {needed_mib}MiB")
                else:
                    self.logger.warning(f"VRAM: failed to evict {name}: {stderr.decode().strip()}")
            except Exception as e:
                self.logger.error(f"VRAM: exception evicting {name}: {e}")
            finally:
                # Phase 5.2.6: caller-side clear. The stamp's only
                # purpose was to absorb the systemd stop cascade; once
                # the stop returns (success or failure), release the
                # supervisor's deferral so a real crash is not silently
                # swallowed.
                if event_bus is not None:
                    event_bus.clear_planned_stop(name)
        return evicted


