# Queue Metrics API handlers
# ===================================================================

def _metrics_service_names(config: Mapping[str, Any]) -> list[str]:
    """Return enabled queue consumers that can emit QueueMetrics records."""

    services = config.get("services", {}) if isinstance(config, Mapping) else {}
    if not isinstance(services, Mapping):
        return []
    return sorted(
        name
        for name, service in services.items()
        if isinstance(name, str)
        and _is_queue_consumer_service(service)
    )

async def handle_get_metrics(request: web.Request):
    """GET /v1/metrics?window=3600 — Queue performance metrics."""
    if not queue_metrics:
        return web.json_response({"error": "Metrics not available"}, status=503)

    window = int(request.query.get("window", 3600))
    window = min(window, QueueMetrics.WINDOW_24H)

    services = _metrics_service_names(_services_config)

    loop = asyncio.get_event_loop()
    stats = await loop.run_in_executor(None, queue_metrics.get_all_stats, services, window)

    return web.json_response({
        "window_seconds": window,
        "services": stats,
    })


async def handle_get_metrics_service(request: web.Request):
    """GET /v1/metrics/{service} — Single service metrics."""
    if not queue_metrics:
        return web.json_response({"error": "Metrics not available"}, status=503)

    service = request.match_info["service"]
    window = int(request.query.get("window", 3600))

    loop = asyncio.get_event_loop()
    stats = await loop.run_in_executor(None, queue_metrics.get_stats, service, window)

    return web.json_response(stats)


async def handle_get_metrics_summary(request: web.Request):
    """GET /v1/metrics/summary — Aggregated across all services."""
    if not queue_metrics:
        return web.json_response({"error": "Metrics not available"}, status=503)

    window = int(request.query.get("window", 3600))
    services = _metrics_service_names(_services_config)

    loop = asyncio.get_event_loop()
    stats = await loop.run_in_executor(None, queue_metrics.get_all_stats, services, window)

    # Aggregate
    total_completed = sum(s["total_completed"] for s in stats.values())
    total_failed = sum(s["total_failed"] for s in stats.values())
    total = total_completed + total_failed

    return web.json_response({
        "total_completed": total_completed,
        "total_failed": total_failed,
        "success_rate": round(total_completed / total * 100, 1) if total else None,
        "sample_count": total,
        "sample_state": "observed" if total else "no_samples",
        "per_service": stats,
    })


async def handle_get_dead_letters(request: web.Request):
    """GET /v1/dead-letters — Show dead-lettered jobs per service.

    Plan 05 public-boundary contract:
      * Outage is distinguishable from empty via ``status`` on each
        per-service entry and on the top-level ``summary``.
      * Policy metadata (cap / ttl / archive_rotation) is included so
        the API is self-describing without calling a separate endpoint.
      * NO purge is performed here — read-only surface.
    """
    if not queue_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)

    loop = asyncio.get_event_loop()
    services_doc = await loop.run_in_executor(
        None, queue_engine.get_all_dead_letter_services,
    )
    # services_doc is now {"status": ..., "services": [...], ...}
    services = services_doc.get("services", []) if isinstance(services_doc, dict) else []

    result = {}
    available_count = 0
    outage_count = 0
    empty_count = 0
    for svc in services:
        doc = await loop.run_in_executor(
            None, queue_engine.get_dead_letters, svc, 10,
        )
        # doc is now a dict; surface outage/available, summary counts
        # only — full entries (already capped) are still returned for
        # operator inspection.
        if not isinstance(doc, dict):
            # Defensive: tolerate unexpected non-dict, treat as outage.
            doc = {"status": "outage", "entries": [], "count": 0,
                   "total": 0, "dropped": 0}
        if doc.get("status") == "outage":
            outage_count += 1
        elif doc.get("count", 0) == 0:
            empty_count += 1
        else:
            available_count += 1
        result[svc] = {
            "status": doc.get("status"),
            "count": doc.get("count", 0),
            "total": doc.get("total", 0),
            "dropped": doc.get("dropped", 0),
            "cap": doc.get("cap"),
            "entries": (doc.get("entries") or [])[:5],  # cap API payload
        }

    return web.json_response({
        "dead_letters": result,
        "summary": {
            "services_with_dead_letters": available_count,
            "services_empty": empty_count,
            "services_outage": outage_count,
            "summary_status": services_doc.get("status")
                if isinstance(services_doc, dict) else "outage",
        },
        "policy": services_doc.get("policy", {})
            if isinstance(services_doc, dict) else {},
    })


async def handle_purge_dead_letters(request: web.Request):
    """POST /v1/dead-letters/purge — Purge dead-lettered jobs.

    Plan 05 public-boundary contract (purge authorization + audit):
      * The handler is the ONLY place in the system that performs
        dead-letter purge. The queue_engine.purge_dead_letters primitive
        REQUIRES actor + reason at the Python boundary and writes a
        durable audit record to ``dead-letter:audit`` carrying
        actor / reason / timestamp / count / service.
      * The handler is a thin authorization + transport layer over
        that primitive. It is NOT bundled with retry / requeue.
      * Authorization contract:
          - ``authorization`` MUST equal ``purge-dead-letters-v1``.
            Missing / wrong → 403, error="authorization_required".
          - ``actor`` MUST be a non-empty string in the request body.
            Empty / missing → 400, status="unauthorized", error="actor_required".
          - ``reason`` MUST be a non-empty string in the request body.
            Empty / missing → 400, status="unauthorized", error="reason_required".
      * Audit-on-success is durable in Redis; the response embeds the
        audit record so the caller can correlate without a follow-up read.
    """
    if not queue_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)

    data = await request.json() if request.can_read_body else {}
    service = (data.get("service") or "").strip()
    authorization = (data.get("authorization") or "").strip()
    actor = (data.get("actor") or "").strip()
    reason = (data.get("reason") or "").strip()

    # Authorization at the public boundary — fail fast before any
    # Redis call. The primitive would also reject these, but the
    # handler MUST surface them as 400 (client error), not 200.
    if authorization != "purge-dead-letters-v1":
        return web.json_response(
            {"status": "unauthorized", "error": "authorization_required"},
            status=403,
        )
    if not actor:
        return web.json_response(
            {"status": "unauthorized", "error": "actor_required"},
            status=400,
        )
    if not reason:
        return web.json_response(
            {"status": "unauthorized", "error": "reason_required"},
            status=400,
        )

    loop = asyncio.get_event_loop()
    if service:
        doc = await loop.run_in_executor(
            None, queue_engine.purge_dead_letters, service, actor, reason,
        )
        # Translate the primitive's status to an HTTP code at the boundary.
        status_str = doc.get("status")
        if status_str == "error":
            return web.json_response(doc, status=503)
        if status_str == "unauthorized":
            return web.json_response(doc, status=400)
        return web.json_response(doc)

    # Bulk purge — every per-service call carries actor + reason and
    # writes its own audit record. The combined response exposes
    # per-service outcomes so a partial failure is observable.
    services_doc = await loop.run_in_executor(
        None, queue_engine.get_all_dead_letter_services,
    )
    if not isinstance(services_doc, dict) or services_doc.get("status") != "available":
        return web.json_response(
            {"status": "outage", "error": "dead_letter_discovery_unavailable"},
            status=503,
        )
    services = services_doc.get("services", []) if isinstance(services_doc, dict) else []
    per_service: dict[str, dict] = {}
    total_purged = 0
    audit_records: list[dict] = []
    any_failed = False
    for svc in services:
        doc = await loop.run_in_executor(
            None, queue_engine.purge_dead_letters, svc, actor, reason,
        )
        per_service[svc] = doc
        total_purged += int(doc.get("purged", 0) or 0)
        if doc.get("audit"):
            audit_records.append(doc["audit"])
        if doc.get("status") != "ok":
            any_failed = True

    return web.json_response({
        "status": "partial_failure" if any_failed else "ok",
        "purged": total_purged,
        "services": services,
        "per_service": per_service,
        "audit": audit_records,
    }, status=207 if any_failed else 200)


# Combined Gemma LLM routing group used by nginx port 8095 (X-Backend: Gemma)
_COMBINED_GEMMA_ROUTING_GROUP = "Gemma"
_combined_gemma_broker: Any | None = None
_combined_gemma_member_cache: Any | None = None


async def _combined_gemma_systemd_facts(service_config: dict) -> dict:
    """Read active/MainPID evidence only; never change a member lifecycle."""
    unit = service_config.get("systemd_unit")
    if not isinstance(unit, str) or not unit:
        return {"systemd_active": False, "main_pid": None}
    try:
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "show", "--property=ActiveState", "--property=MainPID", "--value", unit,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL,
        )
        stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=3)
        if proc.returncode != 0:
            return {"systemd_active": False, "main_pid": None}
        values = stdout.decode("utf-8", "replace").splitlines()
        active = values[0].strip() == "active" if values else False
        try:
            pid = int(values[1].strip()) if len(values) > 1 else 0
        except ValueError:
            pid = 0
        return {"systemd_active": active, "main_pid": pid if pid > 0 else None}
    except Exception:
        return {"systemd_active": False, "main_pid": None}


async def _refresh_combined_gemma_member_snapshots() -> None:
    """Refresh semantic backend evidence for an embedded broker only."""
    if not _combined_gemma_broker_embedded():
        return
    cache = _combined_gemma_member_cache
    broker = _combined_gemma_broker
    if cache is None or broker is None or session is None or session.closed:
        return
    broker_config = (_services_config or {}).get("combined_gemma_broker", {})
    ordered_members = broker_config.get("ordered_members") if isinstance(broker_config, Mapping) else None
    if (
        not isinstance(ordered_members, (list, tuple))
        or not ordered_members
        or any(not isinstance(name, str) or not name for name in ordered_members)
        or len(set(ordered_members)) != len(ordered_members)
    ):
        logger.error("Combined Gemma readiness refresh refused invalid ordered_members")
        return
    def _dispatcher_state(member_name: str) -> tuple[bool, int]:
        return (
            bool(getattr(broker.dispatch_loop, "is_running", False)),
            int(broker._repository.lease_count(member_name)),
        )

    observer = MemberObserver(
        getattr(cache, "_configs", {}),
        session=session,
        systemd_probe=_combined_gemma_systemd_facts,
        dispatcher_state=_dispatcher_state,
        timeout=3.0,
    )
    for name in ordered_members:
        try:
            probes = await observer.observe(name, now=time.time())
            readiness = cache.update(name, probes, now=time.time())
            stale_lifecycle = False
            # A persisted JOINING state can survive a manager crash/restart
            # while the fresh probe has already proved the member healthy.
            # Complete that fenced lifecycle transition instead of mirroring
            # JOINING forever and letting reserve_job.lua reject every claim.
            try:
                from gemma_broker.redis_store import ReservationStale
                repository = getattr(broker, "_repository", None)
                persisted = repository.get_member(name) if repository is not None else None
                persisted_state = getattr(getattr(persisted, "state", None), "value", None)
                # Readiness is evidence, not lifecycle authority.  Preserve an
                # explicit drain/offline/fault quarantine in the embedded path
                # just as the standalone broker does; otherwise a healthy probe
                # can reopen a member while a stop or recovery fence is still
                # in flight.
                lifecycle_states = {
                    "draining": "member drain in progress",
                    "offline": "member rejoin required",
                    "faulted": "member faulted; explicit rejoin required",
                }
                if (
                    repository is not None
                    and persisted is not None
                    and persisted_state in lifecycle_states
                ):
                    readiness = dataclasses.replace(
                        readiness,
                        state=getattr(persisted, "state"),
                        accepting=False,
                        state_version=int(getattr(persisted, "state_version", 0) or 0),
                        generation_fence=int(getattr(persisted, "generation_fence", 0) or 0),
                        compatible_free_slots=0,
                        blockers=tuple(dict.fromkeys((*readiness.blockers, lifecycle_states[persisted_state]))),
                    )
                    cache._snapshots[name] = readiness
                if (
                    repository is not None
                    and persisted is not None
                    and persisted_state == "joining"
                    and readiness.state.value == "ready_accepting"
                    and readiness.accepting
                    and int(getattr(persisted, "dispatcher_leases", 0) or 0) == 0
                ):
                    readiness = repository.complete_member_rejoin(
                        name,
                        expected_state_version=int(persisted.state_version),
                        readiness=readiness,
                    )
                    cache._snapshots[name] = readiness
                    logger.warning(
                        "BROKER_REFRESH: completed persisted rejoin member=%s state_version=%s",
                        name, readiness.state_version,
                    )
            except ReservationStale:
                # A concurrent drain/rejoin won the generation-fenced CAS.
                # Never publish this tick's older probe over the newer member
                # record; leave Redis authoritative and retry on the next
                # refresh instead of reopening a member with a stale fence.
                stale_lifecycle = True
                logger.info(
                    "BROKER_REFRESH: lifecycle changed during rejoin member=%s; "
                    "skipping stale readiness write",
                    name,
                )
            except Exception:
                logger.warning(
                    "BROKER_REFRESH: persisted rejoin reconciliation skipped member=%s",
                    name,
                    exc_info=True,
                )
            if stale_lifecycle:
                continue
        except Exception:
            # Preserve the cache's initialized unready snapshot on every malformed observation.
            logger.warning("Combined Gemma readiness refresh failed for %s", name, exc_info=True)
        # DIAGNOSTIC: periodic state dump
        try:
            s = cache._snapshots.get(name)
            if s is not None:
                logger.warning(
                    "BROKER_REFRESH: %s state=%s accepting=%s blockers=%s",
                    s.name, s.state, s.accepting, list(s.blockers)[:3],
                )
                # The runtime owns member state for the broker; the Lua scripts
                # in ``reserve_job.lua`` read state from a Redis member-hash
                # (``KEYS[3]``), so the in-memory cache snapshot must be
                # mirrored into Redis on every refresh, otherwise
                # ``reserve_next`` rejects with RESERVATION_STATE_STALE.
                try:
                    if _combined_gemma_broker_embedded() and hasattr(broker, "_repository") and broker._repository is not None:
                        broker._repository.put_member(s)
                except Exception:
                    pass
        except Exception:
            pass
        # END DIAGNOSTIC


async def _combined_gemma_refresh_loop() -> None:
    while _combined_gemma_broker_embedded() and _combined_gemma_broker is not None:
        await _refresh_combined_gemma_member_snapshots()
        await asyncio.sleep(2.0)


async def _initialize_combined_gemma_broker() -> Any | None:
    """Build the in-process broker only in embedded deployment mode."""
    global _combined_gemma_broker, _combined_gemma_member_cache
    if not _combined_gemma_broker_embedded():
        return None
    if _combined_gemma_broker is not None:
        return _combined_gemma_broker
    if _queue_redis is None or session is None or session.closed:
        logger.error("Combined Gemma broker unavailable: Redis or shared HTTP session missing")
        return None
    try:
        from combined_gemma_broker_service import build_member_configs
        from gemma_broker.config import BrokerConfig
        from gemma_broker.member_cache import StrictMemberSnapshotCache
        from gemma_broker.redis_store import RedisJobRepository
        from gemma_broker.runtime import BufferedAiohttpTransport, build_runtime

        # Read the validated broker config in two steps: peek the raw block to
        # extract the explicit ``candidate_mode`` boolean, then re-parse via
        # ``BrokerConfig.from_dict`` with that value as the ``candidate``
        # kwarg. The validated config is the single source of truth for mode;
        # no literal ``candidate=True`` is hard-coded here.
        raw_block = _services_config.get("combined_gemma_broker")
        if not isinstance(raw_block, dict):
            raise ValueError("COMBINED_GEMMA_BROKER_BLOCK_MISSING")
        if type(raw_block.get("candidate_mode")) is not bool:
            raise ValueError("COMBINED_GEMMA_BROKER_CANDIDATE_MODE_BOOL_REQUIRED")
        candidate = raw_block["candidate_mode"]
        broker_config = BrokerConfig.from_dict(
            _services_config["combined_gemma_broker"], candidate=candidate,
        )
        services = _services_config.get("services", {})
        member_configs, endpoints = build_member_configs(services, broker_config)
        member_forward_timeouts: list[float] = []
        for name in broker_config.ordered_members:
            service_config = services.get(name)
            if not isinstance(service_config, dict) or service_config.get("enabled") is not True:
                raise ValueError(f"COMBINED_GEMMA_MEMBER_CONFIG_INVALID:{name}")
            member_config = member_configs[name]
            forward_timeout = float(member_config.get("forward_timeout", 600))
            if forward_timeout <= 0:
                raise ValueError(f"COMBINED_GEMMA_FORWARD_TIMEOUT_INVALID:{name}")
            member_forward_timeouts.append(forward_timeout)

        def _request_for_member(member, request_body):
            payload = dict(request_body)
            model = member_configs.get(member.name, {}).get("model")
            if isinstance(model, str) and model:
                payload["model"] = model
            return payload

        cache = StrictMemberSnapshotCache(member_configs, freshness_ms=int(broker_config.freshness_seconds * 1000))
        repository = RedisJobRepository(
            _queue_redis,
            prefix=broker_config.redis_namespace,
            aging_seconds=broker_config.aging_interval_seconds,
            leadership_clock=time.time,
        )
        recovered_claims = repository.recover_stale_pre_acceptance_claims(
            now=time.monotonic(),
            max_age_seconds=120.0,
        )
        if recovered_claims:
            logger.warning(
                "BROKER_RECOVERY: requeued %d stale pre-acceptance claims",
                len(recovered_claims),
            )
        # The broker's internal request and compatibility waits must cover the
        # same generation budget as every owned backend.  The old implicit
        # 30-second defaults converted slow-but-valid model work into
        # post-acceptance OUTCOME_UNKNOWN/dropped client requests.  Keep the
        # existing service contract authoritative and add the same 60-second
        # lease/cleanup buffer used by GPUManager's forwarding path.
        broker_request_timeout = max(member_forward_timeouts or [600.0]) + 60.0
        transport = BufferedAiohttpTransport(
            session=session,
            endpoint_for_member=lambda member: endpoints.get(member.name, ""),
            request_for_member=_request_for_member,
            timeout=broker_request_timeout,
        )
        runtime = build_runtime(
            config=broker_config, repository=repository, members_provider=cache.snapshots,
            transport=transport,
            clock=time.monotonic,
            request_timeout=broker_request_timeout,
            compat_timeout=broker_request_timeout,
        )
        await runtime.dispatch_loop.start()
        _combined_gemma_member_cache = cache
        _combined_gemma_broker = runtime
        runtime.schedule_background(_combined_gemma_refresh_loop())
        await _refresh_combined_gemma_member_snapshots()
        # DIAGNOSTIC: log initial cache state for the readiness gap investigation
        try:
            cache_snap = list(cache.snapshots())
            api_members = list(runtime.api_service.members())
            logger.warning(
                "BROKER_DEBUG: cache_configs=%d cache_snapshots=%d runtime_members=%d",
                len(cache._configs), len(cache_snap), len(api_members),
            )
            for s in cache_snap:
                logger.warning(
                    "BROKER_DEBUG: snapshot %s state=%s accepting=%s blockers=%s",
                    s.name, s.state, s.accepting, list(s.blockers)[:3],
                )
        except Exception:
            logger.exception("BROKER_DEBUG failed")
        logger.info("Combined Gemma broker initialized with fail-closed semantic readiness")
        return runtime
    except Exception:
        _combined_gemma_member_cache = None
        _combined_gemma_broker = None
        logger.exception("Combined Gemma broker initialization failed")
        return None


class _CombinedGemmaAPIProxy:
    """Late-bind HTTP calls to the live broker instance."""

    @staticmethod
    def _service():
        from gemma_broker.api import APIError

        broker = _combined_gemma_broker
        service = getattr(broker, "api_service", broker)
        if service is None:
            raise APIError(503, "broker_unavailable", "combined Gemma broker unavailable")
        return service

    def submit(self, payload: dict):
        return self._service().submit(payload)

    def status(self, job_id: str):
        return self._service().status(job_id)

    def cancel(self, job_id: str):
        return self._service().cancel(job_id)

    @property
    def repository(self):
        """Expose the live repository required by status/cancel attempt lookup."""
        return self._service().repository

    @staticmethod
    def _runtime():
        from gemma_broker.api import APIError

        runtime = _combined_gemma_broker
        if runtime is None:
            raise APIError(503, "broker_unavailable", "combined Gemma broker unavailable")
        return runtime

    def health_live(self):
        self._runtime()
        return {"status": "ok", "broker": "combined_gemma", "liveness": "alive"}

    def health_ready(self):
        from gemma_broker.contracts import MemberState

        runtime = self._runtime()
        members = list(runtime._members_provider())
        ready = [
            member
            for member in members
            if member.state is MemberState.READY_ACCEPTING
            and member.accepting is True
            and (member.compatible_free_slots or 0) > 0
            and member.semantic_health is True
        ]
        body = {
            "status": "ok" if not runtime._closed and ready else "unavailable",
            "readiness": "ready" if not runtime._closed and ready else "no_ready_accepting_member",
            "broker": "combined_gemma",
            "ready_members": len(ready),
            "members": [member.to_dict() for member in members],
        }
        return body, 200 if body["status"] == "ok" else 503

    def health_dispatch(self):
        runtime = self._runtime()
        loop = runtime.dispatch_loop
        running = bool(loop.is_running)
        body = {
            "status": "ok" if running else "unavailable",
            "broker": "combined_gemma",
            "dispatch_loop": loop.metrics,
            "owner": runtime.owner_token,
        }
        return body, 200 if running else 503

    def broker_metrics(self):
        from gemma_broker.observability import SCHEMA_VERSION

        runtime = self._runtime()
        members = list(runtime._members_provider())
        lease_counts = {
            member.name: runtime._repository.lease_count(member.name)
            for member in members
        }
        queue_depth = int(getattr(runtime._repository, "queue_total"))
        payload = runtime.metrics.snapshot(
            members=members,
            queue_depth=queue_depth,
            now=runtime._clock(),
            lease_counts=lease_counts,
            schema=SCHEMA_VERSION,
            namespace=runtime.config.redis_namespace,
            leader={
                "owner": runtime.owner_token,
                "token": runtime.dispatch_loop.fencing_token,
                "expires_at": None,
            },
            dispatch_loop=runtime.dispatch_loop.metrics,
        )
        payload["members"] = list(payload["members"].values())
        return payload


_combined_gemma_api_proxy = _CombinedGemmaAPIProxy()
_combined_gemma_generation_fences: dict[str, int] = {}
_combined_gemma_rejoin_retry_at: dict[str, float] = {}
_COMBINED_GEMMA_REJOIN_SCAN_INTERVAL = 30.0
_COMBINED_GEMMA_REJOIN_RETRY_DELAY = 60.0


def _combined_gemma_deployment_config(config: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Validate and normalize the Combined Gemma ownership mode.

    The legacy shape has no deployment block and remains embedded. External
    mode is deliberately strict: only a loopback HTTP endpoint is accepted so
    a malformed or remote URL cannot silently redirect lifecycle control.
    """
    raw = (_services_config if config is None else config).get(
        "combined_gemma_deployment", {}
    )
    if raw in (None, {}):
        return {"mode": "embedded", "endpoint": None}
    if not isinstance(raw, Mapping):
        raise ValueError("combined_gemma_deployment must be an object")
    mode = raw.get("mode", "embedded")
    if mode not in {"embedded", "external"}:
        raise ValueError(f"unsupported combined_gemma_deployment.mode: {mode!r}")
    if mode == "embedded":
        if raw.get("endpoint") not in (None, ""):
            raise ValueError("embedded deployment must not define endpoint")
        return {"mode": mode, "endpoint": None}

    from urllib.parse import urlsplit

    endpoint = raw.get("endpoint")
    if not isinstance(endpoint, str) or not endpoint:
        raise ValueError("external deployment requires endpoint")
    parsed = urlsplit(endpoint)
    if parsed.scheme != "http" or parsed.username or parsed.password:
        raise ValueError("external broker endpoint must be plain loopback HTTP")
    if parsed.query or parsed.fragment or parsed.path not in ("", "/"):
        raise ValueError("external broker endpoint must not include path/query/fragment")
    host = (parsed.hostname or "").lower()
    if host not in {"127.0.0.1", "localhost", "::1"}:
        raise ValueError("external broker endpoint must resolve to loopback")
    try:
        port = parsed.port
    except ValueError as exc:
        raise ValueError("external broker endpoint has an invalid port") from exc
    if port is None:
        raise ValueError("external broker endpoint requires an explicit port")
    if not (1 <= port <= 65535):
        raise ValueError("external broker endpoint port is out of range")
    return {"mode": mode, "endpoint": endpoint.rstrip("/")}


def _combined_gemma_broker_enabled() -> bool:
    """Return True for the logical broker feature in either deployment mode."""
    cfg = _services_config.get("combined_gemma_broker", {})
    return isinstance(cfg, Mapping) and cfg.get("enabled") is True


def _combined_gemma_broker_embedded() -> bool:
    """Return whether GPUManager may construct or mutate an in-process broker."""
    if not _combined_gemma_broker_enabled():
        return False
    try:
        return _combined_gemma_deployment_config().get("mode") == "embedded"
    except ValueError as exc:
        logger.error("Invalid Combined Gemma deployment configuration: %s", exc)
        return False


def _next_combined_gemma_generation_fence(service_name: str) -> int:
    """Allocate a process-local high-water fence exact through Redis/Lua."""
    # Allocation consumes the value even if the later repository CAS fails.
    # Redis remains authoritative for the committed member generation.
    candidate = time.time_ns() // 1_000_000
    previous = _combined_gemma_generation_fences.get(service_name, 0)
    fence = max(candidate, previous + 1)
    _combined_gemma_generation_fences[service_name] = fence
    return fence


def _combined_gemma_broker_owns_service(service_name: str, service_config: dict) -> bool:
    """Whether shared logical-group queue ownership moved to the broker."""
    return (
        _combined_gemma_broker_enabled()
        and service_config.get("enabled") is True
        and service_config.get("type") == "llm_backend"
        and service_config.get("routing_group") == _COMBINED_GEMMA_ROUTING_GROUP
    )


def _broker_owned_queue_routing_groups() -> frozenset[str]:
    """Return logical streams whose durable queue belongs to the Gemma broker."""

    if _combined_gemma_broker_enabled():
        return frozenset({_COMBINED_GEMMA_ROUTING_GROUP})
    return frozenset()


async def _external_combined_gemma_control(
    service_name: str,
    action: str,
    *,
    timeout: float,
    generation_fence: int | None = None,
    expected_state_version: int | None = None,
) -> dict[str, Any] | None:
    """Call the standalone broker lifecycle endpoint and validate its reply."""
    deployment = _combined_gemma_deployment_config()
    if deployment["mode"] != "external":
        return None
    if session is None or session.closed:
        raise RuntimeError("external Combined Gemma broker session unavailable")
    if action not in {"drain", "rejoin"}:
        raise ValueError(f"unsupported external broker action: {action}")
    from urllib.parse import quote

    payload: dict[str, Any] = {"timeout": float(timeout)}
    if generation_fence is not None:
        payload["generation_fence"] = int(generation_fence)
    if expected_state_version is not None:
        payload["expected_state_version"] = int(expected_state_version)
    url = (
        f"{deployment['endpoint']}/v1/gemma/members/"
        f"{quote(service_name, safe='')}/{action}"
    )
    async with session.post(url, json=payload, timeout=ClientTimeout(total=timeout + 5.0)) as response:
        if response.status not in (200, 409):
            raise RuntimeError(f"external broker {action} failed with HTTP {response.status}")
        body = await response.json(content_type=None)
    if not isinstance(body, Mapping):
        raise RuntimeError(f"external broker {action} returned non-object JSON")
    member = body.get("member")
    if not isinstance(member, Mapping) or member.get("name") != service_name:
        raise RuntimeError(f"external broker {action} returned invalid member identity")
    if action == "drain":
        if type(body.get("drained")) is not bool:
            raise RuntimeError("external broker drain response missing boolean drained")
        if not isinstance(body.get("lease_count"), int) or body["lease_count"] < 0:
            raise RuntimeError("external broker drain response missing lease_count")
        if not isinstance(body.get("blockers", []), list):
            raise RuntimeError("external broker drain response has invalid blockers")
    elif body.get("rejoined") is not True:
        raise RuntimeError("external broker rejoin response missing rejoined=true")
    return dict(body)


async def _drain_combined_gemma_member_before_stop(
    service_name: str, *, timeout: float = DRAIN_TIMEOUT
) -> bool:
    """Use the broker's member-local lease barrier before a planned stop."""
    service_config = _services_config.get("services", {}).get(service_name, {})
    if not _combined_gemma_broker_owns_service(service_name, service_config):
        return True
    if not _combined_gemma_broker_embedded():
        try:
            result = await _external_combined_gemma_control(
                service_name, "drain", timeout=timeout
            )
        except Exception as exc:
            logger.error("External Combined Gemma member drain failed for %s: %s", service_name, exc)
            return False
        drained = bool(result and result.get("drained") is True)
        if not drained:
            logger.warning(
                "Combined Gemma external member drain denied for %s: "
                "lease_count=%s blockers=%s",
                service_name,
                result.get("lease_count") if isinstance(result, Mapping) else None,
                result.get("blockers") if isinstance(result, Mapping) else None,
            )
        return drained
    broker = _combined_gemma_broker
    if broker is None or not hasattr(broker, "drain_member"):
        logger.error(
            "Combined Gemma member drain unavailable for %s; refusing stop",
            service_name,
        )
        return False
    try:
        member = broker.repository.get_member(service_name)
        if member is None:
            raise RuntimeError(f"Combined Gemma member not found: {service_name}")
        result = await broker.drain_member(
            service_name,
            expected_state_version=member.state_version,
            timeout=timeout,
            retry_stale=True,
        )
    except Exception as exc:
        logger.error("Combined Gemma member drain failed for %s: %s", service_name, exc)
        return False
    drained = bool(getattr(result, "drained", result is True))
    if not drained:
        logger.warning(
            "Combined Gemma member %s still has durable leases; refusing stop",
            service_name,
        )
    return drained


async def _rejoin_combined_gemma_member_after_start(
    service_name: str, *, timeout: float = DRAIN_TIMEOUT,
    expected_state_version: int | None = None,
) -> bool:
    """Rejoin a broker-owned member only after startup health is verified."""
    service_config = _services_config.get("services", {}).get(service_name, {})
    if not _combined_gemma_broker_owns_service(service_name, service_config):
        return True
    if _combined_gemma_broker_embedded():
        broker = _combined_gemma_broker
        repository = getattr(broker, "_repository", None)
        if repository is None:
            logger.error(
                "Embedded Combined Gemma member rejoin unavailable for %s",
                service_name,
            )
            return False
        try:
            current = repository.get_member(service_name)
            if current is None:
                raise RuntimeError(
                    f"Combined Gemma member not found: {service_name}"
                )
            state = getattr(getattr(current, "state", None), "value", None)
            if state == "unhealthy":
                if broker is None or not hasattr(broker, "drain_member"):
                    raise RuntimeError(
                        "Embedded Combined Gemma member drain unavailable for "
                        f"{service_name}"
                    )
                drained = await broker.drain_member(
                    service_name,
                    expected_state_version=int(current.state_version),
                    timeout=timeout,
                    retry_stale=True,
                )
                if (
                    getattr(drained, "drained", False) is not True
                    or int(getattr(drained, "lease_count", -1)) != 0
                ):
                    raise RuntimeError(
                        f"Combined Gemma member {service_name} did not drain cleanly"
                    )
                current = repository.get_member(service_name)
                state = getattr(getattr(current, "state", None), "value", None)
                if current is None or state != "offline":
                    raise RuntimeError(
                        f"Combined Gemma member {service_name} did not enter offline"
                    )
                expected_state_version = int(current.state_version)
                logger.info(
                    "Embedded Combined Gemma member normalized from unhealthy "
                    "to offline before rejoin: %s",
                    service_name,
                )
            if state == "ready_accepting" and current.accepting is True:
                return True
            if state == "offline":
                expected = (
                    int(current.state_version)
                    if expected_state_version is None
                    else int(expected_state_version)
                )
                generation_fence = max(
                    _next_combined_gemma_generation_fence(service_name),
                    int(getattr(current, "generation_fence", 0) or 0) + 1,
                )
                _combined_gemma_generation_fences[service_name] = generation_fence
                joining = repository.begin_member_rejoin(
                    service_name,
                    expected_state_version=expected,
                    generation_fence=generation_fence,
                )
                state = getattr(getattr(joining, "state", None), "value", None)
            elif state == "joining":
                # The persisted generation is authoritative. A controller can
                # restart with an empty process-local high-water map while a
                # valid JOINING record survives in Redis.
                if (
                    expected_state_version is not None
                    and int(current.state_version) != int(expected_state_version)
                ):
                    raise RuntimeError(
                        "Combined Gemma member state changed before rejoin"
                    )
            else:
                raise RuntimeError(
                    f"Combined Gemma member {service_name} cannot rejoin from {state!r}"
                )
            if state != "joining":
                raise RuntimeError(
                    f"Combined Gemma member {service_name} did not enter joining"
                )

            deadline = time.monotonic() + max(0.0, float(timeout))
            while True:
                # Refresh completes JOINING only after fresh probes are ready
                # and dispatcher leases are zero. Poll until that fenced CAS
                # wins or the caller's bounded timeout expires.
                await _refresh_combined_gemma_member_snapshots()
                current = repository.get_member(service_name)
                if current is None:
                    raise RuntimeError(
                        f"Combined Gemma member disappeared: {service_name}"
                    )
                state = getattr(getattr(current, "state", None), "value", None)
                if state == "ready_accepting" and current.accepting is True:
                    logger.info(
                        "Embedded Combined Gemma member rejoined after start: %s",
                        service_name,
                    )
                    return True
                if state != "joining":
                    raise RuntimeError(
                        f"Combined Gemma member {service_name} left joining as {state!r}"
                    )
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise TimeoutError(
                        f"Combined Gemma member rejoin timed out: {service_name}"
                    )
                await asyncio.sleep(min(0.25, remaining))
        except Exception as exc:
            logger.error(
                "Embedded Combined Gemma member rejoin failed for %s: %s",
                service_name,
                exc,
            )
            return False
    try:
        result = await _external_combined_gemma_control(
            service_name,
            "rejoin",
            timeout=timeout,
            generation_fence=_next_combined_gemma_generation_fence(service_name),
            expected_state_version=expected_state_version,
        )
    except Exception as exc:
        logger.error("External Combined Gemma member rejoin failed for %s: %s", service_name, exc)
        return False
    return bool(result and result.get("rejoined") is True)


async def _rejoin_combined_gemma_bundle_members_after_start(
    member_names: list[str],
    services_cfg: Mapping[str, Any],
    *,
    timeout: float,
) -> bool:
    """Rejoin every broker-owned member in a newly healthy bundle."""
    for service_name in member_names:
        service_config = services_cfg.get(service_name, {})
        if not isinstance(service_config, Mapping):
            logger.error(
                "Combined Gemma bundle member config invalid for %s",
                service_name,
            )
            return False
        if not _combined_gemma_broker_owns_service(
            service_name, dict(service_config)
        ):
            continue
        if not await _rejoin_combined_gemma_member_after_start(
            service_name,
            timeout=timeout,
        ):
            logger.error(
                "Combined Gemma bundle member failed to rejoin after start: %s",
                service_name,
            )
            return False
    return True


async def _fetch_external_combined_gemma_health() -> tuple[dict[str, dict], str | None]:
    """Read per-member semantic health for the external broker rejoin gate."""
    deployment = _combined_gemma_deployment_config()
    if deployment["mode"] != "external":
        return {}, "broker_not_external"
    if session is None or session.closed:
        return {}, "http_session_unavailable"
    try:
        async with session.get(
            f"{deployment['endpoint']}/health",
            timeout=ClientTimeout(total=3.0, connect=0.5, sock_read=2.5),
        ) as response:
            # A broker with no accepting members may correctly return 503 while
            # still exposing the member evidence needed to decide a safe rejoin.
            if response.status not in (200, 503):
                return {}, f"broker_health_http_{response.status}"
            body = await response.json(content_type=None)
    except asyncio.TimeoutError:
        return {}, "broker_health_probe_timeout"
    except Exception as exc:
        return {}, f"broker_health_unavailable:{type(exc).__name__}"
    raw_members = body.get("members") if isinstance(body, Mapping) else None
    if not isinstance(raw_members, list):
        return {}, "broker_health_members_missing"
    members: dict[str, dict] = {}
    for member in raw_members:
        if not isinstance(member, Mapping) or not isinstance(member.get("name"), str):
            return {}, "broker_health_member_invalid"
        name = member["name"]
        if name in members:
            return {}, f"broker_health_duplicate_member:{name}"
        members[name] = dict(member)
    return members, None


def _external_rejoin_evidence_is_safe(
    service_name: str,
    service_config: Mapping[str, Any],
    metric: Mapping[str, Any],
    health: Mapping[str, Any],
) -> bool:
    """Require matching, fresh, idle evidence before asking a broker to rejoin."""
    if metric.get("name") != service_name or health.get("name") != service_name:
        return False
    if metric.get("state") not in {"joining", "offline"} or health.get("state") != metric.get("state"):
        return False
    if metric.get("fresh") is not True or metric.get("stale") is not False or metric.get("unknown") is not False:
        return False
    if health.get("systemd_active") is not True or health.get("semantic_health") is not True:
        return False
    if health.get("dispatcher_registered") is not True:
        return False
    if service_config.get("gpu_id"):
        if health.get("model_resident") is not True:
            return False
        if health.get("idle_service_configured") != service_name:
            return False
        if health.get("idle_service_effective") is not True:
            return False
    total = metric.get("backend_slots_total")
    busy = metric.get("backend_slots_busy")
    if type(total) is not int or total <= 0 or type(busy) is not int or busy != 0:
        return False
    lease_count = metric.get("live_lease_count", metric.get("dispatcher_leases"))
    if type(lease_count) is not int or lease_count != 0:
        return False
    if type(metric.get("state_version")) is not int or metric["state_version"] < 0:
        return False
    if type(metric.get("generation_fence")) is not int or metric["generation_fence"] < 0:
        return False
    if health.get("state_version") != metric.get("state_version"):
        return False
    if health.get("generation_fence") != metric.get("generation_fence"):
        return False
    blockers = health.get("blockers")
    if not isinstance(blockers, list) or any(
        blocker != (
            "member rejoin in progress" if metric.get("state") == "joining"
            else "member rejoin required"
        ) for blocker in blockers
    ):
        return False
    return True


async def _reconcile_external_combined_gemma_rejoins() -> dict[str, Any]:
    """Rejoin proved healthy idle members left JOINING/OFFLINE after restart.

    Draining, drained and faulted members require their lifecycle owner; they
    are deliberately excluded even if a health endpoint responds.
    """
    if not _combined_gemma_broker_enabled() or _combined_gemma_broker_embedded():
        return {"status": "disabled", "attempted": [], "skipped": []}
    metrics, metrics_error = await _fetch_combined_gemma_visibility()
    if not isinstance(metrics, dict):
        return {"status": "unavailable", "reason": metrics_error or "broker_unavailable", "attempted": [], "skipped": []}
    raw_members = metrics.get("members")
    if not isinstance(raw_members, list):
        return {"status": "invalid", "reason": "broker_members_missing", "attempted": [], "skipped": []}
    candidates = {
        item.get("name"): item
        for item in raw_members
        if isinstance(item, Mapping) and isinstance(item.get("name"), str)
        and item.get("state") in {"joining", "offline"}
    }
    if not candidates:
        return {"status": "ok", "attempted": [], "skipped": []}
    health_members, health_error = await _fetch_external_combined_gemma_health()
    if health_error:
        return {"status": "unavailable", "reason": health_error, "attempted": [], "skipped": sorted(candidates)}
    services = (_services_config.get("services", {}) if isinstance(_services_config, Mapping) else {})
    attempted: list[str] = []
    skipped: list[str] = []
    now = time.monotonic()
    for name, metric in candidates.items():
        service_config = services.get(name, {}) if isinstance(services, Mapping) else {}
        if not isinstance(service_config, Mapping) or not _combined_gemma_broker_owns_service(name, dict(service_config)):
            skipped.append(name)
            continue
        retry_at = _combined_gemma_rejoin_retry_at.get(name, 0.0)
        if now < retry_at:
            skipped.append(name)
            continue
        health = health_members.get(name)
        if not isinstance(health, Mapping) or not _external_rejoin_evidence_is_safe(
            name, service_config, metric, health
        ):
            skipped.append(name)
            continue
        attempted.append(name)
        try:
            rejoined = await _rejoin_combined_gemma_member_after_start(
                name,
                timeout=min(DRAIN_TIMEOUT, 30.0),
                expected_state_version=int(metric["state_version"]),
            )
        except Exception:
            rejoined = False
            logger.warning("External Combined Gemma rejoin reconciliation failed for %s", name, exc_info=True)
        if rejoined:
            _combined_gemma_rejoin_retry_at.pop(name, None)
        else:
            _combined_gemma_rejoin_retry_at[name] = now + _COMBINED_GEMMA_REJOIN_RETRY_DELAY
    return {"status": "ok", "attempted": attempted, "skipped": skipped}


async def _external_combined_gemma_rejoin_loop() -> None:
    """Periodically recover only verified, lease-free external JOINING members."""
    first_pass = True
    while True:
        try:
            if not first_pass:
                await asyncio.sleep(_COMBINED_GEMMA_REJOIN_SCAN_INTERVAL)
            first_pass = False
            await _reconcile_external_combined_gemma_rejoins()
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.warning("External Combined Gemma rejoin monitor tick failed", exc_info=True)


def _combined_gemma_ingress_service_name(service_name: str | None) -> str | None:
    """Canonicalize only the logical broker group, preserving concrete pins."""
    if (
        _combined_gemma_broker_enabled()
        and isinstance(service_name, str)
        and service_name.casefold() == _COMBINED_GEMMA_ROUTING_GROUP.casefold()
    ):
        return _COMBINED_GEMMA_ROUTING_GROUP
    return service_name


async def _external_combined_gemma_ingress(
    *, method: str, path: str, body: bytes | None, headers,
):
    """Forward logical ingress to the validated standalone broker endpoint."""
    deployment = _combined_gemma_deployment_config()
    if deployment["mode"] != "external":
        return None
    if session is None or session.closed:
        raise RuntimeError("external Combined Gemma broker session unavailable")

    hop_by_hop = {
        "connection", "keep-alive", "proxy-authenticate", "proxy-authorization",
        "te", "trailer", "transfer-encoding", "upgrade", "host", "content-length",
    }
    forwarded_headers = {
        key: value for key, value in headers.items()
        if key.lower() not in hop_by_hop
    }
    wait_timeout = float(
        _services_config.get("combined_gemma_broker", {}).get("api_wait_timeout", 30.0)
    )
    requested_timeout = headers.get("X-Compat-Timeout") or headers.get("x-compat-timeout")
    if requested_timeout is not None:
        try:
            parsed_timeout = float(requested_timeout)
        except (TypeError, ValueError):
            parsed_timeout = wait_timeout
        if math.isfinite(parsed_timeout) and parsed_timeout > 0:
            wait_timeout = min(600.0, max(1.0, parsed_timeout))
    # The broker owns the terminal wait contract. Keep the outer HTTP
    # transport alive beyond that deadline so event-loop/Redis jitter cannot
    # turn a broker 200/504 into a proxy-generated 503.
    timeout = ClientTimeout(total=max(15.0, wait_timeout + 15.0))
    url = f"{deployment['endpoint']}{path}"
    async with session.request(
        method, url, data=body, headers=forwarded_headers, timeout=timeout,
    ) as response:
        response_body = await response.read()
        response_headers = {
            key: value for key, value in response.headers.items()
            if key.lower() not in hop_by_hop
        }
        return web.Response(
            status=response.status,
            body=response_body,
            headers=response_headers,
        )


async def _maybe_handle_combined_gemma_ingress(
    *, service_name: str | None, method: str, path: str, body: bytes | None, headers,
    request: web.Request | None = None,
):
    """Route only logical ``Gemma`` ingress to the durable broker.

    Returning ``None`` preserves every concrete-service pin and all legacy
    behavior while the feature flag is disabled.  Once enabled, a missing
    broker fails closed instead of falling back to a competing consumer.
    """
    if not _combined_gemma_broker_enabled():
        return None
    if service_name != _COMBINED_GEMMA_ROUTING_GROUP:
        return None
    try:
        deployment = _combined_gemma_deployment_config()
        if deployment["mode"] == "external":
            return await _external_combined_gemma_ingress(
                method=method, path=path, body=body, headers=headers,
            )
    except Exception as exc:
        logger.error("External Combined Gemma ingress failed: %s", exc)
        return web.json_response(
            {
                "error": "combined_gemma_broker_unavailable",
                "code": "combined_gemma_broker_unavailable",
                "retry_after": 5,
            },
            status=503,
        )
    if _combined_gemma_broker is None:
        return web.json_response(
            {
                "error": "combined_gemma_broker_unavailable",
                "code": "combined_gemma_broker_unavailable",
                "retry_after": 5,
            },
            status=503,
        )
    proxy_kwargs = {
        "method": method,
        "path": path,
        "body": body,
        "headers": headers,
    }
    if request is not None:
        proxy_kwargs["request"] = request
    return await _combined_gemma_broker.handle_proxy(**proxy_kwargs)


async def handle_llm_proxy(request: web.Request):
    """Proxy /v1/* to llama.cpp backend. Supports ?service=name or X-Backend header for routing."""
    path = request.path
    method = request.method
    llm.total_requests += 1

    body = None
    if request.can_read_body:
        body = await request.read()

    # Validate model capabilities before routing
    task_hint = request.headers.get("X-Task-Hint", "")
    requested_model = request.query.get("service") or request.headers.get("X-Backend") or ""
    if not requested_model and body:
        try:
            body_json = json.loads(body)
            requested_model = body_json.get("model", "")
        except Exception:
            pass

    if _model_validator and (task_hint or requested_model):
        result = _model_validator.validate(
            requested_model,
            task_hint=task_hint,
            requirements=_extract_requirements(body)
        )
        if not result["ok"]:
            if result["action"] == "upgrade" and result.get("suggested_model"):
                logger.info(f"VALIDATOR: upgrading {requested_model} -> {result['suggested_model']} ({result['reason']})")
                requested_model = result["suggested_model"]
            elif result["action"] == "reject":
                logger.warning(f"VALIDATOR: rejecting {requested_model} ({result['reason']})")
                return web.json_response(
                    {"error": result["reason"], "code": "model_capability_mismatch"},
                    status=422
                )

    # Check for service override (query param or header)
    service_name = request.query.get("service") or request.headers.get("X-Backend")
    # If validator upgraded the model, override service_name
    if not service_name and requested_model and requested_model != (request.query.get("service") or request.headers.get("X-Backend")):
        service_name = requested_model

    service_name = _combined_gemma_ingress_service_name(service_name)

    _combined_response = await _maybe_handle_combined_gemma_ingress(
        service_name=service_name,
        method=method,
        path=path,
        body=body,
        headers=request.headers,
        request=request,
    )
    if _combined_response is not None:
        return _combined_response

    # If X-Backend is a routing group name (not a service), resolve to a service via routing engine
    _routing_group_from_header = ""
    if service_name and service_name not in _services_config.get("services", {}):
        # Check if it's a routing group
        if routing_engine:
            _group_members = routing_engine.get_group_members(service_name)
            if _group_members:
                _routing_group_from_header = service_name
                # Lane-based routing: same depth-based preference policy
                # as handle_submit_job so the proxy path benefits from lanes too.
                _qd = _queue_depth_for_group(service_name)
                _prio = _qd <= _PREFER_PRIORITY_DEPTH_THRESHOLD
                _resolved = routing_engine.find_service_for_group(
                    service_name,
                    queue_depth=_qd,
                    prefer_priority=_prio,
                )
                if _resolved:
                    logger.debug(f"PROXY: X-Backend '{service_name}' resolved to routing group -> service '{_resolved}'")
                    service_name = _resolved
                else:
                    logger.warning(f"PROXY: X-Backend '{service_name}' is a routing group but no service available")
                    service_name = ""

    if service_name:
        svc = _services_config.get("services", {}).get(service_name)
        if svc and svc.get("enabled") and svc.get("type") == "llm_backend":
            gpu_id = svc.get("gpu_id")

            if not gpu_id:
                # CPU-only service (e.g. gemma-vision) — keep direct proxy path
                if svc.get("mutex_group"):
                    try:
                        backend_url = await _ensure_mutex_exclusive(service_name)
                        logger.info(f"PROXY ({service_name}): mutex exclusive, backend={backend_url}")
                    except RuntimeError as e:
                        logger.error(f"PROXY ({service_name}): mutex activation failed: {e}")
                        return web.json_response(
                            {"error": f"Service activation failed: {e}", "retry_after": 10},
                            status=503,
                        )
                else:
                    backend_url = f"http://localhost:{svc['port']}"
                logger.debug(f"PROXY ({service_name}): {method} {path} (CPU direct)")
                return await _forward_llm(method, path, body, request.headers, backend_url=backend_url)

            # GPU-backed LLM service — enqueue into per-GPU queue
            gpu_priority = svc.get("priority", 3)
            gpu_state = _get_gpu_state(gpu_id)

            # Create a Future for this request
            loop = asyncio.get_event_loop()
            request_future = loop.create_future()

            # Check if service is already healthy (fast path)
            port = svc.get("port")
            already_healthy = False
            if port:
                try:
                    async with session.get(
                        f"http://127.0.0.1:{int(port)}/health",
                        timeout=ClientTimeout(total=3),
                    ) as resp:
                        if resp.status == 200:
                            already_healthy = True
                except Exception:
                    pass

            if already_healthy:
                # An explicit service selection is a pin, not a suggestion.
                # Shared routing-group requests still use the Redis queue, but
                # `model`/`service`/`X-Backend` naming a concrete healthy service
                # must execute on that backend.
                if not _routing_group_from_header and requested_model == service_name:
                    logger.info(
                        "PROXY (%s): explicit healthy service; forwarding directly",
                        service_name,
                    )
                    return await _forward_llm(
                        method,
                        path,
                        body,
                        request.headers,
                        backend_url=f"http://localhost:{port}",
                    )
                # Service already running — route through Redis queue if available
                if queue_engine and job_tracker and slot_manager:
                    logger.debug(f"PROXY ({service_name}): {method} {path} (queuing to healthy {service_name})")
                    # Submit to Redis queue and wait for the worker to process it
                    _proxy_job_id = job_tracker.next_job_id()
                    if not _proxy_job_id:
                        # Fallback to direct forward if ID allocation fails
                        return await _forward_llm(method, path, body, request.headers, backend_url=f"http://localhost:{port}")

                    _proxy_headers = {k: v for k, v in request.headers.items()
                                      if k.lower() not in ("host", "content-length", "transfer-encoding")}
                    _proxy_payload = {
                        "job_id": _proxy_job_id,
                        "prompt": "",
                        "messages": "",
                        "max_tokens": "0",
                        "source": "proxy",
                        "model": service_name,
                        "routing_group": svc.get("routing_group", ""),
                        "http_method": method,
                        "http_path": path,
                        "headers": json.dumps(_proxy_headers),
                        "body_b64": __import__("base64").b64encode(body or b"").decode("ascii") if body else "",
                        "priority": int(gpu_priority),
                        "priority_convention": "legacy_lower_is_urgent",
                        "priority_source": "service_config",
                    }

                    _proxy_loop = asyncio.get_event_loop()
                    _proxy_routing_group = svc.get("routing_group", "")
                    logger.info(f"handle_llm_proxy: enqueueing job_id={_proxy_job_id} routing_group={_proxy_routing_group} service_name={service_name}")
                    _proxy_entry = await _proxy_loop.run_in_executor(
                        None, lambda args: queue_engine.enqueue(*args),
                        (service_name, _proxy_payload, _proxy_routing_group)
                    )
                    if _proxy_entry:
                        llm.durable_queue_admissions += 1
                        llm.total_queued += 1
                        logger.info(f"handle_llm_proxy: enqueued job_id={_proxy_job_id} entry_id={_proxy_entry}")
                    if not _proxy_entry:
                        return await _forward_llm(method, path, body, request.headers, backend_url=f"http://localhost:{port}")

                    job_tracker.create_job(
                        job_id=_proxy_job_id,
                        service_name=service_name,
                        source="proxy",
                        prompt=f"{method} {path}",
                        max_tokens=0,
                        routing_group=svc.get("routing_group", ""),
                        priority=int(gpu_priority),
                    )
                    job_tracker.update_status(_proxy_job_id, "queued", entry_id=_proxy_entry)

                    # Poll until the job is completed/failed or timeout
                    _poll_start = time.monotonic()
                    _poll_timeout = 600  # 10 minutes max
                    while time.monotonic() - _poll_start < _poll_timeout:
                        _jstate = await _proxy_loop.run_in_executor(None, job_tracker.get_job, _proxy_job_id)
                        if not _jstate:
                            break
                        _js = _jstate.get("status", "")
                        if _js in ("completed", "failed", "cancelled"):
                            if _js == "completed":
                                _result_raw = _jstate.get("result", "")
                                # Backward compat: old envelope format {status, body, content_type}
                                try:
                                    _result_data = json.loads(_result_raw)
                                    if isinstance(_result_data, dict) and "body" in _result_data and "content_type" in _result_data:
                                        return web.Response(
                                            status=_result_data.get("status", 200),
                                            text=_result_data.get("body", ""),
                                            content_type=_result_data.get("content_type", "application/json"),
                                        )
                                except (json.JSONDecodeError, TypeError):
                                    pass
                                # New format — raw passthrough (already JSON from converter)
                                return web.Response(
                                    status=200,
                                    text=_result_raw,
                                    content_type="application/json",
                                )
                            else:
                                _err = _jstate.get("error", "Job failed")
                                return web.json_response({"error": _err}, status=502)
                        await asyncio.sleep(0.1)

                    # Timeout — return error
                    job_tracker.update_status(_proxy_job_id, "failed", error="proxy poll timeout")
                    return web.json_response({"error": "Queue timeout", "retry_after": 30}, status=503)
                else:
                    # No queue engine — direct forward (backward compat)
                    logger.debug(f"PROXY ({service_name}): {method} {path} (direct, no queue engine)")
                    return await _forward_llm(method, path, body, request.headers, backend_url=f"http://localhost:{port}")

            # Service not running — enqueue and wait for scheduler to start it
            llm.queued_requests += 1
            llm.total_queued += 1
            llm.active_requests += 1  # Prevent idle manager from swapping while we wait
            logger.info(
                f"PROXY ({service_name}): enqueueing into GPU {gpu_id} queue "
                f"(priority={gpu_priority}, queue_depth={len(gpu_state.priority_queue)})"
            )

            # Enqueue into per-GPU queue with llm backend
            enqueue_entry_request_data = {
                "backend": "llm",
                "service_name": service_name,
                "future": request_future,
                "method": method,
                "path": path,
                "body": body,
                "headers": dict(request.headers),
            }
            gpu_state.enqueue(
                bundle_name=f"llm:{service_name}",
                priority=gpu_priority,
                request_data=enqueue_entry_request_data,
            )
            llm.durable_queue_admissions += 1

            # Signal the scheduler to process per-GPU queues
            if scheduler:
                scheduler._idle_check_event.set()

            try:
                # Wait for the scheduler to start the service and resolve our future
                result = await asyncio.wait_for(request_future, timeout=300)
                # Service is ready — forward the actual LLM request
                result_port = result.get("port") if isinstance(result, dict) else port
                backend_url = f"http://localhost:{result_port}"
                logger.debug(f"PROXY ({service_name}): {method} {path} (queued, now ready)")
                return await _forward_llm(method, path, body, request.headers, backend_url=backend_url)
            except asyncio.TimeoutError:
                logger.warning(f"PROXY ({service_name}): timeout waiting for GPU queue (300s)")
                return web.json_response(
                    {"error": f"Service {service_name} timed out waiting for GPU queue", "retry_after": 30},
                    status=503,
                )
            except RuntimeError as e:
                logger.error(f"PROXY ({service_name}): queue processing failed: {e}")
                return web.json_response(
                    {"error": f"Service activation failed: {e}", "retry_after": 10},
                    status=503,
                )
            except Exception as e:
                logger.error(f"PROXY ({service_name}): unexpected error: {e}")
                return web.json_response(
                    {"error": f"Service error: {e}", "retry_after": 10},
                    status=503,
                )
            finally:
                llm.queued_requests -= 1
                llm.active_requests -= 1

        # Check providers.json for cloud provider
        cloud_providers = _providers_config.get("providers", {})
        if service_name in cloud_providers and cloud_providers[service_name].get("type") == "cloud":
            return await _route_to_cloud(method, path, body, request.headers, cloud_providers[service_name])

        # Check providers.json for local mesh instances
        local_instances = cloud_providers.get("local", {}).get("instances", {})
        if service_name in local_instances:
            inst = local_instances[service_name]
            backend_url = f"http://{inst['host']}:{inst['port']}"
            return await _forward_remote(method, path, body, request.headers, backend_url)

    # Default: use configured LLM backend with health/queue logic
    # If queue engine is available and LLM is healthy, route through queue
    # Phase 5.2.53 Fix A: fail-fast when generation is pinned and LLM is offline.
    # Without this guard, requests enqueue into queue:LLM-Primary but the
    # scheduler re-enqueues the LLM start forever (worker_in_flight=1 from
    # comfyui). Each request waits LLM_WAIT_TIMEOUT=120s then 503s.
    # If the user explicitly wants to race the pin they should use
    # ?service=LLM-Primary (handled earlier in this function).
    if llm._llm_healthy is False:
        _scheduling_cfg = _services_config.get("scheduling", {})
        _pinned = _scheduling_cfg.get("pinned_service", "") or ""
        if _pinned in ("comfyui", "acestep"):
            logger.debug(
                f"PROXY: rejecting default-LLM request — pinned={_pinned}, LLM offline"
            )
            return web.json_response(
                {
                    "error": "LLM unavailable while generation is pinned",
                    "retry_after": 60,
                    "pinned_service": _pinned,
                },
                status=503,
            )
    if llm._llm_healthy:
        if queue_engine and job_tracker and slot_manager:
            # Phase 5.2.80 R3a: use the existing combined-gemma-proxy
            # routing_group _COMBINED_GEMMA_ROUTING_GROUP (which gpu-manager already knows
            # about via routing_engine.get_group_members) instead of
            # hardcoding "LLM-Primary" as the default service. The
            # combined-proxy infrastructure (port 8095 + X-Backend:
            # Gemma) handles all of this automatically: it finds
            # whichever gemma service is currently configured and
            # available, regardless of which GPU hosts gemma. This
            # also fixes the cold-start bug where the module-global
            # _services_config starts as an empty module-global cache and
            # handle_llm_proxy previously read it without calling
            # _load_services_config(). Use a non-shadowing local name to avoid
            # breaking earlier reads of the module-global _services_config
            # elsewhere in this function.
            _dp_services_config = _load_services_config()
            _proxy_job_id = job_tracker.next_job_id()
            if _proxy_job_id:
                _proxy_headers = {k: v for k, v in request.headers.items()
                                  if k.lower() not in ("host", "content-length", "transfer-encoding")}
                _default_svc_name = _COMBINED_GEMMA_ROUTING_GROUP  # the routing group, not a service
                _dp_routing_group = _COMBINED_GEMMA_ROUTING_GROUP
                # Phase 5.2.80 R3c: the empty-string placeholders below
                # (`"prompt": ""`, `"messages": ""`, `"max_tokens": "0"`)
                # are NOT the LLM input. They are bookkeeping fields read
                # by job_tracker.create_job() below for display
                # labels only. The worker in _execute_job reads
                # `body_b64` and forwards those bytes verbatim to the backend
                # HTTP endpoint — that is the actual LLM input. If a reviewer
                # sees an empty prompt and worries the worker might LLM-process
                # empty content, the answer is: the worker doesn't read these
                # fields. body_b64 is the channel. llama-server itself rejects
                # empty bodies with HTTP 400 if body_b64 is "" — no spurious
                # inference happens.
                _proxy_payload = {
                    "job_id": _proxy_job_id,
                    "prompt": "",
                    "messages": "",
                    "max_tokens": "0",
                    "source": "proxy-direct",
                    "model": _COMBINED_GEMMA_ROUTING_GROUP,
                    "routing_group": _dp_routing_group,
                    "http_method": method,
                    "http_path": path,
                    "headers": json.dumps(_proxy_headers),
                    "body_b64": __import__("base64").b64encode(body or b"").decode("ascii") if body else "",
                }
                _dp_loop = asyncio.get_event_loop()
                logger.info(f"handle_llm_proxy: enqueueing job_id={_proxy_job_id} routing_group={_dp_routing_group} service_name={_default_svc_name}")
                _proxy_entry = await _dp_loop.run_in_executor(
                    None, lambda args: queue_engine.enqueue(*args),
                    (_default_svc_name, _proxy_payload, _dp_routing_group)
                )
                if _proxy_entry:
                    llm.durable_queue_admissions += 1
                    llm.total_queued += 1
                    logger.info(f"handle_llm_proxy: enqueued job_id={_proxy_job_id} entry_id={_proxy_entry}")
                    job_tracker.create_job(
                        job_id=_proxy_job_id,
                        service_name=_default_svc_name,
                        source="proxy-direct",
                        prompt=f"{method} {path}",
                        max_tokens=0,
                    )
                    job_tracker.update_status(_proxy_job_id, "queued", entry_id=_proxy_entry)

                    _poll_start = time.monotonic()
                    _poll_timeout = 600
                    while time.monotonic() - _poll_start < _poll_timeout:
                        _jstate = await _dp_loop.run_in_executor(None, job_tracker.get_job, _proxy_job_id)
                        if not _jstate:
                            break
                        _js = _jstate.get("status", "")
                        if _js in ("completed", "failed", "cancelled"):
                            if _js == "completed":
                                _result_raw = _jstate.get("result", "")
                                # Backward compat: old envelope format {status, body, content_type}
                                try:
                                    _result_data = json.loads(_result_raw)
                                    if isinstance(_result_data, dict) and "body" in _result_data and "content_type" in _result_data:
                                        return web.Response(
                                            status=_result_data.get("status", 200),
                                            text=_result_data.get("body", ""),
                                            content_type=_result_data.get("content_type", "application/json"),
                                        )
                                except (json.JSONDecodeError, TypeError):
                                    pass
                                # New format — raw passthrough (already JSON from converter)
                                return web.Response(
                                    status=200,
                                    text=_result_raw,
                                    content_type="application/json",
                                )
                            else:
                                _err = _jstate.get("error", "Job failed")
                                return web.json_response({"error": _err}, status=502)
                        await asyncio.sleep(0.1)
                    job_tracker.update_status(_proxy_job_id, "failed", error="proxy-direct poll timeout")
                    return web.json_response({"error": "Queue timeout", "retry_after": 30}, status=503)
        # Fallback: direct forward (no queue engine or job ID failure)
        logger.debug(f"PROXY (direct): {method} {path}")
        return await _forward_llm(method, path, body, request.headers)

    llm.queued_requests += 1
    llm.wait_attempts += 1
    logger.info(f"PROXY (waiting for idle route): {method} {path} [waiters: {llm.queued_requests}]")

    try:
        ready = await llm.wait_for_llm(timeout=LLM_WAIT_TIMEOUT)
        if not ready:
            llm.wait_timeouts += 1
            llm.total_timeouts += 1
            return web.json_response(
                {"error": "LLM temporarily unavailable", "retry_after": 30},
                status=503,
            )
        return await _forward_llm(method, path, body, request.headers)
    finally:
        llm.queued_requests -= 1


_FORWARD_LLM_STRIPPED_HEADERS = frozenset(
    {
        # Credentials that must not leak past this controller.
        "authorization",
        "cookie",
        "proxy-authorization",
        "x-api-key",
        # Hop-by-hop headers that aiohttp / the upstream will set from
        # the outgoing request itself; echoing caller-supplied values
        # either contradicts the framework's framing or smuggles
        # transport-layer controls past the public boundary.
        "host",
        "content-length",
        "transfer-encoding",
        "connection",
        "upgrade",
        "keep-alive",
        "proxy-authenticate",
        "proxy-connection",
        "te",
        "trailers",
        "trailer",
        "expect",
    }
)


async def _forward_llm(method: str, path: str, body: bytes | None, headers: dict, backend_url: str = None) -> web.Response:
    llm.active_requests += 1
    llm.forward_attempts += 1
    url = f"{backend_url or LLM_BACKEND_URL}{path}"
    try:
        # Strip both caller-supplied credential headers AND hop-by-hop
        # transport headers so a malicious upstream cannot impersonate
        # the controller via headers smuggled on a forwarded request.
        fwd_headers = {
            key: value
            for key, value in headers.items()
            if isinstance(key, str) and key.lower() not in _FORWARD_LLM_STRIPPED_HEADERS
        }
        async with session.request(
            method=method, url=url,
            data=body, headers=fwd_headers,
            timeout=ClientTimeout(total=600),
        ) as resp:
            resp_body = await resp.read()
            llm.backend_responses += 1
            llm.total_served += 1
            if resp.status < 500:
                llm.backend_successes += 1
            else:
                llm.backend_failures += 1
            response = web.Response(status=resp.status, body=resp_body)
            if "content-type" in resp.headers:
                response.content_type = resp.headers["content-type"]
            return response
    except Exception as e:
        llm.backend_failures += 1
        logger.error(f"LLM proxy error ({url}): {e}")
        return web.json_response({"error": f"LLM backend error: {e}"}, status=502)
    finally:
        llm.active_requests -= 1


async def _forward_remote(method, path, body, headers, backend_url, timeout=300):
    """Forward request to a remote LLM backend on the tailnet mesh."""
    url = f"{backend_url.rstrip('/')}{path}"
    fwd_headers = {"Content-Type": "application/json"}
    try:
        async with session.request(
            method, url, data=body,
            headers=fwd_headers,
            timeout=ClientTimeout(total=timeout),
        ) as resp:
            resp_body = await resp.read()
            response = web.Response(status=resp.status, body=resp_body)
            if "content-type" in resp.headers:
                response.content_type = resp.headers["content-type"]
            return response
    except Exception as e:
        logger.error(f"Remote proxy error ({url}): {e}")
        return web.json_response({"error": f"Remote backend error: {e}"}, status=502)


async def _route_to_cloud(method, path, body, headers, provider_config):
    """Route request to a cloud provider API endpoint."""
    api_base = provider_config.get("api_base", "")
    env_var = provider_config.get("env_var", "")
    api_key = os.environ.get(env_var, "")

    if not api_key:
        return web.json_response(
            {"error": f"No API key configured for provider (${env_var} not set)"},
            status=502
        )

    url = f"{api_base.rstrip('/')}/chat/completions"
    try:
        async with session.post(
            url, data=body,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {api_key}"
            },
            timeout=ClientTimeout(total=300)
        ) as resp:
            resp_body = await resp.read()
            response = web.Response(status=resp.status, body=resp_body)
            if "content-type" in resp.headers:
                response.content_type = resp.headers["content-type"]
            return response
    except Exception as e:
        logger.error(f"Cloud proxy error ({url}): {e}")
        return web.json_response({"error": f"Cloud backend error: {e}"}, status=502)


# ── ComfyUI Direct Handlers ────────────────────────────────────────

async def handle_comfyui_status(request: web.Request):
    """GET /comfyui/status"""
    try:
        async with session.get(f"{COMFYUI_URL}/queue") as resp:
            queue = await resp.json()
        return web.json_response({
            "running": len(queue.get("queue_running", [])),
            "pending": len(queue.get("queue_pending", [])),
        })
    except Exception as e:
        return web.json_response({"error": str(e)}, status=502)


async def handle_comfyui_free(request: web.Request):
    """POST /comfyui/free — manual free."""
    try:
        async with session.post(
            f"{COMFYUI_URL}/free",
            json={"unload_models": True, "free_memory": True},
        ) as resp:
            return web.json_response({"status": "ok", "http_code": resp.status})
    except Exception as e:
        return web.json_response({"error": str(e)}, status=502)


# ── Pipeline Batch Queue Handlers ──────────────────────────────────

_PIPELINE_RUN_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$")


def _resolve_pipeline_run_id(raw: Any = None, *, generate: bool = False) -> str:
    """Return a path-safe pipeline identity or fail before any side effect.

    The compatibility pipeline still writes logs and artifacts under the
    project tree.  Keep that legacy route from turning a caller-controlled
    ``run_id`` into a path traversal, and do not use a second-resolution
    timestamp that can launch two jobs into the same output directory.
    """
    if raw is None and generate:
        return f"fader-{time.time_ns()}-{uuid.uuid4().hex[:8]}"
    if not isinstance(raw, str) or not raw or not _PIPELINE_RUN_ID_RE.fullmatch(raw):
        raise ValueError(
            "run_id must be 1-128 characters using letters, digits, '-' or '_' "
            "and must start with a letter or digit"
        )
    return raw

async def handle_pipeline_trigger(request: web.Request):
    """POST /pipeline/trigger — Start pipeline-orchestrator.py in background."""
    _owner_fence = _queue_owner_route_fence('legacy', '/pipeline/trigger')
    if _owner_fence is not None:
        return _owner_fence
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON body"}, status=400)

    if not isinstance(data, Mapping):
        return web.json_response({"error": "JSON body must be an object"}, status=400)

    topic = data.get("topic")
    if not topic:
        return web.json_response({"error": "Missing 'topic'"}, status=400)

    import subprocess as _sp

    try:
        run_id = _resolve_pipeline_run_id(data.get("run_id"), generate=True)
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    duration = str(data.get("duration", 30))
    style = data.get("style", "informative")
    tts = data.get("tts", "edge")
    skip_llm = data.get("skip_llm", False)
    bgm = data.get("bgm", False)

    pipeline_script = str(PROJECT_ROOT / "scripts/pipeline-orchestrator.py")
    venv_python = os.environ.get(
        "GPU_MANAGER_PIPELINE_PYTHON", str(PROJECT_ROOT / ".venv/bin/python3")
    )
    log_dir = str(LOG_DIR)
    os.makedirs(log_dir, exist_ok=True)

    cmd = [
        venv_python, pipeline_script,
        "--topic", topic,
        "--duration", duration,
        "--style", style,
        "--tts", tts,
        "--run-id", run_id,
    ]
    if skip_llm:
        cmd.append("--skip-llm")
    if not bgm:
        cmd.append("--no-bgm")
    cmd.append("--json")

    log_path = os.path.join(log_dir, f"pipeline-{run_id}.log")

    try:
        # Popen duplicates the descriptor for the child; close the parent's
        # handle immediately so a compatibility request cannot leak one per
        # background pipeline.
        with open(log_path, "w") as log_f:
            _sp.Popen(cmd, stdout=log_f, stderr=_sp.STDOUT, start_new_session=True)
    except Exception as e:
        return web.json_response({"error": f"Failed to start pipeline: {e}"}, status=500)

    return web.json_response({
        "run_id": run_id,
        "status": "started",
        "topic": topic,
        "duration": int(duration),
        "log": log_path,
        "poll_result": f"/pipeline/trigger/{run_id}/status",
    }, status=201)


async def handle_pipeline_trigger_status(request: web.Request):
    """GET /pipeline/trigger/{run_id}/status"""
    try:
        run_id = _resolve_pipeline_run_id(request.match_info["run_id"])
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    result_path = str(PROJECT_ROOT / "output" / run_id / f"{run_id}_result.json")

    if os.path.exists(result_path):
        with open(result_path) as f:
            return web.json_response(json.load(f))
    else:
        run_dir = str(PROJECT_ROOT / "output" / run_id)
        if os.path.isdir(run_dir):
            return web.json_response({"run_id": run_id, "status": "running"})
        return web.json_response({"run_id": run_id, "status": "not_found"}, status=404)


async def _submit_durable_pipeline_compat(request: web.Request):
    """Translate the legacy pipeline submit shape into the durable queue.

    This is deliberately a narrow compatibility adapter: the caller may
    provide a sanitized ComfyUI graph, but endpoint, routing group, bundle and
    protocol are selected from the server registry.  Execution then follows
    the same WorkerPool/ComfyUI path as `/v1/submit/generation`.
    """
    if not queue_engine or not job_tracker:
        return web.json_response({"error": "Queue engine not available"}, status=503)
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON body"}, status=400)
    if not isinstance(data, Mapping):
        return web.json_response({"error": "JSON body must be an object"}, status=400)

    workflow = data.get("workflow") or data.get("prompt")
    if not isinstance(workflow, Mapping):
        return web.json_response(
            {"error": "Missing 'workflow' object"}, status=400
        )
    from comfyui_workflow_sanitize import sanitize_comfyui_workflow
    workflow = sanitize_comfyui_workflow(
        workflow, source="durable_pipeline_compat"
    )

    cfg = _load_services_config() or {}
    services = cfg.get("services", {}) or {}
    comfy_cfg = services.get("comfyui", {}) if isinstance(services, Mapping) else {}
    if not isinstance(comfy_cfg, Mapping):
        comfy_cfg = {}
    if (
        not comfy_cfg
        or comfy_cfg.get("enabled") is not True
        or comfy_cfg.get("type") not in {"generation_backend", "generation"}
    ):
        return web.json_response(
            {
                "error": "durable ComfyUI compatibility backend unavailable",
                "reason": "comfyui_backend_not_registered",
            },
            status=503,
        )

    # Prefer a server-declared ComfyUI template's routing/bundle contract;
    # never accept those fields from the compatibility request itself.
    declared_template = None
    templates = cfg.get("generation_templates", {}) or {}
    if isinstance(templates, Mapping):
        for _name, _candidate in templates.items():
            if not isinstance(_candidate, Mapping):
                continue
            if _candidate.get("backend") == "comfyui":
                declared_template = _candidate
                break
    declared_template = declared_template or {}
    routing_group = (
        declared_template.get("routing_group")
        or comfy_cfg.get("routing_group")
        or "comfyui-gen"
    )
    bundle = declared_template.get("bundle") or comfy_cfg.get("bundle") or ""
    endpoint = (
        comfy_cfg.get("endpoint")
        or comfy_cfg.get("base_url")
        or COMFYUI_URL
    )
    request_path = comfy_cfg.get("http_path") or "/prompt"
    metadata = data.get("metadata", {})
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, Mapping):
        return web.json_response({"error": "metadata must be an object"}, status=400)
    metadata = {
        **dict(metadata),
        "compatibility_route": "/pipeline/submit",
        "workflow_timeout_s": 900,
    }
    try:
        priority = int(data.get("priority", 5))
    except (TypeError, ValueError):
        return web.json_response({"error": "priority must be an integer"}, status=400)

    compat_template = {
        "workflow": copy.deepcopy(dict(workflow)),
        "backend": "comfyui",
        "workflow_backend": "comfyui",
        "routing_group": str(routing_group),
        "bundle": str(bundle) if bundle else None,
        "endpoint": str(endpoint),
        "request_path": str(request_path),
        "timeout": 900,
    }
    try:
        entry, error = await _build_comfyui_workflow_entry(
            service_name="comfyui",
            tmpl=compat_template,
            params={},
            job_id=str(uuid.uuid4())[:8],
            priority=priority,
            callback_url=data.get("callback_url"),
            metadata=metadata,
        )
    except Exception as exc:
        logger.exception("durable pipeline compatibility entry build failed")
        return web.json_response(
            {"error": f"workflow admission failed: {exc}"}, status=503
        )
    if error or entry is None:
        return web.json_response(
            error or {"error": "workflow admission failed"},
            status=int((error or {}).get("status", 503)),
        )

    job_id = entry["job_id"]
    try:
        created = job_tracker.create_job(
            job_id=job_id,
            service_name="comfyui",
            source="pipeline_compat",
            prompt="legacy pipeline workflow",
            max_tokens=0,
            routing_group=entry.get("routing_group", ""),
            priority=entry.get("priority"),
            priority_class=entry.get("priority_class"),
            broker_priority=entry.get("broker_priority"),
            priority_convention=entry.get("priority_convention"),
            priority_source="request",
        )
    except Exception as exc:
        logger.exception("durable pipeline compatibility job creation failed")
        return web.json_response({"error": str(exc)}, status=503)
    if created is None:
        return web.json_response(
            {"error": "Failed to persist durable compatibility job"}, status=503
        )

    _acquire_comfyui_admission(job_id)
    loop = asyncio.get_event_loop()
    try:
        entry_id = await loop.run_in_executor(
            None,
            queue_engine.enqueue,
            "comfyui",
            entry,
            entry.get("routing_group"),
        )
    except Exception as exc:
        logger.exception("durable pipeline compatibility enqueue failed")
        job_tracker.update_status(job_id, "failed", error=str(exc))
        _release_comfyui_admission(job_id)
        return web.json_response({"error": "Failed to enqueue"}, status=503)
    if not entry_id:
        job_tracker.update_status(job_id, "failed", error="queue enqueue failed")
        _release_comfyui_admission(job_id)
        return web.json_response({"error": "Failed to enqueue"}, status=503)

    workflow_sha256 = hashlib.sha256(
        json.dumps(workflow, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    _update_fields = getattr(job_tracker, "update_fields", None)
    if callable(_update_fields):
        _update_fields(
            job_id,
            entry_id=entry_id,
            workflow_sha256=workflow_sha256,
        )
    else:
        # Narrow compatibility fallback for old tracker doubles/releases;
        # production JobTracker has the status-preserving method above.
        job_tracker.update_status(
            job_id,
            "queued",
            entry_id=entry_id,
            workflow_sha256=workflow_sha256,
        )
    try:
        position = await loop.run_in_executor(
            None,
            queue_engine.get_queue_depth,
            "comfyui",
            entry.get("routing_group"),
        )
    except Exception:
        position = None
    return web.json_response(
        {
            "job_id": job_id,
            "entry_id": entry_id,
            "model_key": "comfyui-compat",
            "routing_group": entry.get("routing_group"),
            "position": position,
            "status": "queued",
            "queue_owner": "durable",
        },
        status=201,
    )


async def _durable_pipeline_queue_status():
    """Return the compatibility view over durable pipeline job records."""
    if not job_tracker or not queue_engine:
        return web.json_response({"error": "Queue engine not available"}, status=503)
    loop = asyncio.get_event_loop()
    try:
        records = await loop.run_in_executor(
            None, job_tracker.get_jobs_by_source, "pipeline_compat"
        )
    except Exception as exc:
        return web.json_response({"error": str(exc)}, status=503)

    def _text(value):
        if isinstance(value, bytes):
            return value.decode("utf-8", errors="replace")
        return value

    jobs = []
    for raw in records or []:
        if not isinstance(raw, Mapping):
            continue
        row = {str(_text(k)): _text(v) for k, v in raw.items()}
        if row.get("status") in {"queued", "in_flight", "running"}:
            jobs.append(row)
    routing_groups = sorted(
        {
            str(row.get("routing_group"))
            for row in jobs
            if row.get("routing_group")
        }
        or {"comfyui-gen"}
    )
    queue_depths = {}
    for routing_group in routing_groups:
        try:
            queue_depths[routing_group] = await loop.run_in_executor(
                None, queue_engine.get_queue_depth, "comfyui", routing_group
            )
        except Exception:
            queue_depths[routing_group] = None
    known_depths = [value for value in queue_depths.values() if isinstance(value, int)]
    durable = globals().get("worker_supervisor")
    return web.json_response(
        {
            "queue_owner": "durable",
            "scheduler_running": False,
            "worker_supervisor_running": bool(
                durable is not None
                and (
                    getattr(durable, "_running", False)
                    or getattr(durable, "running", False)
                )
            ),
            "queue_depth": sum(known_depths) if len(known_depths) == len(queue_depths) else None,
            "queue_depths": queue_depths,
            "jobs": jobs,
        }
    )


async def handle_pipeline_submit(request: web.Request):
    """POST /pipeline/submit — Queue a ComfyUI workflow for batch execution."""
    _owner_fence = _queue_owner_route_fence('legacy', '/pipeline/submit')
    if _owner_fence is not None:
        if _queue_owner_mode() == 'durable':
            return await _submit_durable_pipeline_compat(request)
        return _owner_fence
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON body"}, status=400)

    workflow = data.get("workflow") or data.get("prompt")
    if not workflow:
        return web.json_response({"error": "Missing 'workflow' field"}, status=400)

    # Phase 5.2.79 (R2): sanitize raw workflow from external callers. Without
    # this, any _meta docstring the caller embeds reaches /prompt unchanged
    # and ComfyUI returns 200 + "missing_node_type" on the _meta key.
    from comfyui_workflow_sanitize import sanitize_comfyui_workflow
    workflow = sanitize_comfyui_workflow(workflow, source="handle_pipeline_submit")

    priority = data.get("priority", 5)
    callback_url = data.get("callback_url")
    metadata = data.get("metadata", {})

    job = scheduler.submit_comfyui(workflow, callback_url, priority, metadata)

    pending = sum(1 for j in scheduler._comfyui_queue if j.status == "queued")
    pending += sum(1 for j in scheduler._acestep_queue if j.status == "queued")

    return web.json_response({
        "job_id": job.id,
        "model_key": job.model_key,
        "fingerprint": job.fingerprint,
        "position": pending,
        "status": job.status,
    }, status=201)


async def handle_pipeline_queue(request: web.Request):
    """GET /pipeline/queue — View queued jobs and current batch."""
    _owner_fence = _queue_owner_route_fence('legacy', '/pipeline/queue')
    if _owner_fence is not None:
        if _queue_owner_mode() == 'durable':
            return await _durable_pipeline_queue_status()
        return _owner_fence
    status = scheduler.get_queue_status()

    # Include job details
    details = []
    for j in scheduler._comfyui_queue:
        if j.status in ("queued", "running"):
            details.append(j.to_dict())
    for j in scheduler._acestep_queue:
        if j.status in ("queued", "running"):
            details.append(j.to_dict())

    status["jobs"] = details
    return web.json_response(status)


async def handle_pipeline_job(request: web.Request):
    """GET /pipeline/job/{job_id} — Get status of a specific job."""
    _owner_fence = _queue_owner_route_fence('legacy', '/pipeline/job/{job_id}')
    if _owner_fence is not None:
        if _queue_owner_mode() == 'durable':
            return await handle_get_job(request)
        return _owner_fence
    job_id = request.match_info["job_id"]
    job = scheduler.get_job(job_id)
    if not job:
        return web.json_response({"error": "Job not found"}, status=404)
    return web.json_response(job.to_dict())


async def handle_pipeline_cancel(request: web.Request):
    """POST /pipeline/cancel — Cancel a job."""
    _owner_fence = _queue_owner_route_fence('legacy', '/pipeline/cancel')
    if _owner_fence is not None:
        if _queue_owner_mode() == 'durable':
            try:
                data = await request.json()
                job_id = data.get("job_id") if isinstance(data, Mapping) else None
            except Exception:
                job_id = request.query.get("job_id")
            if not job_id:
                return web.json_response({"error": "Missing job_id"}, status=400)
            # MatchInfo is mutable in aiohttp; assigning the compatibility
            # body ID lets the existing durable cancellation primitive handle
            # queued-vs-in-flight races and release accounting exactly once.
            try:
                request.match_info["job_id"] = str(job_id)
            except Exception:
                return web.json_response(
                    {"error": "durable cancellation route unavailable"}, status=503
                )
            return await handle_cancel_job(request)
        return _owner_fence
    try:
        data = await request.json()
        job_id = data.get("job_id")
    except Exception:
        job_id = request.query.get("job_id")

    if not job_id:
        return web.json_response({"error": "Missing job_id"}, status=400)

    if scheduler.cancel(job_id):
        return web.json_response({"status": "cancelled", "job_id": job_id})
    return web.json_response({"error": "Job not found or not cancellable"}, status=404)


# ── VRAM Lifecycle Handlers ────────────────────────────────────────


async def handle_vram_list(request: web.Request):
    """GET /vram — List all GPUs with VRAM info and processes."""
    try:
        snapshot = await _poll_vram()
        gpus = copy.deepcopy(snapshot.get("gpus", []))
        has_gpu_procs = any(gpu.get("processes") for gpu in gpus)

        result = {
            'gpus': gpus,
            'system_ram': await asyncio.get_event_loop().run_in_executor(None, _read_system_ram),
            'timestamp': time.time(),
        }
        # Always include top-level processes from /proc for per-process RAM breakdown
        # (even when GPU processes exist, so consumers see system services like docker, wireguard, etc.)
        try:
            proc_result = await _get_proc_list()
            result['processes'] = proc_result.get('processes', [])
        except Exception:
            result['processes'] = []

        _apply_runtime_semantics(result)
        return web.json_response(result)
    except Exception as e:
        return web.json_response({'error': str(e)}, status=500)


async def _get_proc_list() -> dict:
    """Get top processes by RAM usage with RSS in MiB (shared helper)."""
    import subprocess
    loop = asyncio.get_event_loop()
    result = await loop.run_in_executor(
        None,
        lambda: subprocess.run(
            ['ps', 'aux', '--sort=-rss'],
            capture_output=True, text=True, timeout=5
        )
    )
    lines = result.stdout.strip().split('\n')
    processes = []
    if len(lines) > 1:
        for line in lines[1:21]:  # Top 20 processes
            parts = line.split(None, 10)
            if len(parts) >= 11:
                try:
                    rss_kb = float(parts[5])
                    proc_name = parts[10][:50]
                    # Categorize process
                    name_lower = proc_name.lower()
                    category = 'other'
                    if any(kw in name_lower for kw in ('llama', 'nomic', 'embed', 'ollama', 'vllm', 'text-generation')):
                        category = 'llm'
                    elif 'python' in name_lower:
                        category = 'python'
                    elif proc_name in ('plasmashell', 'kwin_wayland', 'Xwayland', 'chromium', 'alacritty'):
                        category = 'desktop'
                    processes.append({
                        'name': proc_name,
                        'pid': int(parts[1]),
                        'cpu_pct': float(parts[2]),
                        'ram_mib': round(rss_kb / 1024, 1),
                        'category': category,
                    })
                except (ValueError, IndexError):
                    continue
    return {
        'processes': processes,
        'system_ram': _read_system_ram(),
        'timestamp': time.time()
    }


async def handle_proc_list(request: web.Request):
    """GET /proc — List top processes by RAM usage with RSS in MiB."""
    try:
        return web.json_response(await _get_proc_list())
    except Exception as e:
        return web.json_response({'error': str(e), 'processes': []}, status=500)


async def handle_vram_evict(request: web.Request):
    """Reject direct eviction; queue admission owns GPU lifecycle."""
    return web.json_response(
        {
            "error": "controller_admission_required",
            "operation": "evict_llm",
            "message": "submit work through queue admission; direct eviction is disabled",
        },
        status=409,
    )


async def handle_vram_restore(request: web.Request):
    """Reject direct restoration; controller admission owns GPU lifecycle."""
    return web.json_response(
        {
            "error": "controller_admission_required",
            "operation": "restore_llm",
            "message": "restore through controller admission; direct restoration is disabled",
        },
        status=409,
    )


async def handle_comfyui_stop(request: web.Request):
    """POST /vram/stop-comfyui — Stop ComfyUI to give Qwen3.6 full VRAM."""
    if not vram:
        return web.json_response({"error": "VRAM manager not initialized"}, status=500)
    success = await vram.stop_comfyui(reason="api_request")
    if success:
        return web.json_response({"status": "comfyui_stopped", **vram.status()})
    return web.json_response({"error": "Failed to stop ComfyUI"}, status=500)


async def handle_comfyui_start(request: web.Request):
    """POST /vram/start-comfyui — Start ComfyUI after LLM work is done."""
    if not vram:
        return web.json_response({"error": "VRAM manager not initialized"}, status=500)
    success = await vram.start_comfyui(reason="api_request")
    if success:
        return web.json_response({"status": "comfyui_started", **vram.status()})
    return web.json_response({"error": "Failed to start ComfyUI"}, status=500)


async def handle_vram_evict_for(request: web.Request):
    """POST /vram/evict-for/{needed_mib} — Evict lowest-priority services to free needed VRAM."""
    try:
        needed_mib = int(request.match_info["needed_mib"])
    except ValueError:
        return web.json_response({"error": "needed_mib must be an integer"}, status=400)

    if not vram:
        return web.json_response({"error": "VRAM manager not initialized"}, status=500)

    evicted = await vram.evict_for_vram(needed_mib)
    return web.json_response({
        "needed_mib": needed_mib,
        "evicted": evicted,
        "vram_status": vram.status(),
    })


