TTS_VOICE_REFERENCES = {
    "fader": {"audio": "clank-orvus-17-21.wav", "reference_text": "I... Do not understand, have I been here before?"},
    "narrator": {"audio": "clank-orvus-17-21.wav", "reference_text": "I... Do not understand, have I been here before?"},
}


def _build_workflow(gen_type: str, params: dict) -> dict:
    """Load a workflow template and inject parameters into the correct nodes."""
    template_info = GENERATION_TEMPLATES.get(gen_type)
    if not template_info:
        raise ValueError(f"Unknown generation type: {gen_type}. "
                         f"Available: {list(GENERATION_TEMPLATES.keys())}")

    with open(template_info["template"]) as f:
        workflow = json.load(f)

    # Phase 5.2.79 (R2): sanitize at the entry of every code path that loads
    # a workflow from disk. Defends against future _meta additions to any
    # template file; the dispatcher (handle_generate non-image branches,
    # MCP submit_generation BLOCKER-1 fallback) all funnel through here.
    from comfyui_workflow_sanitize import sanitize_comfyui_workflow
    workflow = sanitize_comfyui_workflow(workflow, source=f"_build_workflow:{gen_type}")

    inject_map = template_info["inject"]  # noqa: F841

    # Inject prompt/text
    if "prompt" in inject_map and "prompt" in params:
        node, field = inject_map["prompt"]["node"], inject_map["prompt"]["field"]
        workflow[node]["inputs"][field] = params["prompt"]

    # Inject negative prompt (video only)
    if "negative" in inject_map and "negative" in params:
        node, field = inject_map["negative"]["node"], inject_map["negative"]["field"]
        workflow[node]["inputs"][field] = params["negative"]

    # Inject tags (music only)
    if "tags" in inject_map and "tags" in params:
        node, field = inject_map["tags"]["node"], inject_map["tags"]["field"]
        workflow[node]["inputs"][field] = params["tags"]

    # Inject lyrics (music only)
    if "lyrics" in inject_map and "lyrics" in params:
        node, field = inject_map["lyrics"]["node"], inject_map["lyrics"]["field"]
        workflow[node]["inputs"][field] = params["lyrics"]

    # Inject text (TTS only)
    if "text" in inject_map and "text" in params:
        node, field = inject_map["text"]["node"], inject_map["text"]["field"]
        workflow[node]["inputs"][field] = params["text"]

    # Inject seed (random if not provided)
    if "seed" in inject_map:
        node, field = inject_map["seed"]["node"], inject_map["seed"]["field"]
        seed_val = params.get("seed", int(time.time() * 1000) % (2**32))
        workflow[node]["inputs"][field] = seed_val

    # Inject seed2 (second stage of two-stage workflows, same seed by default)
    if "seed2" in inject_map:
        node, field = inject_map["seed2"]["node"], inject_map["seed2"]["field"]
        seed_val = params.get("seed", int(time.time() * 1000) % (2**32))
        workflow[node]["inputs"][field] = seed_val

    # Inject dimensions (image only)
    if "width" in inject_map and "width" in params:
        node, field = inject_map["width"]["node"], inject_map["width"]["field"]
        workflow[node]["inputs"][field] = params["width"]
    if "height" in inject_map and "height" in params:
        node, field = inject_map["height"]["node"], inject_map["height"]["field"]
        workflow[node]["inputs"][field] = params["height"]

    # Inject BPM/duration (music only)
    if "bpm" in inject_map and "bpm" in params:
        node, field = inject_map["bpm"]["node"], inject_map["bpm"]["field"]
        workflow[node]["inputs"][field] = params["bpm"]
    if "duration" in inject_map and "duration" in params:
        node, field = inject_map["duration"]["node"], inject_map["duration"]["field"]
        workflow[node]["inputs"][field] = params["duration"]

    # Inject seconds (music latent size)
    if "seconds" in inject_map and "seconds" in params:
        node, field = inject_map["seconds"]["node"], inject_map["seconds"]["field"]
        workflow[node]["inputs"][field] = params["seconds"]
    elif "seconds" in inject_map and "duration" in params:
        node, field = inject_map["seconds"]["node"], inject_map["seconds"]["field"]
        workflow[node]["inputs"][field] = params["duration"]

    # Inject source image (image-edit only)
    if "source_image" in inject_map and "source_image" in params:
        node, field = inject_map["source_image"]["node"], inject_map["source_image"]["field"]
        workflow[node]["inputs"][field] = params["source_image"]

    # Inject TTS voice reference
    if "reference_audio" in inject_map:
        voice = params.get("voice", "fader")
        ref = TTS_VOICE_REFERENCES.get(voice, TTS_VOICE_REFERENCES["fader"])
        node, field = inject_map["reference_audio"]["node"], inject_map["reference_audio"]["field"]
        workflow[node]["inputs"][field] = ref["audio"]
        if "reference_text" in inject_map:
            node2, field2 = inject_map["reference_text"]["node"], inject_map["reference_text"]["field"]
            workflow[node2]["inputs"][field2] = params.get("reference_text", ref["reference_text"])

    # Set filename prefix
    prefix = params.get("prefix", f"gen-{gen_type}")
    for key in ("prefix", "base_prefix"):
        if key in inject_map:
            node, field = inject_map[key]["node"], inject_map[key]["field"]
            workflow[node]["inputs"][field] = prefix

    return workflow


async def _submit_generate_via_durable_owner(
    request: web.Request, gen_type: str,
):
    """Normalize a legacy `/generate/{type}` body for durable submission."""
    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON body"}, status=400)
    if not isinstance(data, Mapping):
        return web.json_response(
            {"error": "JSON body must be an object"}, status=400
        )
    params = (
        data.get("params")
        if "params" in data
        else {
            key: value
            for key, value in data.items()
            if key not in {
                "type", "priority", "priority_class", "callback_url", "metadata",
            }
        }
    ) or {}
    if not isinstance(params, Mapping):
        return web.json_response(
            {"error": "params must be an object"}, status=400
        )
    params = dict(params)
    if "service_pipeline_id" not in params and "service_pipeline_id" in data:
        params["service_pipeline_id"] = data.get("service_pipeline_id")
    return await handle_submit_generation(
        request,
        data_override={
            "type": gen_type,
            "params": params,
            "priority": data.get("priority", 50),
            "priority_class": data.get("priority_class"),
            "callback_url": data.get("callback_url"),
            "metadata": data.get("metadata") or {},
        },
    )


async def handle_generate(request: web.Request):
    """POST /generate/{type} — High-level generation endpoint.

    ComfyUI types go to comfyui queue.
    Normal music resolves to the enabled MiniMax Music 3 workflow. ACE-Step
    template names return a permanent retirement response and are never
    admitted to the retained legacy scheduler.

    B2 ROUTING FIX: `image` type is now routed to comfyui via
    services.json generation_templates (the Krea 2 workflow
    replaces the legacy ERNIE-Image-Turbo fallback).
    The legacy GENERATION_TEMPLATES is kept as a fallback for the
    remaining types (image-edit, video, ltx-video, tts).
    """
    requested_gen_type = request.match_info["type"]
    cfg = _load_services_config() or {}
    gen_type, alias_error = _resolve_generation_alias(cfg, requested_gen_type)
    if alias_error:
        return web.json_response(
            alias_error, status=int(alias_error.get("status", 400))
        )
    declared_templates = (cfg.get("generation_templates", {}) or {})
    declared_template = declared_templates.get(gen_type)
    is_acestep_template = (
        isinstance(declared_template, dict)
        and str(declared_template.get("backend") or "").startswith("acestep")
    )

    # Retired aliases never reach the retained historical scheduler state.
    if gen_type in {"music-acestep", "music-acestep-candidate"} or is_acestep_template:
        return await handle_acestep_generate(request, gen_type=gen_type)

    internal_workflow = (cfg.get("services", {}) or {}).get(gen_type, {})
    if _is_internal_workflow_service(internal_workflow):
        try:
            data = await request.json()
        except Exception:
            return web.json_response({"error": "Invalid JSON body"}, status=400)
        if not isinstance(data, Mapping):
            return web.json_response({"error": "JSON body must be an object"}, status=400)
        params = data.get("params") if "params" in data else {
            key: value
            for key, value in data.items()
            if key not in {"priority", "priority_class", "callback_url", "metadata"}
        }
        return await handle_submit_generation(
            request,
            data_override={
                "type": gen_type,
                "params": params or {},
                "priority": data.get("priority", 50),
                "priority_class": data.get("priority_class"),
                "callback_url": data.get("callback_url"),
                "metadata": data.get("metadata") or {},
            },
        )

    # Generic music must never fall back to the retired ACE-Step path.
    if gen_type == "music":
        return web.json_response(
            {
                "error": "MiniMax Music 3 is not activated",
                "reason": "music_service_unavailable",
                "service": "minimax-music3-full",
            },
            status=503,
        )

    # Registry-owned generation types use the durable WorkerPool whenever the
    # durable owner is selected. This makes newly registered services follow
    # one admission/lifecycle path without adding a controller conditional.
    if _queue_owner_mode() == "durable" and (
        gen_type in declared_templates or gen_type in {"image", "image-edit"}
    ):
        return await _submit_generate_via_durable_owner(request, gen_type)

    # Queue-owned generation submission replaces the synchronous
    # _load_bundle + direct sd-server forward for the `image` type with an
    # enqueue onto the per-routing_group Redis stream.  The WorkerPool
    # owns the bundle-load lifecycle (Step 8) and the actual HTTP call.
    #
    # We use the shared `_build_generation_entry()` helper so the body
    # shape / http_path / param_map logic stays in one place (same as
    # /v1/submit/generation).  Legacy callers that post `{"prompt": ...}`
    # directly are still accepted: when `params` is absent the body is
    # treated as params with gen_type=image.
    if gen_type in {"image", "image-edit"}:
        # The durable-owner compatibility path is handled above. Split/legacy
        # mode retains the historical adapter below; WorkerPool owns any
        # registry-declared route in durable mode.
        _owner_fence = _queue_owner_route_fence(
            'durable', f'/generate/{gen_type}'
        )
        if _owner_fence is not None:
            return _owner_fence
        if not queue_engine:
            return web.json_response(
                {"error": "Queue engine not available"}, status=503
            )
        try:
            data = await request.json()
        except Exception:
            return web.json_response({"error": "Invalid JSON body"}, status=400)

        # Accept either the new shape ({type, params}) or the legacy shape
        # ({prompt, ...}).  Legacy shape is treated as params.
        params = (data.get("params") if "params" in data else data) or {}
        if not isinstance(params, Mapping):
            return web.json_response(
                {"error": "params must be an object"}, status=400
            )
        params = dict(params)
        if "service_pipeline_id" not in params and "service_pipeline_id" in data:
            params["service_pipeline_id"] = data.get("service_pipeline_id")
        metadata = dict(data.get("metadata") or {})
        compiled_pipeline, pipeline_err = await _resolve_ingress_pipeline(
            gen_type,
            params,
            declared_templates.get(gen_type) or {},
        )
        if pipeline_err:
            return web.json_response(
                pipeline_err, status=int(pipeline_err.get("status", 400))
            )
        if (
            compiled_pipeline
            and compiled_pipeline.get("pipeline_coordinator_required")
            and not _coordinator_runtime_attached(request)
        ):
            return web.json_response(
                {
                    "error": "pipeline_coordinator_unavailable",
                    "reason": "pipeline_coordinator_unavailable",
                    "pipeline_id": compiled_pipeline.get("pipeline_id"),
                },
                status=503,
            )

        entry, err = await _build_generation_entry(
            gen_type=gen_type,
            params=params,
            priority=int(data.get("priority", 50)),
            callback_url=data.get("callback_url"),
            metadata=metadata,
            compiled_pipeline=compiled_pipeline,
        )
        if err:
            return web.json_response(err, status=err.get("status", 400))
        if entry is None:
            return web.json_response(
                {"error": "internal: generation entry missing after err=None"},
                status=500,
            )

        # Register before enqueue so WorkerPool cannot win the race and create
        # an incomplete JobTracker hash. Promote the bounded node-6/workflow
        # evidence produced by the shared entry builder.
        if job_tracker:
            try:
                _gjob = job_tracker.create_job(
                    job_id=entry["job_id"],
                    service_name=entry.get("service_name", "") or "",
                    source="nginx_image",
                    prompt=(params or {}).get("prompt", "") or "",
                    max_tokens=0,
                    routing_group=entry.get("routing_group", "") or "",
                )
                if _gjob is None:
                    return web.json_response(
                        {"error": "job_tracker.create_job returned None (redis error?)"},
                        status=503,
                    )
                try:
                    _entry_metadata = json.loads(entry.get("metadata") or "{}")
                except (TypeError, json.JSONDecodeError):
                    _entry_metadata = {}
                _prompt_evidence = _entry_metadata.get("prompt_evidence")
                _queued_fields = {}
                if isinstance(_prompt_evidence, dict):
                    _queued_fields = {
                        "prompt_evidence": json.dumps(
                            _prompt_evidence,
                            sort_keys=True,
                            separators=(",", ":"),
                            ensure_ascii=False,
                        ),
                        "effective_prompt_sha256": _prompt_evidence.get(
                            "effective_prompt_sha256"
                        ),
                        "workflow_sha256": _prompt_evidence.get("workflow_sha256"),
                        "prompt_target": _prompt_evidence.get("prompt_target"),
                    }
                job_tracker.update_status(
                    entry["job_id"], "queued", **_queued_fields
                )
            except Exception as _job_register_err:
                return web.json_response(
                    {"error": f"job_tracker registration failed: {_job_register_err}"},
                    status=500,
                )

        def _terminalize_legacy_submit_failure(error: str) -> None:
            """Do not strand legacy ingress records after pre-enqueue failures."""
            if not job_tracker:
                return
            try:
                job_tracker.update_status(entry["job_id"], "failed", error=error)
            except Exception:
                logger.exception(
                    "handle_generate: failed to terminalize %s after %s",
                    entry["job_id"],
                    error,
                )

        _comfyui_admission_held = (
            entry.get("routing_group") == "comfyui-gen"
            or entry.get("request_kind") == "comfyui_workflow"
        )
        if _comfyui_admission_held:
            _acquire_comfyui_admission(entry["job_id"])

        # Bundle-load precheck (mirrors handle_submit_generation).  We
        # refuse to enqueue when the bundle can't come up — better to
        # fail fast with 500 than to leave a job stranded in the stream.
        cfg = _load_services_config() or {}
        tmpl = (cfg.get("generation_templates", {}) or {}).get(gen_type, {}) or {}
        bundle_name = tmpl.get("bundle")
        # Use the effective scheduler setting, including GPU_MANAGER_SCHEDULER_OWNS_LOAD.
        # Reading only services.json here can make ingress synchronously load a
        # bundle even though the live scheduler owns loading, delaying the 202
        # acknowledgement long enough for a client timeout to orphan the request.
        # In durable mode the WorkerPool owns bundle admission; never perform
        # a second synchronous load or evict_first cascade in the HTTP handler.
        scheduler_owns_load = (
            _queue_owner_mode() == "durable"
            or bool(_phase3_scheduling_config().get("scheduler_owns_load", False))
        )
        if scheduler_owns_load:
            logger.info("handle_generate: enqueue accepted without handler pre-load")
        if bundle_name and not scheduler_owns_load:
            try:
                ok = await _evict_then_load_bundle(bundle_name, reason="nginx_image")
            except Exception as e:
                logger.error(
                    "handle_generate: bundle load raised for %s: %s",
                    bundle_name, e,
                )
                error = f"Bundle load failed: {e}"
                _terminalize_legacy_submit_failure(error)
                if _comfyui_admission_held:
                    _release_comfyui_admission(entry["job_id"])
                return web.json_response(
                    {"error": error}, status=500
                )
            if not ok:
                error = f"Bundle '{bundle_name}' failed to load"
                _terminalize_legacy_submit_failure(error)
                if _comfyui_admission_held:
                    _release_comfyui_admission(entry["job_id"])
                return web.json_response(
                    {"error": error},
                    status=500,
                )

        # Also evict any required_services before enqueueing
        # so the LLM doesn't keep holding VRAM while ComfyUI loads its
        # models.  Look up systemd_unit per service from services.json and
        # systemctl stop it; failures are logged but don't block enqueue.
        _evict_list = tmpl.get("evict_first", []) or []
        if _evict_list and not scheduler_owns_load:
            _svc_cfg_root = (cfg.get("services") or {})
            for _svc_name in _evict_list:
                _unit = (_svc_cfg_root.get(_svc_name) or {}).get(
                    "systemd_unit", ""
                )
                if not _unit:
                    logger.warning(
                        "handle_generate: evict_first service %r has no "
                        "systemd_unit in services.json — skipping",
                        _svc_name,
                    )
                    continue
                try:
                    logger.info(
                        "handle_generate: evicting %s (unit=%s) for %s",
                        _svc_name, _unit, gen_type,
                    )
                    # Phase 5.1.5: stamp this as a planned stop so the
                    # Supervisor doesn't kill unrelated pools on the
                    # cascading unhealthy event.
                    if event_bus is not None:
                        event_bus.mark_planned_stop(_svc_name)
                    _ev_proc = await asyncio.create_subprocess_exec(
                        "sudo", "systemctl", "stop", _unit,
                        stdout=asyncio.subprocess.PIPE,
                        stderr=asyncio.subprocess.PIPE,
                    )
                    try:
                        _ev_out, _ev_err = await asyncio.wait_for(
                            _ev_proc.communicate(), timeout=30.0,
                        )
                    except asyncio.TimeoutError:
                        _ev_proc.kill()
                        logger.warning(
                            "handle_generate: systemctl stop %s timed out",
                            _unit,
                        )
                        continue
                    if _ev_proc.returncode != 0:
                        logger.warning(
                            "handle_generate: systemctl stop %s failed "
                            "(rc=%s): %s",
                            _unit, _ev_proc.returncode,
                            _ev_err.decode("utf-8", errors="replace")[:300],
                        )
                except Exception as _evict_err:
                    logger.warning(
                        "handle_generate: failed to evict %s: %s",
                        _svc_name, _evict_err,
                    )
                finally:
                    # Phase 5.2.6: caller-side clear. The stamp's only
                    # purpose was to absorb the systemd stop cascade;
                    # release the supervisor's deferral once the stop
                    # returns (success, failure, or timeout).
                    if event_bus is not None:
                        event_bus.clear_planned_stop(_svc_name)

        # Enqueue onto the per-routing_group Redis stream.
        loop = asyncio.get_running_loop()
        routing_group = entry["routing_group"]
        service_name = entry.get("service_name") or routing_group
        logger.info(f"handle_generate: enqueueing job_id={entry.get('job_id', 'unknown')} routing_group={routing_group} service_name={service_name}")
        try:
            entry_id = await loop.run_in_executor(
                None, queue_engine.enqueue, service_name, entry, routing_group,
            )
            if entry_id:
                logger.info(f"handle_generate: enqueued job_id={entry.get('job_id', 'unknown')} entry_id={entry_id}")
        except Exception as e:
            logger.error("handle_generate: redis enqueue failed: %s", e)
            error = f"redis enqueue failed: {e}"
            _terminalize_legacy_submit_failure(error)
            if _comfyui_admission_held:
                _release_comfyui_admission(entry["job_id"])
            return web.json_response(
                {"error": error}, status=503
            )
        if not entry_id:
            error = "Failed to enqueue (redis stream error)"
            _terminalize_legacy_submit_failure(error)
            if _comfyui_admission_held:
                _release_comfyui_admission(entry["job_id"])
            return web.json_response(
                {"error": error}, status=503
            )
        if job_tracker:
            job_tracker.update_status(
                entry["job_id"], "queued", entry_id=entry_id
            )

        # Queue depth for client-side backpressure hint (XLEN-style).
        try:
            position = await loop.run_in_executor(
                None, queue_engine.get_queue_depth, service_name, routing_group,
            )
        except Exception:
            position = None

        return web.json_response(
            {
                "job_id": entry["job_id"],
                "entry_id": entry_id,
                "type": gen_type,
                "routing_group": routing_group,
                "status": "queued",
                "position": position,
            },
            status=202,
        )

    _owner_fence = _queue_owner_route_fence('legacy', f'/generate/{gen_type}')
    if _owner_fence is not None:
        return _owner_fence

    try:
        data = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON body"}, status=400)

    # Build workflow from template + params
    try:
        workflow = _build_workflow(gen_type, data)
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)
    except FileNotFoundError as e:
        return web.json_response({"error": f"Template not found: {e}"}, status=500)

    # Submit to ComfyUI queue
    priority = data.get("priority", 5)
    callback_url = data.get("callback_url")
    metadata = {
        **(data.get("metadata", {})),
        "gen_type": gen_type,
        "gen_params": {k: v for k, v in data.items()
                       if k not in ("callback_url", "metadata", "priority")},
    }

    job = scheduler.submit_comfyui(workflow, callback_url, priority, metadata)
    pending = sum(1 for j in scheduler._comfyui_queue if j.status == "queued")
    pending += sum(1 for j in scheduler._acestep_queue if j.status == "queued")

    return web.json_response({
        "job_id": job.id,
        "type": gen_type,
        "model_key": job.model_key,
        "fingerprint": job.fingerprint,
        "status": job.status,
        "position": pending,
    }, status=201)


def _generation_runtime_observation(
    *,
    service_name: str | None,
    service_cfg: Mapping[str, Any] | None,
    legacy_backend: str | None = None,
    qualification_status: Any = None,
) -> dict[str, Any]:
    """Return a read-only registration/lifecycle snapshot for discovery.

    Discovery must not start services or perform health probes.  ``healthy``
    therefore comes from the manager's cached observation, while
    ``accepting`` requires an actually running local queue consumer (or an
    explicit provider observation).  This keeps a configured-but-stopped
    backend from being advertised as ready merely because its registry entry
    exists.
    """
    service_cfg = service_cfg if isinstance(service_cfg, Mapping) else {}
    service = str(service_name or legacy_backend or "").strip() or None
    configured = bool(service_name or legacy_backend)
    activated = False
    activation_reason = "no_backend"
    qualification = (
        str(qualification_status).strip().lower()
        if qualification_status is not None
        else ""
    )
    public_qualification = qualification in {"", "enabled", "qualified"}
    if service is not None:
        configured = True
        if not service_cfg:
            # The built-in templates remain a compatibility route.  They are
            # intentionally marked legacy so callers can distinguish them
            # from registry-owned services even when no service entry exists.
            activated = bool(legacy_backend) and public_qualification
            activation_reason = (
                "legacy_fallback" if activated
                else f"qualification_{qualification}" if qualification
                else "missing_service"
            )
        elif service_cfg.get("enabled", True) is True:
            activated = public_qualification
            activation_reason = (
                "enabled" if activated
                else f"qualification_{qualification}"
            )
        else:
            activation_reason = "disabled"

    health = _service_health_cache.get(service, {}) if service else {}
    if not isinstance(health, Mapping):
        health = {}
    health_observation = str(health.get("overall") or "missing")
    healthy = bool(activated and health_observation == "healthy")
    accepting = False
    accepting_reason = "no_accepting_consumer"

    # WorkerSupervisor is the authoritative local consumer for declarative
    # services.  Require a fully started pool and a free slot; merely having a
    # pool object is a startup-in-progress state, not acceptance.
    pools = getattr(worker_supervisor, "_pools", {}) if worker_supervisor else {}
    pool = pools.get(service) if isinstance(pools, Mapping) and service else None
    if activated and pool is not None:
        running = bool(getattr(pool, "_running", False))
        desired = int(getattr(pool, "desired_slots", 0) or 0)
        workers = list(getattr(pool, "_workers", []) or [])
        workers_alive = sum(
            1 for worker in workers
            if callable(getattr(worker, "done", None)) and not worker.done()
        )
        slots_free = int(getattr(pool, "slots_free", 0) or 0)
        if running and desired > 0 and workers_alive >= desired and slots_free > 0:
            accepting = True
            accepting_reason = "worker_pool_free_slot"
            # Internal orchestrators have no systemd/port health signal; a
            # fully started pool is the checked health observation for them.
            if service_cfg.get("type") == "orchestrator":
                healthy = True
                health_observation = "worker_pool_ready"
        elif not running:
            accepting_reason = "worker_pool_stopped"
        elif desired > 0 and workers_alive < desired:
            accepting_reason = "worker_pool_starting"
        elif slots_free <= 0:
            accepting_reason = "worker_pool_busy"

    # Legacy ComfyUI submission is queue-accepting while the retained
    # scheduler is running, even if the backend is intentionally idle.  This
    # is only reported for built-in fallback entries; registry-owned routes
    # should use their WorkerPool/provider observation instead.
    if (
        not accepting
        and legacy_backend == "comfyui"
        and not service_cfg
        and scheduler is not None
        and bool(getattr(scheduler, "_running", False))
    ):
        accepting = True
        accepting_reason = "legacy_scheduler"

    if not activated:
        state = "configured" if configured else "unconfigured"
    elif not healthy:
        state = "activated"
    elif not accepting:
        state = "healthy"
    else:
        state = "accepting"
    return {
        "service": service,
        "configured": bool(configured),
        "activated": bool(activated),
        "healthy": bool(healthy),
        "accepting": bool(accepting),
        "state": state,
        "activation_reason": activation_reason,
        "health_observation": health_observation,
        "accepting_reason": accepting_reason,
    }


def _generation_discovery_entry(
    name: str,
    info: Mapping[str, Any],
    *,
    service_name: str | None,
    service_cfg: Mapping[str, Any] | None,
    registered: bool,
    source: str,
    legacy_backend: str | None = None,
) -> dict[str, Any]:
    """Build one stable, non-secret ``GET /generate`` discovery entry."""
    info = info if isinstance(info, Mapping) else {}
    service_cfg = service_cfg if isinstance(service_cfg, Mapping) else {}
    inject = info.get("inject")
    if not isinstance(inject, Mapping):
        inject = {}
    allowed = info.get("allowed_params") or info.get("params")
    if not isinstance(allowed, (list, tuple)):
        param_map = info.get("param_map")
        allowed = list(param_map) if isinstance(param_map, Mapping) else list(inject)
    defaults = info.get("defaults")
    if not isinstance(defaults, Mapping):
        defaults = {}
    timeout = info.get("timeout")
    if timeout is None:
        admission = service_cfg.get("admission")
        timeout = admission.get("execution_timeout_seconds", 900) if isinstance(admission, Mapping) else 900
    output_type = info.get("output_type")
    if not output_type:
        outputs = service_cfg.get("outputs")
        output_type = outputs[0] if isinstance(outputs, list) and outputs else "unknown"
    model_key = info.get("model_key")
    if not model_key:
        models = service_cfg.get("models")
        model_key = models[0] if isinstance(models, list) and models else None
    description = info.get("description") or service_cfg.get("display") or name
    try:
        timeout = int(timeout)
    except (TypeError, ValueError):
        timeout = 900
    entry = {
        "description": str(description),
        "model_key": model_key,
        "timeout": max(1, timeout),
        "defaults": dict(defaults),
        "output_type": str(output_type),
        "params": [str(param) for param in allowed],
        "registered": bool(registered),
        "source": source,
    }
    if info.get("qualification_status") is not None:
        entry["qualification_status"] = str(info["qualification_status"])
    if info.get("routing_group"):
        entry["routing_group"] = str(info["routing_group"])
    if service_name:
        entry["service"] = str(service_name)
    entry.update(
        _generation_runtime_observation(
            service_name=service_name,
            service_cfg=service_cfg,
            legacy_backend=legacy_backend,
            qualification_status=info.get("qualification_status"),
        )
    )
    retired = _retired_minimax_comfyui_template(name, info)
    if retired is not None:
        # Keep the historical definition visible for receipts and operator
        # audit, but make its inventory-only state unambiguous even when an
        # older registry omitted qualification_status.
        entry.update(
            {
                "retired": True,
                "activated": False,
                "healthy": False,
                "accepting": False,
                "state": "retired",
                "activation_reason": retired["reason"],
                "accepting_reason": retired["reason"],
                "replacement": retired["replacement"],
            }
        )
    return entry


async def handle_generate_types(request: web.Request):
    """GET /generate — list registry-owned types and lifecycle state.

    The response preserves the historical template fields, then adds
    ``registered`` plus configured/activated/healthy/accepting booleans.  It
    is intentionally observational: no systemd, network or model lifecycle
    action is performed while rendering discovery.
    """
    cfg = _load_services_config() or {}
    services = cfg.get("services", {}) or {}
    templates = cfg.get("generation_templates", {}) or {}
    if not isinstance(services, Mapping):
        services = {}
    if not isinstance(templates, Mapping):
        templates = {}

    types: dict[str, dict[str, Any]] = {}
    # Keep the old built-in compatibility surface, but clearly mark it as a
    # legacy fallback unless the registry supplies a same-named route below.
    legacy_backends = {
        "image": "comfyui",
        "image-edit": "comfyui",
        "video": "comfyui",
        "ltx-video": "comfyui",
        "tts": "comfyui",
    }
    for name, info in GENERATION_TEMPLATES.items():
        if name.startswith("music-acestep"):
            continue
        types[name] = _generation_discovery_entry(
            name,
            info,
            service_name=None,
            service_cfg={},
            registered=False,
            source="legacy_fallback",
            legacy_backend=legacy_backends.get(name),
        )

    # Registry templates are the source of truth for newly added services;
    # merge them over the compatibility entries without exposing endpoints or
    # other executable/provider details.
    for name, template in templates.items():
        if not isinstance(name, str) or not isinstance(template, Mapping):
            continue
        backend = str(template.get("backend") or "").strip() or None
        if name.startswith("music-acestep") or (backend and backend.startswith("acestep")):
            continue
        service_cfg = services.get(backend, {}) if backend else {}
        info = dict(template)
        prior = types.get(name, {})
        for key in ("description", "model_key", "timeout", "defaults", "output_type", "inject"):
            if key not in info and key in prior:
                info[key] = prior[key]
        types[name] = _generation_discovery_entry(
            name,
            info,
            service_name=backend,
            service_cfg=service_cfg,
            registered=True,
            source="registry_template",
        )

    # Orchestrators may expose an alias without a generation_template (the
    # MiniMax graph is intentionally one such service).  Include aliases from
    # the registry so the GUI can show a disabled/unhealthy route honestly.
    for service_name, service_cfg in services.items():
        if not isinstance(service_name, str) or not isinstance(service_cfg, Mapping):
            continue
        aliases = service_cfg.get("aliases")
        if not isinstance(aliases, list):
            aliases = []
        if _is_internal_workflow_service(service_cfg) and not aliases:
            aliases = [service_name]
        for alias in aliases:
            if not isinstance(alias, str) or not alias or alias.startswith("music-acestep"):
                continue
            if alias in types and types[alias].get("registered"):
                continue
            if alias in {"music", service_name} and _is_internal_workflow_service(service_cfg):
                info = {
                    "description": service_cfg.get(
                        "display", "MiniMax Music 3 — prepared and quality checked"
                    ),
                    "model_key": "minimax-music3",
                    "timeout": 7200,
                    "defaults": {
                        "duration_seconds": 30,
                        "research_policy": "required_live",
                    },
                    "output_type": "audio",
                    "allowed_params": [
                        "brief", "lyrics", "duration_seconds", "research_policy",
                        "seed", "diffusion_seed",
                    ],
                    "routing_group": service_cfg.get("routing_group"),
                }
            else:
                info = {
                    "description": service_cfg.get("display", alias),
                    "model_key": None,
                    "timeout": (
                        service_cfg.get("admission", {}).get("execution_timeout_seconds", 900)
                        if isinstance(service_cfg.get("admission"), Mapping) else 900
                    ),
                    "output_type": "unknown",
                    "allowed_params": list((service_cfg.get("input_contract") or {}).keys()),
                    "routing_group": service_cfg.get("routing_group"),
                }
            types[alias] = _generation_discovery_entry(
                alias,
                info,
                service_name=service_name,
                service_cfg=service_cfg,
                registered=True,
                source="registry_service_alias",
            )
    return web.json_response(types)


_GENERATE_OUTPUT_FILENAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,255}$")


def _is_within(candidate: Path, root: Path) -> bool:
    """Return True iff ``candidate`` is the same file as ``root`` or
    lives beneath it (after symlink resolution)."""
    try:
        candidate.relative_to(root)
    except ValueError:
        return False
    return True


def _safe_generate_output_name(raw: Any) -> str | None:
    """Validate and normalize a generated-output filename.

    Rejects:
      * non-strings, empty strings, strings with control characters
      * absolute paths (``/etc/passwd``)
      * path separators (``subdir/file``, ``..\\windows.png``)
      * dot segments (``.`` or ``..``)
      * URL-decoded traversal (``%2e%2e%2fsecret``)

    Returns the basename on success, ``None`` on rejection.  The
    returned value is intentionally not ``os.path.normpath``-ed so a
    legitimate trailing dot is preserved; the regex already forbids
    path separators and dot-only names.
    """
    if not isinstance(raw, str) or not raw:
        return None
    if any(ord(char) < 0x20 or ord(char) == 0x7F for char in raw):
        return None
    if "%" in raw:
        # Any URL-encoded form is suspicious: percent-decoded segments
        # may have slipped past the route regex.  Refuse outright so a
        # caller cannot bypass the separator / dot-segment checks.
        return None
    if os.path.isabs(raw) or os.sep in raw or "/" in raw or "\\" in raw:
        return None
    if raw in {".", ".."}:
        return None
    if not _GENERATE_OUTPUT_FILENAME_RE.fullmatch(raw):
        return None
    return raw


async def handle_generate_output(request: web.Request):
    """GET /generate/output/{filename} — Serve a generated file.

    Only basenames are accepted; any absolute path, path separator,
    dot segment, or URL-decoded traversal is rejected before the file
    system is touched, and the resolved path must remain inside one
    of the configured COMFYUI output/input roots.
    """
    raw_filename = request.match_info["filename"]
    safe_filename = _safe_generate_output_name(raw_filename)
    if safe_filename is None:
        return web.json_response(
            {"error": f"Invalid filename: {raw_filename!r}"}, status=400
        )

    output_root = (COMFYUI_ROOT / "output").resolve()
    input_root = (COMFYUI_ROOT / "input").resolve()
    candidate = (output_root / safe_filename).resolve()
    if candidate.is_file() and _is_within(candidate, output_root):
        return web.FileResponse(str(candidate))
    candidate = (input_root / safe_filename).resolve()
    if candidate.is_file() and _is_within(candidate, input_root):
        return web.FileResponse(str(candidate))

    return web.json_response(
        {"error": f"File not found: {safe_filename}"}, status=404
    )


async def handle_generate_library(request: web.Request):
    """GET /generate/library — List generated files."""
    gen_type = request.query.get("type", "all")
    limit = min(int(request.query.get("limit", "50")), 200)
    prefix_filter = request.query.get("prefix", "")

    output_dir = str(COMFYUI_ROOT / "output")
    if not os.path.isdir(output_dir):
        return web.json_response({"files": [], "total": 0})

    ext_map = {
        "image": {".png", ".jpg", ".jpeg", ".webp"},
        "video": {".mp4", ".webm", ".avi", ".gif"},
        "audio": {".wav", ".mp3", ".ogg", ".flac"},
    }
    allowed_ext = ext_map.get(gen_type, None)

    files = []
    for fname in sorted(os.listdir(output_dir), reverse=True):
        if prefix_filter and not fname.startswith(prefix_filter):
            continue
        ext = os.path.splitext(fname)[1].lower()
        if allowed_ext and ext not in allowed_ext:
            continue

        fpath = os.path.join(output_dir, fname)
        stat = os.stat(fpath)
        files.append({
            "filename": fname,
            "size": stat.st_size,
            "modified": stat.st_mtime,
            "url": f"/generate/output/{fname}",
        })
        if len(files) >= limit:
            break

    return web.json_response({"files": files, "total": len(files)})


async def handle_generate_wait(request: web.Request):
    """GET /generate/job/{job_id}/wait — Block until job completes."""
    job_id = request.match_info["job_id"]
    timeout = min(int(request.query.get("timeout", "600")), 3600)

    job = scheduler.get_job(job_id)
    if not job:
        return web.json_response({"error": f"Job {job_id} not found"}, status=404)

    if job.status in ("completed", "failed", "cancelled"):
        return web.json_response(job.to_dict())

    start = time.time()
    while time.time() - start < timeout:
        await asyncio.sleep(3)
        if job.status in ("completed", "failed", "cancelled"):
            return web.json_response(job.to_dict())

    return web.json_response(
        {"error": f"Timeout waiting for job {job_id}", "status": job.status},
        status=408,
    )


# ── ACE-Step Handler (now queues through scheduler) ──────────────────

async def handle_acestep_generate(
    request: web.Request,
    *,
    gen_type: str = "music-acestep",
    data_override: dict | None = None,
    idempotency_key: str | None = None,
    request_sha256: str | None = None,
):
    """Reject every new ACE-Step request after backend retirement.

    The scheduler's old job/state types stay available while historical jobs
    and evidence are drained, but no public or qualification marker can create
    new ACE work. MiniMax Music 3 is the sole music-generation replacement.
    """
    return web.json_response(
        {
            "error": "ACE-Step music generation is retired",
            "reason": "acestep_retired",
            "replacement": "minimax-music3-full",
        },
        status=410,
    )


async def handle_acestep_status(request: web.Request):
    """GET /acestep/status — Check ACE-Step API health."""
    try:
        async with session.get(
            f"{ACESTEP_URL}/health",
            timeout=ClientTimeout(total=5),
        ) as resp:
            data = await resp.json()
            return web.json_response(data)
    except Exception as e:
        return web.json_response(
            {"status": "error", "error": str(e)}, status=502,
        )


async def handle_acestep_audio(request: web.Request):
    """GET /acestep/audio/{path} — Proxy audio file download from ACE-Step."""
    audio_path = request.match_info["path"]
    try:
        async with session.get(
            f"{ACESTEP_URL}/v1/audio?path={audio_path}",
            timeout=ClientTimeout(total=30),
        ) as resp:
            body = await resp.read()
            response = web.Response(status=resp.status, body=body)
            if "content-type" in resp.headers:
                response.content_type = resp.headers["content-type"]
            return response
    except Exception as e:
        return web.json_response({"error": str(e)}, status=502)


# ── Background Tasks ───────────────────────────────────────────────

async def background_loop(app: web.Application):
    """Combined health check + ComfyUI monitor + idle LLM restore."""
    global _comfyui_was_busy

    await session_init()
    global scheduler, vram
    _queue_owner = _queue_owner_mode()
    scheduler.session = session
    vram.session = session
    llm.session = session
    if _queue_owner != 'durable':
        scheduler.start()
    else:
        logger.info(
            "Background loop: durable queue owner selected; legacy GPUScheduler "
            "dispatch/idle monitor is fenced"
        )

    # Initial checks
    healthy = await llm.check_health()
    llm.update_health(healthy)
    logger.info(
        f"Background loop started (LLM healthy: {healthy}, "
        f"GPU state: {vram.gpu_state.value})"
    )

    # State persistence counter: save every STATE_SAVE_INTERVAL iterations (~10s)
    _save_counter = 0

    while True:
        try:
            # LLM health
            llm.update_health(await llm.check_health())

            # ── Maintenance mode timeout check ──
            _cfg = _load_services_config()
            _scheduling = _cfg.get("scheduling", {})
            if _scheduling.get("maintenance_mode") is True and _scheduling.get("maintenance_mode_expires"):
                if time.time() > _scheduling["maintenance_mode_expires"]:
                    _cfg["scheduling"]["maintenance_mode"] = False
                    _cfg["scheduling"].pop("maintenance_mode_expires", None)
                    _save_services_config(_cfg)
                    logger.info("Maintenance mode auto-disabled (timeout expired)")

            # In durable-owner mode the Redis WorkerSupervisor owns generation
            # dispatch and demand-loading.  It deliberately does not run the
            # compatibility scheduler, but idle eviction/restoration must stay
            # alive or the last generation bundle holds the GPU indefinitely.
            # These lifecycle helpers are guarded by the shared transition,
            # admission, in-flight and durable-queue fences, so they cannot
            # become a second dispatch/load owner.
            if _queue_owner == 'durable':
                await scheduler._auto_evict_idle_bundles()
                await scheduler._ensure_idle_service()
                _save_counter += 1
                if _save_counter >= STATE_SAVE_INTERVAL:
                    _save_counter = 0
                    await asyncio.get_event_loop().run_in_executor(None, _save_state)
                await asyncio.sleep(HEALTH_POLL_INTERVAL)
                continue

            # ── Idle monitor: ensure LLM is loaded when nothing needs GPU ──
            if vram.gpu_state in (GpuState.LLM_LOADED, GpuState.RESTORING):
                # Already in correct state or being restored
                pass
            elif vram._llm_evicted and not scheduler._current_backend and not scheduler._swapping and not scheduler._restoring:
                # Maintenance mode: skip auto-restore
                cfg = _load_services_config()
                if _maintenance_mode_enabled(cfg.get("scheduling", {})):
                    pass  # Hands off
                else:
                    # LLM evicted but no active GPU work — check if queues are empty
                    c_active = any(j.status in ("queued", "running") for j in scheduler._comfyui_queue)
                    a_active = any(j.status in ("queued", "running") for j in scheduler._acestep_queue)
                    if not c_active and not a_active:
                        logger.info(
                            "Idle monitor: LLM evicted with no GPU work — restoring"
                        )
                        await scheduler._restore_after_gpu_work()

            # Idle-service crash detection and recovery are owned exclusively by
            # GPUScheduler._ensure_idle_service.  Keeping a second direct-port
            # watchdog here caused duplicate probes, duplicate warning paths, and
            # a non-durable health cache that could race the bundle lifecycle
            # controller.  The scheduler loop below runs the fenced reducer,
            # durable observation writes, and restart transition as one owner.

            # ComfyUI busy/idle detection for auto-free
            # (only for direct submissions, not scheduler-managed)
            try:
                async with session.get(f"{COMFYUI_URL}/queue") as resp:
                    queue = await resp.json()
                comfyui_busy = len(queue.get("queue_running", [])) > 0 or \
                               len(queue.get("queue_pending", [])) > 0
            except Exception:
                comfyui_busy = False

            direct_idle_deferred = False
            _direct_idle_terminally_stopped = bool(
                vram is not None
                and (
                    getattr(vram, "_comfyui_stopped", False)
                    or getattr(vram, "_comfyui_auto_stopped", False)
                )
            )
            if _should_run_direct_idle_fence(
                was_busy=_comfyui_was_busy,
                comfyui_busy=comfyui_busy,
                comfyui_terminally_stopped=_direct_idle_terminally_stopped,
            ):
                _direct_blockers = _direct_idle_stop_blockers(
                    comfyui_busy=comfyui_busy,
                    current_backend=getattr(scheduler, "_current_backend", None),
                    worker_in_flight=_bundle_worker_in_flight("comfyui"),
                    transition_active=_bundle_transition_is_active(),
                    admission_in_flight=_comfyui_admission_in_flight(),
                )
                if _direct_blockers:
                    direct_idle_deferred = True
                    _log_direct_idle_fence_state("blocked", blockers=_direct_blockers)
                else:
                    _log_direct_idle_fence_state("awaiting_terminal_fence", blockers=[])
                    await asyncio.sleep(AUTO_FREE_DELAY)
                    try:
                        async with session.get(f"{COMFYUI_URL}/queue") as resp:
                            q = await resp.json()
                        _queue_busy_after_delay = bool(
                            q.get("queue_running") or q.get("queue_pending")
                        )
                        _direct_blockers = _direct_idle_stop_blockers(
                            comfyui_busy=_queue_busy_after_delay,
                            current_backend=getattr(scheduler, "_current_backend", None),
                            worker_in_flight=_bundle_worker_in_flight("comfyui"),
                            transition_active=_bundle_transition_is_active(),
                            admission_in_flight=_comfyui_admission_in_flight(),
                        )
                        if not _direct_blockers:
                            logger.info(
                                "ComfyUI terminal fence clear — auto-freeing models"
                            )
                            await scheduler._free_comfyui()
                            scheduler.total_auto_frees += 1
                            if vram is not None:
                                _direct_stopped = await vram.stop_comfyui(
                                    reason="direct_idle"
                                )
                                if _direct_stopped:
                                    vram._comfyui_auto_stopped = True
                        else:
                            direct_idle_deferred = True
                            _log_direct_idle_fence_state(
                                "blocked_after_delay", blockers=_direct_blockers
                            )
                    except Exception as _direct_idle_err:
                        _stopped_during_fence = bool(
                            vram is not None
                            and (
                                getattr(vram, "_comfyui_stopped", False)
                                or getattr(vram, "_comfyui_auto_stopped", False)
                            )
                        )
                        if _stopped_during_fence:
                            _log_direct_idle_fence_state(
                                "terminal_stopped", blockers=[]
                            )
                        else:
                            direct_idle_deferred = True
                            _log_direct_idle_fence_state(
                                "probe_failed",
                                blockers=[
                                    f"queue_probe_error:{type(_direct_idle_err).__name__}"
                                ],
                            )
            elif _comfyui_was_busy and not comfyui_busy and _direct_idle_terminally_stopped:
                _log_direct_idle_fence_state("terminal_stopped", blockers=[])

            # Re-arm the busy→idle edge while terminal ownership is still held.
            # Once the WorkerPool commits JobTracker and releases its lease, the
            # next background tick retries and can safely stop ComfyUI.
            _comfyui_was_busy = comfyui_busy or direct_idle_deferred

            # ── Periodic state persistence (~10s) ──
            _save_counter += 1
            if _save_counter >= STATE_SAVE_INTERVAL:
                _save_counter = 0
                await asyncio.get_event_loop().run_in_executor(None, _save_state)

        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.error(f"Background loop error: {e}", exc_info=True)

        await asyncio.sleep(HEALTH_POLL_INTERVAL)


async def session_init():
    """Ensure one process-wide shared HTTP session exists.

    ``on_startup`` initializes it before handlers run; ``background_loop`` also
    calls this helper. Replacing the live session here would orphan its sockets
    because cleanup can close only the final global reference.
    """
    global session
    if session is None or session.closed:
        session = ClientSession(timeout=ClientTimeout(total=300, connect=10))


# ── Peer Monitor ──────────────────────────────────────────────────

class PeerMonitor:
    """Periodically health-checks all remote peers in the mesh."""

    def __init__(self, providers_config: dict, services_config: dict):
        self.providers_config = providers_config
        self.services_config = services_config
        self.peer_status: dict = {}
        self.instances = providers_config.get("providers", {}).get("local", {}).get("instances", {})

    async def check_all(self):
        """Check health of every remote instance and cloud provider."""
        for name, inst in self.instances.items():
            host = inst.get("host", "localhost")
            port = inst.get("port")
            is_local = bool(inst.get("local")) or host in {
                "localhost", "127.0.0.1", "::1"
            }
            remote_processes = []

            if is_local:
                is_up = await self._check_local_service(name)
                if is_up:
                    vram_data = await _poll_vram()
                    slots, tps = await self._get_llama_slots(host, port)
                else:
                    vram_data = {}
                    slots, tps = [], 0
            else:
                is_up = await self._check_remote_health(host, port)
                vram_data = {}
                if is_up:
                    slots, remote_model = await self._get_remote_slots(host, port)
                else:
                    slots, remote_model = [], None
                tps = inst.get("tokens_per_second", 0)
                agent_port = inst.get("agent_port", 0)
                if is_up and agent_port:
                    agent_data = await self._get_remote_agent_data(host, agent_port)
                    if agent_data:
                        vram_info = agent_data.get("vram", {})
                        # Remote agent returns "system_ram" (not "memory")
                        mem_info = agent_data.get("memory", agent_data.get("system_ram", {}))
                        if vram_info.get("used_mib") is not None:
                            vram_data["used_vram_mib"] = vram_info.get("used_mib")
                            vram_data["total_vram_mib"] = vram_info.get("total_mib")
                        if mem_info.get("ram_total_mib") or mem_info.get("total_mib"):
                            ram_total = mem_info.get("ram_total_mib") or mem_info.get("total_mib", 0)
                            ram_used = mem_info.get("ram_used_mib") or mem_info.get("used_mib", 0)
                            inst["ram_used_gb"] = round(ram_used / 1024, 1)
                            inst["ram_total_gb"] = round(ram_total / 1024, 1)
                        # Collect per-process RAM data from agent
                        remote_processes = agent_data.get("processes", [])
                        if not remote_processes:
                            # Try the GPU processes arrays
                            for gpu in agent_data.get("gpus", []):
                                if gpu.get("processes"):
                                    remote_processes.extend(gpu["processes"])

            self.peer_status[name] = {
                "healthy": is_up,
                "host": host,
                "port": port,
                "machine": inst.get("machine", "host"),
                "last_check": time.time(),
                "model": inst.get("model", "unknown"),
                "gpu": inst.get("gpu", "unknown"),
                "vram_used_gb": inst.get("vram_used_gb"),
                "vram_total_gb": inst.get("vram_total_gb"),
                "ram_used_gb": inst.get("ram_used_gb"),
                "ram_total_gb": inst.get("ram_total_gb"),
                "tokens_per_second": tps or inst.get("tokens_per_second"),
                "slots": slots,
                "is_local": is_local,
                "agent_port": inst.get("agent_port"),
                "kv_cache": inst.get("kv_cache"),
                "parallel_slots": inst.get("parallel_slots"),
                "vram_live_mib": vram_data.get("used_vram_mib"),
                "vram_live_total_mib": vram_data.get("total_vram_mib"),
                "processes": remote_processes,
            }

        for name, prov in self.providers_config.get("providers", {}).items():
            if prov.get("type") == "cloud":
                is_up = await self._check_cloud(prov.get("api_base"))
                self.peer_status[f"cloud:{name}"] = {
                    "healthy": is_up,
                    "host": prov.get("api_base"),
                    "machine": "Cloud",
                    "last_check": time.time(),
                    "models": list(prov.get("models", {}).keys()),
                    "is_cloud": True,
                }

    async def _check_remote_health(self, host: str, port: int) -> bool:
        """Simple TCP + HTTP health check for remote llama.cpp instances."""
        try:
            import aiohttp
            async with aiohttp.ClientSession() as s:
                async with s.get(
                    f"http://{host}:{port}/health",
                    timeout=aiohttp.ClientTimeout(total=3),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        return data.get("status") == "ok"
                    return False
        except Exception:
            return False

    async def _get_remote_slots(self, host: str, port: int) -> tuple[list, str | None]:
        """Get slot info and model name from a remote llama.cpp instance."""
        import aiohttp
        slots = []
        model_name = None
        try:
            async with aiohttp.ClientSession() as s:
                async with s.get(
                    f"http://{host}:{port}/slots",
                    timeout=aiohttp.ClientTimeout(total=3),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        for sl in (data if isinstance(data, list) else []):
                            slots.append({
                                "id": sl.get("id"),
                                "state": "idle" if sl.get("state") == 0 else "processing",
                                "n_prompt_tokens": sl.get("n_prompt_tokens", 0),
                                "n_prompt_tokens_processed": sl.get("n_prompt_tokens_processed", 0),
                            })
        except Exception:
            pass

        # Also try to get model name from /v1/models
        try:
            async with aiohttp.ClientSession() as s:
                async with s.get(
                    f"http://{host}:{port}/v1/models",
                    timeout=aiohttp.ClientTimeout(total=3),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        models = data.get("data", [])
                        if models:
                            model_name = models[0].get("id", None)
        except Exception:
            pass

        return slots, model_name

    async def _get_remote_agent_data(self, host: str, agent_port: int = 8899) -> dict:
        """Get VRAM + memory + processes from remote agent."""
        try:
            import aiohttp
            async with aiohttp.ClientSession() as s:
                async with s.get(
                    f"http://{host}:{agent_port}/vram",
                    timeout=aiohttp.ClientTimeout(total=3),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        # Always fetch /proc for system-level processes (docker, wireguard, etc.)
                        # and merge with GPU processes from /vram
                        try:
                            async with s.get(
                                f"http://{host}:{agent_port}/proc",
                                timeout=aiohttp.ClientTimeout(total=3),
                            ) as proc_resp:
                                if proc_resp.status == 200:
                                    proc_data = await proc_resp.json()
                                    proc_list = proc_data.get("processes", [])
                                    # Merge: GPU processes from /vram + system processes from /proc
                                    # Deduplicate by PID (GPU processes take priority)
                                    gpu_pids = set()
                                    for gpu in data.get("gpus", []):
                                        for p in gpu.get("processes", []):
                                            pid = p.get("pid")
                                            if pid:
                                                gpu_pids.add(pid)
                                    # Also track PIDs from top-level /vram processes
                                    for p in data.get("processes", []):
                                        pid = p.get("pid")
                                        if pid:
                                            gpu_pids.add(pid)
                                    # Add system processes not already in GPU list
                                    for p in proc_list:
                                        pid = p.get("pid")
                                        if pid and pid not in gpu_pids:
                                            data.setdefault("processes", []).append(p)
                                    # Use /proc system_ram if /vram didn't have it
                                    if not data.get("system_ram") and proc_data.get("system_ram"):
                                        data["system_ram"] = proc_data["system_ram"]
                        except Exception:
                            pass
                        return data
        except Exception:
            pass
        return {}

    async def _check_local_service(self, name: str) -> bool:
        """Check if a local service is running via providers.json or services.json."""
        # First check providers.json for systemd_unit field
        inst = self.instances.get(name, {})
        unit = inst.get("systemd_unit", "")
        if not unit:
            # Fall back to services.json
            svc = self.services_config.get("services", {}).get(name, {})
            unit = svc.get("systemd_unit", f"{name}.service")
        try:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", "--quiet", unit
            )
            await proc.wait()
            return proc.returncode == 0
        except Exception:
            return False

    async def _get_llama_slots(self, host: str, port: int) -> tuple[list, int]:
        """Get slot info from a local llama.cpp instance."""
        try:
            import aiohttp
            async with aiohttp.ClientSession() as s:
                async with s.get(
                    f"http://{host}:{port}/slots",
                    timeout=aiohttp.ClientTimeout(total=2),
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        slots = []
                        tps = 0
                        for sl in data if isinstance(data, list) else []:
                            slots.append({
                                "id": sl.get("id"),
                                "state": "idle" if sl.get("state") == 0 else "processing",
                            })
                            tokens = sl.get("tokens_processed", 0)
                            t_start = sl.get("t_start")
                            if t_start and tokens > 0 and t_start > 0:
                                elapsed = time.time() - t_start
                                if elapsed > 0:
                                    tps += int(tokens / elapsed)
                        return slots, tps
                    return [], 0
        except Exception:
            return [], 0

    async def _check_cloud(self, api_base: str) -> bool:
        """Check cloud provider reachability."""
        try:
            import aiohttp
            async with aiohttp.ClientSession() as s:
                url = f"{api_base.rstrip('/')}/models"
                async with s.get(url, timeout=aiohttp.ClientTimeout(total=5)) as resp:
                    return resp.status < 500
        except Exception:
            return False


