# Headers whose presence on caller-supplied outbound requests would
# smuggle a credential past the upstream.  Forwarding them unchanged
# defeats the loopback allowlist.
_FORBIDDEN_PROXY_HEADER_NAMES = frozenset(
    {"authorization", "cookie", "proxy-authorization", "x-api-key"}
)


def _strip_credential_headers(headers: Any) -> dict[str, str]:
    """Return a copy of *headers* with credential headers removed.

    Non-dict inputs return an empty dict.  String values are preserved
    unchanged; bytes values are decoded as UTF-8 with replacement so
    that header construction cannot fail on caller-supplied garbage.
    """
    if not isinstance(headers, Mapping):
        return {}
    result: dict[str, str] = {}
    for key, value in headers.items():
        if not isinstance(key, str) or not key:
            continue
        # Header field names cannot legally contain surrounding whitespace,
        # but normalize it here so malformed caller-supplied mappings cannot
        # evade the credential denylist before aiohttp serializes them.
        if key.strip().lower() in _FORBIDDEN_PROXY_HEADER_NAMES:
            continue
        if isinstance(value, bytes):
            try:
                value = value.decode("utf-8")
            except UnicodeDecodeError:
                value = value.decode("utf-8", errors="replace")
        if not isinstance(value, str):
            continue
        result[key] = value
    return result


def _api_proxy_target_url(url: Any) -> str | None:
    """Validate *url* and return its canonical loopback target URL.

    Only http/https loopback URLs are considered.  Userinfo, missing
    or malformed ports, the controller's own LISTEN_PORT, and ports
    that are not declared on any enabled service in
    ``_services_config`` are rejected.  The returned URL is rebuilt from
    these validated parsed components, never from the caller's raw string.
    """
    from urllib.parse import urlparse, urlunparse

    if not isinstance(url, str) or not url:
        return None
    if any(ord(char) < 0x20 for char in url):
        return None
    try:
        parsed = urlparse(url)
    except ValueError:
        return None
    scheme = parsed.scheme.lower()
    if scheme not in {"http", "https"}:
        return None
    if parsed.username is not None or parsed.password is not None:
        return None
    hostname = parsed.hostname
    if hostname is None:
        return None
    hostname = hostname.lower()
    if hostname not in {"localhost", "127.0.0.1", "::1"}:
        return None
    try:
        port = parsed.port
    except ValueError:
        return None
    if port is None:
        return None
    if port == LISTEN_PORT:
        return None

    cfg = _services_config if isinstance(_services_config, Mapping) else {}
    services = cfg.get("services") if isinstance(cfg, Mapping) else None
    if not isinstance(services, Mapping):
        return None
    declared = False
    for svc in services.values():
        if not isinstance(svc, Mapping):
            continue
        if not svc.get("enabled", False):
            continue
        declared_ports = set()
        for field in ("port", "proxy_port"):
            value = svc.get(field)
            if isinstance(value, bool):
                continue
            if isinstance(value, int) and 0 < value < 65536:
                declared_ports.add(value)
        if port in declared_ports:
            declared = True
            break
    if not declared:
        return None

    # Rebuild the authority from the validated hostname and explicit port.
    # Brackets are required for the IPv6 loopback literal.
    authority_host = f"[{hostname}]" if ":" in hostname else hostname
    return urlunparse((scheme, f"{authority_host}:{port}", parsed.path, "", parsed.query, ""))


def _api_proxy_target_is_allowed(url: Any) -> bool:
    """Return True iff *url* points at an enabled service's declared port."""
    return _api_proxy_target_url(url) is not None


async def handle_api_proxy(request: web.Request) -> web.Response:
    """POST /api/proxy — Forward arbitrary HTTP requests to localhost backends (CORS proxy).

    Only explicit loopback http/https URLs whose port is declared as
    ``port`` or ``proxy_port`` on an enabled service in
    ``_services_config`` are accepted.  Userinfo, missing/malformed
    ports, the controller's own LISTEN_PORT, and undeclared ports are
    all rejected before any I/O.  Authorization, Cookie,
    Proxy-Authorization and X-API-Key headers are stripped from
    caller-supplied headers before forwarding.
    """
    try:
        body = await request.json()
    except (ValueError, json.JSONDecodeError):
        return web.json_response({"error": "Invalid JSON body"}, status=400)

    url = body.get("url")
    if not url:
        return web.json_response({"error": "Missing 'url' field"}, status=400)

    method = body.get("method", "GET").upper()
    allowed_methods = {"GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"}
    if method not in allowed_methods:
        return web.json_response({"error": f"Unsupported method: {method}"}, status=400)

    target_url = _api_proxy_target_url(url)
    if target_url is None:
        return web.json_response(
            {"error": "proxy target is not an enabled service port"},
            status=403,
        )

    req_headers = body.get("headers", {})
    safe_headers = _strip_credential_headers(req_headers)
    req_body = body.get("body")

    if req_body and isinstance(req_body, str):
        body_bytes = req_body.encode("utf-8")
    elif req_body:
        body_bytes = json.dumps(req_body).encode("utf-8")
    else:
        body_bytes = None

    if body_bytes and len(body_bytes) > 10 * 1024 * 1024:
        return web.json_response({"error": "Request body exceeds 10MB limit"}, status=413)

    timeout = ClientTimeout(total=30)
    start = time.monotonic()
    try:
        async with session.request(
            method,
            target_url,
            headers=safe_headers,
            data=body_bytes,
            timeout=timeout,
            ssl=False,
        ) as resp:
            elapsed_ms = int((time.monotonic() - start) * 1000)
            try:
                resp_body = await resp.text()
            except Exception:
                resp_body = ""
            return web.json_response({
                "status": resp.status,
                "headers": dict(resp.headers),
                "body": resp_body,
                "elapsed_ms": elapsed_ms,
            })
    except asyncio.TimeoutError:
        return web.json_response({"error": "Upstream request timed out"}, status=504)
    except aiohttp.ClientError as e:
        return web.json_response({"error": f"Upstream connection error: {e}"}, status=502)
    except Exception as e:
        return web.json_response({"error": str(e)}, status=500)


# ── Application Setup ──────────────────────────────────────────────

# ── Phase 4: explicit OOM recovery watchdog + scheduler health + MCP killer ─
# These three loops are the always-on "watchdog" tier. They run independently
# of any pusher / worker so that even if the vram pusher or scheduler stalls,
# OOM recovery still fires and stale MCP siblings still get killed.


async def _oom_recovery_watchdog_loop():
    """Dedicated OOM recovery watchdog. Runs every OOM_WATCHDOG_POLL_INTERVAL_S.

    Per adversarial #17: wrap entire body in try/except so the loop never dies.
    Per adversarial #19: use job-specific stall detection, not blanket timeout.
    Per adversarial #21: per-GPU stall timeout (180s gpu_primary, 120s gpu_secondary).

    Responsibilities:
      1. Update _last_oom_heartbeat_ts and (best-effort) write the Redis
         OOM_REDIS_HEARTBEAT key so peers can see this manager is alive.
      2. Promote GPUs stuck in 'detected' for too long to 'permanent_failed'
         so the system never hangs waiting for a recovery that won't run.
      3. Reset GPUs stuck in 'draining'/'verifying'/'recovering' back to
         'detected' so the pipeline can retry.
      4. Trigger recovery for any GPU currently in 'detected' (the primary
         recovery trigger — the vram pusher also fires, but this one is
         always on).
    """
    global _last_oom_heartbeat_ts
    logger.info("[oom-watchdog] Starting OOM recovery watchdog")
    while True:
        try:
            await asyncio.sleep(OOM_WATCHDOG_POLL_INTERVAL_S)

            # ── Heartbeat: always-on (every poll = every 2s) ──
            now = time.time()
            _last_oom_heartbeat_ts = now

            # Best-effort Redis write every OOM_WATCHDOG_HEARTBEAT_INTERVAL_S
            # (default 10s). We deliberately don't fail the loop if Redis
            # is unreachable.
            heartbeat_count = getattr(_oom_recovery_watchdog_loop, "_heartbeat_count", 0) + 1
            # Functions accept arbitrary attribute assignment at runtime;
            # Pyright models them as plain FunctionType so we silence.
            _oom_recovery_watchdog_loop._heartbeat_count = heartbeat_count  # type: ignore[attr-defined]
            # Phase 5: refresh dead-letter cache every ~30s (15 polls * 2s)
            if heartbeat_count % 15 == 0:
                try:
                    await _refresh_dead_letter_cache()
                except Exception as _dl_cache_err:
                    logger.debug(f"[oom-watchdog] dead-letter cache refresh failed: {_dl_cache_err}")
            if heartbeat_count % max(
                1, OOM_WATCHDOG_HEARTBEAT_INTERVAL_S // OOM_WATCHDOG_POLL_INTERVAL_S
            ) == 0:
                try:
                    redis_client = globals().get("_redis_client") or globals().get("redis_client")
                    if redis_client is not None:
                        payload = json.dumps({
                            "ts": now,
                            "count": heartbeat_count,
                            "hostname": socket.gethostname(),
                        })
                        await asyncio.to_thread(
                            redis_client.set,
                            OOM_REDIS_HEARTBEAT,
                            payload,
                            ex=60,  # 60s TTL — peer treats key absence as dead
                        )
                except Exception as e:
                    logger.debug(f"[oom-watchdog] heartbeat write failed: {e}")

            # ── Stall detection: GPUs stuck in 'detected' → permanent_failed ──
            for gpu_id, bs in list(_gpu_states.items()):
                if bs.oom_state == "detected" and bs.oom_state_since > 0:
                    age = now - bs.oom_state_since
                    # Per adversarial #21: per-GPU timeout. The constants
                    # are deliberately re-checked (not snapshotted) so a
                    # future per-GPU config can override without touching
                    # this loop.
                    timeout = OOM_EVICTING_STUCK_TIMEOUT_S  # default 180s
                    if gpu_id == "gpu_primary":
                        timeout = 180
                    elif gpu_id == "gpu_secondary":
                        timeout = 120
                    if age > timeout:
                        logger.error(
                            f"[oom-watchdog] {gpu_id} stuck in 'detected' for "
                            f"{age:.1f}s (> {timeout}s), forcing permanent_failed"
                        )
                        try:
                            bs.set_oom_state(
                                "permanent_failed",
                                source="_oom_recovery_watchdog_loop",
                                reason=f"stuck in detected for {age:.1f}s",
                            )
                            bs.oom_permanent_failure_count += 1
                            # Phase 5: record to dead-letter list if we know the job
                            try:
                                wid = bs.oom_active_recovery_job_id or ""
                                if wid:
                                    await _add_to_dead_letter(
                                        job_id=wid,
                                        gpu_id=gpu_id,
                                        reason=f"stuck_in_detected {age:.1f}s",
                                        last_state="permanent_failed",
                                    )
                            except Exception as _dl_err:
                                logger.debug(f"[oom-watchdog] dead-letter add failed: {_dl_err}")
                        except Exception as e:
                            logger.warning(f"[oom-watchdog] set_oom_state failed: {e}")

                elif (
                    bs.oom_state in ("draining", "verifying", "recovering")
                    and bs.oom_state_since > 0
                ):
                    age = now - bs.oom_state_since
                    timeout = OOM_RECOVERY_TIMEOUT_S  # 30s for non-detected stages
                    if age > timeout:
                        logger.warning(
                            f"[oom-watchdog] {gpu_id} stuck in "
                            f"'{bs.oom_state}' for {age:.1f}s, "
                            f"escalating to detected for retry"
                        )
                        try:
                            bs.set_oom_state(
                                "detected",
                                source="_oom_recovery_watchdog_loop",
                                reason=f"stuck in {bs.oom_state}",
                            )
                        except Exception as e:
                            logger.warning(f"[oom-watchdog] reset to detected failed: {e}")

            # ── Recovery trigger: any GPU in 'detected' → kick pipeline ──
            for gpu_id, bs in list(_gpu_states.items()):
                if bs.oom_state != "detected":
                    continue
                inflight_ts = _oom_recovery_in_progress.get(gpu_id)
                if inflight_ts and now - inflight_ts < OOM_RECOVERY_TIMEOUT_S:
                    # Recovery already running — don't pile up
                    continue
                service_name = _resolve_service_for_gpu(gpu_id)
                _oom_recovery_in_progress[gpu_id] = now
                job_id = bs.oom_active_recovery_job_id or ""
                reason = bs.oom_last_reason or "watchdog_detected"
                try:
                    asyncio.create_task(
                        _run_recovery_with_cleanup(gpu_id, service_name, job_id, reason)
                    )
                except Exception as e:
                    logger.error(f"[oom-watchdog] create_task for {gpu_id} failed: {e}")
                    _oom_recovery_in_progress.pop(gpu_id, None)

        except asyncio.CancelledError:
            logger.info("[oom-watchdog] Shutting down")
            raise
        except Exception as e:
            # Per adversarial #17: never let the watchdog die.
            logger.exception(f"[oom-watchdog] Unhandled exception in loop: {e}")
            await asyncio.sleep(1)  # back off briefly


async def _run_recovery_with_cleanup(
    gpu_id: str, service_name: str, job_id: str, reason: str
):
    """Wrap _oom_recovery_pipeline with bookkeeping for _oom_recovery_in_progress.

    The watchdog fires every 2s; without this wrapper two ticks could both
    decide the GPU is detected and both schedule a recovery. The wrapper
    guarantees _oom_recovery_in_progress is cleared even if the pipeline
    raises (so the next tick can re-evaluate).
    """
    try:
        await _oom_recovery_pipeline(
            gpu_id, service_name, job_id=job_id, oom_reason=reason
        )
    except Exception as e:
        logger.warning(
            f"[oom-watchdog] _oom_recovery_pipeline({gpu_id}) raised: {e}"
        )
    finally:
        _oom_recovery_in_progress.pop(gpu_id, None)


# Phase 5.2.49: stale-job reaper. Periodically scans Redis for in_flight jobs
# whose started_at is older than the safe deadline (forward_timeout +
# post_load_grace + 5min buffer). Force-fails them so the scheduler stops
# re-feeding the queue. Complements the Redis TTL added in queue_engine.py.
_STALE_JOB_REAPER_INTERVAL_S = 60   # poll every 60s
_STALE_JOB_DEFAULT_DEADLINE_S = 2700  # 45 min — same as TTL in queue_engine.py


async def _stale_job_continuation_signals(redis_client, data: dict) -> tuple[bool, bool, bool]:
    """Return (PEL owns job, stream contains job, backend running).

    Inspection failures are treated conservatively as continuation signals so
    the reaper cannot terminalize a job on incomplete evidence.
    """
    job_id = data.get("job_id", "")
    routing_group = data.get("routing_group") or data.get("service_name") or ""
    stream_has_entry = True
    stream_has_pel = True

    if routing_group and job_id:
        try:
            queue = globals().get("queue_engine")
            if queue is not None and getattr(queue, "priority_lanes_enabled", False):
                stream_specs = queue._stream_specs(
                    routing_group, routing_group=routing_group
                )
            else:
                stream_specs = [(f"queue:{routing_group}", None)]
            found_entry = False
            found_pel = False
            for stream, _lane in stream_specs:
                entries = redis_client.xrange(stream, min="-", max="+", count=1000)
                matching_ids = {
                    str(entry_id)
                    for entry_id, fields in entries
                    if str((fields or {}).get("job_id", "")) == str(job_id)
                }
                if matching_ids:
                    found_entry = True
                    pending = redis_client.xpending_range(
                        stream, RedisQueue.GROUP, min="-", max="+", count=1000
                    )
                    if any(
                        str((item or {}).get("message_id", "")) in matching_ids
                        for item in (pending or [])
                    ):
                        found_pel = True
            stream_has_entry = found_entry
            stream_has_pel = found_pel
        except Exception:
            logger.exception(
                "[stale-reaper] continuation inspection failed for job=%s routing_group=%s",
                job_id, routing_group,
            )
            stream_has_entry = True
            stream_has_pel = True

    service_running = True
    service_name = data.get("service_name", "")
    try:
        svc = (_load_services_config().get("services", {}) or {}).get(service_name, {})
        unit = svc.get("systemd_unit", "")
        if unit:
            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", unit,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.DEVNULL,
            )
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=5)
            service_running = stdout.decode(errors="replace").strip() == "active"
    except Exception:
        logger.exception(
            "[stale-reaper] backend-state inspection failed for job=%s service=%s",
            job_id, service_name,
        )
        service_running = True

    return stream_has_pel, stream_has_entry, service_running


async def _stale_job_reaper_loop() -> None:
    """Force-fail orphaned in_flight jobs whose worker died mid-poll.

    Scans Redis `job:*` hashes every 60s. For each entry where:
      - status == "in_flight"
      - started_at is older than (now - deadline)

    mark it failed with an audit message. The TTL in queue_engine.py would
    eventually auto-expire these, but the watchdog lets us react faster and
    keeps scheduler state in sync with Redis.
    """
    from datetime import datetime, timezone
    logger.info("[stale-reaper] Starting stale-job reaper (interval=%ds)",
                _STALE_JOB_REAPER_INTERVAL_S)
    while True:
        try:
            await asyncio.sleep(_STALE_JOB_REAPER_INTERVAL_S)
            now = time.time()
            # Allow override via env var for tighter testing
            deadline_s = int(os.environ.get(
                "GPU_MANAGER_STALE_JOB_DEADLINE_S",
                _STALE_JOB_DEFAULT_DEADLINE_S))
            # Best-effort: get redis handle. Prefer _queue_redis module global
            # set by create_app; fall back to constructing a fresh client.
            redis_client = globals().get("_queue_redis")
            if redis_client is None:
                try:
                    redis_client = _redis_mod.Redis(**_redis_connection_kwargs())
                except Exception as e:
                    logger.debug("[stale-reaper] cannot create redis client: %s", e)
                    continue
            reaped = 0
            for key in redis_client.scan_iter(match="job:*", count=100):
                try:
                    data = redis_client.hgetall(key)
                    if not data:
                        continue
                    if data.get("status") != "in_flight":
                        continue
                    started_at = data.get("started_at")
                    if not started_at:
                        continue
                    # started_at is ISO-8601. Parse to epoch.
                    try:
                        started_ts = datetime.fromisoformat(
                            started_at.replace("Z", "+00:00")
                        ).timestamp()
                    except (ValueError, AttributeError):
                        continue
                    age_s = now - started_ts
                    if age_s < deadline_s:
                        continue
                    # Orphan candidate. Terminalize only when the stream PEL,
                    # stream body, and backend state all prove continuation is
                    # impossible. Any positive/unknown signal preserves it.
                    job_id = data.get("job_id") or key.split(":", 1)[-1]
                    stream_has_pel, stream_has_entry, service_running = (
                        await _stale_job_continuation_signals(redis_client, data)
                    )
                    tracker = JobTracker(r=redis_client)
                    decision = terminalize_job_if_impossible(
                        tracker,
                        job_id,
                        stream_has_pel=stream_has_pel,
                        stream_has_entry=stream_has_entry,
                        service_running=service_running,
                        force=True,
                    )
                    if decision.get("action") == "terminalized":
                        logger.warning(
                            "[stale-reaper] terminalized job=%s age=%.0fs deadline=%ds",
                            job_id, age_s, deadline_s,
                        )
                        reaped += 1
                    else:
                        logger.info(
                            "[stale-reaper] preserved job=%s age=%.0fs reason=%s",
                            job_id, age_s, decision.get("reason", "unknown"),
                        )
                except Exception:
                    # Per-pattern from OOM watchdog: never let inner loop die.
                    logger.exception("[stale-reaper] error processing key %s", key)
            if reaped:
                logger.info("[stale-reaper] reaped %d orphaned in_flight job(s)",
                            reaped)
        except Exception:
            # Per-pattern from OOM watchdog: never let loop die.
            logger.exception("[stale-reaper] outer loop error, continuing")


async def _scheduler_health_check_loop():
    """Periodically check if the scheduler is running. Restart if dead.

    Per adversarial C.6: if scheduler_running=false for >30s, restart.

    The scheduler is started once in background_loop. If its loop task dies
    (uncaught exception, GC pressure, etc.), the whole queue system freezes
    silently — services stay running but no new jobs are dispatched. This
    loop catches that and either:
      - logs a clear warning so operators can intervene, or
      - if `scheduler.run()` exists and is safe to call, restarts it.

    We do NOT auto-restart by default (the scheduler class has internal
    state we don't want to clobber). We log + emit an event so the failure
    is visible.
    """
    last_false_ts: float | None = None
    last_durable_false_ts: float | None = None
    check_interval = 15  # s
    fail_threshold = 30  # s — how long it can be down before we shout
    while True:
        try:
            await asyncio.sleep(check_interval)
            owner_mode = _queue_owner_mode()
            scheduler_obj = globals().get("scheduler")
            if owner_mode == 'durable':
                # The compatibility scheduler is intentionally not started in
                # this mode.  Observe only the durable owner; never restart or
                # construct the legacy dispatcher from this watchdog.
                durable = globals().get("worker_supervisor")
                if durable is not None:
                    durable_running = bool(
                        getattr(durable, "_running", False)
                        or getattr(durable, "running", False)
                    )
                    now = time.time()
                    if not durable_running:
                        if last_durable_false_ts is None:
                            last_durable_false_ts = now
                        elif now - last_durable_false_ts > fail_threshold:
                            logger.warning(
                                "[scheduler-health] durable worker supervisor "
                                "running=false for >%ss — Redis generation dispatch may be stalled",
                                fail_threshold,
                            )
                            last_durable_false_ts = now
                    else:
                        last_durable_false_ts = None
                continue
            if scheduler_obj is None:
                continue
            running = bool(
                getattr(scheduler_obj, "_running", False)
                or getattr(scheduler_obj, "running", False)
            )
            now = time.time()
            if not running:
                if last_false_ts is None:
                    last_false_ts = now
                elif now - last_false_ts > fail_threshold:
                    logger.warning(
                        f"[scheduler-health] scheduler_running=false for "
                        f">{fail_threshold}s — queue dispatch may be stalled"
                    )
                    # Phase 5: prefer first-class scheduler.restart(); fall back
                    # to getattr(run_async/run) for backward compatibility.
                    restart_method = getattr(scheduler_obj, "restart", None)
                    if callable(restart_method):
                        try:
                            # restart is async in our impl
                            coro = restart_method()
                            if asyncio.iscoroutine(coro):
                                asyncio.create_task(coro)
                            else:
                                # Sync restart fallback
                                restart_method()
                            logger.info(
                                "[scheduler-health] Scheduler restart triggered via scheduler.restart()"
                            )
                            last_false_ts = None
                        except Exception as e:
                            logger.error(
                                f"[scheduler-health] scheduler.restart() failed: {e}"
                            )
                    else:
                        # Attempt restart: prefer run_async if available, else run.
                        # If neither is callable, we just keep logging.
                        run_method = (
                            getattr(scheduler_obj, "run_async", None)
                            or getattr(scheduler_obj, "run", None)
                        )
                        if callable(run_method):
                            try:
                                # run_method is a coroutine function (e.g.
                                # scheduler.run_async); Pyright can't infer this
                                # through getattr.
                                coro = run_method()  # type: ignore[func-returns-value]
                                asyncio.create_task(coro)  # type: ignore[arg-type]
                                logger.info(
                                    "[scheduler-health] Scheduler restart triggered (fallback run_method)"
                                )
                                last_false_ts = None
                            except Exception as e:
                                logger.error(
                                    f"[scheduler-health] Restart failed: {e}"
                                )
                    # Reset last_false_ts so we don't spam every iteration;
                    # next false-streak will re-arm.
                    last_false_ts = now
            else:
                last_false_ts = None

            # The Redis worker owner is a separate dispatch authority.  Do
            # not call its supervisor loop from this watchdog (that could
            # create duplicate pools); retain a bounded warning/health signal
            # until the ownership consolidation slice gives it a dedicated
            # restart contract.
            durable = globals().get("worker_supervisor")
            if durable is not None and owner_mode != 'legacy':
                durable_running = bool(
                    getattr(durable, "_running", False)
                    or getattr(durable, "running", False)
                )
                if not durable_running:
                    if last_durable_false_ts is None:
                        last_durable_false_ts = now
                    elif now - last_durable_false_ts > fail_threshold:
                        logger.warning(
                            "[scheduler-health] durable worker supervisor "
                            "running=false for >%ss — Redis generation dispatch may be stalled",
                            fail_threshold,
                        )
                        # Re-arm after the warning; lifecycle/restart ownership
                        # remains with WorkerSupervisor until the two-owner
                        # migration is complete.
                        last_durable_false_ts = now
                else:
                    last_durable_false_ts = None
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.debug(f"[scheduler-health] health check error: {e}")


def _kill_stale_mcp_siblings():
    """Kill any other gpu-manager.py --mcp processes besides this one.

    Per Phase 1 known issue: stale --mcp processes from earlier sessions
    don't reload the new code and report stale state. We walk /proc for
    processes whose cmdline contains 'gpu-manager.py --mcp', skip ourselves,
    and send SIGTERM to each. We deliberately do NOT send SIGKILL — if the
    sibling is mid-write to a state file, SIGTERM gives it a chance to
    clean up. systemd will restart it if appropriate.

    Phase 6 — companion cron on zeroclaw-pi:
        This function is the in-process cleanup, but it only runs at
        process start. If an --mcp child process becomes orphaned (parent
        gone, but the child lingers because of broken stdio), nothing here
        can detect it. The cron spec is documented in
        scripts/PHASE6_OUTCOME.md § "Orphan --mcp cleanup cron". Per the
        user's standing rule (2026-06-14), that cron lives INSIDE
        zeroclaw, not as a systemd timer.
    """
    my_pid = os.getpid()
    try:
        with open(f"/proc/{my_pid}/cmdline", "rb") as f:
            my_cmdline = f.read().decode("utf-8", errors="replace")
        if "--mcp" not in my_cmdline:
            # Only kill siblings if WE are an --mcp process — otherwise we
            # shouldn't be in the MCP-killer business at all.
            return
    except Exception:
        return

    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        pid = int(entry)
        if pid == my_pid:
            continue
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as f:
                cmdline = f.read().decode("utf-8", errors="replace")
        except (FileNotFoundError, ProcessLookupError, PermissionError):
            continue
        if "gpu-manager.py" not in cmdline or "--mcp" not in cmdline:
            continue
        try:
            os.kill(pid, signal.SIGTERM)
            logger.info(
                f"[mcp-cleanup] Sent SIGTERM to stale --mcp process {pid}"
            )
        except ProcessLookupError:
            pass
        except Exception as e:
            logger.debug(f"[mcp-cleanup] Could not kill PID {pid}: {e}")



async def _expire_reservations_loop():
    while True:
        try:
            expired = expire_reservations()
            if expired:
                logger.info(f"Released expired GPU reservations for: {expired}")
        except Exception as e:
            logger.error(f"Error in expire reservations tick: {e}")
        await asyncio.sleep(5)

async def handle_debug_reserve_gpus(request: web.Request):
    """POST /v1/debug/reserve-gpus — Stage 3 debug hook.

    Body: {"gpus": ["gpu_primary","gpu_secondary"], "hold_s": <1..30>, "reason": "..."}
    Returns 200 {token, expires_at} on success; 409 {"error":"Conflict", ...}
    on overlap; 400/422 on bad input. Always clamps hold_s into [1, 30].
    Only registered when gpu-manager is launched with --debug-reservations.
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    gpus = body.get("gpus", [])
    hold_s = body.get("hold_s", 10)
    if not isinstance(gpus, list) or len(gpus) == 0:
        return web.json_response({"error": "gpus must be a non-empty list"}, status=422)
    configured_gpu_ids = set(
        ((_load_services_config().get("gpu_devices", {}) or {}).keys())
    )
    if (
        not all(isinstance(g, str) for g in gpus)
        or not set(gpus).issubset(configured_gpu_ids)
    ):
        return web.json_response(
            {"error": "gpus must be registered device identifiers"}, status=422
        )
    try:
        hold_s = float(hold_s)
    except Exception:
        return web.json_response({"error": "hold_s must be a number"}, status=400)

    # Hard cap: no caller-supplied value may exceed the 30s ceiling.
    hold_s = max(1.0, min(30.0, hold_s))

    token_hex = uuid.uuid4().hex
    ok, data = reserve_gpus(group="debug", gpu_ids=gpus, hold_s=int(hold_s), token=token_hex)
    if not ok:
        # Surface "Conflict" explicitly so test harness can match on it.
        conflict_body = {"error": "Conflict"}
        if isinstance(data, dict):
            conflict_body.update(data)
        return web.json_response(conflict_body, status=409)
    return web.json_response(data)

async def handle_debug_release_gpus(request: web.Request):
    """POST /v1/debug/release-gpus — Stage 3 debug hook.

    Body: {"token": "<uuid4 hex>"}
    Returns 200 {released: [...]} on success; 404 if token unknown/expired.
    Only registered when gpu-manager is launched with --debug-reservations.
    """
    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)
    token = body.get("token")
    if not token:
        return web.json_response({"error": "token required"}, status=400)
    ok, data = release_gpus(group="debug", token=token, reason="debug_release")
    if not ok:
        return web.json_response({"error": "Not found or expired"}, status=404)
    return web.json_response(data)

async def handle_debug_list_reservations(request: web.Request):
    return web.json_response({"gpu_reservations": _gpu_reservations})


async def _delayed_stale_mcp_cleanup():
    """Wait for this process to fully initialize, then kill stale MCP siblings.

    30s delay: gives our own MCP server (if we're an --mcp instance) time to
    bind its stdio / register tools before we start killing siblings. If we
    ARE the stale one (e.g. a fresh restart replacing an old instance), the
    30s gives the old instance a chance to notice systemd's stop signal and
    shut down cleanly.
    """
    await asyncio.sleep(30)
    _kill_stale_mcp_siblings()



async def handle_debug_simulate_oom(request: web.Request):
    """POST /v1/debug/simulate-oom — Stage 4 safe OOM simulation hook."""
    import uuid
    try:
        body = await request.json()
    except Exception:
        body = {}

    gpu_id = body.get("gpu_id")
    configured_gpu_ids = set(
        ((_load_services_config().get("gpu_devices", {}) or {}).keys())
    ) | set(_gpu_states)
    if not isinstance(gpu_id, str) or gpu_id not in configured_gpu_ids:
        return web.json_response(
            {"error": "gpu_id required and must identify a registered device"},
            status=422,
        )

    service_name = body.get("service_name", "debug-oom-sim")
    job_id = body.get("job_id", f"debug-oom-{uuid.uuid4().hex[:8]}")
    reason = body.get("reason", "synthetic OOM simulation")
    details = body.get("details", "debug endpoint, no real VRAM exhaustion")

    try:
        result = _handle_oom_event(
            gpu_id=gpu_id,
            service_name=service_name,
            job_id=job_id,
            detection_source="debug-simulate-oom",
            reason=reason,
            details=details
        )
        gpu_state = _gpu_states.get(gpu_id)
        recorded = bool(result.get("recorded")) if isinstance(result, dict) else False
        status = 200 if recorded else 422
        return web.json_response({
            "ok": recorded,
            "event": result,
            "gpu_oom_state": gpu_state.oom_state if gpu_state else "unknown",
            "gpu_id": gpu_id,
            "job_id": job_id
        }, status=status)
    except Exception as e:
        logger.error(f"Error in simulate OOM hook: {e}")
        return web.json_response({"error": str(e)}, status=500)

async def handle_debug_oom_state(request: web.Request):
    """GET /v1/debug/oom-state/{gpu_id}"""
    gpu_id = request.match_info.get("gpu_id")
    if gpu_id not in _gpu_states:
        return web.json_response({"error": "Unknown GPU"}, status=404)

    state = _gpu_states[gpu_id]
    return web.json_response({
        "oom_state": state.oom_state,
        "oom_event_count": state.oom_event_count,
        "oom_last_reason": state.oom_last_reason,
        "oom_recovery_count": state.oom_recovery_count
    }, status=200)

def _coordinator_job_dict(job):
    if job is None:
        return None
    if isinstance(job, dict):
        return dict(job)
    if hasattr(job, "to_dict"):
        return job.to_dict()
    return dict(vars(job))


async def _admit_internal_generation_leaf(service_id, resource_id, job_id, trusted_config):
    """Admit one deterministic coordinator child through the durable queue."""
    if queue_engine is None or job_tracker is None:
        raise RuntimeError("generation queue unavailable")
    identity_sha = hashlib.sha256(json.dumps(
        {"service_id": service_id, "resource_id": resource_id, "config": trusted_config},
        sort_keys=True, separators=(",", ":"),
    ).encode()).hexdigest()
    existing = _coordinator_job_dict(job_tracker.get_job(job_id))
    if existing is not None:
        if str(existing.get("parent_job_id") or "") != str(trusted_config.get("parent_job_id") or ""):
            raise RuntimeError("deterministic child identity conflict")
        if existing.get("request_sha256") and existing["request_sha256"] != identity_sha:
            raise RuntimeError("deterministic child request conflict")
        if not existing.get("entry_id"):
            raise RuntimeError("child outcome unknown: missing queue admission receipt")
        return {"job_id": job_id, "service_id": service_id, "resource_id": resource_id}

    resolved = dict(trusted_config.get("resolved_inputs") or {})
    native = dict(resolved.get("native_brief") or {})
    duration = max(10, min(60, int(resolved.get("duration_seconds") or 60)))
    request_params = {
        "model": "minimax-music3-audiocpp-q8-bf16",
        "request": {
            "text": str(native.get("caption") or native.get("prompt") or ""),
            "lyrics": str(native.get("lyrics") or "[Instrumental]"),
            "options": {
                "duration_sec": float(duration),
                "num_inference_steps": 30,
                "guidance_scale": 1.7,
                "ar_guidance_scale": 1.5,
                "top_k": 50,
                "seed": int(hashlib.sha256(job_id.encode()).hexdigest()[:8], 16),
                "flow_uncond_interval": 1,
                "flow_uncond_warmup": 2,
                "flow_chunk_hop_frames": 0,
                "ensemble_takes": 1,
                "ensemble_prefix_frames": 0,
            },
        },
    }
    parent_job_id = str(trusted_config.get("parent_job_id") or "")
    parent = _coordinator_job_dict(job_tracker.get_job(parent_job_id)) or {}
    priority = int(parent.get("priority", 50))
    priority_class = parent.get("priority_class") or None
    metadata = {
        "parent_job_id": parent_job_id,
        "parent_run_id": trusted_config.get("parent_run_id"),
        "stage_id": trusted_config.get("id"),
        "idempotency_key": trusted_config.get("idempotency_key"),
        "candidate": "audio-cpp-q8-20260908",
        "workflow_timeout_s": 7200,
    }
    source_artifact = None
    if native:
        entry, error = await _build_generation_entry(
            gen_type="minimax-music3-audiocpp-bf16-dit-qualification",
            params=request_params, priority=priority, priority_class=priority_class,
            parent_priority=priority, parent_priority_class=priority_class,
            callback_url=None, metadata=metadata,
        )
    else:
        # Existing protocols are selected by reviewed provider + template,
        # not by a growing controller list of individual service names.
        config = _load_services_config()
        provider = (config.get("pipeline_providers") or {}).get(service_id) or {}
        template = copy.deepcopy((config.get("generation_templates") or {}).get(resource_id) or {})
        backend = template.get("backend")
        service = (config.get("services") or {}).get(backend) or {}
        if (provider.get("adapter") != "gpu_manager_generation"
                or provider.get("endpoint_ref") != backend
                or not _service_is_publicly_qualified(template)
                or not _service_is_publicly_qualified(service)):
            raise RuntimeError("reviewed leaf provider/template binding unavailable")
        error = (_validate_template_qualification(resource_id, template)
                 or _validate_q5_template_identity(resource_id, template))
        if error:
            raise RuntimeError(str(error.get("error")))
        context = trusted_config.get("context") or {}
        request_params = dict(context.get("request_params") or {})
        request_params["prompt"] = str(context.get("effective_prompt") or request_params.get("prompt") or "")
        request_params.setdefault("seed", int(hashlib.sha256(job_id.encode()).hexdigest()[:8], 16))
        stage_params = trusted_config.get("params") or {}
        for key in {item[0] for item in _resolve_inject_keys(template)}:
            if key in stage_params:
                request_params[key] = stage_params[key]
        metadata.pop("candidate", None)
        if template.get("workflow_backend") == "comfyui" or backend == "comfyui":
            # Parent coordinator owns preparation/QC. Do not recursively run
            # inline enhancement or correction inside its generation child.
            template.pop("prompt_enhance", None)
            template.pop("post_generate", None)
            template.pop("service_pipeline_id", None)
            image_targets = [item for item in _resolve_inject_keys(template) if item[0] == "source_image"]
            if image_targets:
                source_artifact = context.get("artifact")
                if not isinstance(source_artifact, Mapping) or not source_artifact.get("sha256"):
                    raise RuntimeError("image correction requires a persisted source artifact")
                request_params["source_image"] = f"{job_id}-source.png"
                metadata["source_image_target"] = list(image_targets[0][1:])
                if context.get("qc_verdict"):
                    request_params["prompt"] += "\nCorrect these observed issues while preserving the requested image: " + json.dumps(context["qc_verdict"].get("report") or {}, sort_keys=True)
            allowed = set(template.get("allowed_params") or [])
            if allowed:
                request_params = {k: v for k, v in request_params.items() if k in allowed}
            entry, error = await _build_comfyui_workflow_entry(
                service_name=backend, tmpl=template, params=request_params,
                job_id=job_id, priority=priority, priority_class=priority_class,
                callback_url=None, metadata=metadata,
            )
        else:
            entry, error = await _build_generation_entry(
                gen_type=resource_id, params=request_params, priority=priority,
                priority_class=priority_class, parent_priority=priority,
                parent_priority_class=priority_class, callback_url=None, metadata=metadata,
            )
    if error or entry is None:
        raise RuntimeError((error or {}).get("error", "generation entry build failed"))
    entry["job_id"] = job_id
    if source_artifact is not None:
        entry["coordinator_source_artifact"] = dict(source_artifact)
    tracked_job = {
        "job_id": job_id, "service_name": entry.get("service_name") or "",
        "source": "pipeline_coordinator_child", "status": "queued",
        "submitted_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "routing_group": entry.get("routing_group") or "",
        "priority": priority, "priority_class": priority_class,
        "parent_job_id": parent_job_id, "request_sha256": identity_sha,
        "stage_id": trusted_config.get("id") or "",
        "idempotency_key_sha256": hashlib.sha256(str(trusted_config.get("idempotency_key") or "").encode()).hexdigest(),
    }
    try:
        entry_id = await asyncio.get_running_loop().run_in_executor(
            None, lambda: queue_engine.enqueue(
                entry.get("service_name") or entry.get("routing_group"), entry,
                entry.get("routing_group"), tracked_job=tracked_job,
            ),
        )
    except Exception:
        # Redis may have committed before the connection failed. Do not
        # overwrite an accepted child's lifecycle with a guessed failure.
        raise
    if not entry_id:
        raise RuntimeError("child admission outcome unknown; reconcile deterministic identity")
    return {"job_id": job_id, "service_id": service_id, "resource_id": resource_id}


def _poll_internal_generation_leaf(job_id):
    job = _coordinator_job_dict(job_tracker.get_job(job_id) if job_tracker else None)
    if not job:
        return {"status": "unknown", "error": "child job not found"}
    result = job.get("result")
    if isinstance(result, str):
        try:
            result = json.loads(result)
        except (TypeError, json.JSONDecodeError):
            result = {}
    result = result if isinstance(result, dict) else {}
    raw_artifact = result.get("artifact")
    if not isinstance(raw_artifact, Mapping):
        files = result.get("files") or result.get("images") or []
        raw_artifact = files[0] if files and isinstance(files[0], Mapping) else None
    artifact = None
    if isinstance(raw_artifact, Mapping):
        path = raw_artifact.get("path_or_url") or raw_artifact.get("path") or raw_artifact.get("url")
        if path:
            artifact = {
                "path_or_url": str(path), "sha256": str(raw_artifact.get("sha256") or ""),
                "producer_stage_id": job.get("stage_id") or "generate-audiocpp", "produced_at": str(raw_artifact.get("produced_at") or ""),
            }
    output = {}
    if artifact:
        output = ({"artifact": artifact, "images": [artifact]}
                  if result.get("images") else
                  {"original_audio": artifact,
                   "generation_receipt": result.get("generation_receipt") or {}})
    return {"status": str(job.get("status") or "unknown"), "artifact": artifact, "output": output, "error": job.get("error") or None}


def _cancel_internal_generation_leaf(job_id):
    job = _coordinator_job_dict(job_tracker.get_job(job_id) if job_tracker else None)
    if not job or job.get("status") in {"completed", "failed", "cancelled"}:
        return False
    if job.get("status") == "in_flight":
        result = job_tracker.mark_cancellation_intent_if_in_flight(job_id)
        return bool(result.get("updated"))
    if job.get("status") == "queued" and job.get("entry_id"):
        result = queue_engine.cancel_queued_atomically(
            service_name=job.get("service_name") or "",
            routing_group=job.get("routing_group") or None,
            entry_id=job["entry_id"], consumer="pipeline-coordinator",
            job_id=job_id, error="parent_cancelled", audit_source="pipeline-coordinator",
            cancelled_by="pipeline-coordinator",
        )
        return bool(result is True or (isinstance(result, dict) and result.get("removed_and_terminalized")))
    return False


def _build_production_coordinator_runtime(config):
    if _queue_redis is None:
        return None
    try:
        from pipeline_coordinator import RedisCoordinatorStore
        from gpu_manager_pipeline_runtime import GPUManagerLeafGenerationClient
        from workflow_coordinator_runtime import build_controller_runtime_from_config
        from minimax_recovered_callbacks import build_recovered_minimax_callbacks

        loop = asyncio.get_running_loop()
        def submit_leaf(service_id, resource_id, job_id, params):
            future = asyncio.run_coroutine_threadsafe(
                _admit_internal_generation_leaf(service_id, resource_id, job_id, params), loop
            )
            return future.result(timeout=420)
        leaf = GPUManagerLeafGenerationClient(
            submit_leaf=submit_leaf,
            poll_leaf=_poll_internal_generation_leaf,
            cancel_leaf=_cancel_internal_generation_leaf,
        )
        runtime, callbacks = build_controller_runtime_from_config(
            config, store=RedisCoordinatorStore(_queue_redis), leaf_client=leaf,
            generic_transport_factory=lambda _provider_id, _provider_cfg: _AiohttpTransport(session, owner_loop=loop),
            custom_callback_factory=build_recovered_minimax_callbacks,
            operation_catalogs=config.get("operation_catalogs") or {},
            leaf_adapters={"audio.cpp", "gpu_manager_generation"},
            external_adapters={"llm", "minimax.preparation", "research.http", "research.validator", "audio.analysis", "local-audio-qc", "artifact-store", "http_json", "http_openai_compatible", "http_flow", "local_pipeline"},
            consumer_name=f"controller-{os.getpid()}",
        )
        logger.info("Production workflow coordinator constructed with %d reviewed adapters", len(callbacks.registry._bindings))
        return runtime
    except Exception:
        logger.exception("Production workflow coordinator initialization failed")
        return None


def create_app(debug_reservations=False, debug_oom_sim=False) -> web.Application:
    global scheduler, vram, _services_config
    app = web.Application(middlewares=[_api_auth_middleware])
    app["debug_reservations"] = debug_reservations
    app["debug_oom_sim"] = debug_oom_sim


    # Create with None session — will be set in background_loop
    scheduler = GPUScheduler(None, logger)
    vram = VRAMLifecycleManager(None, logger)

    # Load services config
    _services_config = _load_services_config()

    # Load providers config
    global _providers_config, _peer_monitor
    _providers_config = _load_providers_config()
    logger.info(f"Loaded providers.json: {len(_providers_config.get('providers',{}))} providers")
    # A pipeline may reference a provider identity supplied only by the
    # companion providers registry. Rebuild once after that registry is loaded
    # so startup order cannot leave a valid graph disabled.
    _load_service_pipelines_from_config(_services_config)

    # Initialize peer monitor for mesh health
    _peer_monitor = PeerMonitor(_providers_config, _services_config)
    logger.info(f"Peer monitor: tracking {len(_peer_monitor.instances)} instances + cloud providers")

    # Initialize model validator
    global _model_validator
    _model_validator = ModelValidator(_providers_config)
    logger.info(f"Model validator initialized: {len(_model_validator.rules)} routing rules")

    # ── Redis Queue Engine ──
    # NOTE: `queue_metrics` MUST be in this `global` declaration. Without it,
    # the `queue_metrics = QueueMetrics(_queue_redis)` assignment below binds
    # a LOCAL name, leaving the module-level `queue_metrics` at None and
    # causing /v1/metrics to return 503 forever. See scripts/test_queue_metrics_initialization.py.
    global queue_engine, job_tracker, slot_manager, routing_engine, capacity_reporter, capacity_tracker, fleet_gossiper, queue_metrics, _queue_redis
    global _async_redis, async_queue, async_slot_manager, async_capacity, async_gossiper, bundle_lifecycle_controller
    try:
        _queue_redis = _redis_mod.Redis(**_redis_connection_kwargs())
        _queue_redis.ping()  # verify Redis is up
        assert _queue_redis.connection_pool.connection_kwargs.get("decode_responses") is True, (
            "queue engine Redis must use decode_responses=True"
        )
        _priority_queue_config = _phase3_scheduling_config()
        queue_engine = RedisQueue(
            _queue_redis,
            externally_owned_routing_groups=_broker_owned_queue_routing_groups(),
            priority_lanes_enabled=_priority_queue_config.get(
                'priority_lanes_enabled', False
            ),
            priority_aging_interval_s=_priority_queue_config.get(
                'priority_aging_interval_s', 60
            ),
            priority_aging_cap=_priority_queue_config.get(
                'queue_priority_aging_cap', 3
            ),
        )
        job_tracker = JobTracker(_queue_redis)
        logger.info("Preserved %s legacy unfinished job receipts without replay",
                    job_tracker.preserve_unfinished_receipts())
        # Build slot config from services.json
        # Admit
        # generation_backend services (e.g. sd-server, comfyui, acestep) in
        # addition to llm_backend. _REDIS_QUEUE_ADMIT_TYPES is defined at
        # module scope.
        _slot_config = {}
        for _sn, _sc in _services_config.get("services", {}).items():
            if _is_queue_consumer_service(_sc):
                _slot_config[_sn] = int(_sc.get("parallel", 1))
        slot_manager = SlotManager(_queue_redis, service_slots=_slot_config)
        # Build routing config from services.json
        # Build routing config and enforce a cross-type guard to admit
        # generation_backend services AND enforce a cross-type guard so
        # that a misconfigured services.json cannot route LLM traffic to a
        # generation backend (or vice versa). _routing_group_seen_types
        # records the routing_group_type that was first admitted for each
        # routing_group; if a later service in the same group has a
        # different type it is rejected (logged + skipped). The plan calls
        # this the "safety belt for the whole rollout" — treat any
        # "routing_group_type" log line as P0 until cleared.
        _routing_config = {}
        _routing_group_seen_types = {}
        for _sn, _sc in _services_config.get("services", {}).items():
            if not _is_queue_consumer_service(_sc):
                continue
            _rg = _sc.get("routing_group", "")
            _rg_type = _sc.get("routing_group_type", "llm")
            # Cross-type guard (CRITICAL — safety belt for the rollout).
            if _rg and _rg in _routing_group_seen_types \
                    and _routing_group_seen_types[_rg] != _rg_type:
                logger.error(
                    "routing_group '%s' mixes types "
                    "(%s vs %s); skipping service %s",
                    _rg, _routing_group_seen_types[_rg], _rg_type, _sn,
                )
                continue
            if _rg:
                _routing_group_seen_types[_rg] = _rg_type
            _routing_config[_sn] = {
                "type": _sc.get("type"),
                "routing_group": _rg,
                "routing_group_type": _rg_type,
                "parallel": int(_sc.get("parallel", 1)),
                "speed": int(_sc.get("speed", 0)),
                "priority": int(_sc.get("priority", 0)),
                "lane": int(_sc.get("lane", 0) or 0),
            }
        capacity_tracker = CapacityTracker(_queue_redis, health_check_fn=_service_health_check)
        # Seed capacity tracking for every admitted service. The
        # init loop was widened in PR4 for SlotManager (Step 3) and
        # RoutingEngine (Step 4) but THIS loop (which seeds _active/_pending
        # dicts for every admitted service) was missed.  Use the same
        # _REDIS_QUEUE_ADMIT_TYPES so generation_backend services (sd-server,
        # comfyui, acestep) get capacity tracked too.  Without this, the
        # capacity_tracker would report 0 capacity for every gen backend and
        # PR5's /v1/submit/generation endpoint would never admit work.
        for svc_name, svc_cfg in _services_config.get("services", {}).items():
            if _is_queue_consumer_service(svc_cfg):
                if svc_name not in capacity_tracker._active:
                    capacity_tracker._active[svc_name] = 0
                if svc_name not in capacity_tracker._pending:
                    capacity_tracker._pending[svc_name] = 0
        routing_engine = RoutingEngine(
            _queue_redis,
            _routing_config,
            slot_manager,
            capacity_tracker,
            priority_lanes_enabled=_priority_queue_config.get(
                'priority_lanes_enabled', False
            ),
        )
        capacity_reporter = CapacityReporter(
            _queue_redis, slot_manager, queue_engine, _routing_config,
        )
        # ── Fleet Gossip ──
        # Fleet peers are private deployment topology, not controller source.
        # A missing block safely disables cross-host gossip while retaining the
        # local durable queue.
        _raw_fleet_peers = _providers_config.get("fleet_peers", {})
        _fleet_peers = {
            str(name): str(host)
            for name, host in _raw_fleet_peers.items()
            if isinstance(name, str)
            and name
            and isinstance(host, str)
            and host
        } if isinstance(_raw_fleet_peers, Mapping) else {}
        fleet_gossiper = FleetGossiper(
            local_redis=_queue_redis,
            machine_id=socket.gethostname(),
            peers=_fleet_peers,
            password=_redis_password(),
            local_capacity_fn=lambda: capacity_reporter.get_local_capacity(),
        )
        # ── Queue Metrics ──
        queue_metrics = QueueMetrics(_queue_redis)
        logger.info(f"Queue engine initialized: {len(_slot_config)} services, {len(_routing_config)} routes, fleet gossip with {len(_fleet_peers)} peers")
        # ── Async Queue Engine (Phase 3) ──
        try:
            import redis.asyncio as _aioredis_mod
            _async_pool = _aioredis_mod.ConnectionPool(
                **_redis_connection_kwargs(), max_connections=30,
            )
            _async_redis = _aioredis_mod.Redis(connection_pool=_async_pool)
            # All bundle-aware backends share one durable lifecycle controller;
            # service-specific brokers may still publish readiness observations,
            # but they do not own transitions or restart fencing.
            bundle_lifecycle_controller = BundleLifecycleController(
                RedisBundleLifecycleStore(_async_redis),
                owner=f"gpu-manager:{socket.gethostname()}:{os.getpid()}",
            )
            # Use the same shared async connection pool for all async objects.
            # Lane routing remains an explicit scheduling-config gate so a
            # source-only audit cannot change the live stream topology.
            async_queue = AsyncRedisQueue(
                _async_redis,
                priority_lanes_enabled=_priority_queue_config.get(
                    'priority_lanes_enabled', False
                ),
                priority_aging_interval_s=_priority_queue_config.get(
                    'priority_aging_interval_s', 60
                ),
            priority_aging_cap=_priority_queue_config.get(
                'queue_priority_aging_cap', 3
                ),
            )
            async_slot_manager = AsyncSlotManager(_async_redis, service_slots=_slot_config)
            async_capacity = AsyncCapacityReporter(
                _async_redis, async_slot_manager, async_queue, _routing_config,
            )
            async_gossiper = AsyncFleetGossiper(
                local_redis=_async_redis,
                machine_id=socket.gethostname(),
                peers=_fleet_peers,
                password=_redis_password(),
                local_capacity_fn=lambda: async_capacity.get_local_capacity(),
            )
            logger.info("Async queue engine initialized (Phase 3)")
        except Exception as _aqe_exc:
            logger.warning(f"Async queue engine init failed: {_aqe_exc}")
            async_queue = async_slot_manager = async_capacity = async_gossiper = None
            _async_redis = None
            bundle_lifecycle_controller = None
        # ── Post-reboot reconciliation ──
        _flushed = _reconcile_stale_queues()
        _recovered = _crash_recovery()
        if _flushed or _recovered:
            logger.info(f"Reconciliation: flushed {_flushed} stale entries, recovered {_recovered} orphaned jobs")
    except Exception as _qe_exc:
        logger.warning(f"Queue engine init failed (Redis unavailable?): {_qe_exc}")
        queue_engine = job_tracker = slot_manager = routing_engine = capacity_reporter = capacity_tracker = fleet_gossiper = queue_metrics = None
        _queue_redis = None

    # Construct exactly one durable coordinator from the same Valkey owner and
    # attach it before the delayed WorkerSupervisor admission tier starts.
    # Restore persisted pin
    persisted_pin = _services_config.get("scheduling", {}).get("pinned_service")
    if persisted_pin:
        rejection = _pin_service_rejection(_services_config, str(persisted_pin))
        if rejection is not None:
            logger.warning("Discarding unavailable persisted pin: %s", persisted_pin)
            _services_config.setdefault("scheduling", {})["pinned_service"] = None
            try:
                _save_services_config(_services_config)
            except Exception as exc:
                # A stale policy value must not turn a read-only or temporarily
                # unavailable registry into a controller startup failure. The
                # runtime pin remains cleared for this process.
                logger.warning("Could not persist stale pin removal: %s", exc)
        else:
            scheduler._pinned_service = persisted_pin
            scheduler._pinned_service_since = time.time()  # Phase 5.2.53 Fix B
            logger.info(f"Restored persisted pin: {persisted_pin}")

    # Health / status
    # ── Debug Reservations ──
    if debug_reservations:
        app.router.add_post("/v1/debug/reserve-gpus", handle_debug_reserve_gpus)
        app.router.add_post("/v1/debug/release-gpus", handle_debug_release_gpus)
        app.router.add_get("/v1/debug/list-reservations", handle_debug_list_reservations)

    if debug_oom_sim:
        app.router.add_post("/v1/debug/simulate-oom", handle_debug_simulate_oom)
        app.router.add_get("/v1/debug/oom-state/{gpu_id}", handle_debug_oom_state)

    app.router.add_get("/health/live", handle_liveness)
    app.router.add_get("/health", handle_health)
    app.router.add_get("/status", handle_health)
    app.router.add_get("/v1/registry/diagnostics", handle_registry_diagnostics)
    app.router.add_get("/oom/recovery/status", handle_oom_recovery_status)
    app.router.add_get("/v1/oom/dead-letters", handle_oom_dead_letters)
    app.router.add_get("/v1/oom/retry/classify", handle_oom_retry_classify)
    app.router.add_get("/v1/oom/retry/correlation", handle_oom_retry_correlation)
    app.router.add_get("/lifecycle", handle_lifecycle)

    # ── API Proxy ──
    app.router.add_post("/api/proxy", handle_api_proxy)

    # Exact durable broker routes must be registered before the wildcard LLM
    # proxy. Disabled mode preserves the production route table byte-for-byte.
    if _combined_gemma_broker_embedded():
        from gemma_broker.api import register_api_routes

        register_api_routes(app, _combined_gemma_api_proxy)

    # LLM proxy
    app.router.add_route("*", "/v1/{path:.*}", handle_llm_proxy)

    # ── Queue API ──
    app.router.add_post("/v1/submit", handle_submit_job)
    # Dedicated asynchronous generation submission
    # generation submit endpoint.  Sits alongside /v1/submit (LLM) so
    # clients can pick the right entry point for the workload type.
    # Returns 202 + job_id; the body is reshaped per
    # services.json::generation_templates and pushed to the
    # queue:{routing_group} stream for the WorkerPool to consume.
    app.router.add_post("/v1/submit/generation", handle_submit_generation)
    app.router.add_get("/v1/job/{job_id}", handle_get_job)
    app.router.add_delete("/v1/job/{job_id}", handle_cancel_job)
    app.router.add_get("/v1/queue/{service_name}", handle_queue_status)
    app.router.add_get("/v1/queue", handle_all_queues)
    app.router.add_get("/v1/fleet", handle_fleet_status)
    app.router.add_get("/v1/workers", handle_workers_status)
    app.router.add_get("/v1/workers/active", handle_workers_active)
    app.router.add_get("/v1/workers/free", handle_workers_free)
    app.router.add_get("/v1/slots", handle_slots)
    app.router.add_get("/v1/stats", handle_stats)
    app.router.add_get("/v1/routing", handle_routing)
    app.router.add_get("/v1/health/all", handle_health_all)
    app.router.add_get("/v1/format/stats", handle_format_stats)
    app.router.add_get("/v1/service-groups", handle_service_groups_state)

    # ── Queue Metrics API ──
    app.router.add_get("/v1/metrics", handle_get_metrics)
    app.router.add_get("/v1/metrics/summary", handle_get_metrics_summary)
    app.router.add_get("/v1/metrics/{service}", handle_get_metrics_service)
    app.router.add_get("/v1/dead-letters", handle_get_dead_letters)
    app.router.add_post("/v1/dead-letters/purge", handle_purge_dead_letters)

    # ComfyUI direct
    app.router.add_get("/comfyui/status", handle_comfyui_status)
    app.router.add_post("/comfyui/free", handle_comfyui_free)

    # Pipeline batch queue
    app.router.add_post("/pipeline/submit", handle_pipeline_submit)
    app.router.add_get("/pipeline/queue", handle_pipeline_queue)
    app.router.add_get("/pipeline/job/{job_id}", handle_pipeline_job)
    app.router.add_post("/pipeline/cancel", handle_pipeline_cancel)

    # Pipeline orchestrator trigger
    app.router.add_post("/pipeline/trigger", handle_pipeline_trigger)
    app.router.add_get("/pipeline/trigger/{run_id}/status", handle_pipeline_trigger_status)

    # Generation API (high-level, template-based)
    app.router.add_get("/generate", handle_generate_types)
    app.router.add_post("/generate/{type}", handle_generate)
    app.router.add_get("/generate/output/{filename}", handle_generate_output)
    app.router.add_get("/generate/library", handle_generate_library)
    app.router.add_get("/generate/job/{job_id}/wait", handle_generate_wait)

    # VRAM lifecycle
    app.router.add_get("/vram", handle_vram_list)
    app.router.add_post("/vram/evict-llm", handle_vram_evict)
    app.router.add_post("/vram/restore-llm", handle_vram_restore)
    app.router.add_post("/vram/stop-comfyui", handle_comfyui_stop)
    app.router.add_post("/vram/start-comfyui", handle_comfyui_start)
    app.router.add_post("/vram/evict-for/{needed_mib}", handle_vram_evict_for)

    # Per-process RAM data
    app.router.add_get("/proc", handle_proc_list)

    # ACE-Step direct endpoints
    app.router.add_post("/acestep/generate", handle_acestep_generate)
    app.router.add_get("/acestep/status", handle_acestep_status)
    app.router.add_get("/acestep/audio/{path:.*}", handle_acestep_audio)

    # ── Dashboard & WebSocket ──
    app.router.add_get("/dashboard", handle_dashboard)
    app.router.add_get("/mesh", handle_mesh)
    app.router.add_get("/mesh/data", handle_mesh_data)
    app.router.add_get("/mesh/queue", handle_mesh_queue)
    app.router.add_get("/mesh/services", handle_mesh_services)
    app.router.add_get("/ws", _websocket_handler)

    # ── Queue management ──
    app.router.add_post("/queue/move", handle_queue_move)
    app.router.add_post("/queue/insert", handle_queue_insert)
    app.router.add_post("/queue/bump/{job_id}", handle_queue_bump)
    app.router.add_post("/queue/demote/{job_id}", handle_queue_demote)
    app.router.add_post("/queue/cancel", handle_queue_cancel)
    app.router.add_post("/queue/cancel-running/{job_id}", handle_queue_cancel_running)
    app.router.add_post("/queue/clear", handle_queue_clear)
    app.router.add_get("/queue/detail", handle_queue_detail)
    app.router.add_get("/idle-job", handle_idle_job)
    app.router.add_post("/idle-job", handle_idle_job)
    app.router.add_post("/idle-job/enable", handle_idle_job_toggle)
    app.router.add_post("/idle-job/disable", handle_idle_job_toggle)

    # ── Scheduling config (idle service, pin) ──
    app.router.add_get("/scheduling/idle-service", handle_idle_service)
    app.router.add_put("/scheduling/idle-service", handle_idle_service)
    app.router.add_post("/scheduling/pin", handle_pin_service)

    # ── Maintenance mode ──
    app.router.add_get("/maintenance", handle_maintenance)
    app.router.add_post("/maintenance/enable", handle_maintenance_toggle)
    app.router.add_post("/maintenance/disable", handle_maintenance_toggle)

    # ── Coexistence mode (Phase 5.2.66) ──
    # In-memory SRE pause of auto-restoration. Sits next to maintenance because
    # it's a sibling control-surface concept (one is persisted, this is ephemeral).
    app.router.add_get("/v1/coexistence/mode", handle_coexistence_mode)
    app.router.add_post("/v1/coexistence/mode", handle_coexistence_mode)

    # ── Service config ──
    app.router.add_get("/services", handle_services_list)
    app.router.add_post("/v1/services/preview", handle_service_preview)
    app.router.add_get(
        "/v1/services/{name}/revisions", handle_service_revision_list
    )
    app.router.add_post(
        "/v1/services/{name}/revisions", handle_service_revision_publish
    )
    app.router.add_post(
        "/v1/services/{name}/revisions/{revision}/activate",
        handle_service_revision_activate,
    )
    app.router.add_post(
        "/v1/services/{name}/revisions/{revision}/deprecate",
        handle_service_revision_deprecate,
    )
    app.router.add_post("/services", handle_service_create)
    app.router.add_get("/services/{name}", handle_service_get)
    app.router.add_put("/services/{name}", handle_service_update)
    app.router.add_delete("/services/{name}", handle_service_delete)
    app.router.add_post("/services/{name}/restart", handle_service_restart)
    app.router.add_get("/services/{name}/status", handle_service_status)
    app.router.add_post("/services/{name}/toggle", handle_service_toggle)
    app.router.add_post("/services/{name}/stop", handle_service_stop)
    app.router.add_post("/services/{name}/fix-degraded", handle_service_fix_degraded)
    app.router.add_post("/v1/bundles/preload", handle_bundle_preload)

    # ── Port Proxies ──
    app.router.add_get("/port-proxies", handle_port_proxies_list)
    app.router.add_post("/port-proxies/{name}/start", handle_port_proxy_start)
    app.router.add_post("/port-proxies/{name}/stop", handle_port_proxy_stop)

    # ── Bundle Proxy (Phase 3) ──
    app.router.add_get("/proxy", handle_bundle_proxy_status)
    app.router.add_route("*", "/proxy/{bundle_name}/{path:.*}", handle_bundle_proxy)
    app.router.add_route("*", "/proxy/{bundle_name}", handle_bundle_proxy)

    app.on_startup.append(on_startup)
    app.on_cleanup.append(on_cleanup)
    return app


async def ensure_services_running():
    """Fire-and-forget: restore compatible startup services.

    In the default split/legacy modes this preserves the historical Idle LLM
    and ComfyUI startup behavior.  Durable queue-owner mode still observes and
    reconciles configured state, but does not issue a direct ComfyUI systemd
    start because generation lifecycle belongs to the durable worker path.

    Uses the CONFIGURED idle_service (from services.json → scheduling.idle_service),
    NOT a hardcoded LLM name. Only starts an LLM if no GPU LLM is already running
    — respects whatever state the system was left in before gpu-manager restarted.

    STATE RESTORE: Reads the persisted state file to understand what was
    happening before the last shutdown. If the LLM was loaded (not evicted),
    ensures it's still running. Detects actual state from systemd rather
    than blindly restoring.

    MAINTENANCE MODE: Skips all auto-starts when active.
    Also checks `systemctl is-enabled` — won't start a service that was
    explicitly disabled by the user.
    """
    # Startup auto-restore can invoke full-GPU telemetry and systemd starts.
    # Keep it behind the same process-wide grace as the VRAM pusher so startup
    # never performs an autonomous first-tick amdgpu_top probe.
    await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
    global _services_config, vram, scheduler
    if _services_config is None:
        _services_config = _load_services_config()

    # ── State Restore ──────────────────────────────────────────────
    # Read persisted state to understand pre-shutdown context
    saved_state = _load_state()
    if saved_state.get("last_updated"):
        logger.info(
            f"State restore: last state was gpu_state={saved_state.get('gpu_state')}, "
            f"llm_evicted={saved_state.get('llm_evicted')}, "
            f"pinned={saved_state.get('pinned_service')}, "
            f"maintenance={saved_state.get('maintenance_mode')}, "
            f"saved at {saved_state.get('last_updated')}"
        )

    # Restore pinned_service from state (if saved, overrides default)
    if saved_state.get("pinned_service"):
        saved_pin = str(saved_state["pinned_service"])
        pin_rejection = _pin_service_rejection(_services_config, saved_pin)
        if scheduler and not scheduler._pinned_service and pin_rejection is None:
            scheduler._pinned_service = saved_pin
            logger.info(f"State restore: pinned_service = {saved_pin}")
        elif pin_rejection is not None:
            logger.warning("Ignoring unavailable saved-state pin: %s", saved_pin)

    # Restore maintenance_mode from state
    if saved_state.get("maintenance_mode"):
        if _services_config is None:
            _services_config = _load_services_config()
        if not _maintenance_mode_enabled(_services_config.get("scheduling", {})):
            _services_config.setdefault("scheduling", {})["maintenance_mode"] = True
            _save_services_config(_services_config)
            logger.info("State restore: maintenance_mode restored from state file")

    # Maintenance mode: hands off everything
    if _maintenance_mode_enabled(_services_config.get("scheduling", {})):
        logger.info("Maintenance mode active — skipping auto-start of critical services")
        return

    scheduling = _services_config.get("scheduling", {})
    idle_svc_name = scheduling.get("idle_service", "")
    services = _services_config.get("services", {})

    async def _ensure_unit_running(name: str, unit: str) -> bool:
        """Start a systemd unit if enabled and not already running. Returns True if started."""
        try:
            # Check is-enabled FIRST — respect explicit user disables
            enabled_proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-enabled", unit,
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL,
            )
            stdout, _ = await asyncio.wait_for(enabled_proc.communicate(), timeout=3)
            if stdout.decode().strip() != "enabled":
                logger.info(f"Auto-start: skipping {name} (is-enabled: {stdout.decode().strip()})")
                return False

            proc = await asyncio.create_subprocess_exec(
                "systemctl", "is-active", "--quiet", unit,
                stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
            )
            await asyncio.wait_for(proc.wait(), timeout=3)
            if proc.returncode != 0:
                logger.info(f"Auto-start: {name} not running, starting {unit}")
                start_proc = await asyncio.create_subprocess_exec(
                    "sudo", "systemctl", "start", unit,
                    stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(start_proc.communicate(), timeout=30)
                if start_proc.returncode == 0:
                    logger.info(f"Auto-start: {name} started successfully")
                    return True
                else:
                    logger.warning(f"Auto-start: failed to start {name}: {stderr.decode().strip()}")
            else:
                logger.info(f"Auto-start: {name} already running")
            return False
        except asyncio.TimeoutError:
            logger.warning(f"Auto-start: timeout checking {name}")
        except Exception as e:
            logger.warning(f"Auto-start: error checking {name}: {e}")
        return False

    # ── Phase 1: ComfyUI (generation backend — always needed) ──
    # In durable-owner mode WorkerSupervisor plus the bundle lifecycle path own
    # generation-service admission.  Starting ComfyUI here would reintroduce a
    # second lifecycle authority during the very cutover this mode is meant to
    # fence.  Keep the observation/reconcile pass below, but do not issue a
    # systemd start from this compatibility startup helper.
    comfy_svc = services.get("comfyui", {})
    comfy_unit = comfy_svc.get("systemd_unit", "")
    if comfy_unit and _queue_owner_mode(scheduling) != "durable":
        await _ensure_unit_running("comfyui", comfy_unit)
    elif comfy_unit:
        logger.info(
            "Queue owner=durable; skipping direct ComfyUI auto-start from "
            "ensure_services_running"
        )

    # ── Phase 2: Idle LLM(s) — start per-GPU idle services independently ──
    all_idle = _get_all_idle_services()
    if not all_idle:
        # Fallback: try global idle_service for backward compat
        idle_svc_name = scheduling.get("idle_service", "")
        if not idle_svc_name:
            logger.info("Auto-start: no idle service configured — skipping LLM start")
            return
        all_idle = [{"gpu_id": None, "service_name": idle_svc_name,
                      "systemd_unit": services.get(idle_svc_name, {}).get("systemd_unit", ""),
                      "port": services.get(idle_svc_name, {}).get("port", 0)}]

    # BUGFIX (2026-05-20d): Don't auto-start LLM if GPU work is pending or
    # services were evicted. This prevents the auto-start from re-loading a
    # 7 GB model while a generation runtime is trying to load into the same VRAM.
    if vram and vram._llm_evicted:
        logger.info("Auto-start: LLM evicted (GPU work active) — skipping idle service start")
        return
    if vram and (scheduler._comfyui_queue or scheduler._acestep_queue):
        c_pending = len([j for j in scheduler._comfyui_queue if j.status == "queued"])
        a_pending = len([j for j in scheduler._acestep_queue if j.status == "queued"])
        logger.info(f"Auto-start: GPU work pending (comfyui={c_pending}, acestep={a_pending}) — skipping idle service start")
        return

    # Phase 5.2.50: VRAM gate. If gpu_primary already has > 8 GiB used
    # (ComfyUI is loaded with its models, or both Coexisted), skip the
    # idle LLM entry targeting that GPU. LLM-Primary uses ~13 GiB; combined
    # with comfyui that's ~17 GiB on a 16 GiB card → CUDA OOM.
    try:
        vram_data = await _poll_vram()
        gpu_primary_entry = _get_vram_entry_for_gpu(vram_data, "gpu_primary")
        gpu_primary_used = gpu_primary_entry.get("vram_used_mib", 0) if gpu_primary_entry else 0
        if gpu_primary_used > 8000:
            logger.warning(
                f"Auto-start: skipping idle LLM on gpu_primary — current usage "
                f"{gpu_primary_used} MiB; would OOM if LLM-Primary (~13 GiB) also loaded"
            )
            all_idle = [e for e in all_idle if e.get("gpu_id") != "gpu_primary"]
    except Exception as _phase1_vram_err:
        logger.debug(f"Auto-start: Phase 2 VRAM check failed: {_phase1_vram_err}")

    for idle_entry in all_idle:
        gpu_id = idle_entry["gpu_id"]
        idle_svc_name = idle_entry["service_name"]
        idle_unit = idle_entry["systemd_unit"]

        if not idle_svc_name or not idle_unit:
            continue

        tag = f" (gpu={gpu_id})" if gpu_id else ""

        # Check if a GPU LLM is already running on this GPU
        already_running = await _check_llm_running_on_gpu(
            services, gpu_id, exclude_svc=idle_svc_name
        )
        if already_running:
            logger.info(
                f"Auto-start: GPU LLM {already_running} already running on "
                f"gpu={gpu_id} — not starting idle service {idle_svc_name}{tag}"
            )
            continue

        # No LLM running on this GPU — start the idle service
        await _ensure_unit_running(idle_svc_name + tag, idle_unit)

    # Direct systemd starts above happen after the early startup probe. Do a
    # second authoritative pass so physical idle tenants become configured
    # bundle IDs in the scheduler ledger rather than an empty/stale cache.
    await _reconcile_authoritative_bundle_state()


async def _seed_comfyui_idle_timer():
    """Set ComfyUI idle timestamp on startup if it's already running.

    When gpu-manager starts, ComfyUI may already be active (e.g., from
    systemd on boot). Without this, the auto-stop timer would never
    trigger because _comfyui_idle_since remains None.
    """
    await asyncio.sleep(10)  # Wait for ensure_services_running to finish
    global vram
    if not vram:
        return
    if _queue_owner_mode() == "durable":
        # The legacy direct-idle monitor is fenced with the legacy scheduler;
        # durable mode must not seed a timer that can later be interpreted as
        # authority to stop a WorkerSupervisor-owned generation bundle.
        logger.info(
            "Queue owner=durable; skipping legacy ComfyUI idle-timer seed"
        )
        return
    try:
        proc = await asyncio.create_subprocess_exec(
            "systemctl", "is-active", "--quiet", "comfyui.service",
            stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.DEVNULL,
        )
        await asyncio.wait_for(proc.wait(), timeout=3)
        if proc.returncode == 0:
            # ComfyUI is running — start the idle countdown.
            # At startup there are no pending jobs, so safe to seed.
            if vram._comfyui_idle_since is None:
                vram._comfyui_idle_since = time.time()
                logger.info(
                    f"ComfyUI already running at startup — "
                    f"idle timer seeded (cooldown={COMFYUI_IDLE_COOLDOWN}s)"
                )
    except Exception as e:
        logger.debug(f"ComfyUI idle timer seed skipped: {e}")


async def _recover_forwarded_comfyui_job_after_restart(
    job_id: str,
    job: dict,
    prompt_id: str,
) -> None:
    """Finish a ComfyUI job whose /prompt ACK was persisted before restart.

    The worker has already crossed the side-effect boundary, so resubmitting
    the workflow is unsafe. Poll the same prompt handle, fetch the generated
    images through ComfyUI's normal /view endpoint, and commit the same
    durable result shape as the normal worker path.
    """
    if session is None or job_tracker is None:
        return
    # Keep this recovery task self-contained: unlike the normal worker path it
    # is scheduled directly during startup, before the worker's local base64
    # alias is imported.
    import base64 as _b64
    endpoint = str(job.get("comfyui_endpoint") or "").strip()
    if not endpoint:
        endpoint = COMFYUI_URL.rstrip("/") + "/prompt"
    comfyui_base = endpoint.rstrip("/")
    if comfyui_base.endswith("/prompt"):
        comfyui_base = comfyui_base[: -len("/prompt")]
    try:
        metadata = json.loads(job.get("metadata") or "{}")
    except (TypeError, json.JSONDecodeError):
        metadata = {}
    timeout_s = max(60, min(7200, int(metadata.get("workflow_timeout_s", 900))))
    deadline = time.time() + timeout_s
    job_tracker.update_status(
        job_id,
        "in_flight",
        restart_recovery="polling_existing_prompt",
        comfyui_prompt_id=prompt_id,
    )
    try:
        while time.time() < deadline:
            try:
                async with session.get(
                    f"{comfyui_base}/history/{prompt_id}",
                    timeout=ClientTimeout(total=10),
                ) as response:
                    history = await response.json()
            except Exception as exc:
                logger.debug("restart recovery history poll failed for %s: %s", job_id, exc)
                await asyncio.sleep(5)
                continue
            entry = history.get(prompt_id) if isinstance(history, dict) else None
            if not entry:
                await asyncio.sleep(5)
                continue
            status = entry.get("status") or {}
            if status.get("status_str") == "error" or entry.get("node_errors"):
                error = "ComfyUI node errors: " + json.dumps(entry.get("node_errors") or {})[:500]
                job_tracker.update_status(
                    job_id, "failed", error=error,
                    comfyui_prompt_id=prompt_id, restart_recovery="terminal",
                )
                return
            if not status.get("completed"):
                await asyncio.sleep(5)
                continue

            image_data: list[dict] = []
            for output in (entry.get("outputs") or {}).values():
                for image in (output.get("images") or []):
                    view_params = {
                        "filename": image.get("filename", ""),
                        "type": image.get("type", "output"),
                        "subfolder": image.get("subfolder", ""),
                    }
                    try:
                        async with session.get(
                            f"{comfyui_base}/view",
                            params=view_params,
                            timeout=ClientTimeout(total=60),
                        ) as view_response:
                            image_bytes = await view_response.read()
                            content_type = str(view_response.headers.get("Content-Type") or "")
                            if view_response.status != 200 or not content_type.startswith("image/"):
                                raise RuntimeError(
                                    f"ComfyUI view returned {view_response.status} {content_type}"
                                )
                            _verified_image_bytes(image_bytes)
                        image_data.append({
                            **view_params,
                            "data_b64": _b64.b64encode(image_bytes).decode("ascii"),
                        })
                    except Exception as exc:
                        logger.warning("restart recovery could not fetch %s: %s", view_params, exc)
            if not image_data:
                job_tracker.update_status(
                    job_id, "failed",
                    error="ComfyUI completed without retrievable image output",
                    comfyui_prompt_id=prompt_id, restart_recovery="terminal",
                )
                return
            result_payload = {
                "prompt_id": prompt_id, "status": "success", "images": image_data,
            }
            artifacts = await asyncio.to_thread(
                lambda: [_persist_generated_image(job_id, item, index)
                         for index, item in enumerate(image_data)]
            )
            result_payload["artifact"] = artifacts[0]
            result_payload["artifacts"] = artifacts
            job_tracker.update_status(
                job_id, "completed", result=json.dumps(result_payload),
                comfyui_prompt_id=prompt_id, restart_recovery="completed",
            )
            logger.info(
                "Restart recovery completed ComfyUI job %s using existing prompt_id=%s",
                job_id, prompt_id,
            )
            return
        job_tracker.update_status(
            job_id, "failed",
            error=f"ComfyUI job {prompt_id} timed out during restart recovery",
            comfyui_prompt_id=prompt_id, restart_recovery="timeout",
        )
    except Exception as exc:
        logger.error("restart recovery failed for %s: %s", job_id, exc, exc_info=True)
        job_tracker.update_status(
            job_id, "failed", error=f"restart recovery failed: {exc}",
            comfyui_prompt_id=prompt_id, restart_recovery="failed",
        )


async def _peer_health_loop():
    """Check peer health every 15 seconds after process-wide GPU probe grace."""
    logger.info(
        "Peer health startup grace: waiting %.1fs before first local GPU probe",
        GPU_PROBE_STARTUP_GRACE_S,
    )
    await asyncio.sleep(GPU_PROBE_STARTUP_GRACE_S)
    while True:
        try:
            if _peer_monitor:
                await _peer_monitor.check_all()
        except Exception as e:
            logger.error(f"Peer health check failed: {e}")
        await asyncio.sleep(15)


async def _reconcile_inflight_after_restart() -> None:
    """Return unresolved Redis PEL jobs to their logical routing streams."""
    if async_queue is None or job_tracker is None:
        return
    cfg = _load_services_config() or {}
    groups = set()
    for svc_name, svc in (cfg.get('services', {}) or {}).items():
        if svc.get('routing_group'):
            groups.add(svc['routing_group'])
    for tmpl in (cfg.get('generation_templates', {}) or {}).values():
        if isinstance(tmpl, dict) and tmpl.get('routing_group'):
            groups.add(tmpl['routing_group'])
    for group in sorted(groups):
        try:
            try:
                pending = await async_queue.get_pending(
                    group, routing_group=group, strict=True
                )
            except TypeError as exc:
                # Narrow staging doubles from older queue adapters may not yet
                # expose the strict keyword.  Preserve compatibility for those
                # doubles, while production AsyncRedisQueue takes the strict
                # path and surfaces a Redis outage to this reconcile loop.
                if "strict" not in str(exc):
                    raise
                pending = await async_queue.get_pending(
                    group, routing_group=group
                )
            if not pending:
                continue
            conn = await async_queue._get_conn()
            for item in pending:
                entry_id = item.get('entry_id')
                # Priority-lane handles are opaque outside the queue engine;
                # resolve them before the payload lookup while retaining the
                # original handle for ACK/YIELD so the exact PEL entry is
                # acknowledged.
                resolver = getattr(async_queue, 'resolve_entry_stream', None)
                if callable(resolver):
                    stream, raw_entry_id, _lane = resolver(
                        group, entry_id or '', routing_group=group
                    )
                else:
                    # Compatibility for narrow test doubles and older queue
                    # adapters; production AsyncRedisQueue always exposes the
                    # resolver once lane handles are enabled.
                    stream = async_queue._stream(group, routing_group=group)
                    raw_entry_id = entry_id or ''
                rows = await conn.xrange(
                    stream, min=raw_entry_id, max=raw_entry_id, count=1
                )
                payload = rows[0][1] if rows else {}
                job_id = payload.get('job_id', '')
                if isinstance(job_id, bytes):
                    job_id = job_id.decode()
                job = await asyncio.to_thread(job_tracker.get_job, job_id) if job_id else None
                status = (job or {}).get('status', '')
                cancellation_intent = str((job or {}).get('cancellation_intent', '')).lower() in {
                    '1', 'true', 'yes', 'on'
                }
                if status in {'completed', 'failed', 'cancelled'} or cancellation_intent:
                    if cancellation_intent and status != 'cancelled':
                        await asyncio.to_thread(
                            job_tracker.update_status, job_id, 'cancelled',
                            error='cancelled before restart reconciliation',
                        )
                    await async_queue.ack(group, 'restart-reconciler', entry_id,
                                          routing_group=group)
                    logger.info(
                        f"Restart reconcile: removed terminal/cancelled PEL job {job_id} "
                        f"from {group} (status={status}, cancellation_intent={cancellation_intent})"
                    )
                    continue
                comfyui_prompt_id = str((job or {}).get('comfyui_prompt_id') or '').strip()
                if comfyui_prompt_id:
                    # A persisted prompt id proves the worker already crossed the
                    # forward boundary. Never requeue the original payload (that
                    # would submit a duplicate prompt); hand the existing handle
                    # to a retained recovery task and ACK this PEL entry.
                    await asyncio.to_thread(
                        job_tracker.update_status,
                        job_id,
                        'in_flight',
                        restart_reconcile='existing_prompt_recovery_started',
                        restart_recovery='scheduled',
                    )
                    recovery_task = asyncio.create_task(
                        _recover_forwarded_comfyui_job_after_restart(
                            job_id,
                            job or {},
                            comfyui_prompt_id,
                        ),
                        name=f"gpu-manager:restart-recovery:{job_id}",
                    )
                    _restart_recovery_tasks.add(recovery_task)
                    recovery_task.add_done_callback(_restart_recovery_tasks.discard)
                    await async_queue.ack(
                        group, 'restart-reconciler', entry_id or '',
                        routing_group=group,
                    )
                    logger.warning(
                        f"Restart reconcile: recovering already-forwarded "
                        f"ComfyUI job {job_id} (prompt_id={comfyui_prompt_id}) "
                        "without duplicate submission"
                    )
                    continue
                idle_ms = int(item.get('idle_ms', 0) or 0)
                if idle_ms < 30000:
                    logger.info(
                        f"Restart reconcile: preserving active PEL job {job_id} "
                        f"from {group} (idle_ms={idle_ms})"
                    )
                    continue
                if await async_queue.yield_pending(group, entry_id,
                                                   routing_group=group):
                    if job_id:
                        await asyncio.to_thread(
                            job_tracker.update_status, job_id, 'queued',
                            reconciled_after_restart='1',
                            error='requeued after GPU Manager restart',
                        )
                    logger.info(
                        f"Restart reconcile: requeued unresolved job {job_id} "
                        f"from {group}"
                    )
        except Exception as exc:
            logger.warning(
                f"Restart reconcile: failed for logical group {group}: {exc}"
            )


async def _reconcile_authoritative_bundle_state() -> None:
    """Rebuild GPU bundle state from healthy configured services after restart.

    Persisted bundle state is only a cache. A stopped generation service must
    not keep claiming its primary GPU or linked reservation-only GPU after a
    manager restart, because that blocks idle restoration indefinitely. Each
    physical GPU set is locked before its first health sample and remains
    locked through the corresponding ownership transition.
    """
    # Never overwrite a ledger while a linked admission/load/unload owns the
    # same physical lanes. The next periodic tick will reconcile it once the
    # transaction has committed or rolled back.
    if _bundle_transition_is_active():
        logger.debug("Authoritative reconcile deferred: bundle transition active")
        return

    cfg = _load_services_config() or {}
    services = cfg.get('services', {})
    bundles = _resolve_bundles()
    claimed_gpu_sets: set[tuple[str, ...]] = set()
    for bundle_name, bundle in bundles.items():
        gpu_id = bundle.get('gpu_id')
        members = [services.get(name, {}) for name in bundle.get('services', [])]
        if not gpu_id or not members:
            continue
        physical_gpu_set = _bundle_physical_gpu_set(
            bundle_name, bundles=bundles
        )
        if not physical_gpu_set:
            logger.warning(
                "Authoritative reconcile: bundle %s has no physical GPU set; "
                "skipping ownership mutation",
                bundle_name,
            )
            continue
        physical_lock = _get_physical_resource_lock(physical_gpu_set)
        async with physical_lock:
            # Re-check after waiting: another transaction may have started
            # while this reconcile was queued on the physical resource.
            if _bundle_transition_is_active():
                logger.debug(
                    "Authoritative reconcile deferred under lock for %s: "
                    "bundle transition active",
                    bundle_name,
                )
                return

            # Retained historical entries can share a port with today's
            # engine. A responding port does not make a retired owner active.
            healthy = all(service_is_publicly_eligible(svc) for svc in members)
            for svc in members:
                if not healthy:
                    break
                port = svc.get('port')
                health_path = str(svc.get('health_path') or '/health')
                if not port or session is None:
                    healthy = False
                    break
                try:
                    async with session.get(
                        f"http://127.0.0.1:{int(port)}{health_path}",
                        timeout=ClientTimeout(total=2, connect=0.5),
                    ) as resp:
                        if resp.status != 200:
                            healthy = False
                            break
                except Exception:
                    healthy = False
                    break

            gs = _get_gpu_state(gpu_id)
            if gs is None:
                continue
            async with _get_bundle_admission_lock(bundle_name):
                if not healthy:
                    # Clear only the unhealthy service-backed owner and its linked
                    # reservations. The shared transition preserves unrelated
                    # bundles already resident on either GPU.
                    if bundle_name in (getattr(gs, "loaded_bundles", []) or []) or \
                       getattr(gs, "loaded_bundle", None) == bundle_name:
                        _transition_linked_bundle_state(
                            bundle_name, [], source="startup_reconcile_unhealthy"
                        )
                        logger.info(
                            f"Startup reconcile: cleared unhealthy bundle "
                            f"'{bundle_name}' from GPU {gpu_id}"
                        )
                    continue

                # A second healthy service touching any already-claimed
                # physical lane is an authority conflict.  Equality is not
                # sufficient here: an RX-only bundle conflicts with a
                # dual-GPU {RX, secondary GPU} bundle even though their tuples differ.
                # Preserve the first deterministic claimant and refuse the
                # incompatible second ledger mutation.
                if any(
                    set(physical_gpu_set).intersection(claimed)
                    for claimed in claimed_gpu_sets
                ):
                    logger.error(
                        "Authoritative reconcile: multiple healthy owners claim "
                        "physical GPU set %s; refusing second owner %s",
                        physical_gpu_set,
                        bundle_name,
                    )
                    _transition_linked_bundle_state(
                        bundle_name, [], source="startup_reconcile_conflict"
                    )
                    continue

                _transition_linked_bundle_state(
                    bundle_name, [bundle_name], source="startup_reconcile"
                )
                claimed_gpu_sets.add(physical_gpu_set)
                gs.state = 'loaded'
                logger.info(
                    f"Startup reconcile: GPU {gpu_id} owns healthy bundle "
                    f"'{bundle_name}' (priority={gs.bundle_priority})"
                )


async def _authoritative_bundle_reconcile_loop() -> None:
    """Continuously heal scheduler ownership from verified service reality.

    This covers direct systemd service operations, which are otherwise
    invisible to the in-memory ledger. It never starts or stops services and
    defers while a bundle transaction is active.
    """
    while True:
        try:
            await asyncio.sleep(30)
            await _reconcile_authoritative_bundle_state()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.warning("Authoritative bundle reconcile tick failed: %s", exc)



BACKGROUND_TASKS_KEY: web.AppKey[dict[str, asyncio.Task]] = web.AppKey(
    "background_tasks", dict
)
BACKGROUND_STARTUP_HANDLES_KEY: web.AppKey[list[asyncio.TimerHandle]] = web.AppKey(
    "background_startup_handles", list
)
# App-owned coordinator state uses typed keys so an optional staging runtime
# does not add string-key warnings or collide with request/config data.
WORKFLOW_COORDINATOR_RUNTIME_KEY: web.AppKey[Any] = web.AppKey(
    "workflow_coordinator_runtime", object
)
WORKFLOW_COORDINATOR_STOP_KEY: web.AppKey[asyncio.Event] = web.AppKey(
    "workflow_coordinator_stop", asyncio.Event
)
BACKGROUND_TASK_CANCEL_TIMEOUT_SECONDS = 10.0
# Keep scheduler cancellation bounded so aiohttp cleanup completes inside the
# systemd 45-second stop window even if a loop suppresses CancelledError.
SCHEDULER_STOP_TIMEOUT_SECONDS = 10.0
# gpu-manager.service grants 45 seconds for a graceful stop. Keep aiohttp's
# request-drain phase inside that deadline so on_cleanup has time to cancel
# retained workers, close Redis, and persist final ownership state.
AIOHTTP_SHUTDOWN_TIMEOUT_SECONDS = 20.0


def register_background_task(app: web.Application, name: str, coro) -> asyncio.Task:
    """Create and retain one application-owned background task.

    ``on_cleanup`` drains this registry before stopping the scheduler.  Every
    long-lived monitor must use this seam; otherwise a task such as
    ``scheduler_health`` can survive teardown and restart dispatch while the
    service is trying to exit.
    """
    tasks = app.get(BACKGROUND_TASKS_KEY)
    if tasks is None:
        tasks = {}
        app[BACKGROUND_TASKS_KEY] = tasks
    if name in tasks:
        raise RuntimeError(f"background task already registered: {name}")
    task = asyncio.create_task(coro, name=f"gpu-manager:{name}")
    tasks[name] = task
    return task


def register_background_callback(
    app: web.Application, delay: float, callback
) -> asyncio.TimerHandle:
    """Retain a delayed startup callback so cleanup can cancel it."""
    handles = app.get(BACKGROUND_STARTUP_HANDLES_KEY)
    if handles is None:
        handles = []
        app[BACKGROUND_STARTUP_HANDLES_KEY] = handles
    handle = asyncio.get_event_loop().call_later(delay, callback)
    handles.append(handle)
    return handle


def attach_workflow_coordinator_runtime(app: web.Application, runtime: Any) -> None:
    """Attach an already-built coordinator runtime to this controller.

    Attachment is explicit and dependency-injected: the default controller
    does not construct a second Redis stream, discover adapters, or activate a
    candidate workflow.  A staging/bootstrap caller may set a
    ``ControllerPipelineRuntime`` here; the tier-2 startup hook then owns one
    ``CoordinatorConsumer`` task and cleanup cancels it with the other app
    tasks.  Passing a second runtime is rejected so a service registration
    cannot accidentally create duplicate consumers.
    """

    if runtime is None or not callable(getattr(runtime, "process_one", None)):
        raise TypeError("workflow coordinator runtime must expose process_one()")
    if app.get(WORKFLOW_COORDINATOR_RUNTIME_KEY) is not None:
        raise RuntimeError("workflow coordinator runtime already attached")
    app[WORKFLOW_COORDINATOR_RUNTIME_KEY] = runtime


def _start_background_tasks(app: web.Application):
    """Create all background tasks — called AFTER server bind via staggered call_later.

    This is deferred from on_startup to avoid blocking loop.create_server()
    on Python 3.14 + aiohttp 3.13 where all create_task() calls in on_startup
    prevent the TCP socket from binding.

    Tasks are staggered to prevent overwhelming the event loop.
    """
    loop = asyncio.get_event_loop()

    # Tier 1 (immediate): Core services that everything else depends on
    app["bg_task"] = register_background_task(app, "background_loop", background_loop(app))
    app["vram_task"] = register_background_task(app, "vram_pusher", _vram_pusher_loop())
    app["proactive_dispatcher"] = register_background_task(app, "proactive_dispatcher", _proactive_dispatch_loop())
    logger.info("Started proactive_dispatch_loop (dry-run mode)")
    register_background_task(app, "peer_health", _peer_health_loop())
    # An external broker owns the lifecycle state for its members.  Keep its
    # healthy-persisted-JOINING repair in a separate, cancellable monitor so
    # ordinary health reads never mutate broker state and embedded deployments
    # do not create a second lifecycle authority.
    try:
        if _combined_gemma_broker_enabled() and not _combined_gemma_broker_embedded():
            register_background_task(
                app,
                "combined_gemma_rejoin",
                _external_combined_gemma_rejoin_loop(),
            )
    except ValueError:
        logger.error("Invalid Combined Gemma deployment; rejoin monitor disabled", exc_info=True)

    # ── Phase 4: watchdog tier — always-on, independent of vram/scheduler ──
    # These three loops are critical infrastructure: they ensure OOM recovery
    # fires even if the vram pusher stalls, that scheduler dispatch can't
    # silently die, and that stale --mcp siblings don't keep serving stale
    # state. We start them alongside Tier 1 so they're up from second 0.
    app["oom_watchdog"] = register_background_task(app, "oom_watchdog", _oom_recovery_watchdog_loop())
    app["scheduler_health"] = register_background_task(app, "scheduler_health", _scheduler_health_check_loop())
    app["mcp_cleanup"] = register_background_task(app, "mcp_cleanup", _delayed_stale_mcp_cleanup())
    # Phase 5.2.49: stale-job reaper — force-fails orphaned in_flight jobs
    app["stale_job_reaper"] = register_background_task(app, "stale_job_reaper", _stale_job_reaper_loop())
    if app.get("debug_reservations"):
        app["expire_reservations_task"] = register_background_task(app, "expire_reservations", _expire_reservations_loop())

    # Tier 2 (1s later): Queue and proxy infrastructure
    def _start_tier2():
        # OLD: app["queue_worker"] = asyncio.create_task(queue_worker_loop())
        # NEW: WorkerSupervisor handles all queue processing
        global _services_config, event_bus, worker_supervisor, _worker_supervisor_task
        _queue_owner = _queue_owner_mode()
        cfg = _services_config
        if cfg is None:
            cfg = _load_services_config()
            _services_config = cfg
        register_background_task(app, "start_port_proxies", _start_all_port_proxies(cfg))
        # Initialize bundle proxy queues
        bundles = _resolve_bundles()
        for bname in bundles:
            _get_bundle_queue(bname)
        logger.info(f"Bundle proxy: initialized {len(bundles)} bundle queues")

        # ── Dynamic Worker Pool: Initialize event bus and supervisor ──
        event_bus = ServiceEventBus()
        # session is set in on_startup (Option A), which runs before _start_tier2.
        # Guard for type-checker: on_startup guarantees non-None, but the global
        # is typed Optional. We fall back to creating a transient session if (in
        # some future refactor) startup ordering changes.
        if session is None:
            worker_session = ClientSession(timeout=ClientTimeout(total=300, connect=10))
        else:
            worker_session = session
        # Optional, explicit coordinator attachment.  Build the admission
        # and terminal-mirror seams before the worker supervisor so every
        # internal-workflow pool receives the same single handoff object.  No
        # runtime is created here: legacy/Krea workers remain unchanged until
        # a reviewed staging bootstrap attaches one to the app.
        _coordinator_runtime = (
            app.get(WORKFLOW_COORDINATOR_RUNTIME_KEY)
            if _queue_owner != 'legacy'
            else None
        )
        _coordinator_admission = None
        _coordinator_mirror = None
        _coordinator_consumer = None
        if _coordinator_runtime is not None:
            try:
                from workflow_coordinator_runtime import (
                    CoordinatorConsumer,
                    CoordinatorJobMirror,
                    CoordinatorParentAdmission,
                )

                _coordinator_admission = CoordinatorParentAdmission(
                    _coordinator_runtime
                )
                if job_tracker is not None:
                    _coordinator_mirror = CoordinatorJobMirror(
                        job_tracker.update_status
                    )
                # Construct the consumer before exposing admission to workers;
                # a graph entry must never be ACKed into a parent stream that
                # has no consumer object ready to drain it.
                _coordinator_consumer = CoordinatorConsumer(
                    _coordinator_runtime,
                    on_terminal=_coordinator_mirror,
                )
            except Exception:
                logger.exception(
                    "Workflow coordinator admission could not be attached"
                )
                app.pop(WORKFLOW_COORDINATOR_RUNTIME_KEY, None)
                _coordinator_runtime = None

        if _queue_owner == 'legacy':
            # Legacy mode is a deliberate compatibility drain: do not create
            # a stopped durable supervisor that can later be mistaken for a
            # second owner.  The background loop owns GPUScheduler only.
            worker_supervisor = None
            _worker_supervisor_task = None
            logger.info(
                "Queue owner=legacy; durable WorkerSupervisor startup is fenced"
            )
        else:
            worker_supervisor = WorkerSupervisor(
                worker_session,
                coordinator_admission=_coordinator_admission,
            )
            _worker_supervisor_task = register_background_task(app, "worker_supervisor", worker_supervisor.run())
            app["worker_supervisor"] = _worker_supervisor_task  # weak ref for shutdown access
            logger.info("Dynamic Worker Pool: supervisor started")
            register_background_task(app, "reconcile_inflight_after_restart", _reconcile_inflight_after_restart())

        # The consumer uses the coordinator's own durable parent stream and is
        # registered in the same app task registry for bounded shutdown.
        if (
            _queue_owner != 'legacy'
            and _coordinator_runtime is not None
            and _coordinator_consumer is not None
            and worker_supervisor is not None
        ):
            try:
                _coordinator_stop = asyncio.Event()
                app[WORKFLOW_COORDINATOR_STOP_KEY] = _coordinator_stop
                app["workflow_coordinator"] = _coordinator_consumer
                register_background_task(
                    app,
                    "workflow_coordinator",
                    _coordinator_consumer.run(_coordinator_stop),
                )
                logger.info("Workflow coordinator consumer attached (explicit runtime)")
            except Exception:
                logger.exception("Workflow coordinator consumer could not be attached")
                app.pop(WORKFLOW_COORDINATOR_RUNTIME_KEY, None)
                # The supervisor may already be running its startup grace
                # period.  Remove the admission object immediately so a pool
                # created after this failure cannot ACK graph entries without
                # a coordinator consumer.
                worker_supervisor.coordinator_admission = None
                for _pool in worker_supervisor._pools.values():
                    _pool.coordinator_admission = None

        # ── Startup health probe: emit "healthy" for already-running services ──
        async def _probe_initial_health():
            """Emit healthy events for services already running at startup."""
            await asyncio.sleep(3)  # let supervisor boot
            svcs = cfg.get("services", {})
            for svc_name, svc_cfg in svcs.items():
                if svc_cfg.get("type") != "llm_backend" or not svc_cfg.get("enabled"):
                    continue
                port = svc_cfg.get("port")
                if not port:
                    continue
                try:
                    async with ClientSession(timeout=ClientTimeout(total=3)) as sess:
                        async with sess.get(f"http://127.0.0.1:{port}/health") as resp:
                            if resp.status == 200:
                                event_bus.emit(svc_name, "healthy")
                                logger.info(f"Startup probe: {svc_name} healthy on :{port}")
                except Exception:
                    logger.debug(f"Startup probe: {svc_name} not reachable on :{port}")

            await _reconcile_authoritative_bundle_state()

        register_background_task(app, "initial_health_probe", _probe_initial_health())
        app["authoritative_bundle_reconciler"] = register_background_task(
            app, "authoritative_bundle_reconciler", _authoritative_bundle_reconcile_loop()
        )

    # Tier 3 (2s later): Non-critical startup tasks
    def _start_tier3():
        register_background_task(app, "ensure_services_running", ensure_services_running())
        register_background_task(app, "regenerate_nginx_config", _regenerate_nginx_config())
        register_background_task(app, "seed_comfyui_idle_timer", _seed_comfyui_idle_timer())

    register_background_callback(app, 1.0, _start_tier2)
    register_background_callback(app, 2.0, _start_tier3)


async def on_startup(app: web.Application):
    # ── Initialize shared ClientSession BEFORE any handler can run (Option A) ──
    # Fixes the 24 broken `session.X` call sites that were None at startup.
    # Idempotent: if background_loop re-runs session_init, we still hold one
    # live session with connection pooling, then close on cleanup.
    global session, vram
    if session is None or session.closed:
        session = ClientSession(timeout=ClientTimeout(total=300, connect=10))

    # The application is now inside its definitive running event loop.  Build
    # and attach the coordinator here (before delayed WorkerPool admission),
    # so run_coroutine_threadsafe always targets this server loop.
    if _queue_owner_mode() != "legacy" and _queue_redis is not None:
        _production_coordinator = _build_production_coordinator_runtime(_services_config)
        if _production_coordinator is not None:
            attach_workflow_coordinator_runtime(app, _production_coordinator)

    # The broker uses the already-initialized shared queue Redis and session.
    # It starts fail-closed: no member can accept until semantic probe evidence
    # is refreshed; initialization never starts/stops/restarts a member.
    await _initialize_combined_gemma_broker()

    # Reconcile lifecycle cache from authoritative systemd state before the
    # API or idle gates can observe it. The constructor defaults to "running",
    # which is wrong after a normal direct-idle shutdown followed by manager
    # restart.
    if vram is not None:
        try:
            _startup_comfyui_states = await vram._comfyui_systemd_state()
            if vram._all_comfyui_units_stopped(_startup_comfyui_states):
                vram._comfyui_stopped = True
                vram._comfyui_auto_stopped = True
                logger.info(
                    "Startup reconcile: all ComfyUI units stopped -> stopped "
                    "(%s)",
                    _startup_comfyui_states,
                )
            elif vram._any_comfyui_unit_active(_startup_comfyui_states):
                vram._comfyui_stopped = False
                vram._comfyui_auto_stopped = False
                logger.info(
                    "Startup reconcile: at least one ComfyUI unit active -> running "
                    "(%s)",
                    _startup_comfyui_states,
                )
            else:
                logger.warning(
                    "Startup reconcile: ComfyUI systemd states unknown=%r; "
                    "retaining conservative running cache",
                    _startup_comfyui_states,
                )
        except Exception as _startup_comfyui_err:
            logger.warning(
                "Startup reconcile: ComfyUI state check failed; retaining "
                "conservative running cache: %s",
                _startup_comfyui_err,
            )

    # CRITICAL: Defer background task creation via call_later() so the event loop
    # can process loop.create_server() in site.start() BEFORE tasks start running.
    # Without this, Python 3.14 + aiohttp 3.13 hangs on port binding.
    loop = asyncio.get_event_loop()
    loop.call_later(5.0, _start_background_tasks, app)

    # ── Restore per-GPU state from persisted state ──
    try:
        saved = _load_state()
        saved_gpu_states = saved.get("gpu_states", {})
        for gpu_id, gpu_data in saved_gpu_states.items():
            gpu = _get_gpu_state(gpu_id)
            gpu.loaded_bundle = gpu_data.get("loaded_bundle")
            gpu.bundle_priority = gpu_data.get("bundle_priority", 0)
            gpu.state = gpu_data.get("state", "idle")
            # Don't restore draining state — that's ephemeral
            if gpu_data.get("draining"):
                logger.info(f"GPU[{gpu_id}]: was draining at shutdown — resetting to idle")
                gpu.draining = False
                gpu.drain_started_at = None
            # Don't restore queue — those requests are lost on restart
            logger.info(
                f"GPU[{gpu_id}]: restored state: bundle={gpu.loaded_bundle}, "
                f"priority={gpu.bundle_priority}, state={gpu.state}"
            )
    except Exception as e:
        logger.debug(f"Per-GPU state restore skipped: {e}")

    logger.info("GPU Manager started (dashboard: http://localhost:8091/dashboard)")

    # ── Phase 5: OOM Redis pool init ──
    # Best-effort: dead-letter store is in Redis. If Redis is unavailable
    # at startup, _init_oom_redis logs a warning and sets _oom_redis_pool=None;
    # the watchdog will retry on the next refresh tick.
    try:
        await _init_oom_redis()
    except Exception as e:
        logger.warning(f"[oom-redis] _init_oom_redis from on_startup raised: {e}")

    # ── OD prompt-enhance project bootstrap (idempotent, best-effort) ──
    # Walk every generation template; for each one with prompt_enhance.enabled,
    # ensure the corresponding OD project exists.  The helper short-circuits
    # on subsequent calls via the module-level _OD_PROJECT_BOOTSTRAP_DONE flag,
    # so this only costs one HTTP round-trip per process lifetime.  OD being
    # down at startup is fine — the per-call path falls through to the direct
    # caption adapter and we'll lazily retry on the next user request.
    try:
        cfg = _load_services_config() or {}
        for _tmpl in (cfg.get("generation_templates") or {}).values():
            _pe = _tmpl.get("prompt_enhance") or {}
            if _pe.get("enabled") and _pe.get("project_id"):
                await _ensure_od_project(
                    _pe["project_id"], _pe.get("design_system_id")
                )
    except Exception as _od_boot_err:
        logger.warning(
            "[od-bootstrap] startup project ensure raised: %s", _od_boot_err
        )


async def on_cleanup(app: web.Application):
    global _controller_shutdown_in_progress
    _controller_shutdown_in_progress = True
    # Save final state before tearing down — this is the clean shutdown state
    _save_state(shutdown=True)
    logger.info("Final state saved on cleanup (clean shutdown)")
    _coordinator_stop = app.get(WORKFLOW_COORDINATOR_STOP_KEY)
    if _coordinator_stop is not None:
        _coordinator_stop.set()
    for handle in app.get(BACKGROUND_STARTUP_HANDLES_KEY, []):
        handle.cancel()
    app[BACKGROUND_STARTUP_HANDLES_KEY] = []
    background_tasks = dict(app.get(BACKGROUND_TASKS_KEY, {}))
    for task in background_tasks.values():
        if not task.done():
            task.cancel()
    if background_tasks:
        done, pending = await asyncio.wait(
            background_tasks.values(),
            timeout=BACKGROUND_TASK_CANCEL_TIMEOUT_SECONDS,
        )
        for name, task in background_tasks.items():
            if task in pending:
                logger.warning(
                    "Background task %s exceeded %.1fs cancellation budget",
                    name,
                    BACKGROUND_TASK_CANCEL_TIMEOUT_SECONDS,
                )
                continue
            try:
                exc = task.exception()
            except asyncio.CancelledError:
                continue
            if exc is not None:
                logger.warning("Background task %s ended during cleanup: %r", name, exc)
    app[BACKGROUND_TASKS_KEY] = {}
    # Close the broker before the shared session/Redis owners begin teardown.
    global _combined_gemma_broker, _combined_gemma_member_cache
    broker = _combined_gemma_broker
    _combined_gemma_broker = None
    _combined_gemma_member_cache = None
    if broker is not None:
        try:
            await broker.close()
        except Exception:
            logger.warning("Combined Gemma broker close failed", exc_info=True)
    # ── Close async Redis connections (Phase 3) ──
    try:
        if async_gossiper:
            await async_gossiper.close()
    except Exception:
        pass
    if _async_redis:
        try:
            await _async_redis.aclose()
        except Exception:
            pass
    await scheduler.stop()
    await _stop_all_port_proxies()
    # Drain all bundle proxy queues with 503 on shutdown
    for bname, q in _bundle_proxy_queues.items():
        q.signal_failed("gpu-manager shutting down")
    _bundle_proxy_queues.clear()
    logger.info("Bundle proxy: all queues drained on shutdown")
    if session:
        try:
            await asyncio.wait_for(session.close(), timeout=5)
        except asyncio.TimeoutError:
            logger.warning("Timed out closing shared HTTP session during shutdown")
    logger.info("GPU Manager shut down")


# ── Main ───────────────────────────────────────────────────────────

def main():
    global LLM_BACKEND_URL, COMFYUI_URL, LISTEN_PORT

    parser = argparse.ArgumentParser(description="GPU Manager — LLM Proxy + Unified GPU Scheduler")
    parser.add_argument("--listen", type=int, default=LISTEN_PORT)
    parser.add_argument("--host", type=str, default="127.0.0.1",
                        help="Host to bind to (default: 127.0.0.1, use 0.0.0.0 for external access)")
    parser.add_argument(
        "--backend", type=int, default=None,
        help="legacy localhost backend port override; otherwise use LLM_BACKEND_URL",
    )
    parser.add_argument(
        "--comfyui", type=int, default=None,
        help="legacy localhost ComfyUI port override; otherwise use COMFYUI_URL",
    )
    parser.add_argument("--mcp", action="store_true", help="Run as MCP stdio server instead of HTTP")
    parser.add_argument("--debug-reservations", action="store_true", help="Enable debug reservation hooks")
    parser.add_argument("--debug-oom-sim", action="store_true", help="Enable safe OOM simulation hook")
    args = parser.parse_args()

    log_directory = os.path.dirname(LOG_FILE)
    if log_directory:
        os.makedirs(log_directory, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(name)s] %(levelname)s: %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
        handlers=[logging.FileHandler(LOG_FILE), logging.StreamHandler()],
    )

    global logger
    logger = logging.getLogger("gpu-manager")

    if args.mcp:
        logger.info("Starting GPU Manager in MCP stdio mode")
        asyncio.run(run_mcp_server())
        return

    LISTEN_PORT = args.listen
    if args.backend is not None:
        LLM_BACKEND_URL = f"http://localhost:{args.backend}"
    if args.comfyui is not None:
        COMFYUI_URL = f"http://localhost:{args.comfyui}"

    logger.info(f"GPU Manager starting on port {LISTEN_PORT}")
    logger.info(f"Backend: {LLM_BACKEND_URL} | ComfyUI: {COMFYUI_URL}")
    logger.info(f"GPU state machine: LLM_LOADED (default) → DRAINING → GPU_WORK → RESTORING")
    logger.info(f"LLM relief threshold: {LLM_RELIEF_THRESHOLD} | drain timeout: {DRAIN_TIMEOUT}s")

    web.run_app(
        create_app(
            debug_reservations=args.debug_reservations,
            debug_oom_sim=args.debug_oom_sim,
        ),
        host=args.host,
        port=LISTEN_PORT,
        print=lambda msg: logger.info(msg),
        handle_signals=True,
        shutdown_timeout=AIOHTTP_SHUTDOWN_TIMEOUT_SECONDS,
        handler_cancellation=True,
    )


if __name__ == "__main__":
    main()
